LOCAL_ATT_MAIN: dict[str, dict[str, Any]] = {
    "A": {"gain": 1.0, "attenuation": False, "ko": "기존 억제 1.0, 조절 OFF"},
    "B": {"gain": 0.0, "attenuation": False, "ko": "기존 억제 0.0, 조절 OFF"},
    "C": {"gain": 1.0, "attenuation": True, "ko": "기존 억제 1.0, 조절 ON"},
    "D": {"gain": 0.0, "attenuation": True, "ko": "기존 억제 0.0, 조절 ON"},
}
