def _db_merge(base: dict[str, Any], upd: dict[str, Any] | None) -> dict[str, Any]:
    s = copy.deepcopy(base)
    for k, v in (upd or {}).items():
        if isinstance(v, dict) and isinstance(s.get(k), dict):
            s[k].update(copy.deepcopy(v))
        else:
            s[k] = copy.deepcopy(v)
    return s


def validate_db_settings(settings: dict[str, Any] | None) -> dict[str, Any]:
    """메뉴 21 설정 검사. 모든 비교 조건에 공통으로 적용되는 값만 바꿀 수 있다 (조건별 조정 없음)."""
    s = _db_merge(db_defaults(), settings)
    th, lr, dbd = s["theta"], s["learning"], s["deadband"]
    lo, init, hi = float(th["min_mV"]), float(th["init_mV"]), float(th["max_mV"])
    if not (0.0 < lo < init < hi):
        raise ValueError(f"0 < theta_min({lo}) < 초기값({init}) < theta_max({hi}) 이어야 한다 (mV).")
    if not (lo <= float(th["l4_fixed_mV"]) <= hi):
        raise ValueError("L4 고정값이 theta 범위 밖이다.")
    if not float(th["fast_bound_mV"]) > 0:
        raise ValueError("fast_bound 는 양수다 (mV).")
    for k in ("kappa_L2_mV", "kappa_L3_mV", "error_scale"):
        if not float(lr[k]) > 0:
            raise ValueError(f"{k} 는 양수다.")
    if not (0.0 <= float(lr["eta_commit"]) <= 1.0):
        raise ValueError("eta_commit 은 [0,1].")
    if int(lr["K_rounds"]) < 1:
        raise ValueError("K_rounds 는 1 이상.")
    if not (0.0 <= float(lr["beta"]) <= 1.0):
        raise ValueError("beta 는 [0,1] (영역 간 동일, 자동 정규화·증폭 없음).")
    if float(lr["rho_fast"]) != 0.0 or lr.get("homeostasis") or lr.get("theta_decay"):
        raise ValueError("rho_fast=0, 항상성·theta 감쇠 OFF 로 고정한다 (0교사 불변 검사 때문).")
    if lr["teacher_gate_rule"] not in ("argmax_wrong_or_tolerance", "argmax_wrong", "target_tolerance"):
        raise ValueError(f"알 수 없는 teacher_gate_rule: {lr['teacher_gate_rule']}")
    if lr["teacher_policy"] != "label_only_prototype":
        raise ValueError("교사 정책은 label_only_prototype 이다 (자동 전환 없음).")
    if lr.get("early_stop"):
        raise ValueError("조기 종료는 OFF 다 (조건 간 settle 수를 맞춘다).")
    for k in ("teacher_tolerance", "legacy_deadband"):
        v = float(dbd[k])
        if not math.isfinite(v) or v < 0:
            raise ValueError(f"deadband.{k} 는 유한한 0 이상 값이다 (정규화 활동 단위).")
    if not float(dbd["legacy_deadband"]) > 0:
        raise ValueError("legacy_deadband 가 0 이면 legacy 와 unfiltered 조건이 같아져 비교가 무의미하다.")
    if list(s["conditions"]) != list(DB_MAIN_CONDITIONS):
        raise ValueError(f"주 비교 조건은 순서까지 {list(DB_MAIN_CONDITIONS)} 로 고정이다 (몰래 빼거나 끼우지 않는다).")
    for c in s["optional_conditions"]:
        if c not in DB_OPTIONAL_CONDITIONS:
            raise ValueError(f"선택 조건은 {list(DB_OPTIONAL_CONDITIONS)} 이다: {c}")
    if s["run_preset"] not in ("smoke", "main"):
        raise ValueError("run_preset 은 smoke | main")
    for key in ("smoke", "main"):
        p = s[key]
        if int(p["epochs"]) < 1 or int(p["batch_size"]) < 1:
            raise ValueError(f"{key}: epochs, batch_size 는 1 이상.")
        if int(p.get("test_bases_per_class", 0)) != 0:
            raise ValueError("개발 main/smoke 는 train/dev 만 쓴다 (test_bases_per_class 는 0, 공개 test 재사용 금지).")
    if s["selection_rule"] not in ("last_epoch", "best_dev_ce"):
        raise ValueError("selection_rule 은 last_epoch | best_dev_ce")
    fr = [float(x) for x in s["data"]["split_fractions"]]
    if len(fr) != 3 or abs(sum(fr) - 1.0) > 1e-9 or min(fr) <= 0:
        raise ValueError("split_fractions 는 양수 3개이고 합이 1 이다.")
    if int(s["data"]["n_base_per_class"]) < 3:
        raise ValueError("base 단위 분할에는 클래스당 원본이 3개 이상 필요하다.")
    ho = s["holdout"]
    if int(ho["n_base_per_class"]) < 1 or int(ho["n_variants"]) < 1 or int(ho["stream_sub"]) < 0:
        raise ValueError("holdout: 원본/클래스 >= 1, 변형 >= 1, stream_sub >= 0.")
    tr = s["trace"]
    if not isinstance(tr.get("enabled"), bool) or int(tr["max_bytes"]) <= 0 or any(int(r) < 0 for r in tr["sample_rows"]):
        raise ValueError("trace: enabled 는 y/n, max_bytes > 0, sample_rows >= 0.")
    if any(int(x) < 0 for x in s["observe_trace_neurons"]):
        raise ValueError("observe_trace_neurons 는 0 이상 정수 id 다.")
    if s["flow_detail"] not in ("full", "summary"):
        raise ValueError("flow_detail 은 full | summary")
    for sd in s["seeds"]:
        int(sd)
    if float(s["stimulus_ms"]) <= 0 or float(s["offset_ms"]) < 0 or float(s["dt_ms"]) <= 0:
        raise ValueError("stimulus_ms > 0, offset_ms >= 0, dt_ms > 0")
    return s


def db_settings_sha(s: dict[str, Any]) -> str:
    """학습 결과에 영향을 주는 설정의 해시. holdout 자료 크기·스트림은 학습에 쓰이지 않으므로 뺀다."""
    return sha256_text(json.dumps({k: v for k, v in s.items() if k != "holdout"}, sort_keys=True))


def db_all_conditions(s: dict[str, Any]) -> list[str]:
    return list(s["conditions"]) + [c for c in s["optional_conditions"] if c not in s["conditions"]]


def db_policy(s: dict[str, Any], name: str) -> DeadbandPolicy:
    """조건 이름 -> 정책. 모든 진입 경로(학습·검증·정책 비교·holdout)가 이 함수만 쓴다."""
    if name not in DB_CONDITION_TABLE:
        raise ValueError(f"알 수 없는 deadband 조건: {name!r}")
    row = DB_CONDITION_TABLE[name]
    leg = float(s["deadband"]["legacy_deadband"])

    def val(v: Any) -> float:
        return leg if v == "legacy" else float(v)
    return DeadbandPolicy(name=name, teacher_tolerance=float(s["deadband"]["teacher_tolerance"]),
                          relay_deadband=val(row["relay"]), update_deadband=val(row["update"]),
                          freeze=bool(row.get("freeze", False)), zero_teacher=bool(row.get("zero_teacher", False)),
                          shuffle=bool(row.get("shuffle", False)))


def db_policy_table(s: dict[str, Any]) -> list[dict[str, Any]]:
    return [{**db_policy(s, c).to_dict(), "description_ko": DB_CONDITIONS_KO[c]} for c in db_all_conditions(s)]


def db_to_tl_settings(s: dict[str, Any]) -> dict[str, Any]:
    """TL 실행기·네트워크가 읽는 키 구조. ``learning.deadband`` 는 넣지 않는다 (정책 객체만 쓴다)."""
    lr = {k: v for k, v in s["learning"].items()}
    lr["deadband"] = None
    return {"preset": s["preset"], "engine_kind": s["engine_kind"], "run_preset": s["run_preset"],
            "seeds": list(s["seeds"]), "stimulus_ms": s["stimulus_ms"], "offset_ms": s["offset_ms"],
            "dt_ms": s["dt_ms"], "theta": dict(s["theta"]), "learning": lr, "conditions": [],
            "optional_conditions": [], "data": dict(s["data"]), "smoke": dict(s["smoke"]),
            "main": dict(s["main"]), "selection_rule": s["selection_rule"],
            "diagnostic_stimuli": list(s["diagnostic_stimuli"]),
            "observe_trace_neurons": list(s["observe_trace_neurons"]),
            "deterministic_engine": bool(s["deterministic_engine"])}


# ---------------------------------------------------------------------- 연산자 (NumPy/torch 공용)
def _xcopy(x: Any) -> Any:
    return x.clone() if _is_torch(x) else np.array(x, copy=True)


def _xlast(x: Any) -> Any:
    return x.unsqueeze(-1) if _is_torch(x) else np.expand_dims(np.asarray(x), -1)


def _xcast(mask: Any, like: Any) -> Any:
    return mask.to(like.dtype) if _is_torch(mask) else np.asarray(mask).astype(np.asarray(like).dtype)


def db_hard(e: Any, d: float) -> Any:
    """H_d(e) = e * 1[|e| > d]. d=0 이어도 정확히 0 인 성분은 0. 기존 e*(|e|>db) 와 같은 연산 순서."""
    return e * _xcast(_xabs(e) > float(d), e)


def db_soft(e: Any, d: float) -> Any:
    """S_d(e) = sign(e) * max(|e| - d, 0) (L1 수신기 soft deadband 와 같은 함수)."""
    return tl_soft_deadband(e, d)


def db_split(e_pre: Any, h: Any, valid: Any, *, relay_db: float, update_db: float) -> dict[str, Any]:
    """e_pre_deadband -> 전달용 (relay) / 로컬 (update) 두 버퍼. 서로 별칭이 아닌 별도 텐서."""
    e_relay = db_hard(e_pre, relay_db)
    e_local = db_hard(e_pre, update_db)
    return {"e_pre_deadband": e_pre,
            "e_relay": e_relay, "target_relay": h - e_relay,
            "needs_relay": valid & correction_needed(e_relay, relay_db),
            "e_local": e_local, "target_local": h - e_local,
            "needs_local": valid & correction_needed(e_local, update_db)}


def db_top_errors(h: Any, t_top: Any, gate: Any, valid: Any, *, relay_db: float, update_db: float
                  ) -> dict[str, Any]:
    """최상위: e_pre = valid*gate*(h - t). invalid 표본은 h-t 를 쓰지 않고 명시적 0."""
    raw = _xwhere(_xlast(valid), h - t_top, _xzeros_like(h))
    g = _xlast(_xcast(gate & valid, h))
    e_pre = raw * g
    out = db_split(e_pre, h, valid, relay_db=relay_db, update_db=update_db)
    out["raw_ungated"] = raw
    return out


def db_lower_errors(restore: Callable[[Any], Any], h_upper: Any, target_relay_upper: Any,
                    needs_relay_upper: Any, h: Any, valid: Any, *, beta: float, relay_db: float,
                    update_db: float, lo: float, hi: float) -> dict[str, Any]:
    """하위: e_raw = beta*(D(h_U) - D(target_relay_U)), gate = needs_relay_U (needs_local 아님).

    target_pre = clip(h - e_raw, lo, hi), e_pre = h - target_pre. 기본 복원 잔차 h - D(h_U) 는 더하지 않는다.
    """
    e_raw, d_h = dtp_lower_error(restore, h_upper, target_relay_upper, beta, needs_relay_upper)
    target_pre = _xclip(h - e_raw, float(lo), float(hi))
    e_pre = h - target_pre
    out = db_split(e_pre, h, valid, relay_db=relay_db, update_db=update_db)
    out.update(e_raw=e_raw, target_pre_deadband=target_pre, d_h=d_h)
    return out


def db_channel_math(h: Any, e_local: Any, valid: Any, groups: Sequence[Any], *, update_db: float, eps: float,
                    project: Callable[[Any, Any], Any] | None = None) -> dict[str, Any]:
    """로컬 교정 -> 두 채널. 분해·needs·L2 투영 여부·candidate 가 모두 update_deadband 를 쓴다."""
    dec = amplitude_pattern_decompose(h, e_local, groups, eps=float(eps))
    e_int, e_pat = dec["intensity"], dec["pattern"]
    out = {"dec": dec, "intensity": e_int, "pattern": e_pat,
           "needs_intensity": valid & correction_needed(e_int, update_db),
           "needs_pattern": valid & correction_needed(e_pat, update_db),
           "cand_intensity": _xcast(_xabs(e_int) > float(update_db), e_int),
           "e_l2": None, "cand_shape": None, "needs_shape": None}
    if project is not None:
        e_l2 = project(e_pat, out["needs_pattern"])
        out["e_l2"] = e_l2
        out["cand_shape"] = _xcast(_xabs(e_l2) > float(update_db), e_l2)
        out["needs_shape"] = out["needs_pattern"] & correction_needed(e_l2, update_db)
    return out


def db_residual_math(h_new: Any, target_local: Any, valid: Any, needs_local: Any, groups: Sequence[Any], *,
                     update_db: float, eps: float) -> dict[str, Any]:
    """L2 수정 뒤 새 활동과 **target_local** 의 잔차 (기존 _residual_packets 의 마스킹·분해 순서 그대로)."""
    e_new = full_target_residual(h_new, target_local, valid & needs_local)
    dec = amplitude_pattern_decompose(h_new, e_new, groups, eps=float(eps))
    e_int = dec["intensity"]
    return {"e_residual": e_new, "dec": dec, "intensity": e_int, "pattern_carried": dec["pattern"],
            "needs_intensity": valid & correction_needed(e_int, update_db),
            "cand_intensity": _xcast(_xabs(e_int) > float(update_db), e_int),
            "needs_residual": valid & correction_needed(e_new, update_db)}


def db_teacher_gate(wrong: Any, h_it: Any, t_src: Any, *, rule: str, tolerance: float) -> tuple[Any, Any]:
    """교사 gate. tolerance 는 정책의 teacher_tolerance (relay/update 와 무관)."""
    off = correction_needed(h_it - t_src, float(tolerance))
    if rule == "argmax_wrong":
        g = wrong
    elif rule == "target_tolerance":
        g = off
    elif rule == "argmax_wrong_or_tolerance":
        g = wrong | off
    else:
        raise ValueError(f"알 수 없는 teacher_gate_rule: {rule!r}")
    return g, off


def db_l1_delta(r: Any, *, valid: Any, needs: Any, cand: Any, confidence: Any, update_db: float,
                error_scale: float, kappa: float) -> Any:
    """L1: kappa*gate*candidate*confidence*tanh(S_update(r)/error_scale). confidence 를 두 번 곱하지 않는다."""
    gate = _xlast(_xcast(valid & needs, r))
    return tl_threshold_delta(r, deadband=float(update_db), error_scale=float(error_scale), kappa=float(kappa),
                              gate=gate, mask=cand, confidence=confidence)


def db_vec_stats(x: Any) -> dict[str, Any]:
    """NumPy 통계 (검사·보고서용). GPU 경로는 DBStatAcc 가 같은 다섯 값을 모은다."""
    a = np.asarray(x, dtype=np.float64)
    if a.size == 0:
        return {"norm": 0.0, "max_abs": 0.0, "n_nonzero": 0, "n_deficit": 0, "n_excess": 0}
    return {"norm": float(np.sqrt(np.sum(a * a))), "max_abs": float(np.max(np.abs(a))),
            "n_nonzero": int(np.sum(a != 0)), "n_deficit": int(np.sum(a < 0)), "n_excess": int(np.sum(a > 0))}


def db_overlap(a: Any, b: Any) -> dict[str, Any]:
    """같은 모양 두 교정 벡터: 공통 생존·새 생존·사라진 좌표의 수와 노름 (크기 진단, 방향 증명 아님)."""
    if _is_torch(a):
        t = require_torch()
        a64, b64 = a.detach().to(t.float64), b.detach().to(t.float64)
        na, nb = a64 != 0, b64 != 0
        z = t.zeros((), dtype=t.float64, device=a64.device)

        def nrm(x: Any, m: Any) -> Any:
            return t.sqrt(t.where(m, x * x, z).sum())
        dot = t.where(na & nb, a64 * b64, z).sum()
        return {"n_nonzero_a": na.sum(), "n_nonzero_b": nb.sum(), "n_common": (na & nb).sum(),
                "n_new_in_b": (nb & ~na).sum(), "n_lost_in_b": (na & ~nb).sum(),
                "norm_a": nrm(a64, na), "norm_b": nrm(b64, nb), "norm_a_common": nrm(a64, na & nb),
                "norm_b_common": nrm(b64, na & nb), "norm_b_new": nrm(b64, nb & ~na),
                "norm_a_lost": nrm(a64, na & ~nb), "dot_common": dot}
    A, Bv = np.asarray(a, np.float64), np.asarray(b, np.float64)
    na, nb = A != 0, Bv != 0

    def nrm_np(x: np.ndarray, m: np.ndarray) -> float:
        return float(np.sqrt(np.sum(np.where(m, x * x, 0.0))))
    return {"n_nonzero_a": int(na.sum()), "n_nonzero_b": int(nb.sum()), "n_common": int((na & nb).sum()),
            "n_new_in_b": int((nb & ~na).sum()), "n_lost_in_b": int((na & ~nb).sum()),
            "norm_a": nrm_np(A, na), "norm_b": nrm_np(Bv, nb), "norm_a_common": nrm_np(A, na & nb),
            "norm_b_common": nrm_np(Bv, na & nb), "norm_b_new": nrm_np(Bv, nb & ~na),
            "norm_a_lost": nrm_np(A, na & ~nb), "dot_common": float(np.sum(np.where(na & nb, A * Bv, 0.0)))}


def db_estimate(*, n_conditions: int, n_train: int, n_dev: int, batch_size: int, epochs: int, K: int,
                n_prep: int, n_diag_stimuli: int, steps: int, eval_train_each_epoch: bool,
                diagnostic_each_epoch: bool = False) -> dict[str, Any]:
    """실행 전 계산량 (실측 시간 없음). settle 1회 = 배치 하나를 steps 만큼 실행."""
    bs = max(1, int(batch_size))
    nb = max(1, math.ceil(n_train / bs))
    per_batch = 2 * int(K) + 2                      # free 1 + 교정 2K + post_update_free 1
    train = int(n_conditions) * int(epochs) * nb * per_batch
    dev_b = math.ceil(n_dev / bs) if n_dev else 0
    tr_b = (math.ceil(n_train / bs) if eval_train_each_epoch else 0)
    per_eval = dev_b + tr_b + (n_diag_stimuli if diagnostic_each_epoch else 0)
    evaluation = (per_eval + n_diag_stimuli                       # 공통 초기 상태
                  + int(n_conditions) * int(epochs) * per_eval     # 에폭 끝 teacher-free
                  + int(n_conditions) * (dev_b + n_diag_stimuli))  # 선택 theta 의 dev + 진단 자극
    prep = math.ceil(n_prep / bs) if n_prep else 0
    tot = train + evaluation + prep
    return {"n_conditions": int(n_conditions), "n_batches_per_epoch": nb, "epochs": int(epochs),
            "K_rounds": int(K), "settles_per_batch": per_batch,
            "train_settles_formula": f"{n_conditions} 조건 x {int(epochs) * nb} 배치 x {per_batch} settle = {train}",
            "settle_calls": {"preparation": prep, "train": train, "evaluation_and_diagnostic": evaluation,
                             "total": tot},
            "physical_steps_total": tot * int(steps), "steps_per_settle": int(steps),
            "note_ko": ("settle 수는 deadband 설정과 무관하다 (모든 조건이 free + 2K + post 를 같은 횟수로 실행, 조기 종료 "
                        "없음). 교정 벡터 계산은 영역별 GPU 텐서 연산이며 실제 시간은 재지 않았다. 사전 검증(메뉴 21-2)·"
                        "holdout(21-7) 은 따로다.")}


def db_theta_epoch_metrics(prev: np.ndarray, cur: np.ndarray, groups: dict[str, np.ndarray], *, lo: float,
                           hi: float) -> dict[str, dict[str, Any]]:
    """에폭 사이 theta_base 변화 (영역/층별): 변경·상승·하락 수, 평균 |변화|, 하한/상한 도달."""
    out = {}
    for g, ids in groups.items():
        ids = np.asarray(ids, np.int64)
        d = np.asarray(cur, np.float64)[ids] - np.asarray(prev, np.float64)[ids]
        v = np.asarray(cur, np.float64)[ids]
        out[g] = {"n": int(ids.size), "n_changed": int((d != 0).sum()), "n_up": int((d > 0).sum()),
                  "n_down": int((d < 0).sum()), "mean_abs_change_mV": float(np.abs(d).mean()) if d.size else 0.0,
                  "max_abs_change_mV": float(np.abs(d).max()) if d.size else 0.0,
                  "at_lower_bound": int((v <= lo + 1e-9).sum()), "at_upper_bound": int((v >= hi - 1e-9).sum())}
    return out


def db_class_separation(h: np.ndarray, labels: np.ndarray) -> dict[str, Any]:
    """IT L3 활동의 클래스 간/내 분산 비 (라벨은 예측 뒤 지표 계산에만). 활동이 전부 0 이면 None."""
    h = np.asarray(h, np.float64)
    labels = np.asarray(labels)
    if h.ndim != 2 or h.shape[0] < 2:
        return {"between_within_ratio": None, "reason_ko": "표본이 2개 미만"}
    mu = h.mean(axis=0)
    classes = sorted(set(labels.tolist()))
    between = sum(float((labels == c).sum()) * float(((h[labels == c].mean(axis=0) - mu) ** 2).sum())
                  for c in classes) / h.shape[0]
    within = sum(float(((h[labels == c] - h[labels == c].mean(axis=0)) ** 2).sum()) for c in classes) / h.shape[0]
    return {"between_class_ss_per_sample": between, "within_class_ss_per_sample": within,
            "between_within_ratio": (None if within <= 0 else between / within),
            "n_classes": len(classes), "all_zero_activity": bool(not np.any(h != 0)),
            "note_ko": "분리 지표일 뿐 정확도가 아니다. within=0 이면 None."}


def db_fmt(v: Any, d: int = 4) -> str:
    """보고서 표시: None 은 '미측정' (0 으로 합산하지 않는다)."""
    if v is None:
        return "미측정"
    if isinstance(v, bool):
        return "예" if v else "아니오"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if not math.isfinite(v):
            return str(v)
        return f"{v:.{d}g}"
    return str(v)


class _NoGlobalDeadband:
    """메뉴 21 네트워크의 ``self.deadband`` 자리. 읽어서 계산에 쓰면 즉시 실패한다 (DB7: 숨은 전역 deadband 금지).

    부모 클래스(PairedDualFeedbackNetwork)의 build_packets / _residual_packets / teacher_gate / describe 는 전역
    ``self.deadband`` 를 쓴다. 메뉴 21 은 이 네 함수를 모두 정책 객체를 쓰는 판으로 바꿨고, 혹시 남은 경로가
    있으면 조용히 옛 값으로 계산하지 않고 여기서 멈춘다.
    """

    _MSG = ("메뉴 21 네트워크에는 전역 deadband 가 없다. teacher_tolerance / relay_deadband / update_deadband 는 "
            "DeadbandPolicy 에서 읽어야 한다 (전역 값 사용 시도를 차단했다).")

    def _fail(self, *args: Any, **kwargs: Any) -> Any:
        raise RuntimeError(self._MSG)

    __float__ = __int__ = __index__ = __bool__ = _fail
    __lt__ = __le__ = __gt__ = __ge__ = _fail
    __add__ = __radd__ = __sub__ = __rsub__ = __mul__ = __rmul__ = __truediv__ = __rtruediv__ = _fail
    __neg__ = __abs__ = _fail

    def __repr__(self) -> str:
        return "<NoGlobalDeadband: DeadbandPolicy 만 사용>"


DB_STAT_KEYS: tuple[str, ...] = ("norm", "max_abs", "n_nonzero", "n_deficit", "n_excess")


class DBStatAcc:
    """GPU 텐서 통계를 모아 episode 끝에 **한 번만** CPU 로 옮긴다 (타임스텝·단계마다 동기화하지 않음).

    ``add(meta, x, **extra)``: x 의 norm·max_abs·비영·부족(<0)·과잉(>0) 수와 extra 텐서 스칼라를 예약한다.
    x 가 None 이면 다섯 값은 None (미측정) 으로 남는다. ``enabled=False`` 면 아무것도 모으지 않는다.
    """

    def __init__(self, enabled: bool = True) -> None:
        self.enabled = bool(enabled)
        self._meta: list[dict[str, Any]] = []
        self._keys: list[list[str]] = []
        self._vals: list[Any] = []

    def add(self, meta: dict[str, Any], x: Any = None, **extra: Any) -> None:
        if not self.enabled:
            return
        t = require_torch()
        row = dict(meta)
        keys: list[str] = []
        if x is not None:
            xd = x.detach()
            if int(xd.numel()):
                x64 = xd.to(t.float64)
                self._vals.extend([x64.norm(), x64.abs().max(), (xd != 0).sum().to(t.float64),
                                   (xd < 0).sum().to(t.float64), (xd > 0).sum().to(t.float64)])
            else:
                z = t.zeros((), dtype=t.float64, device=xd.device)
                self._vals.extend([z, z, z, z, z])
            keys.extend(DB_STAT_KEYS)
        else:
            for k in DB_STAT_KEYS:
                row.setdefault(k, None)
        for k, v in extra.items():
            if _is_torch(v):
                self._vals.append(v.detach().to(t.float64).reshape(()))
                keys.append(k)
            else:
                row[k] = v
        self._meta.append(row)
        self._keys.append(keys)

    def finish(self) -> list[dict[str, Any]]:
        if not self._meta:
            return []
        t = require_torch()
        host = t.stack(self._vals).to("cpu").tolist() if self._vals else []
        rows, i = [], 0
        for meta, keys in zip(self._meta, self._keys):
            r = dict(meta)
            for k in keys:
                v = host[i]
                i += 1
                r[k] = int(round(v)) if k.startswith("n_") else float(v)
            rows.append(r)
        self._meta, self._keys, self._vals = [], [], []
        return rows


class DBReceiver(TLReceiver):
    """L1 수신기. soft deadband 값은 복사해 두지 않고 매번 **현재 정책의 update_deadband** 를 읽는다."""

    def __init__(self, area: str, readout: "SlotActivityReadout", net: "DBPairedNetwork") -> None:
        DualL1Receiver.__init__(self, area, readout)
        self._net = net

    @property
    def deadband(self) -> float:                                   # type: ignore[override]
        """읽기 전용 (setter 없음: 직접 대입하면 AttributeError). 값은 정책의 update_deadband 에서만 온다."""
        return float(self._net.policy.update_deadband)


class DBThresholdController(TLThresholdController):
    """TLThresholdController 와 같은 식. apply_round_lazy 는 기록용 동기화 없이 같은 계산만 한다."""

    def apply_round_lazy(self, theta_fast: Any, delta: Any) -> tuple[Any, Any, Any]:
        t = require_torch()
        m = self.mask.view(1, 1, -1).to(self.dtype)
        dm = delta * m
        raw = theta_fast + dm
        nxt = t.clamp(raw, -self.fast_bound, self.fast_bound)
        return nxt, dm, raw


class DBPairedNetwork(TLPairedNetwork):
    """메뉴 21: TLPairedNetwork 의 F0r settle·순차 이중 교정 구조 그대로 + deadband 정책 분리.

    바꾼 곳 (이 클래스에서만, 메뉴 20 의 TLPairedNetwork 는 그대로):
    * build_packets: 영역마다 e_pre_deadband / e_relay / target_relay / needs_relay / e_local / target_local /
      needs_local 를 따로 만든다. 하위 DTP 는 target_relay·needs_relay, 로컬 분해·패킷은 e_local·update_deadband.
    * _residual_packets: 새 활동과 **target_local** (needs_local) 의 잔차, update_deadband.
    * teacher_gate: teacher_tolerance (조건과 무관하게 같은 값).
    * L1 수신기: soft deadband = update_deadband (정책에서 매번 읽음).
    * self.deadband: 사용 금지 표식 (_NoGlobalDeadband).
    * 기록: DBStatAcc 로 단계별 통계를 모아 episode 끝에 한 번 CPU 로 옮긴다. 기존 per-sample CPU 분류 루프는 뺐다.
    """

    def __init__(self, cfg: dict[str, Any], model: "CorticalModel", seeds: "SeedStreams", *,
                 tl: dict[str, Any], policy: DeadbandPolicy, learn_mask: Any, obs_steps: int, stim_steps: int,
                 window_steps: tuple[int, int], gate_ref: Any) -> None:
        tl2 = copy.deepcopy(tl)
        tl2["learning"]["deadband"] = float(policy.teacher_tolerance)   # 부모 생성자 호환용. 직후 무효화한다.
        super().__init__(cfg, model, seeds, tl=tl2, condition="frozen", learn_mask=learn_mask,
                         obs_steps=obs_steps, stim_steps=stim_steps, window_steps=window_steps, gate_ref=gate_ref)
        self.tl = tl
        self.fb["deadband"] = "policy_only (DeadbandPolicy)"
        self.deadband = _NoGlobalDeadband()
        th = tl["theta"]
        self.controller = DBThresholdController(model.neurons, mask=learn_mask, lo=float(th["min_mV"]),
                                                hi=float(th["max_mV"]), fast_bound=float(th["fast_bound_mV"]),
                                                device=self.device, dtype=self.dtype)
        self.policy = policy
        self.receivers = {a: DBReceiver(a, self.activity, self) for a in self.activity.order}
        self.numeric_log = {"invalid_teacher_target_samples": 0, "nonfinite_activity_episodes": 0}
        self.set_policy(policy, learn_mask)

    # ------------------------------------------------------------------ 정책
    def set_policy(self, policy: DeadbandPolicy, learn_mask: Any) -> None:
        if not isinstance(policy, DeadbandPolicy):
            raise TypeError("DeadbandPolicy 가 필요하다")
        self.policy = policy
        self.tl_condition = policy.name
        self.condition = "location_shuffled_matched" if policy.shuffle else "sequential_dual"
        self.controller.mask = learn_mask
        self.model.neurons.theta_trainable = learn_mask.clone()

    def set_condition(self, condition: str, learn_mask: Any) -> None:            # noqa: D102
        raise RuntimeError("메뉴 21 네트워크는 set_policy(DeadbandPolicy, mask) 만 쓴다 (조건 이름만으로 바꾸지 않는다).")

    # ------------------------------------------------------------------ 교사 gate
    def teacher_gate(self, free: dict[str, Any], labels: Any, t_it: Any) -> tuple[Any, dict[str, Any]]:
        cmp_free = self.comparator.evaluate(free["logits"], labels)
        rule = str(self.fb["teacher_gate_rule"])
        wrong = cmp_free["teacher_gate"] > 0
        g, off = db_teacher_gate(wrong, free["h_IT"], t_it, rule=rule,
                                 tolerance=float(self.policy.teacher_tolerance))
        return g, {"rule": rule, "teacher_tolerance": float(self.policy.teacher_tolerance),
                   "argmax_wrong_count": wrong.sum(), "outside_tolerance_count": off.sum(),
                   "n_gate_samples": int(wrong.numel()), "cmp": cmp_free}

    # ------------------------------------------------------------------ 패킷
    def build_packets(self, state: dict[str, Any], t_top: Any, gate_top: Any, valid_top: Any, *,
                      sample_id: int, episode_id: int, round_id: int) -> dict[str, dict[str, Any]]:
        """위에서 아래로 전달/로컬 교정을 따로 만든다. 기존 build_packets 와 같은 순서·같은 연산자."""
        t = require_torch()
        pol = self.policy
        rdb, udb = float(pol.relay_deadband), float(pol.update_deadband)
        acts = state["activities"]
        l2acts = state.get("l2_activities", {})
        order = list(reversed(self.activity.order))
        lo_clip, hi_clip = (float(v) for v in self.fb["target_clip"])
        eps = float(self.fb["decomposition"]["eps_norm"])
        version = self._new_version()
        out: dict[str, dict[str, Any]] = {}
        upper: str | None = None
        for area in order:
            h = acts[area]
            R, B = h.shape[0], h.shape[1]
            tag3 = self.activity.tag(area, "L3")
            reliability = None
            restore_err = None
            if upper is None:
                core = db_top_errors(h, t_top, gate_top, valid_top, relay_db=rdb, update_db=udb)
                valid = valid_top.clone()
            else:
                up = out[upper]
                D = self.decoders[upper]
                core = db_lower_errors(D.forward, acts[upper], up["target_relay"], up["needs_relay"], h,
                                       up["valid"], beta=self._beta(upper), relay_db=rdb, update_db=udb,
                                       lo=lo_clip, hi=hi_clip)
                valid = up["valid"].clone()
                restore_err = h - core["d_h"]                          # 지표로만 (교사 교정에 더하지 않음)
                rel = 1.0 - restore_err.norm(dim=-1, keepdim=True) / (h.norm(dim=-1, keepdim=True) + 1e-9)
                reliability = t.clamp(rel, 0.0, 1.0)
            has_l2 = area in self.activity.l2_specs
            proj = ((lambda e_pat, needs_pat, _a=area, _h=h: self._project_to_l2(_a, _h, e_pat, needs_pat))
                    if has_l2 else None)
            ch = db_channel_math(h, core["e_local"], valid, self.groups[area], update_db=udb, eps=eps, project=proj)
            conf3, basis = self._confidence(reliability, (R, B, 1))
            conf2 = conf3
            a2 = l2acts.get(area)
            if has_l2 and str(self.fb["confidence_mode"]) == "restorer_reliability" \
                    and a2 is not None and self.l3_to_l2[area].trained:
                err2 = a2 - self.l3_to_l2[area].forward(h)
                rel2 = t.clamp(1.0 - err2.norm(dim=-1, keepdim=True) / (a2.norm(dim=-1, keepdim=True) + 1e-9),
                               0.0, 1.0)
                conf2 = conf3 * rel2
            sender = upper if upper is not None else "frontal_comparator"
            meta = {"policy": pol.name, "relay_deadband": rdb, "update_deadband": udb}
            pk_int = DualCorrectionPacket(
                run_id=self.run_id, sample_id=sample_id, frame_id=0, episode_id=episode_id, round_id=round_id,
                state_version=version, sender_area=sender, receiver_area=area, channel="intensity",
                target_layer="L3", target_neuron_ids=self.activity.specs[area].neuron_ids, representation=tag3,
                reference_activity=h.detach().clone(), correction=ch["intensity"],
                candidate_mask=ch["cand_intensity"], confidence=conf3, confidence_basis=basis, valid=valid,
                needs_correction=ch["needs_intensity"], meta=dict(meta))
            pk_shape = None
            if ch["e_l2"] is not None:
                pk_shape = DualCorrectionPacket(
                    run_id=self.run_id, sample_id=sample_id, frame_id=0, episode_id=episode_id,
                    round_id=round_id, state_version=version, sender_area=sender, receiver_area=area,
                    channel="shape", target_layer="L2", target_neuron_ids=self.activity.l2_specs[area].neuron_ids,
                    representation=self.activity.tag(area, "L2"),
                    reference_activity=(a2.detach().clone() if a2 is not None else t.zeros_like(ch["e_l2"])),
                    correction=ch["e_l2"], candidate_mask=ch["cand_shape"], confidence=conf2,
                    confidence_basis=basis + ("; x T_B 복원 신뢰도" if conf2 is not conf3 else ""),
                    valid=valid, needs_correction=ch["needs_shape"], meta=dict(meta))
            out[area] = {"h": h, "valid": valid, **core, "intensity": ch["intensity"], "pattern": ch["pattern"],
                         "inactive_mask": ch["dec"]["inactive_mask"],
                         "decomposition_residual_max": ch["dec"]["sum_residual_max"],
                         "needs_intensity": ch["needs_intensity"], "needs_pattern": ch["needs_pattern"],
                         "e_l2": ch["e_l2"], "a2": a2, "packet_intensity": pk_int, "packet_shape": pk_shape,
                         "reliability": reliability, "restore_error": restore_err, "sender": sender,
                         "beta_applied": (None if upper is None else self._beta(upper)),
                         "version": version, "policy": pol.name}
            upper = area
        return out

    def _residual_packets(self, state: dict[str, Any], stored: dict[str, dict[str, Any]], *, sample_id: int,
                          episode_id: int, round_id: int) -> dict[str, dict[str, Any]]:
        """L2 수정·재실행 뒤 새 활동과 **target_local** 의 잔차. 마스킹(valid & needs_local)·분해 순서는 기존 그대로."""
        version = self._new_version()
        udb = float(self.policy.update_deadband)
        eps = float(self.fb["decomposition"]["eps_norm"])
        out: dict[str, dict[str, Any]] = {}
        for area, old in stored.items():
            h_new = state["activities"][area]
            pk = old["packet_intensity"]
            require_same_representation(self.activity.tag(area, "L3"), pk.representation, f"{area} 잔차 재계산")
            valid = old["valid"]
            rm = db_residual_math(h_new, old["target_local"], valid, old["needs_local"], self.groups[area],
                                  update_db=udb, eps=eps)
            new_pk = DualCorrectionPacket(
                run_id=self.run_id, sample_id=sample_id, frame_id=0, episode_id=episode_id, round_id=round_id,
                state_version=version, sender_area=pk.sender_area, receiver_area=area, channel="intensity",
                target_layer="L3", target_neuron_ids=pk.target_neuron_ids, representation=pk.representation,
                reference_activity=h_new.detach().clone(), correction=rm["intensity"],
                candidate_mask=rm["cand_intensity"], confidence=pk.confidence,
                confidence_basis=pk.confidence_basis, valid=valid, needs_correction=rm["needs_intensity"],
                meta={"recomputed_after_shape_step": True, "from_state_version": pk.state_version,
                      "residual_target": "target_local", "policy": self.policy.name})
            out[area] = {"h": h_new, "valid": valid, "e_residual": rm["e_residual"], "intensity": rm["intensity"],
                         "pattern_carried": rm["pattern_carried"], "needs_residual": rm["needs_residual"],
                         "target_local": old["target_local"], "e_local_before": old["e_local"],
                         "packet_intensity": new_pk, "packet_shape": None, "version": version,
                         "from_version": old["version"]}
        return out

    def _db_deliver(self, packets: dict[str, dict[str, Any]], channel: str, *, sample_id: int, R: int
                    ) -> tuple[Any, dict[str, Any]]:
        """기존 _deliver 와 같은 수신·버전 검사·drive·consume. 패킷 요약(동기화)은 만들지 않는다."""
        t = require_torch()
        B = int(packets[self.top_area]["h"].shape[1])
        full = t.zeros((R, B, self.model.neurons.n), dtype=self.dtype, device=self.device)
        kappa = float(self.fb["kappa_shape_mV"] if channel == "shape" else self.fb["kappa_intensity_mV"])
        rec: dict[str, Any] = {}
        for area, p in packets.items():
            pk = p["packet_shape" if channel == "shape" else "packet_intensity"]
            if pk is None:
                continue
            rx = self.receivers[area]
            if not rx.receive(pk, sample_id=sample_id):
                rec[area] = {"accepted": False, "reason": rx.rejected[-1]["reason"]}
                continue
            d = rx.drive(channel, kappa=kappa, error_scale=self.error_scale, attention=None)
            rx.consume(channel)
            full[:, :, pk.target_neuron_ids] = d
            rec[area] = {"accepted": True, "packet": pk, "delta": d}
        return full, rec

    def describe(self) -> dict[str, Any]:
        fb = self.fb
        pol = self.policy
        return {"network": "DBPairedNetwork (TLPairedNetwork 상속)", "policy": pol.to_dict(),
                "units_ko": DB_UNITS_KO, "slot_map_hash": self.slot_map.hash,
                "max_iterations": self.K, "beta": self.beta, "teacher_gate_rule": fb["teacher_gate_rule"],
                "kappa_shape_mV": fb["kappa_shape_mV"], "kappa_intensity_mV": fb["kappa_intensity_mV"],
                "error_scale": self.error_scale, "l3_to_l2_projection": fb["l3_to_l2_projection"],
                "confidence_mode": fb["confidence_mode"], "target_clip": list(fb["target_clip"]),
                "uses_backprop": False,
                "dtp": "e_raw_L = beta*(D_U(h_U) - D_U(target_relay_U)); gate = needs_relay_U",
                "local": "e_local = H_update(e_pre); 분해·투영·패킷·L1·잔차는 update_deadband"}

    # ------------------------------------------------------------------ 기록 보조
    def _slices(self, channel: str) -> list[tuple[str, str, Any]]:
        out = []
        for area in self.activity.order:
            spec = self.activity.l2_specs.get(area) if channel == "shape" else self.activity.specs.get(area)
            if spec is not None:
                out.append((area, "L2" if channel == "shape" else "L3", spec.neuron_ids))
        return out

    def _flow_build(self, acc: DBStatAcc, packets: dict[str, dict[str, Any]], *, round_id: int,
                    gate: Any, ungated: dict[str, dict[str, Any]] | None) -> None:
        prev: str | None = None
        for area, p in packets.items():
            base = {"area": area, "round": round_id}
            e_pre, e_relay, e_local = p["e_pre_deadband"], p["e_relay"], p["e_local"]
            if "raw_ungated" in p:
                ext: dict[str, Any] = {}
                if ungated is not None:
                    ug = ungated[area]["e_pre_deadband"]
                    acc.add({**base, "stage": "teacher_ungated", "layer": "L3", "channel": "total"}, ug)
                    ext["n_zero_by_gate_or_invalid"] = ((ug != 0) & (e_pre == 0)).sum()
                gv = (gate & p["valid"]).unsqueeze(-1)
                ext["n_zero_correction_itself"] = (gv & (p["raw_ungated"] == 0)).sum()
                ext["n_gate_on_samples"] = (gate & p["valid"]).sum()
                ext["n_invalid_samples"] = (~p["valid"]).sum()
                acc.add({**base, "stage": "teacher_gated", "layer": "L3", "channel": "total"}, e_pre, **ext)
            else:
                up = packets[prev] if prev is not None else None
                acc.add({**base, "stage": "dtp_input", "layer": "L3", "channel": "total", "from_area": prev},
                        None if up is None else up["e_relay"],
                        n_gate_samples=(None if up is None else up["needs_relay"].sum()))
                acc.add({**base, "stage": "dtp_output", "layer": "L3", "channel": "total",
                         "beta_applied": p["beta_applied"]}, p["e_raw"])
                acc.add({**base, "stage": "target_clip_after", "layer": "L3", "channel": "total"}, e_pre,
                        n_removed_by_target_clip=((p["e_raw"] != 0) & (e_pre == 0)).sum(),
                        n_reduced_by_target_clip=(e_pre.abs() < p["e_raw"].abs()).sum())
            nsamp = int(p["valid"].numel())
            acc.add({**base, "stage": "relay_after", "layer": "L3", "channel": "relay", "n_samples": nsamp}, e_relay,
                    n_blocked_by_relay_deadband=((e_pre != 0) & (e_relay == 0)).sum(),
                    n_samples_needs_relay=p["needs_relay"].sum())
            acc.add({**base, "stage": "local_after", "layer": "L3", "channel": "local", "n_samples": nsamp}, e_local,
                    n_blocked_by_update_deadband=((e_pre != 0) & (e_local == 0)).sum(),
                    n_samples_needs_local=p["needs_local"].sum(),
                    n_silent_deficit_candidates=((p["h"] <= 0) & (e_local < 0)).sum())
            acc.add({**base, "stage": "decomp_intensity", "layer": "L3", "channel": "intensity"}, p["intensity"],
                    n_zero_after_decomposition=((e_local != 0) & (p["intensity"] == 0)).sum(),
                    n_silent_deficit_no_intensity=((p["h"] <= 0) & (e_local < 0) & (p["intensity"] == 0)).sum(),
                    n_samples_needs_intensity=p["needs_intensity"].sum())
            acc.add({**base, "stage": "decomp_pattern", "layer": "L3", "channel": "pattern"}, p["pattern"],
                    n_samples_needs_pattern=p["needs_pattern"].sum())
            if p["e_l2"] is not None:
                np_ = p["needs_pattern"].unsqueeze(-1)
                ext2: dict[str, Any] = {"n_l2_projection_zero": (np_ & (p["e_l2"] == 0)).sum()}
                if p["a2"] is not None:
                    ext2["n_negative_implicit_target"] = (np_ & ((p["a2"] - p["e_l2"]) < 0)).sum()
                acc.add({**base, "stage": "l2_projection", "layer": "L2", "channel": "shape"}, p["e_l2"], **ext2)
            prev = area

    def _flow_packet(self, acc: DBStatAcc, pk: Any, *, area: str, layer: str, channel: str, round_id: int) -> None:
        base = {"area": area, "layer": layer, "channel": channel, "round": round_id}
        g = (pk.valid & pk.needs_correction).to(pk.correction.dtype).unsqueeze(-1)
        cn = pk.correction * pk.candidate_mask * g
        acc.add({**base, "stage": "packet_candidate_needs"}, cn)
        conf = pk.confidence.expand_as(cn)
        acc.add({**base, "stage": "packet_confidence"}, cn * conf,
                n_removed_by_confidence=((cn != 0) & (conf <= 0)).sum())
        acc.add({**base, "stage": "l1_soft_before"}, cn)
        s = db_soft(pk.correction, float(self.policy.update_deadband)) * g * pk.candidate_mask
        acc.add({**base, "stage": "l1_soft_after", "update_deadband": float(self.policy.update_deadband)}, s,
                n_removed_by_soft_deadband=((cn != 0) & (s == 0)).sum())

    def _core_extra(self, core: DBStatAcc, packets: dict[str, dict[str, Any]], *, round_id: int) -> None:
        """하위 실험의 추가 요약 기록 지점 (메뉴 21 에서는 아무것도 하지 않는다)."""
        return None

    def _flow_apply(self, acc: DBStatAcc, rec: dict[str, Any], *, channel: str, round_id: int, d_req: Any,
                    d_after: Any | None, dm: Any, change: Any, shuffled: bool, raw: Any | None = None) -> None:
        """raw (clamp 전 theta_fast 후보) 는 메뉴 22 계측용으로만 넘긴다. 메뉴 21 기록은 그대로다."""
        mask = self.controller.mask
        for area, layer, ids in self._slices(channel):
            base = {"area": area, "layer": layer, "channel": channel, "round": round_id}
            r = rec.get(area)
            if r is not None and r.get("accepted"):
                pk, d = r["packet"], r["delta"]
                ref = pk.reference_activity
                acc.add({**base, "stage": "delta_request"}, d,
                        n_silent_with_delta=((ref <= 0) & (d != 0)).sum(),
                        n_silent_deficit_with_delta=((ref <= 0) & (d < 0)).sum())
            elif r is not None:
                acc.add({**base, "stage": "delta_request", "rejected_reason": r.get("reason")}, None)
            if shuffled and d_after is not None:
                acc.add({**base, "stage": "after_shuffle"}, d_after[:, :, ids],
                        norm_before_shuffle=d_req[:, :, ids].to(require_torch().float64).norm())
            src = d_after if d_after is not None else d_req
            acc.add({**base, "stage": "after_learning_mask"}, dm[:, :, ids],
                    n_outside_learning_mask=((src[:, :, ids] != 0) & ~mask[ids].view(1, 1, -1)).sum())
            acc.add({**base, "stage": "fast_clip_change"}, change[:, :, ids],
                    n_fast_clip_limited=((dm[:, :, ids] != 0) & (change[:, :, ids] != dm[:, :, ids])).sum())

    # ------------------------------------------------------------------ 같은 free 상태 정책 비교
    def policy_compare(self, state: dict[str, Any], t_it: Any, gate: Any, valid_top: Any,
                       policies: Sequence[DeadbandPolicy], acc: DBStatAcc, *, meta: dict[str, Any]) -> dict[str, Any]:
        """같은 free 상태에서 정책별 교정 벡터만 계산한다 (신경망 추가 실행·수신·적용 없음).

        모델·수신기 버퍼·state_version·theta 를 바꾸지 않는다 (끝나면 정책·버전을 되돌린다, 검사 DB9).
        L3 강도 채널의 실제 적용값은 L2 수정 뒤 재실행이 필요하므로 여기서는 잔차 전 패킷만 비교한다.
        """
        saved_policy, saved_version = self.policy, self._state_version
        vec: dict[str, dict[str, dict[str, Any]]] = {}
        es = float(self.error_scale)
        k2, k3 = float(self.fb["kappa_shape_mV"]), float(self.fb["kappa_intensity_mV"])
        try:
            for pol in policies:
                self.policy = pol
                pk = self.build_packets(state, t_it, gate, valid_top, sample_id=-7, episode_id=-7, round_id=-7)
                v: dict[str, dict[str, Any]] = {}
                for area, p in pk.items():
                    ent = {"relay_L3": p["e_relay"], "local_L3": p["e_local"]}
                    pi = p["packet_intensity"]
                    ent["delta_L3_pre_residual"] = db_l1_delta(
                        pi.correction, valid=pi.valid, needs=pi.needs_correction, cand=pi.candidate_mask,
                        confidence=pi.confidence, update_db=pol.update_deadband, error_scale=es, kappa=k3)
                    ps = p["packet_shape"]
                    if ps is not None:
                        ent["delta_L2_shape"] = db_l1_delta(
                            ps.correction, valid=ps.valid, needs=ps.needs_correction, cand=ps.candidate_mask,
                            confidence=ps.confidence, update_db=pol.update_deadband, error_scale=es, kappa=k2)
                    v[area] = ent
                vec[pol.name] = v
        finally:
            self.policy = saved_policy
            self._state_version = saved_version
        pairs = (("B_vs_A", "legacy_deadband", "relay_unfiltered"),
                 ("C_vs_B", "relay_unfiltered", "relay_and_update_unfiltered"),
                 ("C_vs_A", "legacy_deadband", "relay_and_update_unfiltered"))
        for tag, pa, pb in pairs:
            if pa not in vec or pb not in vec:
                continue
            for area, ent in vec[pa].items():
                for kind, a in ent.items():
                    b = vec[pb].get(area, {}).get(kind)
                    if b is None:
                        continue
                    acc.add({**meta, "pair": tag, "policy_a": pa, "policy_b": pb, "area": area, "vector": kind},
                            None, **db_overlap(a, b))
        return {"policies": [p.name for p in policies], "state_version_restored": self._state_version == saved_version}

    # ------------------------------------------------------------------ episode
    def db_episode(self, x: Any, labels: Any, *, sample_id: int, episode_id: int, drive_key: tuple[str, int],
                   train: bool, compare_policies: Sequence[DeadbandPolicy] | None = None,
                   detail: str = "full", flow_meta: dict[str, Any] | None = None) -> dict[str, Any]:
        """명세 7절 순서: free -> (패킷 -> L2 -> 재실행 -> target_local 잔차 -> L3 -> 재실행) x K -> commit -> post.

        조건과 무관하게 settle 수가 같다 (free 1 + 2K + post 1). 조기 종료 없음.
        """
        t = require_torch()
        pol = self.policy
        T = self.obs_steps
        fm = dict(flow_meta or {})
        drive = self.episode_drive(x, drive_key)
        ctx = {"attention": None, "drive_key": drive_key}
        for rx in self.receivers.values():
            rx.last_version = {"shape": -1, "intensity": -1}
            rx.buffers = {"shape": None, "intensity": None}
        acc = DBStatAcc(enabled=(detail == "full"))
        core = DBStatAcc(enabled=True)
        cmp_acc = DBStatAcc(enabled=bool(compare_policies))
        calls = 0
        free = self.settle_chain(None, None, None, ctx, drive, None, T)
        calls += 1
        if "h_IT" not in free:
            return {"status": STATUS_INSUFFICIENT_SIGNAL, "reason": "활동 벡터를 만들 수 없다 (준비 미완료)"}
        R, B = int(free["h_IT"].shape[0]), int(free["h_IT"].shape[1])
        finite = t.ones((), dtype=t.bool, device=self.device)
        for v in free["activities"].values():
            finite = finite & t.isfinite(v).all()
        sel = self.targets.select_prototype(free["h_IT"], labels)          # 라벨은 교사 경로에만
        t_src = sel["target"]
        valid_top = t.isfinite(t_src).all(dim=-1)
        gate_raw, gate_info = self.teacher_gate(free, labels, t_src)
        cmp_free = gate_info.pop("cmp")
        gate_true = gate_raw & valid_top
        ones = t.ones_like(gate_true)
        raw_pk = self.build_packets(free, self.comparator.it_target(free["h_IT"], ones.to(self.dtype), t_src),
                                    ones & valid_top, valid_top, sample_id=sample_id, episode_id=episode_id,
                                    round_id=-1)
        gate = t.zeros_like(gate_true) if pol.zero_teacher else gate_true
        t_it = self.comparator.it_target(free["h_IT"], gate.to(self.dtype), t_src)
        cmp_info = None
        if compare_policies:
            free_c = {"activities": {k: v.detach().clone() for k, v in free["activities"].items()},
                      "l2_activities": {k: v.detach().clone() for k, v in free.get("l2_activities", {}).items()}}
            cmp_info = self.policy_compare(free_c, t_it.detach().clone(), gate.clone(), valid_top.clone(),
                                           compare_policies, cmp_acc, meta={**fm, "condition": pol.name})
        theta_fast = t.zeros((R, B, self.model.neurons.n), dtype=self.dtype, device=self.device)
        rounds: list[dict[str, Any]] = []
        current = free
        guided_ce: list[Any] = []
        for it in range(int(self.K)):                                  # 조기 종료 없음
            rid = 2 * it
            packets = self.build_packets(current, t_it, gate, valid_top, sample_id=sample_id,
                                         episode_id=episode_id, round_id=rid)
            self._flow_build(acc, packets, round_id=rid, gate=gate, ungated=raw_pk if it == 0 else None)
            if it == 0:
                for area, p in packets.items():
                    core.add({"kind": "reach", "area": area, "n_samples": int(p["valid"].numel())}, None,
                             n_samples_needs_relay=p["needs_relay"].sum(), n_samples_needs_local=p["needs_local"].sum(),
                             relay_norm=p["e_relay"].to(t.float64).norm(),
                             local_norm=p["e_local"].to(t.float64).norm())
                self._core_extra(core, packets, round_id=rid)
            for area, p in packets.items():
                if p["packet_shape"] is not None:
                    self._flow_packet(acc, p["packet_shape"], area=area, layer="L2", channel="shape", round_id=rid)
                if p["e_l2"] is not None and p["a2"] is not None:
                    core.add({"kind": "l2_negative_implicit_target", "area": area, "round": rid}, None,
                             n=(p["needs_pattern"].unsqueeze(-1) & ((p["a2"] - p["e_l2"]) < 0)).sum())
            d_shape, srec = self._db_deliver(packets, "shape", sample_id=sample_id, R=R)
            d_req = d_shape
            d_shape, sh_info = self._condition_shuffle(d_shape, "shape", rid)
            if pol.freeze:
                d_shape = t.zeros_like(d_shape)                        # 기록만 하고 적용하지 않는다
            nxt, dm, _raw = self.controller.apply_round_lazy(theta_fast, d_shape)
            self._flow_apply(acc, srec, channel="shape", round_id=rid, d_req=d_req,
                             d_after=(d_shape if pol.shuffle else None), dm=dm, change=nxt - theta_fast,
                             shuffled=pol.shuffle, raw=_raw)
            theta_fast = nxt
            current = self.settle_chain(None, None, theta_fast, ctx, drive, None, T)
            calls += 1
            for v in current["activities"].values():
                finite = finite & t.isfinite(v).all()
            residual = self._residual_packets(current, packets, sample_id=sample_id, episode_id=episode_id,
                                              round_id=rid + 1)
            for area, r in residual.items():
                b2 = {"area": area, "layer": "L3", "round": rid + 1}
                acc.add({**b2, "stage": "residual_after_shape", "channel": "total"}, r["e_residual"],
                        n_newly_mismatched=((r["e_local_before"] == 0) & (r["e_residual"] != 0)).sum(),
                        n_samples_needs_residual=r["needs_residual"].sum())
                acc.add({**b2, "stage": "residual_intensity", "channel": "intensity"}, r["intensity"])
                self._flow_packet(acc, r["packet_intensity"], area=area, layer="L3", channel="intensity",
                                  round_id=rid + 1)
            d_int, irec = self._db_deliver(residual, "intensity", sample_id=sample_id, R=R)
            d_req2 = d_int
            d_int, in_info = self._condition_shuffle(d_int, "intensity", rid + 1)
            if pol.freeze:
                d_int = t.zeros_like(d_int)
            nxt, dm, _raw = self.controller.apply_round_lazy(theta_fast, d_int)
            self._flow_apply(acc, irec, channel="intensity", round_id=rid + 1, d_req=d_req2,
                             d_after=(d_int if pol.shuffle else None), dm=dm, change=nxt - theta_fast,
                             shuffled=pol.shuffle, raw=_raw)
            theta_fast = nxt
            current = self.settle_chain(None, None, theta_fast, ctx, drive, None, T)
            calls += 1
            for v in current["activities"].values():
                finite = finite & t.isfinite(v).all()
            cmp_it = self.comparator.evaluate(current["logits"], labels)
            guided_ce.append(cmp_it["cross_entropy"].mean())
            rounds.append({"iteration": it, "shape_rejections": {a: r["reason"] for a, r in srec.items()
                                                                  if not r.get("accepted")},
                           "intensity_rejections": {a: r["reason"] for a, r in irec.items() if not r.get("accepted")},
                           **({"shuffle_shape": sh_info, "shuffle_intensity": in_info} if pol.shuffle else {})})
        guided = current
        cmp_g = self.comparator.evaluate(guided["logits"], labels)
        # ---- 배치 경계: 수치 오류를 commit 전에 확인 (NaN/Inf 를 0 으로 바꾸지 않는다) ----
        fast_ok = bool(t.isfinite(theta_fast).all())
        act_ok = bool(finite)
        if not (fast_ok and act_ok):
            self.numeric_log["nonfinite_activity_episodes"] += 1
            raise EngineDivergence(f"{pol.name}: 활동 또는 theta_fast 에 NaN/Inf (활동 유한 {act_ok}, theta_fast 유한 "
                                   f"{fast_ok}). 0 으로 바꾸지 않고 멈춘다 (commit 전).")
        mean_fast = theta_fast.mean(dim=(0, 1))
        pos = (theta_fast > 0).any(dim=1).any(dim=0)
        neg = (theta_fast < 0).any(dim=1).any(dim=0)
        nzs = (theta_fast != 0).any(dim=1).any(dim=0)
        for area, layer, ids in self._slices("shape") + self._slices("intensity"):
            base = {"area": area, "layer": layer, "channel": "batch", "round": None}
            acc.add({**base, "stage": "batch_mean_fast"}, mean_fast[ids],
                    n_batch_mean_sign_cancel=(pos[ids] & neg[ids]).sum(),
                    n_mean_zero_with_nonzero_samples=((mean_fast[ids] == 0) & nzs[ids]).sum())
            core.add({"kind": "applied", "area": area, "layer": layer, "n_samples": R * B}, None,
                     n_samples_fast_nonzero=(theta_fast[:, :, ids] != 0).any(dim=-1).sum(),
                     n_neurons_fast_nonzero=nzs[ids].sum())
        replay_diff = None
        if pol.freeze or pol.zero_teacher:
            replay_diff = t.stack([(guided["activities"][a] - free["activities"][a]).abs().max()
                                   for a in free["activities"]]).max()
        commit: dict[str, Any]
        if train and not pol.freeze:
            before = self.model.neurons.theta_base.detach().clone()
            commit, req, act = self.controller.commit(theta_fast, float(self.tl["learning"]["eta_commit"]))
            new = self.model.neurons.theta_base
            m3 = self.controller.mask
            cand = before + req
            for area, layer, ids in self._slices("shape") + self._slices("intensity"):
                base = {"area": area, "layer": layer, "channel": "commit", "round": None}
                acc.add({**base, "stage": "commit_request"}, req[ids])
                acc.add({**base, "stage": "commit_actual"}, act[ids],
                        n_base_clip_limited=(m3[ids] & (req[ids] != 0) & (new[ids] != cand[ids])).sum(),
                        n_float32_no_change=(m3[ids] & (req[ids] != 0) & (cand[ids] == before[ids])).sum(),
                        n_changed_outside_mask=((new[ids] != before[ids]) & ~m3[ids]).sum())
        else:
            commit = {"applied": False, "requested_norm": 0.0, "actual_norm": 0.0,
                      "reason": "frozen: 영구 학습 없음" if pol.freeze else "train=False"}
            for area, layer, ids in self._slices("shape") + self._slices("intensity"):
                base = {"area": area, "layer": layer, "channel": "commit", "round": None,
                        "not_applicable": commit["reason"]}
                acc.add({**base, "stage": "commit_request"}, None)
                acc.add({**base, "stage": "commit_actual"}, None)
        post = self.settle_chain(None, None, None, ctx, drive, None, T)    # theta_fast 0, 교사 없음, 상태 재초기화
        calls += 1
        post_fast_zero = bool((self.model.state.theta_fast == 0).all())
        cmp_post = self.comparator.evaluate(post["logits"], labels)
        # ---- 배치 경계: 한 번에 CPU 로 ----
        scal = t.stack([cmp_free["correct"].to(t.float64).mean(), cmp_free["cross_entropy"].to(t.float64).mean(),
                        cmp_g["correct"].to(t.float64).mean(), cmp_g["cross_entropy"].to(t.float64).mean(),
                        cmp_post["correct"].to(t.float64).mean(), cmp_post["cross_entropy"].to(t.float64).mean(),
                        gate.to(t.float64).mean(), gate_true.to(t.float64).mean(),
                        theta_fast.to(t.float64).norm(), theta_fast.abs().max().to(t.float64),
                        (~valid_top).sum().to(t.float64), gate_info["argmax_wrong_count"].to(t.float64),
                        gate_info["outside_tolerance_count"].to(t.float64), sel["distance"].to(t.float64).mean(),
                        (replay_diff.to(t.float64) if replay_diff is not None
                         else t.zeros((), dtype=t.float64, device=self.device))]
                       + [g.to(t.float64) for g in guided_ce]).to("cpu").tolist()
        n_invalid = int(round(scal[10]))
        self.numeric_log["invalid_teacher_target_samples"] += n_invalid
        flow_rows = acc.finish()
        for r in flow_rows:
            r.update(fm)
            r["condition"] = pol.name
        core_rows = core.finish()
        cmp_rows = cmp_acc.finish() if compare_policies else []
        return {
            "status": "completed", "condition": pol.name, "policy": pol.to_dict(), "sample_id": sample_id,
            "K": int(self.K), "forward_calls": calls, "teacher_gate_fraction": scal[6],
            "teacher_gate_fraction_true": scal[7],
            "teacher_gate": {"rule": gate_info["rule"], "teacher_tolerance": gate_info["teacher_tolerance"],
                             "argmax_wrong_fraction": scal[11] / max(1, gate_info["n_gate_samples"]),
                             "outside_tolerance_fraction": scal[12] / max(1, gate_info["n_gate_samples"])},
            "prototype_distance_mean": scal[13], "invalid_teacher_target_samples": n_invalid,
            "free_before": {"accuracy": scal[0], "cross_entropy": scal[1]},
            "guided": {"accuracy": scal[2], "cross_entropy": scal[3], "per_round_ce": scal[15:],
                       "note_ko": "교사가 있는 상태의 값이다. 일반화 성능이 아니다."},
            "post_update_free": {"accuracy": scal[4], "cross_entropy": scal[5]},
            "commit": commit, "rounds": rounds, "flow": flow_rows, "core": core_rows, "same_state": cmp_rows,
            "same_state_info": cmp_info, "theta_fast_final_norm": scal[8], "theta_fast_final_max_abs": scal[9],
            "replay_activity_max_abs_diff": (scal[14] if replay_diff is not None else None),
            "post_theta_fast_zero": post_fast_zero}


# ---------------------------------------------------------------------- CPU 합성 검사용 작은 대역 (실제 회로 아님)
class _DBStubReadout:
    """합성 검사 전용 활동 판독 대역: 영역 순서·슬롯 id·표현 표식만 가진다."""

    def __init__(self, areas: Sequence[str], n3: int, n2: int, device: Any) -> None:
        from types import SimpleNamespace
        t = require_torch()
        self.order = list(areas)
        self.specs, self.l2_specs = {}, {}
        off = 0
        for a in self.order:
            self.specs[a] = SimpleNamespace(neuron_ids=t.arange(off, off + n3, device=device), size=n3)
            off += n3
            self.l2_specs[a] = SimpleNamespace(neuron_ids=t.arange(off, off + n2, device=device), size=n2)
            off += n2
        self.n_total = off

    def tag(self, area: str, layer: str) -> "RepresentationTag":
        n = (self.specs if layer == "L3" else self.l2_specs)[area].size
        return RepresentationTag(area, layer, "stub_slot_rate", "normalized_activity", int(n))


class _DBStubDecoder:
    def __init__(self, W: Any) -> None:
        self.W = W
        self.trained = True

    def forward(self, z: Any) -> Any:
        return z @ self.W.T


def db_make_stub(kind: str, *, areas: Sequence[str] = ("A1", "A2", "A3"), n3: int = 4, n2: int = 4,
                 decoders: dict[str, Any] | None = None, l3_to_l2: dict[str, Any] | None = None,
                 groups: dict[str, list[Any]] | None = None, policy: DeadbandPolicy | None = None,
                 legacy_deadband: float = 0.02, beta: float = 0.2, kappa: float = 0.25, error_scale: float = 0.1,
                 projection: str = "paired_identity", theta: Any = None, mask: Any = None, dtype: Any = None
                 ) -> Any:
    """CPU 합성 검사용: 실제 클래스(TLPairedNetwork / DBPairedNetwork)의 메서드를 그대로 쓰는 작은 대역 객체.

    ``areas`` 는 아래->위 순서 (마지막이 최상위). 회로·엔진·준비 단계는 없다. 이 객체로 얻은 값은 합성 산술 사례이며
    실제 피질 성능 예측이 아니다.
    """
    from types import SimpleNamespace
    t = require_torch()
    dev = t.device("cpu")
    dt = dtype or t.float32
    obj = object.__new__(DBPairedNetwork if kind == "db" else TLPairedNetwork)
    act = _DBStubReadout(areas, n3, n2, dev)
    obj.activity = act
    obj.device, obj.dtype = dev, dt
    obj.run_id = "stub"
    obj._state_version = 0
    obj.top_area = act.order[-1]
    obj.beta = float(beta)
    obj.K = 1
    obj.error_scale = float(error_scale)
    obj.fb = {"target_clip": [0.0, 1.0], "beta_by_area": {}, "kappa_shape_mV": float(kappa),
              "kappa_intensity_mV": float(kappa), "l3_to_l2_projection": projection,
              "confidence_mode": "restorer_reliability", "constant_confidence": 1.0,
              "teacher_gate_rule": "argmax_wrong_or_tolerance",
              "decomposition": {"eps_norm": 1e-9, "grouping": "surface_tiles", "tile_mm": 1.0,
                                "intensity_dominant_fraction": 0.8, "shape_dominant_fraction": 0.2}}
    eye = t.eye(n3, dtype=dt)
    obj.decoders = {act.order[i + 1]: _DBStubDecoder(eye.clone() if decoders is None
                                                      else decoders[act.order[i + 1]])
                    for i in range(len(act.order) - 1)}
    obj.l3_to_l2 = {a: _DBStubDecoder(t.eye(n2, n3, dtype=dt) if l3_to_l2 is None else l3_to_l2[a])
                    for a in act.order}
    obj.groups = groups or {a: [t.arange(n3)] for a in act.order}
    obj.slot_map = SimpleNamespace(areas={a: {"n_paired": min(n2, n3)} for a in act.order}, hash="stub")
    th = t.full((act.n_total,), 3.0, dtype=dt) if theta is None else theta
    msk = t.ones(act.n_total, dtype=t.bool) if mask is None else mask
    obj.model = SimpleNamespace(neurons=SimpleNamespace(n=act.n_total, theta_base=th))
    obj.tl = {"learning": {"eta_commit": 0.1}}
    obj.attention = SimpleNamespace(apply_to_gate=False)
    if kind == "db":
        obj.policy = policy
        obj.deadband = _NoGlobalDeadband()
        obj.receivers = {a: DBReceiver(a, act, obj) for a in act.order}
        obj.controller = DBThresholdController(obj.model.neurons, mask=msk, lo=1.0, hi=30.0, fast_bound=1.0,
                                               device=dev, dtype=dt)
        obj.condition = "sequential_dual"
    else:
        obj.deadband = float(legacy_deadband)
        obj.receivers = {a: TLReceiver(a, act, float(legacy_deadband)) for a in act.order}
        obj.controller = TLThresholdController(obj.model.neurons, mask=msk, lo=1.0, hi=30.0, fast_bound=1.0,
                                               device=dev, dtype=dt)
        obj.condition = "sequential_dual"
    return obj


# ---------------------------------------------------------------------- 사전 검증 DB1~DB11 (메뉴 21-2)
DB_CHECK_TOL_ABS: float = 1e-6        # 회로 비교의 부동소수 허용오차 (비트 일치는 따로 기록)
DB_CHECK_TOL_SYNTH: float = 1e-12     # float64 합성 산술 사례의 허용오차


class _DBCmp:
    """두 경로의 텐서를 비교해 비트 일치·최대차를 모은다."""

    def __init__(self, tol: float = 0.0) -> None:
        self.rows: list[dict[str, Any]] = []
        self.tol = float(tol)

    def __call__(self, name: str, a: Any, b: Any) -> bool:
        t = require_torch()
        if a is None or b is None:
            eq = a is None and b is None
            self.rows.append({"item": name, "bitwise_equal": eq, "max_abs_diff": 0.0 if eq else None,
                              "within_tolerance": eq})
            return eq
        if tuple(a.shape) != tuple(b.shape):
            self.rows.append({"item": name, "bitwise_equal": False, "max_abs_diff": None, "within_tolerance": False,
                              "shape": [list(a.shape), list(b.shape)]})
            return False
        eq = bool(t.equal(a, b))
        if int(a.numel()) == 0:
            md = 0.0
        elif a.dtype == t.bool or b.dtype == t.bool:
            md = float((a.to(t.float64) - b.to(t.float64)).abs().max())
        else:
            diff = (a.to(t.float64) - b.to(t.float64)).abs()
            both_nan = t.isnan(a.to(t.float64)) & t.isnan(b.to(t.float64))
            md = float(t.where(both_nan, t.zeros_like(diff), diff).max())
        within = eq or (a.dtype != t.bool and md <= self.tol)
        self.rows.append({"item": name, "bitwise_equal": eq, "max_abs_diff": md, "within_tolerance": within})
        return within

    def summary(self) -> dict[str, Any]:
        mds = [r["max_abs_diff"] for r in self.rows if r["max_abs_diff"] is not None]
        return {"n_compared": len(self.rows), "n_bitwise_equal": sum(1 for r in self.rows if r["bitwise_equal"]),
                "n_within_tolerance": sum(1 for r in self.rows if r["within_tolerance"]),
                "max_abs_diff": max(mds) if mds else None, "tolerance_abs": self.tol,
                "failed_items": [r for r in self.rows if not r["within_tolerance"]][:30]}


def _db_cmp_packets(cmp: _DBCmp, tag: str, pl: dict[str, Any], pn: dict[str, Any]) -> None:
    cmp(f"{tag} e_total~e_local", pl["e_total"], pn["e_local"])
    cmp(f"{tag} e_total~e_relay", pl["e_total"], pn["e_relay"])
    cmp(f"{tag} target_total~target_local", pl["target_total"], pn["target_local"])
    cmp(f"{tag} target_total~target_relay", pl["target_total"], pn["target_relay"])
    cmp(f"{tag} needs_total~needs_local", pl["needs_total"], pn["needs_local"])
    cmp(f"{tag} needs_total~needs_relay", pl["needs_total"], pn["needs_relay"])
    cmp(f"{tag} valid", pl["valid"], pn["valid"])
    for ch in ("packet_intensity", "packet_shape"):
        a, b = pl[ch], pn[ch]
        if a is None or b is None:
            cmp(f"{tag} {ch} 존재", None if a is None else a.correction, None if b is None else b.correction)
            continue
        cmp(f"{tag} {ch}.correction", a.correction, b.correction)
        cmp(f"{tag} {ch}.candidate_mask", a.candidate_mask, b.candidate_mask)
        cmp(f"{tag} {ch}.needs_correction", a.needs_correction, b.needs_correction)
        cmp(f"{tag} {ch}.confidence", a.confidence, b.confidence)


def _db_check_db1_cpu(dbs: dict[str, Any], *, trials: int = 4, seed: int = 20261003) -> dict[str, Any]:
    """DB1a: 같은 합성 상태에서 legacy_deadband == 메뉴 20 local_all_L23 (CPU float32, 결정론, 비트 일치 요구)."""
    t = require_torch()
    gen = t.Generator().manual_seed(int(seed))
    dt = t.float32
    areas, n3, n2 = ("A1", "A2", "A3"), 6, 5
    D = {u: t.rand((n3, n3), generator=gen, dtype=dt) * 0.4 for u in areas[1:]}
    T = {a: t.rand((n2, n3), generator=gen, dtype=dt) * 0.5 for a in areas}
    groups = {a: [t.arange(0, 3), t.arange(3, n3)] for a in areas}
    leg_db = float(dbs["deadband"]["legacy_deadband"])
    pol = db_policy(dbs, "legacy_deadband")
    lr = dbs["learning"]
    cmp = _DBCmp(tol=0.0)
    for trial in range(int(trials)):
        kw = dict(decoders=D, l3_to_l2=T, groups=groups, n3=n3, n2=n2, projection="restorer_difference", dtype=dt,
                  areas=areas, beta=float(lr["beta"]), kappa=float(lr["kappa_L2_mV"]), error_scale=float(lr["error_scale"]))
        leg = db_make_stub("tl", legacy_deadband=leg_db, **kw)
        new = db_make_stub("db", policy=pol, **kw)
        R, B = 1, 5
        h = {}
        for a in areas:
            v = t.rand((R, B, n3), generator=gen, dtype=dt)
            v[t.rand((R, B, n3), generator=gen) < 0.3] = 0.0            # 침묵 성분
            h[a] = v
        l2 = {a: t.rand((R, B, n2), generator=gen, dtype=dt) for a in areas}
        spread = 0.05 if trial == 2 else 0.2                             # trial 2: deadband 근처의 작은 교정
        t_top = (h[areas[-1]] + (t.rand((R, B, n3), generator=gen, dtype=dt) - 0.5) * spread).clamp(0.0, 1.0)
        if trial == 1:
            t_top[0, 0, 0] = float("nan")                               # invalid 표본 1개
        valid = t.isfinite(t_top).all(dim=-1)
        gate = t.rand((R, B), generator=gen) > 0.3
        state = {"activities": h, "l2_activities": l2}
        Pl = PairedDualFeedbackNetwork.build_packets(leg, state, t_top, gate, valid, sample_id=1, episode_id=0,
                                                     round_id=0)
        Pn = DBPairedNetwork.build_packets(new, state, t_top, gate, valid, sample_id=1, episode_id=0, round_id=0)
        for a in areas:
            _db_cmp_packets(cmp, f"t{trial} {a} r0", Pl[a], Pn[a])
        d_l, _ = leg._deliver(Pl, "shape", sample_id=1, att=None, R=R)
        d_n, _ = new._db_deliver(Pn, "shape", sample_id=1, R=R)
        cmp(f"t{trial} delta_shape", d_l, d_n)
        f0 = t.zeros_like(d_l)
        fl, _ = leg.controller.apply_round(f0, d_l)
        fn, _dm, _raw = new.controller.apply_round_lazy(f0, d_n)
        cmp(f"t{trial} theta_fast after L2", fl, fn)
        h2 = {a: (h[a] + (t.rand((R, B, n3), generator=gen, dtype=dt) - 0.5) * 0.1).clamp(0.0, 1.0) for a in areas}
        st2 = {"activities": h2}
        Rl = PairedDualFeedbackNetwork._residual_packets(leg, st2, Pl, sample_id=1, episode_id=0, round_id=1)
        Rn = DBPairedNetwork._residual_packets(new, st2, Pn, sample_id=1, episode_id=0, round_id=1)
        for a in areas:
            cmp(f"t{trial} {a} residual e", Rl[a]["e_total_after_shape"], Rn[a]["e_residual"])
            for f_ in ("correction", "candidate_mask", "needs_correction", "confidence"):
                cmp(f"t{trial} {a} residual packet.{f_}", getattr(Rl[a]["packet_intensity"], f_),
                    getattr(Rn[a]["packet_intensity"], f_))
        d_l2, _ = leg._deliver(Rl, "intensity", sample_id=1, att=None, R=R)
        d_n2, _ = new._db_deliver(Rn, "intensity", sample_id=1, R=R)
        cmp(f"t{trial} delta_intensity", d_l2, d_n2)
        fl2, _ = leg.controller.apply_round(fl, d_l2)
        fn2, _dm, _raw = new.controller.apply_round_lazy(fn, d_n2)
        cmp(f"t{trial} theta_fast after L3", fl2, fn2)
        _rl, req_l, act_l = leg.controller.commit(fl2, float(lr["eta_commit"]))
        _rn, req_n, act_n = new.controller.commit(fn2, float(lr["eta_commit"]))
        cmp(f"t{trial} commit request", req_l, req_n)
        cmp(f"t{trial} commit actual", act_l, act_n)
        cmp(f"t{trial} theta_base after commit", leg.model.neurons.theta_base, new.model.neurons.theta_base)
    s = cmp.summary()
    ok = s["n_bitwise_equal"] == s["n_compared"]
    return {"status": DB_PASSED if ok else DB_FAILED, "part": "cpu_synthetic", "trials": int(trials), **s,
            "criterion": ("같은 합성 상태·같은 입력에서 legacy_deadband 의 패킷 (L3 강도·L2 형태)·L2/L3 임시 수정량·잔차·commit 이 "
                          "메뉴 20 경로 (PairedDualFeedbackNetwork.build_packets / _residual_packets / _deliver, TLReceiver, "
                          "TLThresholdController) 와 비트 단위로 같다 (CPU float32, 허용오차 0)."),
            "note_ko": "합성 산술 사례 (작은 대역 객체). 실제 회로 비교는 DB1b."}


def _db_chain_numpy(policy: DeadbandPolicy, *, q0: float, beta: float, kappa: float, error_scale: float,
                    n_areas: int = 3) -> dict[str, Any]:
    """NumPy 공용 연산자만으로 identity 복원기 사슬을 계산한다 (DB2 의 두 번째 경로)."""
    h = np.full((1, 1, 2), 0.5)
    t_top = h.copy()
    t_top[0, 0, 0] -= q0
    gate = np.ones((1, 1), bool)
    valid = gate.copy()
    out: dict[str, Any] = {}
    p = db_top_errors(h, t_top, gate, valid, relay_db=policy.relay_deadband, update_db=policy.update_deadband)
    up = p
    for k in range(n_areas):
        if k > 0:
            p = db_lower_errors(lambda z: z, h, up["target_relay"], up["needs_relay"], h, valid, beta=beta,
                                relay_db=policy.relay_deadband, update_db=policy.update_deadband, lo=0.0, hi=1.0)
        rm = db_residual_math(h, p["target_local"], valid, p["needs_local"], [np.array([0]), np.array([1])],
                              update_db=policy.update_deadband, eps=1e-9)
        d3 = db_l1_delta(rm["intensity"], valid=valid, needs=rm["needs_intensity"], cand=rm["cand_intensity"],
                         confidence=np.ones((1, 1, 1)), update_db=policy.update_deadband, error_scale=error_scale,
                         kappa=kappa)
        out[f"level{k}"] = {"relay": float(np.max(np.abs(p["e_relay"]))), "local": float(np.max(np.abs(p["e_local"]))),
                            "needs_relay": bool(p["needs_relay"].any()), "needs_local": bool(p["needs_local"].any()),
                            "delta_L3_max_abs": float(np.max(np.abs(d3)))}
        up = p
    return out


def _db_check_db2_cpu(dbs: dict[str, Any]) -> dict[str, Any]:
    """DB2: identity 복원기 사슬 0.03 -> 0.006 -> 0.0012 (beta 0.2 고정, float64). 합성 산술 사례."""
    t = require_torch()
    dt = t.float64
    beta, q0 = 0.2, 0.03
    q = [q0, beta * q0, beta * beta * q0]
    areas = ("C1", "C2", "C3")                      # 아래 -> 위 (C3 최상위)
    lr = dbs["learning"]
    kappa, es = float(lr["kappa_L3_mV"]), float(lr["error_scale"])
    h = {a: t.full((1, 1, 2), 0.5, dtype=dt) for a in areas}
    t_top = h["C3"].clone()
    t_top[0, 0, 0] -= q0
    gate = t.ones((1, 1), dtype=t.bool)
    valid = gate.clone()
    groups = {a: [t.tensor([0]), t.tensor([1])] for a in areas}
    res: dict[str, Any] = {}
    ok = True
    for name in DB_COMPARE_POLICIES:
        pol = db_policy(dbs, name)
        stub = db_make_stub("db", areas=areas, n3=2, n2=2, policy=pol, dtype=dt, beta=beta, kappa=kappa,
                            error_scale=es, groups=groups)
        P = DBPairedNetwork.build_packets(stub, {"activities": h, "l2_activities": {}}, t_top, gate, valid,
                                          sample_id=1, episode_id=0, round_id=0)
        Rr = DBPairedNetwork._residual_packets(stub, {"activities": h}, P, sample_id=1, episode_id=0, round_id=1)
        d_int, _ = stub._db_deliver(Rr, "intensity", sample_id=1, R=1)
        row: dict[str, Any] = {"policy": pol.to_dict()}
        exp_ok = True
        for k, a in enumerate(reversed(areas)):                     # 위 -> 아래 (C3, C2, C1)
            relay = float(P[a]["e_relay"].abs().max())
            local = float(P[a]["e_local"].abs().max())
            ids = stub.activity.specs[a].neuron_ids
            dl3 = float(d_int[:, :, ids].abs().max())
            # 기대값: 전달은 위 단계가 살아남았을 때만 내려온다. 살아남음 = 값 > deadband (strict)
            alive_relay = all(q[j] > pol.relay_deadband for j in range(k + 1))
            exp_relay = q[k] if alive_relay else 0.0
            alive_up = all(q[j] > pol.relay_deadband for j in range(k))
            exp_local = q[k] if (alive_up and q[k] > pol.update_deadband) else 0.0
            ok_r = (relay == 0.0) if exp_relay == 0.0 else abs(relay - exp_relay) <= DB_CHECK_TOL_SYNTH
            ok_l = (local == 0.0) if exp_local == 0.0 else abs(local - exp_local) <= DB_CHECK_TOL_SYNTH
            ok_d = (dl3 == 0.0) if exp_local == 0.0 else dl3 > 0.0
            exp_ok = exp_ok and ok_r and ok_l and ok_d
            row[a] = {"relay": relay, "expected_relay": exp_relay, "local": local, "expected_local": exp_local,
                      "delta_L3_mV_max_abs": dl3, "delta_expected_nonzero": exp_local != 0.0,
                      "ok": bool(ok_r and ok_l and ok_d)}
        npc = _db_chain_numpy(pol, q0=q0, beta=beta, kappa=kappa, error_scale=es)
        np_ok = all(abs(npc[f"level{k}"]["relay"] - row[a]["relay"]) <= DB_CHECK_TOL_SYNTH
                    and abs(npc[f"level{k}"]["local"] - row[a]["local"]) <= DB_CHECK_TOL_SYNTH
                    and abs(npc[f"level{k}"]["delta_L3_max_abs"] - row[a]["delta_L3_mV_max_abs"]) <= DB_CHECK_TOL_SYNTH
                    for k, a in enumerate(reversed(areas)))
        row["numpy_core"] = npc
        row["torch_stub_equals_numpy_core"] = bool(np_ok)
        row["ok"] = bool(exp_ok and np_ok)
        ok = ok and row["ok"]
        res[name] = row
    return {"status": DB_PASSED if ok else DB_FAILED, "part": "cpu_synthetic", "chain": q, "beta": beta,
            "tolerance_abs": DB_CHECK_TOL_SYNTH, "policies": res,
            "criterion": ("legacy: 0.006 에서 잘리고 그 아래 전달 0. relay_unfiltered: 0.006·0.0012 전달 (로컬 갱신은 "
                          "update_deadband 로 0 일 수 있음). relay_and_update_unfiltered: 작은 로컬 교정과 L3 증분이 남는다 "
                          "(gate 1, confidence 1). torch 대역 객체와 NumPy 공용 연산자 두 경로가 같은 값."),
            "note_ko": "합성 산술 사례이며 실제 피질 성능 예측이 아니다."}


def _db_check_db3_cpu(dbs: dict[str, Any], seed: int = 31) -> dict[str, Any]:
    """DB3: 0교정. teacher=0 / target=activity / beta=0 에서 교사 유래 패킷·증분·theta 변화 정확히 0."""
    t = require_torch()
    dt = t.float64
    gen = t.Generator().manual_seed(int(seed))
    areas, n3, n2 = ("Z1", "Z2", "Z3"), 4, 3
    D = {u: t.eye(n3, dtype=dt) * 0.3 for u in areas[1:]}          # 기본 복원 잔차가 큰 복원기
    h = {a: 0.2 + 0.6 * t.rand((1, 3, n3), generator=gen, dtype=dt) for a in areas}
    l2 = {a: 0.2 + 0.6 * t.rand((1, 3, n2), generator=gen, dtype=dt) for a in areas}
    t_rand = (h["Z3"] - 0.1 * t.rand((1, 3, n3), generator=gen, dtype=dt)).clamp(0.0, 1.0)
    lr = dbs["learning"]
    res: dict[str, Any] = {}
    ok = True
    base_res = {a: float((h[a] - h[areas[i + 1]] @ D[areas[i + 1]].T).norm(dim=-1).mean())
                for i, a in enumerate(areas[:-1])}
    for name in DB_COMPARE_POLICIES:
        pol = db_policy(dbs, name)
        for case in ("teacher_zero", "target_equals_activity", "beta_zero"):
            theta = t.full((len(areas) * (n3 + n2),), 3.0, dtype=dt)
            stub = db_make_stub("db", areas=areas, n3=n3, n2=n2, decoders=D, policy=pol, dtype=dt,
                                beta=(0.0 if case == "beta_zero" else float(lr["beta"])), kappa=float(lr["kappa_L2_mV"]),
                                error_scale=float(lr["error_scale"]), theta=theta)
            gate = t.zeros((1, 3), dtype=t.bool) if case == "teacher_zero" else t.ones((1, 3), dtype=t.bool)
            t_top = h["Z3"].clone() if case == "target_equals_activity" else t_rand
            valid = t.ones((1, 3), dtype=t.bool)
            P = DBPairedNetwork.build_packets(stub, {"activities": h, "l2_activities": l2}, t_top, gate, valid,
                                              sample_id=1, episode_id=0, round_id=0)
            d_s, _ = stub._db_deliver(P, "shape", sample_id=1, R=1)
            Rr = DBPairedNetwork._residual_packets(stub, {"activities": h}, P, sample_id=1, episode_id=0, round_id=1)
            d_i, _ = stub._db_deliver(Rr, "intensity", sample_id=1, R=1)
            f0 = t.zeros_like(d_s)
            f1, _dm, _raw = stub.controller.apply_round_lazy(f0, d_s)
            f2, _dm, _raw = stub.controller.apply_round_lazy(f1, d_i)
            check = list(areas) if case != "beta_zero" else list(areas[:-1])     # beta=0: 하위 영역만 교사 유래 0
            nz: dict[str, int] = {}
            for a in check:
                p = P[a]
                for k in ("e_pre_deadband", "e_relay", "e_local", "intensity", "pattern"):
                    nz[f"{a}.{k}"] = int((p[k] != 0).sum())
                nz[f"{a}.shape_packet"] = int((p["packet_shape"].correction != 0).sum())
                nz[f"{a}.residual_intensity"] = int((Rr[a]["intensity"] != 0).sum())
                for ch, spec in (("L2", stub.activity.l2_specs[a]), ("L3", stub.activity.specs[a])):
                    nz[f"{a}.theta_fast_{ch}"] = int((f2[:, :, spec.neuron_ids] != 0).sum())
            before = stub.model.neurons.theta_base.clone()
            if case != "beta_zero":
                stub.controller.commit(f2, float(lr["eta_commit"]))
                theta_same = bool(t.equal(before, stub.model.neurons.theta_base))
            else:
                theta_same = None
            c_ok = all(v == 0 for v in nz.values()) and theta_same in (True, None)
            ok = ok and c_ok
            res[f"{name}|{case}"] = {"ok": bool(c_ok), "nonzero_counts": {k: v for k, v in nz.items() if v},
                                     "areas_checked": check, "theta_base_bitwise_unchanged": theta_same}
    return {"status": DB_PASSED if ok else DB_FAILED, "part": "cpu_synthetic", "cases": res,
            "base_restore_residual_norm": base_res,
            "criterion": ("세 정책 x (teacher=0, target=activity, beta=0) 에서 교사 유래 e_pre/e_relay/e_local/분해/패킷/"
                          "theta_fast 가 정확히 0, commit 뒤 theta_base 비트 불변 (beta=0 은 최상위의 직접 교사 교정이 남으므로 "
                          "하위 영역만). 기본 복원 잔차 h_L - D(h_U) 가 커도 교정에 섞이지 않는다.")}


def _db_check_db4_db5(dbs: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    """DB4 부호·소거·경계, DB5 soft deadband 크기 (NumPy 공용 연산자 + torch 같은 함수)."""
    t = require_torch()
    lr = dbs["learning"]
    kappa, es = float(lr["kappa_L3_mV"]), float(lr["error_scale"])
    d = float(dbs["deadband"]["legacy_deadband"])
    rows4: dict[str, Any] = {}

    def both(fn: Callable[[Any], Any], x: list[float]) -> tuple[np.ndarray, np.ndarray]:
        a = np.asarray(fn(np.asarray(x, np.float64)))
        b = fn(t.tensor(x, dtype=t.float64)).numpy()
        return a, b
    q = 0.05
    for dd in (d, 0.0):
        a, b = both(lambda z: correction_needed(z, dd), [[q, -q]])
        rows4[f"cancel_[+q,-q]_d={dd}"] = {"needs": bool(a[0]), "torch_same": bool(a[0] == b[0]), "sum": 0.0,
                                           "ok": bool(a[0]) and bool(a[0] == b[0])}
    a, b = both(lambda z: correction_needed(z, 0.0), [[1e-7, 0.0]])
    rows4["d=0_tiny_nonzero"] = {"needs": bool(a[0]), "ok": bool(a[0]) and bool(b[0])}
    a, b = both(lambda z: correction_needed(z, 0.0), [[0.0, -0.0]])
    rows4["d=0_exact_zero"] = {"needs": bool(a[0]), "ok": (not bool(a[0])) and (not bool(b[0]))}
    xs = [d, -d, d * (1 + 1e-9), d * (1 - 1e-9), 0.0, -0.0]
    hn, ht = both(lambda z: db_hard(z, d), xs)
    sn, stt = both(lambda z: db_soft(z, d), xs)
    rows4["hard_boundary"] = {"x": xs, "H_d": hn.tolist(),
                              "ok": bool(hn[0] == 0 and hn[1] == 0 and hn[2] != 0 and hn[3] == 0 and hn[4] == 0
                                         and hn[5] == 0 and np.array_equal(hn, ht))}
    rows4["soft_boundary"] = {"x": xs, "S_d": sn.tolist(),
                              "ok": bool(sn[0] == 0 and sn[1] == 0 and sn[2] > 0 and sn[3] == 0 and sn[4] == 0
                                         and np.array_equal(sn, stt))}
    h0, _ = both(lambda z: db_hard(z, 0.0), [0.0, -0.0, 1e-30, -1e-30])
    rows4["hard_d0_keeps_tiny_drops_zero"] = {"H_0": h0.tolist(),
                                              "ok": bool(h0[0] == 0 and h0[1] == 0 and h0[2] == 1e-30 and h0[3] == -1e-30)}
    sgn: dict[str, float] = {}
    for label, r, dd in (("deficit_r=-0.05", -0.05, d), ("excess_r=+0.05", 0.05, d), ("deficit_d0_r=-1e-4", -1e-4, 0.0),
                         ("zero_r=0", 0.0, 0.0)):
        sgn[label] = float(tl_threshold_delta(np.asarray([r]), deadband=dd, error_scale=es, kappa=kappa)[0])
    rows4["delta_sign"] = {"values_mV": sgn, "ok": sgn["deficit_r=-0.05"] < 0 < sgn["excess_r=+0.05"]
                           and sgn["deficit_d0_r=-1e-4"] < 0 and sgn["zero_r=0"] == 0.0,
                           "convention_ko": "e = 실제 - 목표. e<0 부족 -> 임계값 하향 (delta<0), e>0 과잉 -> 상향"}
    ok4 = all(v["ok"] for v in rows4.values())
    db4 = {"status": DB_PASSED if ok4 else DB_FAILED, "part": "cpu_synthetic", "cases": rows4, "deadband": d,
           "criterion": ("[+q,-q] 는 합이 0 이어도 교정 필요. d=0 에서 작은 비영은 유지, 정확한 0 은 0. |e| = d 는 제거 "
                         "(strict >). 부족은 임계값 하향, 과잉은 상향. NumPy 와 torch 가 같은 값.")}
    r = 0.03
    s002 = float(db_soft(np.asarray([r]), 0.02)[0])
    s0 = float(db_soft(np.asarray([r]), 0.0)[0])
    s002_t = float(db_soft(t.tensor([r], dtype=t.float64), 0.02)[0])
    d_old = float(tl_threshold_delta(np.asarray([r]), deadband=0.02, error_scale=es, kappa=kappa)[0])
    d_new = float(tl_threshold_delta(np.asarray([r]), deadband=0.0, error_scale=es, kappa=kappa)[0])
    grid = np.linspace(-0.05, 0.05, 101)
    n_old = int((tl_threshold_delta(grid, deadband=0.02, error_scale=es, kappa=kappa) != 0).sum())
    n_new = int((tl_threshold_delta(grid, deadband=0.0, error_scale=es, kappa=kappa) != 0).sum())
    ok5 = abs(s002 - 0.01) <= 1e-15 and s0 == 0.03 and abs(s002_t - s002) <= 1e-15
    db5 = {"status": DB_PASSED if ok5 else DB_FAILED, "part": "cpu_synthetic",
           "S_0.02(0.03)": s002, "S_0(0.03)": s0, "torch_S_0.02(0.03)": s002_t,
           "delta_mV_d0.02": d_old, "delta_mV_d0": d_new, "delta_ratio_d0_over_d0.02": (d_new / d_old) if d_old else None,
           "grid_[-0.05,0.05]_101": {"n_nonzero_delta_d0.02": n_old, "n_nonzero_delta_d0": n_new},
           "kappa_mV": kappa, "error_scale": es,
           "criterion": "S_0.02(0.03)=0.01 (허용 1e-15), S_0(0.03)=0.03 (정확히)",
           "note_ko": ("deadband 를 0 으로 하면 수정 대상 수(격자에서 비영 증분 수)뿐 아니라 기존 대상의 수정 강도도 바뀐다 "
                       "(같은 r=0.03 에서 증분 비율 위 값). 개선이 보여도 방향 정보 개선이라고 단정하지 않는다.")}
    return db4, db5


def _db_check_db6_cpu(dbs: dict[str, Any]) -> dict[str, Any]:
    """DB6: 같은 logits·활동·목표에서 모든 정책의 teacher gate 가 같다 (tolerance 는 relay/update 와 무관)."""
    t = require_torch()
    tol = float(dbs["deadband"]["teacher_tolerance"])
    pols = [db_policy(dbs, c) for c in DB_CONDITION_TABLE]
    tols = {p.name: p.teacher_tolerance for p in pols}
    wrong = np.array([[True, False, False, False, False]])
    h = np.full((1, 5, 3), 0.5)
    tt = h.copy()
    tt[0, 1, 0] -= tol * 1.5
    h[0, 2, 0] = 0.0
    tt[0, 2, 0] = -tol                                  # |h - t| = tol 정확히 (경계, 제외)
    tt[0, 3, 0] -= tol * 0.5
    tt[0, 4, 1] += tol * 3
    gates = {p.name: db_teacher_gate(wrong, h, tt, rule="argmax_wrong_or_tolerance", tolerance=p.teacher_tolerance)[0]
             .tolist() for p in pols}
    same_np = len({json.dumps(v) for v in gates.values()}) == 1
    comp = FrontalComparator({}, ["c0", "c1", "c2"], t.device("cpu"), t.float64)
    logits = t.tensor([[[2.0, 0.0, 0.0], [0.0, 2.0, 0.0], [0.0, 0.0, 2.0], [2.0, 0.0, 0.0], [0.0, 2.0, 0.0]]],
                      dtype=t.float64)
    labels = t.tensor([1, 1, 2, 0, 1])
    free = {"logits": logits, "h_IT": t.tensor(h)}
    tg: dict[str, list[Any]] = {}
    for p in pols:
        stub = db_make_stub("db", policy=p, dtype=t.float64)
        stub.comparator = comp
        g, _info = DBPairedNetwork.teacher_gate(stub, free, labels, t.tensor(tt))
        tg[p.name] = g.tolist()
    same_t = len({json.dumps(v) for v in tg.values()}) == 1
    tol_same = len(set(tols.values())) == 1 and next(iter(tols.values())) == tol
    ok = same_np and same_t and tol_same
    return {"status": DB_PASSED if ok else DB_FAILED, "part": "cpu_synthetic", "teacher_tolerance_by_policy": tols,
            "gates_numpy": gates, "gates_network_method": tg, "expected_outside_tolerance_ko": "표본 1, 4 (|e|>tol), 2 는 |e|=tol 로 제외",
            "criterion": "모든 조건 정책에서 teacher gate 가 같고 teacher_tolerance 가 설정값 하나다 (relay/update 와 무관)."}


def _db_check_db7_cpu(dbs: dict[str, Any]) -> dict[str, Any]:
    """DB7: 잔차는 새 활동 vs target_local, 별칭 오염·오래된 패킷·중복 적용·숨은 전역 deadband 없음."""
    t = require_torch()
    dt = t.float64
    areas = ("P1", "P2")
    tt = float(dbs["deadband"]["teacher_tolerance"])
    probe = DeadbandPolicy(name="db7_probe_relay0.05_update0", teacher_tolerance=tt, relay_deadband=0.05,
                           update_deadband=0.0)
    h = {a: t.full((1, 1, 2), 0.5, dtype=dt) for a in areas}
    t_top = h["P2"].clone()
    t_top[0, 0, 0] -= 0.03
    gate = t.ones((1, 1), dtype=t.bool)
    valid = gate.clone()
    stub = db_make_stub("db", areas=areas, n3=2, n2=2, policy=probe, dtype=dt,
                        groups={a: [t.tensor([0]), t.tensor([1])] for a in areas})
    P = DBPairedNetwork.build_packets(stub, {"activities": h, "l2_activities": {}}, t_top, gate, valid, sample_id=1,
                                      episode_id=0, round_id=0)
    h_new = {a: h[a] + 0.01 for a in areas}
    Rr = DBPairedNetwork._residual_packets(stub, {"activities": h_new}, P, sample_id=1, episode_id=0, round_id=1)
    top = "P2"
    exp_local = h_new[top] - P[top]["target_local"]
    wrong_relay = h_new[top] - P[top]["target_relay"]
    res_ok = bool(t.equal(Rr[top]["e_residual"], exp_local)) and not bool(t.equal(Rr[top]["e_residual"], wrong_relay))
    alias = {}
    for a in areas:
        p = P[a]
        alias[a] = {"target_relay_vs_local_distinct_storage": p["target_relay"].data_ptr() != p["target_local"].data_ptr(),
                    "e_relay_vs_local_distinct_storage": p["e_relay"].data_ptr() != p["e_local"].data_ptr()}
    tl_before = P[top]["target_local"].clone()
    P[top]["target_relay"].add_(1.0)                                  # 전달용 버퍼를 바꿔도 로컬 목표는 그대로
    alias_inplace_ok = bool(t.equal(P[top]["target_local"], tl_before))
    P[top]["target_relay"].sub_(1.0)
    stub2 = db_make_stub("db", areas=areas, n3=2, n2=2, policy=probe, dtype=dt)
    P2 = DBPairedNetwork.build_packets(stub2, {"activities": h, "l2_activities": {}}, t_top, gate, valid, sample_id=1,
                                       episode_id=0, round_id=0)
    _d1, rec1 = stub2._db_deliver(P2, "shape", sample_id=1, R=1)
    _d2, rec2 = stub2._db_deliver(P2, "shape", sample_id=1, R=1)        # 같은 패킷 다시 전달 -> 거부
    stale_ok = all(r.get("accepted") for r in rec1.values()) and all(not r.get("accepted") for r in rec2.values())
    rx = stub2.receivers[top]
    try:
        rx.drive("shape", kappa=0.25, error_scale=0.1, attention=None)
        consumed_ok = False
    except RuntimeError:
        consumed_ok = True                                             # consume 뒤 버퍼 없음 -> 재적용 불가
    try:
        float(stub2.deadband)
        sentinel_ok = False
    except RuntimeError:
        sentinel_ok = True
    odd = DeadbandPolicy(name="db7_probe_odd", teacher_tolerance=tt, relay_deadband=0.0071, update_deadband=0.0137)
    gen = t.Generator().manual_seed(7)
    h3 = {a: t.rand((1, 4, 2), generator=gen, dtype=dt) for a in areas}
    t3 = (h3[top] + (t.rand((1, 4, 2), generator=gen, dtype=dt) - 0.5) * 0.06).clamp(0.0, 1.0)
    stub3 = db_make_stub("db", areas=areas, n3=2, n2=2, policy=odd, dtype=dt)
    P3 = DBPairedNetwork.build_packets(stub3, {"activities": h3, "l2_activities": {}}, t3, t.ones((1, 4), dtype=t.bool),
                                       t.ones((1, 4), dtype=t.bool), sample_id=1, episode_id=0, round_id=0)
    cons = True
    for a in areas:
        p = P3[a]
        cons &= bool(t.equal(p["e_relay"], p["e_pre_deadband"] * (p["e_pre_deadband"].abs() > 0.0071).to(dt)))
        cons &= bool(t.equal(p["e_local"], p["e_pre_deadband"] * (p["e_pre_deadband"].abs() > 0.0137).to(dt)))
        cons &= bool(t.equal(p["packet_intensity"].candidate_mask,
                             (p["packet_intensity"].correction.abs() > 0.0137).to(dt)))
        if p["packet_shape"] is not None:
            cons &= bool(t.equal(p["packet_shape"].candidate_mask, (p["packet_shape"].correction.abs() > 0.0137).to(dt)))
        cons &= stub3.receivers[a].deadband == 0.0137
    ok = (res_ok and all(all(v.values()) for v in alias.values()) and alias_inplace_ok and stale_ok and consumed_ok
          and sentinel_ok and cons)
    return {"status": DB_PASSED if ok else DB_FAILED, "part": "cpu_synthetic",
            "residual_uses_target_local": res_ok, "alias_storage": alias, "alias_inplace_isolated": alias_inplace_ok,
            "stale_packet_rejected": stale_ok, "consumed_packet_not_reapplied": consumed_ok,
            "global_deadband_blocked": sentinel_ok, "odd_policy_consistent_all_paths": bool(cons),
            "criterion": ("relay 0.05 / update 0 의 검사용 정책에서 잔차 = h_new - target_local (target_relay 아님). target_relay "
                          "와 target_local 은 별도 저장소. 같은 패킷 재전달 거부, 소비 뒤 재적용 불가, 전역 deadband 접근 차단, "
                          "relay 0.0071 / update 0.0137 정책이 relay·local·candidate·L1 에 일관되게 쓰임.")}


def db_cpu_checks(dbs: dict[str, Any]) -> dict[str, Any]:
    """CPU 합성 검사 (회로 없음, 결정론). 사용자 PC 의 torch CPU 로 실행한다."""
    out: dict[str, Any] = {}
    for key, fn in (("DB1a_cpu_synthetic", lambda: _db_check_db1_cpu(dbs)), ("DB2", lambda: _db_check_db2_cpu(dbs)),
                    ("DB3", lambda: _db_check_db3_cpu(dbs)), ("DB6a_cpu_synthetic", lambda: _db_check_db6_cpu(dbs)),
                    ("DB7", lambda: _db_check_db7_cpu(dbs))):
        g = lat_guard(key, fn)
        out[key] = g["result"] if g["status"] == "completed" else {
            "status": DB_FAILED, "error": {k: v for k, v in g.items() if k != "result"}}
    g = lat_guard("DB4_DB5", lambda: _db_check_db4_db5(dbs))
    if g["status"] == "completed":
        out["DB4"], out["DB5"] = g["result"]
    else:
        err = {"status": DB_FAILED, "error": {k: v for k, v in g.items() if k != "result"}}
        out["DB4"], out["DB5"] = err, dict(err)
    return out


class _DBChecksMixin:
    """DeadbandAblation 의 회로 검사 (DB1b·DB6b·DB8~DB11) 와 최종 holdout (메뉴 21-7)."""

    # ------------------------------------------------------------------ 보조
    def _db_snapshot(self) -> dict[str, Any]:
        t = require_torch()
        net = self.net
        return {**self._purity(), "state_version": net._state_version, "policy": net.policy.name,
                "receivers": {a: [dict(rx.last_version), all(v is None for v in rx.buffers.values()),
                                  dict(rx.accepted), len(rx.rejected)] for a, rx in net.receivers.items()},
                "fixed_unchanged": self.model.verify_fixed_unchanged()["unchanged"],
                "theta_trainable": tensor_hash(self.model.neurons.theta_trainable.to(t.uint8)),
                "classifier": net.classifier.signature(),
                "decoders": {u: d.signature() for u, d in net.decoders.items()},
                "l3_to_l2": {a: d.signature() for a, d in net.l3_to_l2.items()},
                "prototypes": net.targets.signature()}

    def _check_batch(self) -> tuple[Any, Any]:
        bs = int(self.pre["batch_size"])
        images, labels = self.runner._batch_tensor(list(self.sel["train"])[:bs])
        x, _ = self.model.encode_batch(images)
        return x, labels

    def _tl_ref_settings(self) -> dict[str, Any]:
        tl = copy.deepcopy(self.tls)
        tl["learning"]["deadband"] = float(self.dbs["deadband"]["legacy_deadband"])
        return tl

    # ------------------------------------------------------------------ DB1b
    def _db1_circuit(self, x: Any, labels: Any) -> dict[str, Any]:
        """같은 모델·준비 상태·theta·입력 사건에서 메뉴 20 local_all_L23 (TLPairedNetwork) vs legacy_deadband."""
        t = require_torch()
        m, net = self.model, self.net
        a, eng = m.neurons, m.engine
        if float(self.dbs["deadband"]["teacher_tolerance"]) != float(self.dbs["deadband"]["legacy_deadband"]):
            return {"status": DB_NOT_RUN, "part": "circuit",
                    "reason_ko": ("teacher_tolerance 와 legacy deadband 가 달라 메뉴 20 경로(한 deadband 를 교사 gate 에도 씀)와 "
                                  "같은 계산이 아니다. 두 값을 같게 둔 설정에서만 동등 비교를 한다.")}
        mask = self.db_masks["legacy_deadband"]
        ref = TLPairedNetwork(self.runner.cfg, m, self.runner.seeds, tl=self._tl_ref_settings(),
                              condition="local_all_L23", learn_mask=mask, obs_steps=self.obs_steps,
                              stim_steps=self.stim_steps, window_steps=self.window, gate_ref=self.ff_gate)
        ref_cal = PairedCalibrationRunner(self.runner.cfg, ref, self.runner.seeds, log=self.runner.recorder.log)
        ref_cal.load_state_dict(copy.deepcopy(self.prep_snapshot))
        prep_same = ref_cal.signatures() == self.prep_sig
        ref.set_condition("local_all_L23", mask)
        cap: dict[str, dict[str, Any]] = {k: {"packets": {}, "residual": {}, "apply": [], "commit": None}
                                          for k in ("tl", "db")}

        def wrap(store: dict[str, Any], key: str, fn: Callable[..., Any]) -> Callable[..., Any]:
            def w(*args: Any, **kw: Any) -> Any:
                out = fn(*args, **kw)
                store[key][kw.get("round_id")] = out
                return out
            return w
        ref.build_packets = wrap(cap["tl"], "packets", ref.build_packets)            # type: ignore[method-assign]
        ref._residual_packets = wrap(cap["tl"], "residual", ref._residual_packets)   # type: ignore[method-assign]
        net.build_packets = wrap(cap["db"], "packets", net.build_packets)            # type: ignore[method-assign]
        net._residual_packets = wrap(cap["db"], "residual", net._residual_packets)   # type: ignore[method-assign]
        o_ap, o_cm = ref.controller.apply_round, ref.controller.commit
        n_ap, n_cm = net.controller.apply_round_lazy, net.controller.commit

        def ap_t(tf: Any, d: Any) -> Any:
            nxt, rec = o_ap(tf, d)
            cap["tl"]["apply"].append((d.detach().clone(), nxt.detach().clone()))
            return nxt, rec

        def ap_d(tf: Any, d: Any) -> Any:
            nxt, dm, raw = n_ap(tf, d)
            cap["db"]["apply"].append((d.detach().clone(), nxt.detach().clone()))
            return nxt, dm, raw

        def cm_t(tf: Any, eta: float) -> Any:
            rec, req, act = o_cm(tf, eta)
            cap["tl"]["commit"] = (req.detach().clone(), act.detach().clone())
            return rec, req, act

        def cm_d(tf: Any, eta: float) -> Any:
            rec, req, act = n_cm(tf, eta)
            cap["db"]["commit"] = (req.detach().clone(), act.detach().clone())
            return rec, req, act
        ref.controller.apply_round, ref.controller.commit = ap_t, cm_t              # type: ignore[method-assign]
        net.controller.apply_round_lazy, net.controller.commit = ap_d, cm_d          # type: ignore[method-assign]
        det0 = eng.deterministic
        try:
            eng.deterministic = True
            a.theta_base.copy_(self.theta_init)
            ep_t = ref.tl_episode(x, labels, sample_id=7, episode_id=0, drive_key=("input_noise", 4242), train=True)
            th_t = a.theta_base.detach().clone()
            a.theta_base.copy_(self.theta_init)
            self.cal.load_state_dict(copy.deepcopy(self.prep_snapshot))
            net.set_policy(self.policies["legacy_deadband"], mask)
            ep_d = net.db_episode(x, labels, sample_id=7, episode_id=0, drive_key=("input_noise", 4242), train=True,
                                  compare_policies=None, detail="summary")
            th_d = a.theta_base.detach().clone()
        finally:
            eng.deterministic = det0
            for nm in ("build_packets", "_residual_packets"):
                net.__dict__.pop(nm, None)
            net.controller.__dict__.pop("apply_round_lazy", None)
            net.controller.__dict__.pop("commit", None)
            a.theta_base.copy_(self.theta_init)
            m.neurons.theta_trainable = mask.clone()
        cmp = _DBCmp(tol=DB_CHECK_TOL_ABS)
        for rid in sorted(k for k in cap["tl"]["packets"] if k is not None and k >= 0):
            pl, pn = cap["tl"]["packets"][rid], cap["db"]["packets"].get(rid)
            if pn is None:
                cmp(f"r{rid} packets 존재", t.zeros(1), None)
                continue
            for area in pl:
                _db_cmp_packets(cmp, f"r{rid} {area}", pl[area], pn[area])
        for rid in sorted(cap["tl"]["residual"]):
            rl, rn = cap["tl"]["residual"][rid], cap["db"]["residual"].get(rid)
            for area in rl:
                cmp(f"res{rid} {area} e", rl[area]["e_total_after_shape"], None if rn is None else rn[area]["e_residual"])
                if rn is not None:
                    for f_ in ("correction", "candidate_mask", "needs_correction", "confidence"):
                        cmp(f"res{rid} {area} packet.{f_}", getattr(rl[area]["packet_intensity"], f_),
                            getattr(rn[area]["packet_intensity"], f_))
        for i, ((dl, nl), (dn, nn)) in enumerate(zip(cap["tl"]["apply"], cap["db"]["apply"])):
            cmp(f"apply{i} delta (L{2 if i % 2 == 0 else 3})", dl, dn)
            cmp(f"apply{i} theta_fast", nl, nn)
        if cap["tl"]["commit"] is not None and cap["db"]["commit"] is not None:
            cmp("commit request", cap["tl"]["commit"][0], cap["db"]["commit"][0])
            cmp("commit actual", cap["tl"]["commit"][1], cap["db"]["commit"][1])
        cmp("theta_base after batch", th_t, th_d)
        s = cmp.summary()
        n_apply = (len(cap["tl"]["apply"]), len(cap["db"]["apply"]))
        ok = prep_same and s["n_within_tolerance"] == s["n_compared"] and n_apply[0] == n_apply[1] == 2 * int(net.K)
        post = {"tl": ep_t["post_update_free"]["cross_entropy"], "db": ep_d["post_update_free"]["cross_entropy"]}
        return {"status": DB_PASSED if ok else DB_FAILED, "part": "circuit", "preparation_signatures_equal": prep_same,
                "deterministic_engine_used": True, "n_apply_rounds": list(n_apply), **s,
                "bitwise_all": s["n_bitwise_equal"] == s["n_compared"],
                "post_update_free_ce": post, "forward_calls": [ep_t["forward_calls"], ep_d["forward_calls"]],
                "criterion": (f"같은 모델·준비 스냅샷·theta_init·배치·입력 사건 (결정론 합산)에서 메뉴 20 TLPairedNetwork.tl_episode "
                              f"(local_all_L23) 와 DBPairedNetwork.db_episode (legacy_deadband) 의 라운드별 패킷·잔차·L2/L3 "
                              f"임시 수정량·commit·theta_base 가 허용오차 {DB_CHECK_TOL_ABS} 안 (비트 일치 여부 따로 기록)."),
                "note_ko": "같은 장치에서 두 경로를 차례로 실행했다. CPU 와 CUDA 사이 비교가 아니다."}

    # ------------------------------------------------------------------ DB6b
    def _db6_circuit(self, x: Any, labels: Any) -> dict[str, Any]:
        t = require_torch()
        net = self.net
        self.model.neurons.theta_base.copy_(self.theta_init)
        drive = net.episode_drive(x, ("input_noise", 66))
        free = net.settle_chain(None, None, None, {"drive_key": ("input_noise", 66)}, drive, None, self.obs_steps)
        sel = net.targets.select_prototype(free["h_IT"], labels)
        saved = net.policy
        gates = {}
        try:
            for c in self.db_conditions:
                net.policy = self.policies[c]
                g, _ = net.teacher_gate(free, labels, sel["target"])
                gates[c] = g.detach().to("cpu")
        finally:
            net.policy = saved
        first = next(iter(gates.values()))
        same = all(bool(t.equal(first, g)) for g in gates.values())
        return {"status": DB_PASSED if same else DB_FAILED, "part": "circuit",
                "gate_fraction": float(first.to(t.float64).mean()), "conditions": list(gates),
                "criterion": "실제 free 상태 하나에서 모든 조건 정책의 teacher gate 가 같다."}

    # ------------------------------------------------------------------ DB8
    def _db8_circuit(self, x: Any, labels: Any) -> dict[str, Any]:
        t = require_torch()
        m, net = self.model, self.net
        a = m.neurons
        lo, hi = float(self.dbs["theta"]["min_mV"]), float(self.dbs["theta"]["max_mV"])
        fb = float(self.dbs["theta"]["fast_bound_mV"])
        per: dict[str, Any] = {}
        ok = True
        for cond in self.db_conditions:
            pol, mask = self.policies[cond], self.db_masks[cond]
            a.theta_base.copy_(self.theta_init)
            net.set_policy(pol, mask)
            n0 = net.controller.n_commits
            ep = net.db_episode(x, labels, sample_id=88, episode_id=0, drive_key=("input_noise", 88), train=True,
                                detail="summary")
            th = a.theta_base
            r = {"outside_mask_unchanged": bool(t.equal(th[~mask], self.theta_init[~mask])),
                 "within_range": bool(((th[mask] >= lo) & (th[mask] <= hi)).all()),
                 "fast_within_bound": ep["theta_fast_final_max_abs"] <= fb + 1e-6,
                 "n_commits": int(net.controller.n_commits - n0), "expected_commits": 0 if pol.freeze else 1,
                 "post_theta_fast_zero": ep["post_theta_fast_zero"], "unchanged_exactly": bool(t.equal(th, self.theta_init)),
                 "theta_fast_final_norm": ep["theta_fast_final_norm"], "forward_calls": ep["forward_calls"]}
            must_zero = pol.freeze or pol.zero_teacher
            r["ok"] = bool(r["outside_mask_unchanged"] and r["within_range"] and r["fast_within_bound"]
                           and r["n_commits"] == r["expected_commits"] and r["post_theta_fast_zero"]
                           and r["forward_calls"] == 2 * int(net.K) + 2
                           and (not must_zero or (r["unchanged_exactly"] and r["theta_fast_final_norm"] == 0.0)))
            ok = ok and r["ok"]
            per[cond] = r
        a.theta_base.copy_(self.theta_init)
        before = a.theta_base.detach().clone()
        gen = t.Generator(device="cpu").manual_seed(8)
        fast = (t.rand((1, 3, a.n), generator=gen) - 0.5).to(m.device, m.dtype) * 2.0
        mask = self.db_masks["relay_and_update_unfiltered"]
        net.set_policy(self.policies["relay_and_update_unfiltered"], mask)
        _rec, _req, _act = net.controller.commit(fast, 1.0)
        rc = {"outside_mask_unchanged": bool(t.equal(a.theta_base[~mask], before[~mask])),
              "inside_mask_changed": bool((a.theta_base[mask] != before[mask]).any()),
              "L4_unchanged": bool(t.equal(a.theta_base[self.l4_mask], before[self.l4_mask])),
              "inhibitory_unchanged": bool(t.equal(a.theta_base[a.dale < 0], before[a.dale < 0]))}
        a.theta_base.copy_(self.theta_init)
        ok = ok and all(rc.values())
        return {"status": DB_PASSED if ok else DB_FAILED, "part": "circuit", "per_condition": per,
                "random_fast_commit": rc,
                "criterion": ("조건마다 1배치: 마스크 밖 비트 불변, theta 범위 [min,max], |theta_fast| <= fast_bound, commit "
                              "1회 (frozen 0), frozen/zero_teacher 는 theta·theta_fast 0 변화, settle 2K+2, post theta_fast 0. "
                              "무작위 theta_fast commit 에서도 마스크 밖·L4·억제성 불변.")}

    # ------------------------------------------------------------------ DB9
    def _db9_circuit(self, x: Any, labels: Any) -> dict[str, Any]:
        t = require_torch()
        m, net = self.model, self.net
        a, eng = m.neurons, m.engine
        a.theta_base.copy_(self.theta_init)
        net.set_policy(self.policies["relay_and_update_unfiltered"], self.db_masks["relay_and_update_unfiltered"])
        drive = net.episode_drive(x, ("input_noise", 99))
        free = net.settle_chain(None, None, None, {"drive_key": ("input_noise", 99)}, drive, None, self.obs_steps)
        sel = net.targets.select_prototype(free["h_IT"], labels)
        valid = t.isfinite(sel["target"]).all(dim=-1)
        g, _ = net.teacher_gate(free, labels, sel["target"])
        g = g & valid
        t_it = net.comparator.it_target(free["h_IT"], g.to(net.dtype), sel["target"])
        copy_state = {"activities": {k: v.detach().clone() for k, v in free["activities"].items()},
                      "l2_activities": {k: v.detach().clone() for k, v in free.get("l2_activities", {}).items()}}
        snap0 = self._db_snapshot()
        acc = DBStatAcc(True)
        net.policy_compare(copy_state, t_it, g, valid, self.compare_policies, acc, meta={"check": "DB9"})
        rows = acc.finish()
        snap1 = self._db_snapshot()
        diff = sorted(k for k in snap0 if snap0[k] != snap1[k])
        det0 = eng.deterministic
        try:
            eng.deterministic = True
            res = {}
            for tag, cmpp, detail in (("logging_on", self.compare_policies, "full"), ("logging_off", None, "summary")):
                a.theta_base.copy_(self.theta_init)
                ep = net.db_episode(x, labels, sample_id=99, episode_id=0, drive_key=("input_noise", 99), train=True,
                                    compare_policies=cmpp, detail=detail)
                res[tag] = {"theta": a.theta_base.detach().clone(), "fast_norm": ep["theta_fast_final_norm"],
                            "post_ce": ep["post_update_free"]["cross_entropy"], "n_flow_rows": len(ep["flow"])}
        finally:
            eng.deterministic = det0
            a.theta_base.copy_(self.theta_init)
        log_same = (bool(t.equal(res["logging_on"]["theta"], res["logging_off"]["theta"]))
                    and res["logging_on"]["fast_norm"] == res["logging_off"]["fast_norm"]
                    and res["logging_on"]["post_ce"] == res["logging_off"]["post_ce"])
        ok = not diff and log_same
        return {"status": DB_PASSED if ok else DB_FAILED, "part": "circuit", "policy_compare_rows": len(rows),
                "snapshot_keys_changed": diff, "logging_on_off_identical": log_same,
                "flow_rows": {k: v["n_flow_rows"] for k, v in res.items()},
                "criterion": ("분리된 활동 복사본에서 세 정책 패킷만 계산해도 theta·준비 모듈(C/D/T/프로토타입)·난수·수신기 버퍼·"
                              "state_version·고정 파라미터가 그대로. 기록 ON(상세+정책 비교) / OFF(요약) 에서 학습 결과가 "
                              "비트 단위로 같다 (결정론 합산).")}

    # ------------------------------------------------------------------ DB10
    def _db10_circuit(self, x: Any) -> dict[str, Any]:
        t = require_torch()
        import inspect as _inspect
        net, eng = self.net, self.model.engine
        gate = self.ff_gate.detach().to("cpu").numpy() > 0
        same_mask = bool(np.array_equal(gate, np.asarray(self.audit["allowed"])))
        d = net.episode_drive(x, ("input_noise", 10))
        tail = float(d.values[self.stim_steps:].abs().max()) if self.obs_steps > self.stim_steps else 0.0
        params = list(_inspect.signature(self._predict_drive).parameters)
        leak_ok = not any(p in ("labels", "label", "y", "target", "targets", "packets", "prototype") for p in params)
        try:
            net.predict(t.zeros((1, 3, 8, 8), dtype=self.model.dtype, device=self.model.device), {"labels": [0]})
            leak_ok = False
        except Exception:                                           # noqa: BLE001
            pass
        self.model.neurons.theta_base.copy_(self.theta_init)
        bs = int(self.pre["batch_size"])
        ev = self._evaluate(list(self.sel["dev"])[:bs], split="dev", cond="(check)", phase="purity")
        self._latency_rows.extend(ev.pop("latency", []))
        win_ok = tuple(self.window) == (int(math.ceil(64.0 / self.dt - 1e-9)), int(math.ceil(160.0 / self.dt - 1e-9)))
        ok = (same_mask and eng.edge_gate is self.ff_gate and self.audit["C2_cycles"]["status"] == PFF_PASSED
              and net.path_log["gate_identity_violations"] == 0 and tail == 0.0 and leak_ok and win_ok
              and ev["purity_preserved"])
        return {"status": DB_PASSED if ok else DB_FAILED, "part": "circuit", "gate_matches_audit": same_mask,
                "engine_gate_is_ff_mask": eng.edge_gate is self.ff_gate, "dag": self.audit["C2_cycles"]["status"],
                "gate_violations": net.path_log["gate_identity_violations"], "episode_drive_tail_max_abs": tail,
                "predict_params": params, "label_free_predict": leak_ok, "readout_window_steps": list(self.window),
                "eval_purity": ev["purity_detail"],
                "criterion": "같은 F0r 마스크·DAG, 외부 입력 160 ms 뒤 0, 판독 창 [64,160), 라벨 없는 predict, 평가 전후 상태 불변."}

    # ------------------------------------------------------------------ DB11
    def _db11_circuit(self) -> dict[str, Any]:
        t = require_torch()
        m = self.model
        a, eng = m.neurons, m.engine
        cond = "relay_and_update_unfiltered"
        det0 = eng.deterministic
        try:
            eng.deterministic = True
            self.resume_from = None
            r1 = self._train_condition(cond, stop_after_batches=2)
            th_a = a.theta_base.detach().clone()
            if len(r1["rows"]) < 2:
                return {"status": DB_NOT_RUN, "part": "circuit", "reason_ko": "train 배치가 2개 미만이라 재개 검사를 할 수 없다"}
            self._train_condition(cond, stop_after_batches=1)
            st = self._load_ckpt(cond, self.run_dir)
            a.theta_base.copy_(self.theta_init)
            r3 = self._train_condition(cond, stop_after_batches=1, resume=st)
            th_b = a.theta_base.detach().clone()
        finally:
            eng.deterministic = det0
            a.theta_base.copy_(self.theta_init)
        same = bool(t.equal(th_a, th_b))
        md = float((th_a.to(t.float64) - th_b.to(t.float64)).abs().max())
        meta = read_json(self.run_dir / "checkpoints" / safe_name(cond) / "latest.json")
        refuse: dict[str, bool] = {}
        for key, val in (("policy_key", "tampered"), ("settings_sha256", "tampered"),
                         ("preparation_signatures", {"tampered": "x"}), ("normalization_sha256", "tampered"),
                         ("data_digest", "tampered"), ("code_sha256", "tampered")):
            m2 = dict(meta)
            m2[key] = val
            refuse[key] = bool(self._db_ckpt_issues(m2, cond))
        if self.allow_code_mismatch:
            refuse.pop("code_sha256", None)
        ok = same and len(r3["rows"]) == 2 and all(refuse.values())
        return {"status": DB_PASSED if ok else DB_FAILED, "part": "circuit", "condition": cond,
                "theta_bitwise_equal": same, "theta_max_abs_diff_mV": md, "rows_after_resume": len(r3["rows"]),
                "mismatch_refused": refuse, "device": str(m.device),
                "criterion": ("2배치 연속 = 1배치 + 체크포인트 + 재개 1배치 (theta_base 비트 일치, 중복 commit 없음). 정책·설정·준비·"
                              "정규화·자료·코드 해시가 다르면 이어 붙이지 않는다."),
                "note_ko": ("같은 장치·결정론 합산에서의 비교다. CPU 와 CUDA 사이에서는 합산 순서가 달라 비트 일치를 기대하지 않으며, "
                            "그 경우 theta_max_abs_diff_mV 를 따로 본다.")}

    # ------------------------------------------------------------------ 메뉴 21-2
    def run_checks(self, *, circuit: bool | None = None) -> dict[str, Any]:
        """DB1~DB11. CPU 합성 검사는 바로, 작은 회로 검사는 확인 뒤 사용자 PC 에서 실행한다."""
        self.run_tag = self._run_tag_given or "deadband_check"
        self._db_open("check")
        self.say("CPU 합성 검사 DB1a·DB2~DB7 (회로 없음) ...")
        cpu = db_cpu_checks(self.dbs)
        bs = int(self.pre["batch_size"])
        n_settle = 2 * (2 * int(self.dbs["learning"]["K_rounds"]) + 2) + 1 + len(self.db_conditions) * (
            2 * int(self.dbs["learning"]["K_rounds"]) + 2) + 1 + 2 * (2 * int(self.dbs["learning"]["K_rounds"]) + 2) \
            + 1 + 4 * (2 * int(self.dbs["learning"]["K_rounds"]) + 2) + math.ceil(len(self.sel["train"]) / bs)
        circ: dict[str, Any] = {}
        do = circuit if circuit is not None else self.confirm(
            f"작은 회로 검사 DB1b·DB6b·DB8·DB9·DB10·DB11 (준비 1회 + 약 {n_settle} settle, 배치 {bs}, 장치 "
            f"{self.runner.device}). 실행할까?")
        if do:
            self._latency_rows, self._tl_arrays, self._selected = [], {}, {}
            prep = self._tl_prepare()
            if prep.get("status") != "completed":
                circ = {k: {"status": DB_NOT_RUN, "reason_ko": "준비 단계 실패 (IT 신호 부족)"}
                        for k in ("DB1b_circuit", "DB6b_circuit", "DB8", "DB9", "DB10", "DB11")}
            else:
                x, labels = self._check_batch()
                for name, fn in (("DB1b_circuit", lambda: self._db1_circuit(x, labels)),
                                 ("DB6b_circuit", lambda: self._db6_circuit(x, labels)),
                                 ("DB8", lambda: self._db8_circuit(x, labels)),
                                 ("DB9", lambda: self._db9_circuit(x, labels)), ("DB10", lambda: self._db10_circuit(x)),
                                 ("DB11", self._db11_circuit)):
                    self._progress({"check": name, "status": "running"})
                    g = lat_guard(name, fn)
                    circ[name] = g["result"] if g["status"] == "completed" else {
                        "status": DB_FAILED, "part": "circuit", "error": {k: v for k, v in g.items() if k != "result"}}
                    self._progress({"check": name, "status": circ[name].get("status")})
                self.model.neurons.theta_base.copy_(self.theta_init)
            self.tl_exec["circuit_checks"] = "completed"
        else:
            circ = {k: {"status": DB_NOT_RUN, "part": "circuit", "reason_ko": "사용자가 회로 검사를 실행하지 않았다"}
                    for k in ("DB1b_circuit", "DB6b_circuit", "DB8", "DB9", "DB10", "DB11")}
        parts = {**cpu, **circ}

        def comb(*keys: str) -> str:
            st = [parts[k]["status"] for k in keys if k in parts]
            if any(s == DB_FAILED for s in st):
                return DB_FAILED
            if st and all(s == DB_PASSED for s in st):
                return DB_PASSED
            return DB_NOT_RUN
        overall = {"DB1": comb("DB1a_cpu_synthetic", "DB1b_circuit"), "DB2": comb("DB2"), "DB3": comb("DB3"),
                   "DB4": comb("DB4"), "DB5": comb("DB5"), "DB6": comb("DB6a_cpu_synthetic", "DB6b_circuit"),
                   "DB7": comb("DB7"), "DB8": comb("DB8"), "DB9": comb("DB9"), "DB10": comb("DB10"), "DB11": comb("DB11")}
        self.tl_exec["cpu_checks"] = "completed"
        checks = {"format": DB_FORMAT, "overall": overall, "parts": parts,
                  "overall_rule_ko": ("부분 중 하나라도 FAILED 면 FAILED, 모든 부분 PASSED 면 PASSED, 그 밖(일부 NOT_RUN)은 "
                                      "NOT_RUN. 부분별 상태는 parts 에 있다."),
                  "note_ko": "성능 향상은 통과 조건이 아니다. 합성 사례는 실제 피질 성능 예측이 아니다."}
        if getattr(self, "_latency_rows", None):
            _write_rows_csv(self.run_dir / "latency_summary.csv", self._latency_rows)
        return self._db_finish({"validation_only": True, "path_log": self.net.path_log, "checks_overall": overall},
                               checks, "completed", "")

    # ------------------------------------------------------------------ 메뉴 21-7 holdout
    def _db_holdout_set(self) -> tuple[list[Any], dict[str, Any]]:
        ho = self.dbs["holdout"]
        sub = int(ho["stream_sub"])
        cfg_h = copy.deepcopy(self.runner.cfg)
        cfg_h["data"]["n_base_per_class"] = int(ho["n_base_per_class"])
        cfg_h["data"]["n_variants"] = int(ho["n_variants"])
        seeds_h = _HoldoutSeeds(int(self.runner.cfg["seed"]), sub)
        stims = SyntheticShapeDataset(cfg_h, seeds_h).build()
        pre = f"holdout{sub}_"
        for s in stims:
            s.stimulus_id = pre + s.stimulus_id
            s.base_id = pre + s.base_id
            s.meta["holdout_stream"] = {"name": "deadband_holdout", "sub": sub}
        existing = list(self.runner.stims)
        ex_hash = {_db_frame_hash(s): s.stimulus_id for s in existing}
        dups = [s.stimulus_id for s in stims if _db_frame_hash(s) in ex_hash]
        base_overlap = sorted({s.base_id for s in stims} & {s.base_id for s in existing})
        near = []
        for s in stims:
            same = [e for e in existing if e.label == s.label]
            if same:
                near.append(min(float(np.max(np.abs(np.asarray(s.frames[0], np.float64)
                                                     - np.asarray(e.frames[0], np.float64)))) for e in same))
        digests = {s.stimulus_id: s.digest() for s in stims}
        man = {"format": DB_FORMAT, "stream": {"name": "deadband_holdout", "offset": STREAM_OFFSETS["deadband_holdout"],
                                               "sub": sub, "master_seed": int(self.runner.cfg["seed"])},
               "n": len(stims), "n_base_per_class": int(ho["n_base_per_class"]), "n_variants": int(ho["n_variants"]),
               "labels": {lab: sum(1 for s in stims if s.label == lab) for lab in sorted({s.label for s in stims})},
               "stimulus_ids": sorted(digests), "base_ids": sorted({s.base_id for s in stims}),
               "digests": digests, "sha256": sha256_text(json.dumps(digests, sort_keys=True)),
               "duplicates": {"n_exact_content_duplicates": len(dups), "examples": dups[:10],
                              "base_id_overlap": base_overlap,
                              "min_max_abs_pixel_diff_to_existing_same_label": (min(near) if near else None),
                              "n_near_identical_below_1e-6": int(sum(1 for v in near if v < 1e-6))},
               "compared_against": {k: len(v) for k, v in self.runner.splits.items()},
               "note_ko": ("기존 train/dev/공개 test 의 증강본을 옮겨 쓰지 않았다. 같은 master seed 의 별도 스트림 "
                           "'deadband_holdout' 로 새 원본·변형을 만들고 원본 식별자와 화소 내용 해시를 기존 분할과 비교했다.")}
        return stims, man

    def _db_selected_extra(self, cond: str, z: Any, meta: dict[str, Any]) -> dict[str, Any] | None:
        """selected.npz 의 theta 외 추가 상태 (메뉴 21 에는 없다)."""
        return None

    def _db_apply_selected_extra(self, cond: str, extra: dict[str, Any] | None) -> None:
        """_db_selected_extra 로 읽은 상태를 평가 전에 적용한다 (메뉴 21 에서는 아무것도 하지 않는다)."""
        return None

    def run_holdout(self, source: Path, conditions: Sequence[str], *, allow_repeat: bool = False) -> dict[str, Any]:
        """확정된 체크포인트(조건별 selected.npz)를 새 holdout 으로 한 번 평가한다. 반복 평가는 독립 시험이 아니다."""
        t = require_torch()
        source = Path(source)
        self.run_tag = self._run_tag_given or "deadband_holdout"
        sel_meta: dict[str, Any] = {}
        for c in conditions:
            if c not in self.db_conditions:
                raise ValueError(f"원 실행 조건이 아니다: {c} (가능: {self.db_conditions})")
            jp = source / "checkpoints" / safe_name(c) / "selected.json"
            npz = source / "checkpoints" / safe_name(c) / "selected.npz"
            if not (jp.is_file() and npz.is_file()):
                raise ValueError(f"{c}: 확정된 체크포인트(selected.json/npz)가 없다. 학습이 정상 완료된 실행만 평가한다.")
            sm = read_json(jp)
            if not sm.get("final"):
                raise ValueError(f"{c}: selected.json 이 확정 상태가 아니다.")
            sel_meta[c] = sm
        self._db_open("holdout")
        prep_path = source / "checkpoints" / "preparation_state.json"
        if not prep_path.is_file():
            raise ValueError("원 실행에 checkpoints/preparation_state.json 이 없다.")
        prep_sha = sha256_file(prep_path)
        self.cal = PairedCalibrationRunner(self.runner.cfg, self.net, self.runner.seeds, log=self.runner.recorder.log)
        self.cal.load_state_dict(read_json(prep_path))
        self.prep_sig = self.cal.signatures()
        self.prep_snapshot = self.cal.state_dict()
        self.prep_file_sha = prep_sha
        issues = {c: self._db_ckpt_issues(m_, c) for c, m_ in sel_meta.items()}
        for c, m_ in sel_meta.items():
            if m_.get("preparation_state_sha256") and m_["preparation_state_sha256"] != prep_sha:
                issues[c].append("preparation_state_sha256")
        bad = {c: v for c, v in issues.items() if v}
        if bad:
            return self._db_finish({"holdout_source": str(source), "issues": bad}, {}, "refused",
                                   f"원 실행과 현재 모델/설정/준비가 다르다: {bad}")
        stims, man = self._db_holdout_set()
        write_json(self.run_dir / "holdout_manifest.json", man)
        dup = man["duplicates"]
        if dup["n_exact_content_duplicates"] or dup["base_id_overlap"] or dup["n_near_identical_below_1e-6"]:
            return self._db_finish({"holdout_source": str(source), "holdout_manifest": man}, {}, "refused",
                                   "holdout 이 기존 분할과 겹친다 (내용 해시/원본 id/거의 같은 영상). 평가하지 않는다.")
        log_path = source / "holdout_access.json"
        log = read_json(log_path) if log_path.is_file() else {"format": DB_FORMAT, "events": [],
                                                               "note_ko": "메뉴 21-7 holdout 접근 기록 (자동 누적)"}
        prior = {c: [e for e in log["events"] if e.get("condition") == c and e.get("holdout_sha256") == man["sha256"]]
                 for c in conditions}
        todo = [c for c in conditions if not prior[c] or allow_repeat]
        refused = [c for c in conditions if c not in todo]
        msg = (f"holdout {man['n']}개 (클래스별 {man['labels']}) 로 조건 {todo} 을 평가한다 (teacher OFF, theta_fast 0). "
               f"이미 평가한 조건 {refused} 은 건너뛴다. 원 실행 폴더에 holdout_access.json 접근 기록을 추가한다 "
               f"({log_path}). 실행할까?")
        if not todo or not self.confirm(msg):
            return self._db_finish({"holdout_source": str(source), "holdout_manifest": man, "refused_repeat": refused},
                                   {}, "cancelled", "평가할 조건이 없거나 사용자가 취소")
        self._latency_rows = []
        a = self.model.neurons
        results: dict[str, Any] = {}
        for c in todo:
            with np.load(source / "checkpoints" / safe_name(c) / "selected.npz", allow_pickle=False) as z:
                th = t.tensor(z["theta_base"], dtype=self.model.dtype, device=self.model.device)
                extra = self._db_selected_extra(c, z, sel_meta[c])
            if tensor_hash(th) != sel_meta[c].get("theta_sha256"):
                results[c] = {"status": DB_FAILED, "reason_ko": "selected.npz 해시가 selected.json 과 다르다"}
                continue
            a.theta_base.copy_(th)
            self._db_apply_selected_extra(c, extra)
            ev = self._evaluate(stims, split="holdout", cond=c, phase="final_holdout")
            self._latency_rows.extend(ev.pop("latency", []))
            n_acc = len(prior[c]) + 1
            results[c] = {**ev, "access_number": n_acc, "independent_evaluation": n_acc == 1,
                          "selection": {k: sel_meta[c].get(k) for k in ("rule", "epoch", "dev_ce", "note_ko")},
                          "note_ko": ("첫 평가" if n_acc == 1 else
                                      f"{n_acc}번째 평가: 같은 holdout 의 반복 평가이며 새로운 독립 시험이 아니다.")}
            log["events"].append({"utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "condition": c,
                                  "seed": int(self.runner.cfg["seed"]), "holdout_sha256": man["sha256"],
                                  "holdout_stream_sub": man["stream"]["sub"], "access_number": n_acc,
                                  "evaluation_run_dir": str(self.run_dir), "accuracy": ev["accuracy"],
                                  "cross_entropy": ev["cross_entropy"]})
            write_json(log_path, log)
        a.theta_base.copy_(self.theta_init)
        self.tl_exec["holdout"] = "completed"
        _cfg_src = read_json(source / "config_effective.json")
        src_cfg = _cfg_src.get("deadband_ablation") or _cfg_src.get("cosine_prototype") or {}
        write_json(self.run_dir / "evaluation.json", {
            "format": DB_FORMAT, "holdout": results, "refused_repeat": refused, "source_run": str(source),
            "source_run_preset": (src_cfg.get("settings") or {}).get("run_preset"),
            "holdout_manifest_sha256": man["sha256"],
            "note_ko": ("선택된 조건·시드당 한 번 평가한다. 단일 시드·소량 자료이면 탐색적 결과다. smoke 실행의 체크포인트이면 "
                        "효과 판정용이 아니다.")})
        write_json(self.run_dir / "test_access.json", {"format": DB_FORMAT, "holdout_access_log_source": str(log_path),
                                                        "events_for_this_holdout": [e for e in log["events"]
                                                                                    if e.get("holdout_sha256") == man["sha256"]]})
        _write_rows_csv(self.run_dir / "latency_summary.csv", self._latency_rows)
        return self._db_finish({"holdout_source": str(source), "holdout_results": {c: {k: v for k, v in r.items()
                                                                                        if k != "latency"}
                                                                                    for c, r in results.items()},
                                "refused_repeat": refused, "holdout_manifest": {k: v for k, v in man.items()
                                                                                  if k != "digests"}},
                               {}, "completed", "")


def run_db_holdout(base_cfg: dict[str, Any], output_root: Path, device_choice: str, *, source: Path,
                   conditions: Sequence[str] | None, env: "EnvironmentInfo | None" = None,
                   progress: Callable[[str], None] | None = None, confirm: Callable[[str], bool] | None = None,
                   allow_repeat: bool = False, allow_code_mismatch: bool = False,
                   holdout_overrides: dict[str, Any] | None = None) -> dict[str, Any]:
    """원 실행의 설정·시드로 같은 모델을 다시 만들어 확정된 체크포인트를 holdout 평가한다 (새 실행 폴더)."""
    source = Path(source)
    cfg_e = read_json(source / "config_effective.json")
    dba = cfg_e.get("deadband_ablation") or {}
    if not dba.get("settings"):
        raise ValueError(f"메뉴 21 실행 폴더가 아니다 (config_effective.json 에 deadband_ablation 없음): {source}")
    met = read_json(source / "metrics.json") if (source / "metrics.json").is_file() else {}
    if met.get("status") != "completed" or met.get("task") not in ("smoke", "main"):
        raise ValueError("정상 완료된 smoke/main 학습 실행만 holdout 평가한다 "
                         f"(상태 {met.get('status')}, 작업 {met.get('task')}).")
    settings = copy.deepcopy(dba["settings"])
    if holdout_overrides:
        settings["holdout"] = {**settings.get("holdout", {}), **holdout_overrides}
    seed = int((cfg_e.get("config") or {}).get("seed"))
    exp = DeadbandAblation(base_cfg, output_root, device_choice, settings=settings, seed=seed, env=env,
                           progress=progress, confirm=confirm, allow_code_mismatch=allow_code_mismatch,
                           run_tag="deadband_holdout")
    conds = list(conditions) if conditions else list(exp.db_conditions)
    return exp.run_holdout(source, conds, allow_repeat=allow_repeat)


