def db_implementation_changes(th: dict[str, Any], dbd: dict[str, Any]) -> list[str]:
    """기존 경로 대비 바꾼 점 (실제 설정값으로 문장을 만든다. 고정 숫자 문구를 쓰지 않는다)."""
    return [
        (f"deadband 분리: teacher_tolerance={dbd['teacher_tolerance']} (모든 조건 공통), relay_deadband / "
         f"update_deadband 는 조건별 (legacy 값 {dbd['legacy_deadband']}). 단위는 정규화 활동이며 mV 가 아니다."),
        "하위 DTP: e_raw_L = beta*(D_U(h_U) - D_U(target_relay_U)), gate = needs_relay_U (기존 target_total/needs_total)",
        "로컬 갱신: e_local = H_update(e_pre) 에서 분해·L2 투영·candidate/needs·L1 soft deadband·L3 잔차 (기존 단일 deadband)",
        "L3 잔차: 새 활동과 target_local 비교 (마스킹 valid & needs_local -> 분해, 기존 순서 그대로)",
        "기존 build_packets 의 표본별 CPU 분해 분류(classify_decomposition) 는 기록에서 뺐다 (GPU 동기화 감소, 학습 계산에 쓰이지 않음)",
        "단계별 통계는 GPU 텐서로 모아 episode 끝에 한 번 CPU 로 옮긴다",
        (f"임계값 범위: 전역 THETA_MIN 은 그대로, 이 실험에서만 엔진 theta_min 속성과 commit 하한을 {th['min_mV']} mV, "
         f"상한 {th['max_mV']} mV, 학습 대상 초기 {th['init_mV']} mV, L4 고정 {th['l4_fixed_mV']} mV"),
        "개발 실행은 train/dev 만 사용 (기존 공개 test 원본은 개발에서 제외), 최종 holdout 은 메뉴 21-7 의 새 자료",
    ]


class _HoldoutSeeds(SeedStreams):
    """최종 holdout 자료 전용 난수: 자극·분할·손상 스트림만 'deadband_holdout' 스트림으로 바꾼다.

    기존 스트림의 수열 위치는 바뀌지 않는다 (같은 master seed, 다른 offset 의 SeedSequence).
    """

    _MAP = {"stimulus": 0, "split": 1, "corruption": 2}

    def __init__(self, master_seed: int, sub: int) -> None:
        super().__init__(master_seed)
        self.sub = int(sub)

    def numpy(self, name: str, sub: int = 0) -> np.random.Generator:
        if name in self._MAP:
            return super().numpy("deadband_holdout", 1000 * self.sub + 10 * self._MAP[name] + int(sub))
        return super().numpy(name, sub)


def _db_frame_hash(s: "Stimulus") -> str:
    h = hashlib.sha256()
    h.update(str(s.label).encode())
    for fr in s.frames:
        h.update(np.ascontiguousarray(fr, dtype=np.float32).tobytes())
    return h.hexdigest()


class DeadbandAblation(_DBChecksMixin, ThresholdLearningF0r):
    """메뉴 21. 같은 F0r 회로·준비 상태·초기 theta·표본 순서·입력 사건에서 deadband 정책만 바꿔 비교한다.

    조건: frozen / legacy_deadband / relay_unfiltered / relay_and_update_unfiltered / zero_teacher_unfiltered
    (+ 선택 location_shuffled_matched). 개발 실행은 train/dev 만 쓴다.
    """

    def __init__(self, base_cfg: dict[str, Any], output_root: Path, device_choice: str, *,
                 settings: dict[str, Any] | None = None, seed: int | None = None,
                 env: "EnvironmentInfo | None" = None, progress: Callable[[str], None] | None = None,
                 confirm: Callable[[str], bool] | None = None, resume_from: Path | None = None,
                 allow_code_mismatch: bool = False, run_tag: str | None = None) -> None:
        dbs = validate_db_settings(settings)
        pre = dbs[dbs["run_preset"]]
        pf = {"preset": dbs["preset"], "engine_kind": dbs["engine_kind"], "stimulus_ms": dbs["stimulus_ms"],
              "offset_ms": dbs["offset_ms"], "dt_ms": dbs["dt_ms"], "conditions": ["F0"], "include_R0": False,
              "input_repair_compare": True, "batch_size": int(pre["batch_size"]), "shapes_per_class": 1,
              "stim_types": ["shape", "no_input"]}
        PairedFeedforwardExperiment.__init__(self, base_cfg, output_root, device_choice, settings=pf, seed=seed,
                                             env=env, progress=progress, confirm=confirm)
        self.dbs = dbs
        self.tls = db_to_tl_settings(dbs)
        self.pre = pre
        self._run_tag_given = run_tag
        self.run_tag = run_tag or f"deadband_{dbs['run_preset']}"
        self.resume_from = Path(resume_from) if resume_from is not None else None
        self.allow_code_mismatch = bool(allow_code_mismatch)
        self.tl_exec: dict[str, Any] = {}
        self.checks: dict[str, Any] = {}
        self.db_conditions = db_all_conditions(dbs)
        self.policies = {c: db_policy(dbs, c) for c in DB_CONDITION_TABLE}
        self.compare_policies = [self.policies[c] for c in DB_COMPARE_POLICIES]
        self.excluded_test: list[Any] = []
        self._log_bytes = 0

    # ------------------------------------------------------------------ 설정·열기
    def model_cfg(self) -> tuple[dict[str, Any], str]:
        cfg, note = PairedFeedforwardExperiment.model_cfg(self)
        d = self.dbs["data"]
        cfg["data"]["n_base_per_class"] = int(d["n_base_per_class"])
        cfg["data"]["n_variants"] = int(d["n_variants"])
        cfg["data"]["split_fractions"] = [float(x) for x in d["split_fractions"]]
        cfg["training"]["batch_size"] = int(self.pre["batch_size"])
        cfg["deterministic"] = bool(self.dbs["deterministic_engine"])
        validate_config(cfg)
        return cfg, note + " deadband 전달/갱신 분리 실험(메뉴 21): 같은 F0r 구조 위에서 L2/L3 theta_base 학습."

    def _make_network(self, runner: "ExperimentRunner", m: "CorticalModel", mask: Any) -> "DBPairedNetwork":
        return DBPairedNetwork(runner.cfg, m, runner.seeds, tl=self.tls, policy=self.policies["frozen"],
                               learn_mask=mask, obs_steps=self.obs_steps, stim_steps=self.stim_steps,
                               window_steps=self.window, gate_ref=self.ff_gate)

    def _db_policy_rows(self) -> list[dict[str, Any]]:
        """config_effective 에 적는 조건/정책 표 (하위 실험이 자기 조건표로 바꾼다)."""
        return db_policy_table(self.dbs)

    def _coverage_policy_names(self) -> tuple[str, ...]:
        """준비 자료의 교사 관측 공백을 계산할 정책 이름 (메뉴 21: legacy / unfiltered)."""
        return ("legacy_deadband", "relay_and_update_unfiltered")

    def _db_fix_split(self) -> None:
        if "test" in self.sel:
            self.excluded_test = list(self.sel.pop("test"))

    def _db_open(self, task: str) -> None:
        self._tl_open(task)
        self._db_fix_split()
        mask = self.masks["local_all_L23"]
        self.db_masks = {c: mask for c in self.policies}
        self.norm_sha = tensor_hash(self.model.encoder.scale) if getattr(self.model.encoder, "scale", None) \
            is not None else None

    def _tl_write_config(self, task: str) -> None:
        """메뉴 21 의 config_effective / source_info / data_split / learning_mask (TL 판을 대신한다)."""
        t = require_torch()
        self._db_fix_split()
        m, rec = self.model, self.runner.recorder
        a = m.neurons
        mask = self.masks["local_all_L23"]
        cuda = str(self.runner.device).startswith("cuda")
        gpu = None
        if cuda:
            try:
                props = t.cuda.get_device_properties(self.runner.device)
                gpu = {"name": props.name, "total_memory_bytes": int(props.total_memory)}
            except Exception as exc:                          # noqa: BLE001
                gpu = {"error": f"{type(exc).__name__}: {exc}"}
        th, dbd = self.dbs["theta"], self.dbs["deadband"]
        changes = db_implementation_changes(th, dbd)
        libs = {"python": sys.version.split()[0], "numpy": np.__version__, "torch": getattr(t, "__version__", None),
                "torch_cuda": getattr(getattr(t, "version", None), "cuda", None)}
        rec.manifest["deadband_ablation"] = {
            "task": task, "version": __version__, "code": source_hash(), "format": DB_FORMAT,
            "base_source": DB_BASE_SOURCE, "implementation_chain": DB_IMPLEMENTATION_CHAIN,
            "implementation_changes": changes, "device": str(self.runner.device), "dtype": str(self.runner.dtype),
            "cuda_used": cuda, "gpu": gpu, "deterministic": bool(m.engine.deterministic),
            "seed": int(self.runner.cfg["seed"]), "command": " ".join(sys.argv), "run_preset": self.dbs["run_preset"],
            "library_versions": libs, "structure": self.structure, "input_repair": self.repair_info,
            "mask_sha256": self.mask_hash, "executed": self.tl_exec}
        write_json(self.run_dir / "source_info.json", {
            "format": DB_FORMAT, "version": __version__, "code": source_hash(), "base_source": DB_BASE_SOURCE,
            "library_versions": libs, "device": str(self.runner.device), "cuda_used": cuda, "gpu": gpu,
            "command": " ".join(sys.argv), "utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            "note_ko": ("CUDA 를 쓰지 않았으면 cuda_used=false 다. GPU 로 실행했다고 적지 않는다. 결과 수치는 이 폴더의 "
                        "저장 파일에만 있다.")})
        cfg_path = self.run_dir / "config_effective.json"
        cur = read_json(cfg_path) if cfg_path.is_file() else {}

        def cnt(msk: Any) -> int:
            return int(msk.sum())
        cur["deadband_ablation"] = {
            "format": DB_FORMAT, "settings": self.dbs, "settings_sha256": db_settings_sha(self.dbs),
            "conditions": self.db_conditions, "policies": self._db_policy_rows(),
            "compare_policies_same_state": list(DB_COMPARE_POLICIES),
            "main_contrasts": [f"{b_} - {a_}" for b_, a_ in DB_MAIN_CONTRASTS], "units_ko": DB_UNITS_KO,
            "teacher_tolerance_fixed_across_conditions": True, "automatic_tuning": False,
            "menu20_defaults_unchanged": {"theta": tl_defaults()["theta"], "learning_deadband": tl_defaults()["learning"]["deadband"]},
            "theta_effective": {"engine_theta_min_mV": float(m.engine.theta_min),
                                "engine_theta_max_mV": float(m.engine.theta_max),
                                "engine_bounds_before": self.engine_theta_bounds_before,
                                "controller_min_mV": float(th["min_mV"]), "controller_max_mV": float(th["max_mV"]),
                                "init_L2_L3_mV": float(th["init_mV"]), "L4_fixed_mV": float(th["l4_fixed_mV"]),
                                "fast_bound_mV": float(th["fast_bound_mV"]),
                                "global_THETA0_unchanged": THETA0, "global_THETA_MIN_unchanged": THETA_MIN,
                                "downward_learning_possible": float(th["min_mV"]) < float(th["init_mV"]),
                                "definition_ko": th["definition_ko"]},
            "learning_effective": dict(self.dbs["learning"]),
            "target_clip": list(self.net.fb["target_clip"]),
            "masks": {"learn_L23_count": cnt(mask), "set_to_init_count": cnt(self.target_mask),
                      "L4_fixed_count": cnt(self.l4_mask), "learn_intersects_L4": cnt(mask & self.l4_mask),
                      "learn_intersects_inhibitory": cnt(mask & (a.dale < 0)),
                      "note_ko": "V1/V2/V4/IT 의 L2/L3 흥분성 피라미드만 학습한다 (모든 조건 같은 마스크)."},
            "windows_ms": [list(w) for w in TL_WINDOWS_MS], "readout_window_steps": list(self.window),
            "readout_window_s": (self.window[1] - self.window[0]) * self.dt / MS_PER_S,
            "stimulus_steps": self.stim_steps, "observation_steps": self.obs_steps,
            "frozen_ko": ["W(w0)·P·지연·막용량·누설·구획 결합·배선 고정, 연결 추가/삭제 없음",
                          "억제 출력 0, GABA-B OFF, 로그 전달률 조절 OFF, attention OFF, 항상성·theta 감쇠 OFF",
                          "준비 뒤 C / D_A / T_B / 프로토타입 / rate_scale / 입력 정규화 고정 (조건마다 같은 스냅샷 재적재)",
                          "L1/L5/L6 교정은 임계값에만. 물리 시냅스에 피드백 전류·재귀 연결을 추가하지 않는다"],
            "implementation_changes": changes, "mask_sha256": self.mask_hash}
        write_json(cfg_path, cur)
        rows = []
        names = (list(a.area_names), list(a.layer_names), list(a.cell_type_names))
        aid = a.area_id.detach().to("cpu").numpy()
        lid = a.layer_id.detach().to("cpu").numpy()
        cid = a.cell_type_id.detach().to("cpu").numpy()
        m_all = mask.detach().to("cpu").numpy()
        for i in np.nonzero(m_all | self.target_mask.detach().to("cpu").numpy())[0]:
            rows.append({"neuron_id": int(i), "area": names[0][aid[i]], "layer": names[1][lid[i]],
                         "cell_type": names[2][cid[i]], "learn_all_conditions": bool(m_all[i]),
                         "theta_init_mV": float(self.theta_init[i])})
        _write_rows_csv(self.run_dir / "learning_mask.csv", rows)
        ids = lambda xs: sorted(str(s.stimulus_id) for s in xs)      # noqa: E731
        split: dict[str, Any] = {
            "rule_ko": ("base_id 단위 분할 (같은 원본의 변형이 다른 분할로 넘어가지 않음), 클래스 균형. train 만 준비에 쓴다. "
                        "개발 실행은 train/dev 만 쓰고 기존 공개 test 원본은 제외한다. 최종 holdout 은 메뉴 21-7 에서 "
                        "별도 난수 스트림으로 새로 만든다."),
            "data_digest": self.runner.data_digest,
            "preset_selection": {k: self.pre.get(f"{k}_bases_per_class") for k in ("train", "dev")}}
        for k, v in self.sel.items():
            split[k] = {"n": len(v), "stimulus_ids": ids(v), "base_ids": sorted({s.base_id for s in v}),
                        "labels": {lab: sum(1 for s in v if s.label == lab) for lab in sorted({s.label for s in v})},
                        "sha256": sha256_text(json.dumps(ids(v)))}
        ex = self.excluded_test
        split["excluded_public_test"] = {
            "n": len(ex), "base_ids": sorted({s.base_id for s in ex}), "stimulus_ids": ids(ex),
            "sha256": sha256_text(json.dumps(ids(ex))),
            "note_ko": "과거 결과에서 공개된 test 원본이다. 메뉴 21 개발 실행·설정 선택에 쓰지 않는다."}
        sets = {"train": {s.base_id for s in self.sel.get("train", [])}, "dev": {s.base_id for s in self.sel.get("dev", [])},
                "excluded_test": {s.base_id for s in ex}}
        split["base_overlap"] = {f"{x}&{y}": sorted(sets[x] & sets[y])
                                 for x, y in (("train", "dev"), ("train", "excluded_test"), ("dev", "excluded_test"))}
        write_json(self.run_dir / "data_split.json", split)

    # ------------------------------------------------------------------ 준비
    def _tl_prepare(self) -> dict[str, Any]:
        info = super()._tl_prepare()
        if info.get("status") in ("completed", "reused_for_resume"):
            self.prep_snapshot = self.cal.state_dict()
            p = self.run_dir / "checkpoints" / "preparation_state.json"
            self.prep_file_sha = sha256_file(p) if p.is_file() else None
        return info

    def _tl_coverage(self, cal: "PairedCalibrationRunner") -> dict[str, Any]:
        """준비 자료의 교사 관측 공백 (추가 물리 실행 없음). legacy / unfiltered 두 정책의 target_local 로 계산."""
        t = require_torch()
        net = self.net
        free = cal._last_free
        labels = free["labels"]
        acts3 = {a: t.clamp(free["rates"][a] / max(net.activity.specs[a].rate_scale_hz, 1e-9), 0.0, 1.0)
                 for a in net.activity.order}
        acts2 = {a: t.clamp(free["l2_rates"][a] / max(net.activity.l2_specs[a].rate_scale_hz, 1e-9), 0.0, 1.0)
                 for a in free["l2_rates"]}
        state = {"activities": {a: v.unsqueeze(0) for a, v in acts3.items()},
                 "l2_activities": {a: v.unsqueeze(0) for a, v in acts2.items()}}
        h = state["activities"][net.top_area]
        state["h_IT"] = h
        state["logits"] = net.classifier.logits(h)
        sel = net.targets.select_prototype(h, labels)
        valid = t.isfinite(sel["target"]).all(dim=-1)
        gate, ginfo = net.teacher_gate(state, labels, sel["target"])
        ginfo.pop("cmp", None)
        gate = gate & valid
        thr = float(self.dbs["deadband"]["teacher_tolerance"])
        lab = labels.detach().to("cpu").numpy()
        out_rows: list[dict[str, Any]] = []
        summ: dict[str, Any] = {"coverage_positive_threshold": thr,
                                "coverage_threshold_ko": ("'양의 목표' 판정 기준 = teacher_tolerance (정규화 활동 단위). "
                                                          "t > 0 인 표본 수도 따로 적는다."),
                                "teacher_gate_fraction_on_prep": float(gate.to(net.dtype).mean()),
                                "by_policy": {}}
        saved, ver = net.policy, net._state_version
        try:
            for pname in self._coverage_policy_names():
                net.policy = self.policies[pname]
                packs = {}
                for tag, g in (("gated", gate), ("all_gate_on", t.ones_like(gate) & valid)):
                    t_it = net.comparator.it_target(h, g.to(net.dtype), sel["target"])
                    packs[tag] = net.build_packets(state, t_it, g, valid, sample_id=-1, episode_id=-1, round_id=-1)
                conf_zero: dict[str, float] = {}
                by_group: dict[str, dict[str, int]] = {}
                for area in net.activity.order:
                    for layer, ids_t, a_act in (("L3", net.activity.specs[area].neuron_ids, acts3[area]),
                                                ("L2", net.activity.l2_specs[area].neuron_ids
                                                 if area in net.activity.l2_specs else None, acts2.get(area))):
                        if ids_t is None or a_act is None:
                            continue
                        tg = {}
                        for tag, pk in packs.items():
                            p = pk[area]
                            if layer == "L3":
                                tg[tag] = p["target_local"][0]
                            else:
                                ps = p["packet_shape"]
                                tg[tag] = a_act - ps.correction[0] if ps is not None else a_act
                        tgn = tg["gated"].detach().to("cpu").numpy()
                        rows = tl_coverage_rows(area, layer, ids_t.detach().to("cpu").numpy(),
                                                a_act.detach().to("cpu").numpy(), tgn, lab, thr)
                        ungated = tg["all_gate_on"].detach().to("cpu").numpy()
                        for j, r in enumerate(rows):
                            r["policy"] = pname
                            r["coverage_threshold"] = thr
                            r["n_target_gt0_samples"] = int((tgn[:, j] > 0).sum())
                            r["n_negative_implicit_target_samples"] = int((tgn[:, j] < 0).sum())
                            r["n_positive_target_if_gate_on"] = int((ungated[:, j] > thr).sum())
                            r["saturated_samples"] = int((a_act[:, j] >= 1.0).sum())
                        out_rows.extend(rows)
                        g_ = by_group.setdefault(f"{area}/{layer}", {
                            "n_neurons": 0, "n_always_silent_no_positive_target": 0, "n_never_active": 0,
                            "n_without_positive_target": 0, "n_silent_deficit_candidate_events": 0,
                            "n_negative_implicit_target_events": 0})
                        for r in rows:
                            g_["n_neurons"] += 1
                            g_["n_always_silent_no_positive_target"] += int(r["always_silent_no_positive_target"])
                            g_["n_never_active"] += int(r["n_active_samples"] == 0)
                            g_["n_without_positive_target"] += int(r["n_positive_target_samples"] == 0)
                            g_["n_silent_deficit_candidate_events"] += r["n_deficit_candidates_silent"]
                            g_["n_negative_implicit_target_events"] += r["n_negative_implicit_target_samples"]
                        pk = packs["gated"][area]["packet_intensity" if layer == "L3" else "packet_shape"]
                        if pk is not None:
                            conf_zero[f"{area}/{layer}"] = float((pk.confidence <= 0).to(net.dtype).mean())
                summ["by_policy"][pname] = {
                    "by_group": by_group, "confidence_zero_fraction": conf_zero,
                    "restore_error_norm": {a: (None if packs["gated"][a]["restore_error"] is None else
                                               float(packs["gated"][a]["restore_error"].norm(dim=-1).mean()))
                                           for a in net.activity.order},
                    "always_silent_no_target_ids": [r["neuron_id"] for r in out_rows
                                                    if r["policy"] == pname and r["always_silent_no_positive_target"]]}
        finally:
            net.policy, net._state_version = saved, ver
        _write_rows_csv(self.run_dir / "target_coverage.csv", out_rows)
        summ["note_ko"] = ("준비 때 한 번도 발화하지 않고 양의 목표도 받지 않는 축은 이번 교사가 재활성화를 시험하지 못한다. "
                           "이 한계(항상 0 인 프로토타입 축, 침묵 L3 의 intensity 교정 부재, L2 암묵적 목표 음수)는 "
                           "이번 실험에서 고치지 않고 관측 항목으로 남긴다.")
        return summ

    # ------------------------------------------------------------------ 라벨 없는 평가
    def _evaluate(self, stims: Sequence[Any], *, split: str, cond: str, phase: str, key_stream: str = "input_noise",
                  key_base: int = 900_000, return_activity: bool = False) -> dict[str, Any]:
        """교사 없는 평가. key_stream/key_base 는 입력 사건 키 (기본값 = 메뉴 21 그대로). return_activity 이면 같은 판독의
        IT 활동·logits·라벨을 명시적 반환값 '_activity' 로 돌려준다 (전역 상태에 넣지 않는다)."""
        t = require_torch()
        runner, m = self.runner, self.model
        if not stims:
            return {"split": split, "n": 0, "status": DB_NOT_RUN, "reason_ko": "분할이 비어 있다"}
        runner._touch_split(split, len(stims), f"deadband {cond} {phase}")
        if split in ("test", "holdout"):
            runner.test_access["n_test_evaluations"] += 1
            runner.test_access["events"].append({"utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                                                 "n": len(stims), "split": split, "note": f"{cond} {phase}",
                                                 "teacher_free": True})
        before = self._purity()
        bs = int(self.pre["batch_size"])
        ce, correct, labs_all, preds = [], 0, [], []
        hs: list[Any] = []
        act_h: list[Any] = []
        act_lg: list[Any] = []
        act_lab: list[Any] = []
        parts: list[dict[str, Any]] = []
        tm = self._timer()
        trace_info: dict[str, Any] | None = None
        for beg in range(0, len(stims), bs):
            sub = stims[beg:beg + bs]
            images, labels = runner._batch_tensor(sub)
            x, _ = m.encode_batch(images)
            key = (str(key_stream), int(key_base) + beg)
            drive = self.net.episode_drive(x, key)
            want_tr = (beg == 0 and phase == "selected" and split == "dev" and bool(self.dbs["trace"]["enabled"]))
            if want_tr:
                pr, trace_info = self._db_trace_probe(drive, len(sub))
            else:
                pr = self._probe(drive, len(sub))
            out = self._predict_drive(drive, key, pr.hook)          # 라벨은 넘기지 않는다
            logits = out["logits"][0]
            ce.extend(float(v) for v in t.nn.functional.cross_entropy(logits, labels, reduction="none"))
            pred = logits.argmax(dim=-1)
            correct += int((pred == labels).sum())
            labs_all.extend(int(v) for v in labels)
            preds.extend(int(v) for v in pred)
            hs.append(out["h_IT"][0].detach().to("cpu"))
            if return_activity:
                act_h.append(out["h_IT"][0].detach())
                act_lg.append(logits.detach())
                act_lab.append(labels.detach())
            part = pr.to_numpy()
            if want_tr and trace_info is not None and trace_info.get("status") == "recording" and "traces" in part:
                tdir = ensure_writable_dir(self.run_dir / "traces")
                tp = tdir / f"{safe_name(cond)}_{phase}_{split}.npz"
                np.savez_compressed(tp, neuron_ids=np.asarray(trace_info["neuron_ids"], np.int64),
                                    sample_ids=np.asarray([sub[r].stimulus_id for r in trace_info["rows"]]),
                                    **{k: v for k, v in part.pop("traces").items()})
                trace_info.update(status="saved", file=str(tp.relative_to(self.run_dir)))
            parts.append(part)
        timing = self._timer_end(tm)
        after = self._purity()
        arr = {k: np.concatenate([p[k] for p in parts], axis=(1 if k == "cnt_win" else 0))
               for k in ("first_in", "exo_first", "first_spike", "n_spk", "n_before_end", "cnt_win")}
        base = {"condition": cond, "phase": phase, "split": split}
        lat = tl_latency_rows(arr, self.groups, win_names=self.win_names, readout_index=0,
                              readout_end_step=self.window[1], dt=self.dt, base=base)
        classes = list(self.runner.cfg["decoder"]["classes"])
        C = len(classes)
        conf = np.zeros((C, C), np.int64)
        for y, p in zip(labs_all, preds):
            conf[y, p] += 1
        h_np = t.cat(hs, dim=0).to(t.float64).numpy()
        it = next((r for r in lat if r["group"] == f"{self.top_area}/L3E"), None)
        res = {"split": split, "condition": cond, "phase": phase, "n": len(stims), "status": "completed",
               "teacher_free": True, "accuracy": correct / max(1, len(stims)),
                "cross_entropy": float(np.mean(ce)), "confusion": conf.tolist(), "classes": classes,
                "per_class_accuracy": {classes[c]: (None if conf[c].sum() == 0 else float(conf[c, c] / conf[c].sum()))
                                       for c in range(C)},
                "n_distinct_predictions": len(set(preds)), "chance": 1.0 / C,
                "it_class_separation": db_class_separation(h_np, np.asarray(labs_all)),
                "purity_preserved": before == after, "purity_detail": {k: before[k] == after[k] for k in before},
                "it_l3": None if it is None else {
                    "spikes_readout_64_160": it["spikes_readout_64_160"], "spikes_whole_0_460": it["spikes_whole_0_460"],
                    "spikes_after_160": it["spikes_post_160_210"] + it["spikes_post_210_310"] + it["spikes_post_310_460"],
                    "n_fired_in_readout": it["n_fired_in_readout"], "n_input_no_spike": it["n_input_no_spike"],
                    "n_no_input": it["n_no_input"], "first_input_median_ms": it["first_input_median_ms"],
                    "first_spike_median_ms": it["first_spike_median_ms"]},
                "timing": timing, "latency": lat, "trace": trace_info,
                "numerics": {"nonfinite_V": sum(p["nonfinite"] for p in parts),
                             "negative_g": sum(p["neg_g"] for p in parts)}}
        if return_activity:
            res["_activity"] = {"h": t.cat(act_h, dim=0), "logits": t.cat(act_lg, dim=0), "labels": t.cat(act_lab, dim=0),
                                "sample_ids": [str(s_.stimulus_id) for s_ in stims],
                                "base_ids": [str(s_.base_id) for s_ in stims], "split": split,
                                "stream": [str(key_stream), int(key_base)]}
        return res

    def _db_trace_probe(self, drive: "ExternalDrive", B: int) -> tuple["LatencyProbe", dict[str, Any]]:
        """선택 표본·선택 뉴런 시계열 (용량 한도 확인 뒤). 엔진 상태를 읽기만 한다 (LatencyProbe)."""
        t = require_torch()
        n = int(self.model.neurons.n)
        ids = [int(i) for i in self.dbs["observe_trace_neurons"] if 0 <= int(i) < n]
        rows = [int(r) for r in self.dbs["trace"]["sample_rows"] if 0 <= int(r) < int(B)]
        n_keys = 9 * N_COMP + 8
        est = int(self.obs_steps) * len(rows) * len(ids) * n_keys * 4
        info: dict[str, Any] = {"neuron_ids": ids, "rows": rows, "estimated_bytes": est,
                                "max_bytes": int(self.dbs["trace"]["max_bytes"])}
        if not ids or not rows or est > int(self.dbs["trace"]["max_bytes"]):
            info["status"] = "skipped"
            info["reason_ko"] = "대상 뉴런·표본이 없거나 용량 한도를 넘는다 (저장하지 않음)"
            return self._probe(drive, B), info
        info["status"] = "recording"
        pr = LatencyProbe(self.model, n_steps=self.obs_steps, batch=B, readout_ids=self.it_ids_t,
                          win_bounds_steps=self.win_steps, readout_end_step=self.window[1],
                          exo_first=lat_exo_first(drive, self.model.neurons.n), onset_mV=0.01,
                          trace_rows=rows, trace_ids=t.tensor(ids, dtype=t.long, device=self.model.device))
        return pr, info

    # ------------------------------------------------------------------ 체크포인트
    def _db_meta_common(self, cond: str) -> dict[str, Any]:
        pol = self.policies[cond]
        return {"format": DB_FORMAT, "condition": cond, "policy": pol.to_dict(), "policy_key": pol.key(),
                "code_sha256": source_hash().get("sha256", ""), "version": __version__,
                "config_sha256": config_hash(self.runner.cfg),
                "settings_sha256": db_settings_sha(self.dbs),
                "data_digest": self.runner.data_digest, "mask_sha256": self.mask_hash,
                "slot_map_hash": self.model.slot_map.hash, "preparation_signatures": self.prep_sig,
                "preparation_state_file": "checkpoints/preparation_state.json",
                "preparation_state_sha256": getattr(self, "prep_file_sha", None),
                "normalization_sha256": self.norm_sha,
                "normalization_scale": (None if getattr(self.model.encoder, "scale", None) is None else
                                        [float(v) for v in self.model.encoder.scale.detach().to("cpu").tolist()]),
                "theta_init_hash": tensor_hash(self.theta_init)}

    def _save_ckpt(self, cond: str, st: dict[str, Any]) -> None:
        t = require_torch()
        jp, npz = self._ckpt_paths(cond)
        meta = {**self._db_meta_common(cond), "epoch": st["epoch"], "next_batch": st["next_batch"],
                "rng": self.runner.seeds.state_dict(),
                "rng_sha256": sha256_text(json.dumps(self.runner.seeds.state_dict(), sort_keys=True, default=str)),
                "torch_cpu_rng_sha256": hashlib.sha256(t.random.get_rng_state().numpy().tobytes()).hexdigest(),
                "rows": st["rows"], "epoch_evals": st["epoch_evals"], "n_commits": st["n_commits"],
                "selection": st["selection"], "holdout_access": [],
                "resume_unit": "completed_minibatch",
                "note_ko": ("완료된 미니배치 경계에서만 재개한다. 같은 배치의 commit 을 두 번 적용하지 않는다. 다른 조건의 "
                            "같은 초기 상태 복사(theta_init + 준비 스냅샷 재적재)와 이 재개는 다른 것이다. holdout 접근 "
                            "이력은 실행 폴더의 holdout_access.json 에 누적된다.")}
        tmp = npz.with_name("latest_tmp.npz")
        nl = int(self.learn_ids.numel())
        np.savez_compressed(tmp, theta_base=self.model.neurons.theta_base.detach().to("cpu").numpy(),
                            theta_history=np.asarray(st["theta_history"], np.float32).reshape(-1, nl),
                            epoch_end_theta=np.asarray(st["epoch_end_theta"], np.float32).reshape(-1, self.model.neurons.n),
                            batch_signs=np.asarray(st["batch_signs"], np.int8).reshape(-1, nl),
                            torch_cpu_rng_state=t.random.get_rng_state().numpy())
        os.replace(tmp, npz)
        write_json(jp, meta)

    def _load_ckpt(self, cond: str, src_root: Path) -> dict[str, Any] | None:
        t = require_torch()
        jp = src_root / "checkpoints" / safe_name(cond) / "latest.json"
        npz = src_root / "checkpoints" / safe_name(cond) / "latest.npz"
        if not (jp.is_file() and npz.is_file()):
            return None
        meta = read_json(jp)
        issues = self._db_ckpt_issues(meta, cond)
        if issues:
            raise RuntimeError(f"체크포인트가 현재 실행과 맞지 않는다 ({cond}): {issues}. 옛 값을 조용히 이어 붙이지 않는다.")
        with np.load(npz, allow_pickle=False) as z:
            theta = t.tensor(z["theta_base"], dtype=self.model.dtype, device=self.model.device)
            st = {"theta_history": list(z["theta_history"]), "epoch_end_theta": list(z["epoch_end_theta"]),
                  "batch_signs": list(z["batch_signs"]),
                  "torch_cpu_rng_state": (z["torch_cpu_rng_state"] if "torch_cpu_rng_state" in z.files else None)}
        st.update(epoch=int(meta["epoch"]), next_batch=int(meta["next_batch"]), rows=list(meta["rows"]),
                  epoch_evals=list(meta["epoch_evals"]), n_commits=int(meta["n_commits"]),
                  selection=dict(meta["selection"]), theta=theta, rng=meta.get("rng"),
                  code_same=meta.get("code_sha256") == source_hash().get("sha256", ""))
        return st

    def _db_ckpt_issues(self, meta: dict[str, Any], cond: str) -> list[str]:
        now = self._db_meta_common(cond)
        issues = [k for k in ("format", "policy_key", "config_sha256", "settings_sha256", "data_digest", "mask_sha256",
                              "slot_map_hash", "theta_init_hash", "normalization_sha256")
                  if meta.get(k) != now.get(k)]
        if meta.get("preparation_signatures") != self.prep_sig:
            issues.append("preparation_signatures")
        if meta.get("code_sha256") != now["code_sha256"] and not self.allow_code_mismatch:
            issues.append("code_sha256 (코드가 다르다. 메뉴/CLI 에서 명시적으로 허용해야만 이어 붙인다)")
        return issues

    def _save_selected(self, cond: str, theta: Any, sel: dict[str, Any]) -> None:
        d = ensure_writable_dir(self.run_dir / "checkpoints" / safe_name(cond))
        np.savez_compressed(d / "selected.npz", theta_base=theta.detach().to("cpu").numpy())
        write_json(d / "selected.json", {**self._db_meta_common(cond), **sel,
                                         "theta_sha256": tensor_hash(theta), "final": True})

    # ------------------------------------------------------------------ 조건 하나 학습
    def _write_jsonl(self, path: Path, rows: Sequence[dict[str, Any]], extra: dict[str, Any]) -> None:
        if not rows:
            return
        with path.open("a", encoding="utf-8") as f:
            for r in rows:
                line = dumps({**extra, **r}, indent=None) + "\n"
                self._log_bytes += len(line.encode("utf-8"))
                f.write(line)

    def _train_condition(self, cond: str, *, stop_after_batches: int = 0,
                         resume: dict[str, Any] | None = None) -> dict[str, Any]:
        t = require_torch()
        m, net, runner = self.model, self.net, self.runner
        a = m.neurons
        pol = self.policies[cond]
        mask = self.db_masks[cond]
        # 같은 준비 스냅샷의 독립 복사본을 다시 싣는다 (조건마다 같은 C / D / T / 프로토타입 / rate_scale)
        self.cal.load_state_dict(copy.deepcopy(self.prep_snapshot))
        if self.cal.signatures() != self.prep_sig:
            raise RuntimeError("준비 스냅샷 재적재 뒤 서명이 다르다. 조건 사이 출발 상태가 같지 않으므로 멈춘다.")
        net.set_policy(pol, mask)
        a.theta_base.copy_(self.theta_init if resume is None else resume["theta"])
        if resume is not None and resume.get("torch_cpu_rng_state") is not None:
            t.random.set_rng_state(t.tensor(resume["torch_cpu_rng_state"], dtype=t.uint8))
        if resume is not None and resume.get("rng"):
            runner.seeds.load_state_dict(resume["rng"])
        train = list(self.sel["train"])
        bs = int(self.pre["batch_size"])
        nb = max(1, math.ceil(len(train) / bs))
        n_epochs = int(self.pre["epochs"])
        lid = self.learn_ids
        st = resume or {"epoch": 0, "next_batch": 0, "rows": [], "epoch_evals": [], "theta_history": [],
                        "epoch_end_theta": [], "batch_signs": [], "n_commits": 0,
                        "selection": {"rule": self.dbs["selection_rule"], "epoch": None, "dev_ce": None}}
        flow_path = self.run_dir / "correction_flow.jsonl"
        cmp_path = self.run_dir / "same_state_policy_comparison.jsonl"
        cmp_pols = self.compare_policies if self.dbs["compare_policies_each_batch"] else None
        cuda = str(m.device).startswith("cuda")
        gpu_peak = 0
        settles0 = net.path_log["settles"]
        tm = self._timer()
        status, reason = "completed", ""
        done_batches = 0
        lo, hi = float(self.dbs["theta"]["min_mV"]), float(self.dbs["theta"]["max_mV"])
        groups_np = {g: ids.detach().to("cpu").numpy() for g, ids in self.theta_groups.items()}
        try:
            for epoch in range(int(st["epoch"]), n_epochs):
                order = self._epoch_order(epoch, len(train))
                b0 = int(st["next_batch"]) if epoch == int(st["epoch"]) else 0
                for bi in range(b0, nb):
                    sel = order[bi * bs:(bi + 1) * bs]
                    batch = [train[int(i)] for i in sel]
                    images, labels = runner._batch_tensor(batch)
                    x, _ = m.encode_batch(images)
                    runner._touch_split("train", len(batch), f"deadband episode {cond}")
                    commits0 = net.controller.n_commits
                    theta0 = a.theta_base.detach().clone()
                    t0 = time.perf_counter()
                    ep = net.db_episode(x, labels, sample_id=epoch * 100_000 + bi * bs, episode_id=epoch,
                                        drive_key=("input_noise", epoch * 10_000 + bi), train=True,
                                        compare_policies=cmp_pols, detail=str(self.dbs["flow_detail"]),
                                        flow_meta={"epoch": epoch, "batch": bi})
                    if ep.get("status") != "completed":
                        raise EngineDivergence(f"episode 미완료: {ep.get('reason')}")
                    if cuda:
                        gpu_peak = max(gpu_peak, int(t.cuda.max_memory_allocated()))
                    dtheta = a.theta_base - theta0
                    n_commit = net.controller.n_commits - commits0
                    sign = t.sign(dtheta[lid]).to(t.int8)
                    cm = ep["commit"]
                    row: dict[str, Any] = {
                        "condition": cond, "epoch": epoch, "batch": bi, "n": len(batch),
                        "relay_deadband": pol.relay_deadband, "update_deadband": pol.update_deadband,
                        "teacher_tolerance": pol.teacher_tolerance,
                        "stimulus_ids": [s.stimulus_id for s in batch],
                        "teacher_gate_fraction": ep["teacher_gate_fraction"],
                        "teacher_gate_fraction_true": ep["teacher_gate_fraction_true"],
                        "invalid_teacher_target_samples": ep["invalid_teacher_target_samples"],
                        "free_before_ce": ep["free_before"]["cross_entropy"],
                        "free_before_accuracy": ep["free_before"]["accuracy"],
                        "guided_ce": ep["guided"]["cross_entropy"], "guided_accuracy": ep["guided"]["accuracy"],
                        "post_update_free_ce": ep["post_update_free"]["cross_entropy"],
                        "post_update_free_accuracy": ep["post_update_free"]["accuracy"],
                        "n_commit_calls": int(n_commit), "commit_applied": bool(cm.get("applied")),
                        "commit_requested_norm": cm.get("requested_norm"), "commit_actual_norm": cm.get("actual_norm"),
                        "n_theta_up": int((dtheta > 0).sum()), "n_theta_down": int((dtheta < 0).sum()),
                        "n_changed_outside_mask": int(((dtheta != 0) & ~mask).sum()),
                        "n_at_lower_bound": cm.get("n_at_lower_bound"), "n_at_upper_bound": cm.get("n_at_upper_bound"),
                        "n_commit_clipped": cm.get("n_clipped"),
                        "theta_fast_final_norm": ep["theta_fast_final_norm"],
                        "theta_fast_final_max_abs": ep["theta_fast_final_max_abs"],
                        "post_theta_fast_zero": ep["post_theta_fast_zero"],
                        "replay_activity_max_abs_diff": ep["replay_activity_max_abs_diff"],
                        "forward_calls": ep["forward_calls"], "wall_s": round(time.perf_counter() - t0, 3)}
                    for cr in ep["core"]:
                        if cr.get("kind") == "reach":
                            ns = max(1, int(cr["n_samples"]))
                            row[f"reach_relay_{cr['area']}"] = cr["n_samples_needs_relay"] / ns
                            row[f"reach_local_{cr['area']}"] = cr["n_samples_needs_local"] / ns
                            row[f"relay_norm_{cr['area']}"] = cr["relay_norm"]
                            row[f"local_norm_{cr['area']}"] = cr["local_norm"]
                        elif cr.get("kind") == "applied":
                            ns = max(1, int(cr["n_samples"]))
                            row[f"applied_{cr['area']}_{cr['layer']}"] = cr["n_samples_fast_nonzero"] / ns
                            row[f"fast_neurons_{cr['area']}_{cr['layer']}"] = cr["n_neurons_fast_nonzero"]
                        elif cr.get("kind") == "l2_negative_implicit_target":
                            k = f"l2_negative_implicit_{cr['area']}"
                            row[k] = int(row.get(k, 0)) + int(cr["n"])
                    for g, ids in self.theta_groups.items():
                        row[f"theta_mean_{g}"] = float(a.theta_base[ids].mean())
                    st["rows"].append(row)
                    st["theta_history"].append(a.theta_base[lid].detach().to("cpu").numpy().astype(np.float32))
                    st["batch_signs"].append(sign.detach().to("cpu").numpy())
                    st["n_commits"] += int(n_commit)
                    self._write_jsonl(flow_path, ep["flow"], {})
                    self._write_jsonl(cmp_path, ep["same_state"], {})
                    st["epoch"], st["next_batch"] = epoch, bi + 1
                    self._save_ckpt(cond, st)
                    done_batches += 1
                    self._progress({"condition": cond, "epoch": epoch, "batch": bi, "status": "batch_done"})
                    if stop_after_batches and done_batches >= stop_after_batches:
                        raise KeyboardInterrupt("stop_after_batches")
                th_e = a.theta_base.detach().to("cpu").numpy().astype(np.float32)
                prev = (np.asarray(st["epoch_end_theta"][-1]) if st["epoch_end_theta"]
                        else self.theta_init.detach().to("cpu").numpy())
                st["epoch_end_theta"].append(th_e)
                ev: dict[str, Any] = {"epoch": epoch,
                                      "theta_change_vs_previous_epoch": db_theta_epoch_metrics(prev, th_e, groups_np,
                                                                                               lo=lo, hi=hi)}
                ev["theta_distribution"] = tl_group_stats(th_e, groups_np, lo=lo, hi=hi)
                prev2 = (np.asarray(st["epoch_end_theta"][-3]) if len(st["epoch_end_theta"]) >= 3
                         else self.theta_init.detach().to("cpu").numpy()) if len(st["epoch_end_theta"]) >= 2 else None
                if prev2 is not None:
                    s_now = np.sign(np.asarray(th_e, np.float64) - np.asarray(prev, np.float64))
                    s_old = np.sign(np.asarray(prev, np.float64) - np.asarray(prev2, np.float64))
                    ev["sign_flips_vs_previous_epoch"] = {g: int(((s_now[ids] * s_old[ids]) < 0).sum())
                                                          for g, ids in groups_np.items()}
                else:
                    ev["sign_flips_vs_previous_epoch"] = None
                for split in (("train", "dev") if self.dbs["eval_train_each_epoch"] else ("dev",)):
                    e_ = self._evaluate(self.sel[split], split=split, cond=cond, phase=f"epoch_{epoch}")
                    self._latency_rows.extend(e_.pop("latency", []) or [])
                    ev[split] = e_
                if self.dbs["diagnostic_each_epoch"]:
                    self._latency_rows.extend(self._evaluate_diagnostic(cond, f"epoch_{epoch}"))
                st["epoch_evals"].append(ev)
                dce = (ev.get("dev") or {}).get("cross_entropy")
                if self.dbs["selection_rule"] == "last_epoch":
                    st["selection"] = {"rule": "last_epoch", "epoch": epoch, "dev_ce": dce,
                                       "note_ko": "마지막 에폭을 고른다. dev 는 선택에 쓰지 않았다."}
                elif dce is not None and (st["selection"].get("dev_ce") is None or dce < st["selection"]["dev_ce"]):
                    st["selection"] = {"rule": "best_dev_ce", "epoch": epoch, "dev_ce": dce,
                                       "note_ko": "dev CE 최소 에폭 (dev 를 선택에 썼다)."}
                st["epoch"], st["next_batch"] = epoch + 1, 0
                self._save_ckpt(cond, st)
        except KeyboardInterrupt as exc:
            status, reason = "interrupted", f"{cond}: {exc or '사용자 중단'}"
        timing = self._timer_end(tm)
        if cuda:
            gpu_peak = max(gpu_peak, int(t.cuda.max_memory_allocated()))
        timing["peak_gpu_memory_bytes_train_batches"] = gpu_peak if cuda else None
        timing["settles"] = int(net.path_log["settles"] - settles0)
        theta_now = a.theta_base.detach().clone()
        sel_info = dict(st["selection"])
        if status == "completed" and st["epoch_end_theta"] and sel_info.get("epoch") is not None:
            k = [int(e["epoch"]) for e in st["epoch_evals"]].index(int(sel_info["epoch"]))
            selected = t.tensor(st["epoch_end_theta"][k], dtype=m.dtype, device=m.device)
            self._save_selected(cond, selected, sel_info)
        else:
            selected, sel_info = theta_now, {"rule": "none (미완료)", "epoch": None}
        d = theta_now - self.theta_init
        lid_np = lid.detach().to("cpu").numpy()
        epoch_signs, prev = [], self.theta_init.detach().to("cpu").numpy()
        for th_e in st["epoch_end_theta"]:
            epoch_signs.append(np.sign(np.asarray(th_e)[lid_np] - prev[lid_np]).astype(np.int64))
            prev = np.asarray(th_e)
        flips_epoch = tl_sign_flips(np.asarray(epoch_signs)) if epoch_signs else np.zeros(lid_np.size, np.int64)
        flips_batch = (tl_sign_flips(np.asarray(st["batch_signs"]).astype(np.int64)) if st["batch_signs"]
                       else np.zeros(lid_np.size, np.int64))
        th_np = theta_now.detach().to("cpu").numpy()
        init_np = self.theta_init.detach().to("cpu").numpy()
        res = {"condition": cond, "policy": pol.to_dict(), "status": status, "reason": reason,
               "epochs_planned": n_epochs, "n_batches_per_epoch": nb, "n_train": len(train), "rows": st["rows"],
               "epoch_evals": st["epoch_evals"], "n_commits": st["n_commits"], "timing": timing,
               "selection": sel_info,
               "theta_change": {"mean_abs_mV": float(d.abs().mean()), "max_abs_mV": float(d.abs().max()),
                                "n_changed": int((d != 0).sum()), "n_up": int((d > 0).sum()), "n_down": int((d < 0).sum()),
                                "n_changed_outside_mask": int(((d != 0) & ~mask).sum()),
                                "outside_mask_bitwise_equal": bool(t.equal(theta_now[~mask], self.theta_init[~mask])),
                                "unchanged_exactly": bool(t.equal(theta_now, self.theta_init)),
                                "by_group": db_theta_epoch_metrics(init_np, th_np, groups_np, lo=lo, hi=hi)},
               "theta_initial_by_group": tl_group_stats(init_np, groups_np, lo=lo, hi=hi),
               "theta_final_by_group": tl_group_stats(th_np, groups_np, lo=lo, hi=hi),
               "sign_flips": {"per_epoch_mean": float(flips_epoch.mean()) if flips_epoch.size else 0.0,
                              "per_epoch_neurons_flipped": int((flips_epoch > 0).sum()),
                              "per_batch_mean": float(flips_batch.mean()) if flips_batch.size else 0.0,
                              "per_batch_neurons_flipped": int((flips_batch > 0).sum())},
               "preparation_signatures_unchanged": self.cal.signatures() == self.prep_sig,
               "numeric_log": dict(net.numeric_log)}
        self._tl_arrays[cond] = {"theta_history": np.asarray(st["theta_history"], np.float32).reshape(-1, lid_np.size),
                                 "theta_final": th_np.astype(np.float32),
                                 "theta_selected": selected.detach().to("cpu").numpy().astype(np.float32),
                                 "epoch_end_theta": np.asarray(st["epoch_end_theta"], np.float32).reshape(-1, th_np.size),
                                 "flips_epoch": flips_epoch, "flips_batch": flips_batch}
        self._selected[cond] = selected
        cdir = ensure_writable_dir(self.run_dir / "conditions")
        write_json(cdir / f"{safe_name(cond)}.json", {k: v for k, v in res.items() if k != "rows"})
        return res

    # ------------------------------------------------------------------ 작업
    def _estimate(self) -> dict[str, Any]:
        n_prep = (len(self.sel["train"]) if not int(self.pre.get("prep_max_samples") or 0)
                  else min(len(self.sel["train"]), int(self.pre["prep_max_samples"])))
        return {**db_estimate(n_conditions=len(self.db_conditions), n_train=len(self.sel["train"]),
                              n_dev=len(self.sel["dev"]), batch_size=int(self.pre["batch_size"]),
                              epochs=int(self.pre["epochs"]), K=int(self.dbs["learning"]["K_rounds"]), n_prep=n_prep,
                              n_diag_stimuli=len(self.dbs["diagnostic_stimuli"]), steps=self.obs_steps,
                              eval_train_each_epoch=bool(self.dbs["eval_train_each_epoch"]),
                              diagnostic_each_epoch=bool(self.dbs["diagnostic_each_epoch"])),
                "model_memory": self.model.memory_estimate(1, int(self.pre["batch_size"])),
                "split_sizes": {k: len(v) for k, v in self.sel.items()},
                "split_labels": {k: {lab: sum(1 for s in v if s.label == lab) for lab in sorted({s.label for s in v})}
                                 for k, v in self.sel.items()},
                "excluded_public_test": len(self.excluded_test),
                "policies": db_policy_table(self.dbs),
                "theta_check": {"init_mV": self.dbs["theta"]["init_mV"], "min_mV": self.dbs["theta"]["min_mV"],
                                "max_mV": self.dbs["theta"]["max_mV"],
                                "downward_learning_possible": float(self.dbs["theta"]["min_mV"])
                                < float(self.dbs["theta"]["init_mV"]),
                                "engine_theta_min_mV": float(self.model.engine.theta_min)},
                "device": str(self.runner.device), "cuda": str(self.runner.device).startswith("cuda")}

    def run_inspect(self) -> dict[str, Any]:
        """회로·정책·학습 대상·분할·예상 계산량 (신경망 실행 없음)."""
        self.run_tag = self._run_tag_given or "deadband_inspect"
        self._db_open("inspect")
        est = self._estimate()
        write_json(self.run_dir / "plan.json", est)
        self.tl_exec["inspect"] = "completed"
        return self._db_finish({"estimate": est, "network": self.net.describe()}, {}, "completed", "")

    def run_train(self, *, stop_after_batches: int = 0) -> dict[str, Any]:
        """smoke / main: 준비 -> 공통 초기 평가 -> 조건별 학습 (에폭 끝 teacher-free train/dev) -> 선택 theta 진단."""
        if self._run_tag_given is None:
            self.run_tag = (f"deadband_resume_{self.dbs['run_preset']}" if self.resume_from is not None
                            else f"deadband_{self.dbs['run_preset']}")
        self._db_open(self.dbs["run_preset"])
        est = self._estimate()
        write_json(self.run_dir / "plan.json", est)
        sc = est["settle_calls"]
        msg = (f"[{self.dbs['run_preset']}] 조건 {self.db_conditions}, train {est['split_sizes']['train']} / dev "
               f"{est['split_sizes']['dev']} (공개 test {est['excluded_public_test']}개는 쓰지 않음), 에폭 {est['epochs']}, "
               f"배치/에폭 {est['n_batches_per_epoch']}, K={est['K_rounds']}, 학습 settle {est['train_settles_formula']}, "
               f"평가·진단 settle {sc['evaluation_and_diagnostic']}, 준비 {sc['preparation']}, 장치 {self.runner.device}. "
               f"theta 초기 {self.dbs['theta']['init_mV']} / 하한 {self.dbs['theta']['min_mV']} mV. 실행할까?")
        if not self.confirm(msg):
            return self._db_finish({"estimate": est}, {}, "cancelled", "실행 전 취소")
        self._latency_rows: list[dict[str, Any]] = []
        self._tl_arrays: dict[str, dict[str, np.ndarray]] = {}
        self._selected: dict[str, Any] = {}
        if getattr(self, "_resume_hook", None) is not None:
            self._resume_hook()
        prep = self._tl_prepare()
        if prep.get("status") not in ("completed", "reused_for_resume"):
            self.tl_exec["preparation"] = prep.get("status")
            return self._db_finish({"estimate": est, "preparation": prep}, {}, "insufficient_signal",
                                   "준비 단계에서 IT 신호 부족 (학습을 시작하지 않는다)")
        self.tl_exec["preparation"] = "completed"
        evaluation: dict[str, Any] = {"initial": {}, "epochs": {}, "selected": {}, "diagnostic": {},
                                      "test": {"status": DB_NOT_RUN, "reason_ko": "개발 실행은 train/dev 만 쓴다."},
                                      "holdout": {"status": DB_NOT_RUN, "reason_ko": "메뉴 21-7 에서 확정 뒤 별도 실행"}}
        a = self.model.neurons
        a.theta_base.copy_(self.theta_init)
        for split in (("train", "dev") if self.dbs["eval_train_each_epoch"] else ("dev",)):
            e_ = self._evaluate(self.sel[split], split=split, cond="(shared_initial)", phase="initial")
            self._latency_rows.extend(e_.pop("latency"))
            evaluation["initial"][split] = e_
        self._latency_rows.extend(self._evaluate_diagnostic("(shared_initial)", "initial"))
        results: dict[str, Any] = {}
        status, reason = "completed", ""
        for ci, cond in enumerate(self.db_conditions):
            self.say(f"[조건 {ci + 1}/{len(self.db_conditions)}] {cond}")
            self._progress({"condition": cond, "status": "running", "policy": self.policies[cond].to_dict()})
            resume = self._load_ckpt(cond, self.resume_from) if self.resume_from is not None else None
            g = lat_guard(cond, lambda c=cond, r=resume: self._train_condition(
                c, stop_after_batches=stop_after_batches, resume=r))
            if g["status"] != "completed":
                results[cond] = {"condition": cond, "status": g["status"],
                                 **{k: v for k, v in g.items() if k not in ("result", "status")}}
                status, reason = ("failed" if g["status"] == "failed" else "interrupted"), f"{cond}: {g.get('reason_ko')}"
                break
            res = g["result"]
            results[cond] = res
            evaluation["epochs"][cond] = res["epoch_evals"]
            if res["status"] != "completed":
                status, reason = res["status"], res["reason"]
                break
        a.theta_base.copy_(self.theta_init)
        self.tl_exec["train"] = status
        if status == "completed":
            for cond in self.db_conditions:
                a.theta_base.copy_(self._selected[cond])
                e_ = self._evaluate(self.sel["dev"], split="dev", cond=cond, phase="selected")
                self._latency_rows.extend(e_.pop("latency"))
                evaluation["selected"][cond] = {**e_, "selection": results[cond]["selection"]}
                self._latency_rows.extend(self._evaluate_diagnostic(cond, "selected"))
            a.theta_base.copy_(self.theta_init)
            self.tl_exec["selected_dev_and_diagnostic"] = "completed"
        return self._db_write_results(results, evaluation, est, prep, status, reason)

    # ------------------------------------------------------------------ 기록
    def _db_write_results(self, results: dict[str, Any], evaluation: dict[str, Any], est: dict[str, Any],
                          prep: dict[str, Any], status: str, reason: str) -> dict[str, Any]:
        rows = [r for c in results.values() for r in (c.get("rows") or [])]
        _write_rows_csv(self.run_dir / "train_history.csv", rows)
        _write_rows_csv(self.run_dir / "latency_summary.csv", self._latency_rows)
        stage_rows = [{k: v for k, v in r.items() if k.startswith(("condition", "phase", "split", "group", "n_neurons",
                                                                   "active_fraction", "spikes_", "n_fired",
                                                                   "n_input", "n_no_input", "first_"))}
                      for r in self._latency_rows]
        _write_rows_csv(self.run_dir / "stage_metrics.csv", stage_rows)
        arrs: dict[str, np.ndarray] = {"learn_neuron_ids": self.learn_ids.detach().to("cpu").numpy(),
                                       "theta_init": self.theta_init.detach().to("cpu").numpy().astype(np.float32)}
        for c, d in self._tl_arrays.items():
            for k, v in d.items():
                arrs[f"{c}__{k}"] = np.asarray(v)
        np.savez_compressed(self.run_dir / "neuron_threshold_history.npz", **arrs)
        write_json(self.run_dir / "evaluation.json", evaluation)
        flow = db_flow_summary(self.run_dir / "correction_flow.jsonl")
        write_json(self.run_dir / "correction_flow_summary.json", flow)
        cmp_ = db_same_state_summary(self.run_dir / "same_state_policy_comparison.jsonl")
        write_json(self.run_dir / "same_state_policy_comparison.json", cmp_)
        checks = self._db_auto_checks(results, evaluation)
        metrics = {"estimate": est, "conditions": {c: {k: v for k, v in r.items() if k != "rows"}
                                                    for c, r in results.items()},
                   "preparation_status": prep.get("status"), "path_log": self.net.path_log,
                   "log_bytes_jsonl": self._log_bytes, "flow_detail": self.dbs["flow_detail"]}
        return self._db_finish(metrics, checks, status, reason)

    def _db_auto_checks(self, results: dict[str, Any], evaluation: dict[str, Any]) -> dict[str, Any]:
        """학습 실행 기록으로 판정할 수 있는 항목만 (나머지 DB 검사는 메뉴 21-2 에서 NOT_RUN 이 아니게 된다)."""
        done = {c: r for c, r in results.items() if r.get("status") == "completed"}
        ch: dict[str, Any] = {}
        for k in ("DB1", "DB2", "DB3", "DB4", "DB5", "DB6", "DB7", "DB9", "DB11"):
            ch[k] = {"status": DB_NOT_RUN, "reason_ko": "메뉴 21-2 (사전 검증) 에서 실행한다."}
        ok_mask = bool(done) and all(r["theta_change"]["outside_mask_bitwise_equal"] for r in done.values())
        fz = [done[c] for c in ("frozen", "zero_teacher_unfiltered") if c in done]
        ok_fz = bool(fz) and all(r["theta_change"]["unchanged_exactly"] for r in fz)
        ok_commit = bool(done) and all(row["n_commit_calls"] == (0 if self.policies[c].freeze else 1)
                                       for c, r in done.items() for row in r["rows"])
        ok_post = bool(done) and all(row.get("post_theta_fast_zero") for r in done.values() for row in r["rows"])
        ok_fast = bool(done) and all((row.get("theta_fast_final_max_abs") or 0.0)
                                     <= float(self.dbs["theta"]["fast_bound_mV"]) + 1e-6
                                     for r in done.values() for row in r["rows"])
        ch["DB8"] = {"status": (DB_NOT_RUN if not done else DB_PASSED if (ok_mask and ok_fz and ok_commit and ok_post
                                                                            and ok_fast) else DB_FAILED),
                     "outside_mask_bitwise_equal": ok_mask, "frozen_zero_teacher_unchanged": ok_fz,
                     "commit_once_per_batch": ok_commit, "post_theta_fast_zero": ok_post,
                     "theta_fast_within_bound": ok_fast, "source": "학습 실행 기록 (메뉴 21-2 에 별도 무작위 commit 검사)",
                     "criterion": "마스크 밖 불변, |theta_fast| <= fast_bound, 배치당 commit 1회(frozen 0), frozen/zero 불변, post theta_fast 0"}
        evs = [v for v in (evaluation.get("initial") or {}).values() if isinstance(v, dict)]
        evs += [e[s] for v in (evaluation.get("epochs") or {}).values() for e in (v or []) for s in ("train", "dev")
                if isinstance(e.get(s), dict)]
        evs += [v for v in (evaluation.get("selected") or {}).values() if isinstance(v, dict)]
        pl = self.net.path_log
        ok10 = (pl["gate_identity_violations"] == 0 and self.audit["C2_cycles"]["status"] == PFF_PASSED
                and tuple(self.window) == (int(math.ceil(64.0 / self.dt - 1e-9)), int(math.ceil(160.0 / self.dt - 1e-9)))
                and all(e.get("purity_preserved") for e in evs))
        ch["DB10"] = {"status": DB_NOT_RUN if not evs else (DB_PASSED if ok10 else DB_FAILED),
                      "settles": pl["settles"], "gate_violations": pl["gate_identity_violations"],
                      "dag": self.audit["C2_cycles"]["status"], "readout_window_steps": list(self.window),
                      "n_evaluations_purity_checked": len(evs),
                      "tail_rows_forced_zero_events": pl["drive_tail_nonzero_rows_zeroed"],
                      "criterion": "모든 settle 같은 F0r 마스크·DAG, 판독 창 [64,160), 평가 전후 상태 불변 (입력 160 ms 뒤 0 은 21-2)"}
        return {"format": DB_FORMAT, "checks": ch,
                "note_ko": "성능 향상은 통과 조건이 아니다. 메뉴 21-2 검증 결과는 그 실행 폴더의 checks.json 에 있다."}

    def _db_finish(self, metrics: dict[str, Any], checks: dict[str, Any], status: str, reason: str) -> dict[str, Any]:
        eng = self.model.engine
        metrics = {"format": DB_FORMAT, "task": self.task, "status": status, "reason": reason, "version": __version__,
                   "run_preset": self.dbs["run_preset"], "dt_ms": getattr(self, "dt", None),
                   "windows_ms": [list(w) for w in TL_WINDOWS_MS], "top_area": getattr(self, "top_area", None),
                   "conditions_planned": self.db_conditions, "policies": db_policy_table(self.dbs),
                   "selection_rule": self.dbs["selection_rule"], "executed": dict(self.tl_exec),
                   "test_access": self.runner.test_access, "split_access": self.runner.split_access, **metrics}
        metrics["run_integrity"] = {"fixed_parameters": self.model.verify_fixed_unchanged(),
                                    "theta_base_restored_to_initial": bool(
                                        require_torch().equal(self.model.neurons.theta_base, self.theta_init))
                                    if hasattr(self, "theta_init") else None}
        write_json(self.run_dir / "metrics.json", metrics)
        if checks:
            write_json(self.run_dir / "checks.json", checks)
        ta_path = self.run_dir / "test_access.json"
        ta = read_json(ta_path) if ta_path.is_file() else {}
        ta.update({"format": DB_FORMAT, "test_access": self.runner.test_access,
                   "split_access_counts": {k: {"n_accesses": v["n_accesses"], "n_samples_seen": v["n_samples_seen"]}
                                           for k, v in self.runner.split_access.items()},
                   "note_ko": ("개발 실행(smoke/main/검증)은 공개 test 와 holdout 을 열지 않는다 (n_test_evaluations 0 이어야 함). "
                               "holdout 평가는 메뉴 21-7 에서만 하며 반복 평가는 독립 시험이 아니다.")})
        write_json(ta_path, ta)
        if hasattr(self, "engine_theta_bounds_before"):
            eng.theta_min, eng.theta_max = self.engine_theta_bounds_before
        mf = self.runner.recorder.manifest.get("deadband_ablation")
        if mf is not None:
            mf["executed"] = dict(self.tl_exec)
            mf["status"] = status
            mf["files"] = sorted(str(p.relative_to(self.run_dir)) for p in self.run_dir.rglob("*") if p.is_file())
        self._progress({"event": "task_end", "task": self.task, "status": status, "reason": reason})
        self._close(status, reason)
        out = {"status": status, "reason": reason, "run_dir": str(self.run_dir)}
        try:
            out["figures"] = make_db_figures(self.run_dir)
        except Exception as exc:                                    # noqa: BLE001
            out["figures_error"] = f"{type(exc).__name__}: {exc}"
        try:
            out["report"] = str(build_db_report(self.run_dir))
        except Exception as exc:                                    # noqa: BLE001
            out["report_error"] = f"{type(exc).__name__}: {exc}"
        return out

    # ------------------------------------------------------------------ 재개
    def _copy_resume_flow(self) -> None:
        """원 실행의 jsonl 기록 중 체크포인트까지 완료된 배치만 옮긴다 (중복 기록 방지)."""
        if self.resume_from is None:
            return
        lim: dict[str, tuple[int, int]] = {}
        for cond in self.db_conditions:
            jp = self.resume_from / "checkpoints" / safe_name(cond) / "latest.json"
            if jp.is_file():
                mt = read_json(jp)
                lim[cond] = (int(mt["epoch"]), int(mt["next_batch"]))
        for name in ("correction_flow.jsonl", "same_state_policy_comparison.jsonl"):
            src = self.resume_from / name
            if not src.is_file():
                continue
            with src.open("r", encoding="utf-8") as fi, (self.run_dir / name).open("a", encoding="utf-8") as fo:
                for line in fi:
                    r = json.loads(line)
                    e, nb = lim.get(r.get("condition"), (-1, 0))
                    if (int(r["epoch"]), int(r["batch"])) < (e, nb):
                        fo.write(line)
                        self._log_bytes += len(line.encode("utf-8"))

    def run_resume(self) -> dict[str, Any]:
        if self.resume_from is None or not (self.resume_from / "checkpoints").is_dir():
            raise ValueError("재개할 실행 폴더(checkpoints 포함)가 필요하다.")
        if not (self.resume_from / "checkpoints" / "preparation_state.json").is_file():
            raise ValueError("원 실행에 준비 상태(checkpoints/preparation_state.json)가 없다. 재개할 수 없다.")
        old = read_json(self.resume_from / "config_effective.json").get("deadband_ablation", {})
        if not old.get("settings"):
            raise ValueError("메뉴 21 실행 폴더가 아니다 (config_effective.json 에 deadband_ablation 설정이 없다).")
        if db_settings_sha(validate_db_settings(old["settings"])) != db_settings_sha(self.dbs):
            raise ValueError("원 실행과 설정이 다르다. 같은 설정으로만 재개한다 (조용히 이어 붙이지 않는다).")
        self._resume_hook = self._copy_resume_flow
        return self.run_train()


# ---------------------------------------------------------------------- 저장 기록 요약 (보고서·재생성 공용)
def db_flow_summary(path: Path) -> dict[str, Any]:
    """correction_flow.jsonl -> (조건, 에폭, 영역, 층, 채널, 단계) 별 합계. None 은 합산하지 않고 '미측정' 으로 남긴다."""
    path = Path(path)
    out: dict[str, Any] = {"format": DB_FORMAT, "groups": {}, "causes_by_condition": {}, "n_records": 0}
    if not path.is_file():
        out["status"] = DB_NOT_RUN
        return out
    groups: dict[str, dict[str, Any]] = {}
    causes: dict[str, dict[str, int]] = {}
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            r = json.loads(line)
            out["n_records"] += 1
            key = "|".join(str(r.get(k)) for k in ("condition", "epoch", "area", "layer", "channel", "stage"))
            g = groups.setdefault(key, {k: r.get(k) for k in ("condition", "epoch", "area", "layer", "channel", "stage")})
            g["records"] = g.get("records", 0) + 1
            for k in ("n_nonzero", "n_deficit", "n_excess"):
                if r.get(k) is not None:
                    g[k] = g.get(k, 0) + int(r[k])
                else:
                    g.setdefault(k, None)
            if r.get("norm") is not None:
                g["norm_sq_sum"] = g.get("norm_sq_sum", 0.0) + float(r["norm"]) ** 2
                g["max_abs"] = max(float(g.get("max_abs") or 0.0), float(r.get("max_abs") or 0.0))
                g["n_measured"] = g.get("n_measured", 0) + 1
            else:
                g["n_unmeasured"] = g.get("n_unmeasured", 0) + 1
            for k, v in r.items():
                if k.startswith("n_") and k not in ("n_nonzero", "n_deficit", "n_excess") and v is not None \
                        and isinstance(v, (int, float)):
                    g[k] = g.get(k, 0) + int(v)
                    if k in DB_CAUSE_KEYS:
                        cc = causes.setdefault(str(r.get("condition")), {})
                        cc[f"{r.get('area')}|{r.get('layer')}|{k}"] = cc.get(f"{r.get('area')}|{r.get('layer')}|{k}", 0) + int(v)
    for g in groups.values():
        if "norm_sq_sum" in g:
            g["norm_total"] = math.sqrt(g.pop("norm_sq_sum"))
    out["groups"] = groups
    out["causes_by_condition"] = causes
    out["cause_keys_ko"] = DB_CAUSE_KO
    out["stages_ko"] = DB_FLOW_STAGES_KO
    out["note_ko"] = ("노름은 배치별 노름의 제곱합 제곱근(전체 좌표 노름)이다. 기록이 없거나 None 인 단계는 '미측정' 이며 "
                      "0 으로 합산하지 않았다. 원인 계수는 좌표 x 표본 단위.")
    return out


def db_same_state_summary(path: Path) -> dict[str, Any]:
    """same_state_policy_comparison.jsonl -> (조건, 에폭, 쌍, 영역, 벡터) 별 합계."""
    path = Path(path)
    out: dict[str, Any] = {"format": DB_FORMAT, "rows_by_group": {}, "n_records": 0,
                           "note_ko": ("같은 free 상태에서 정책별 교정 벡터만 계산한 크기 진단이다 (추가 신경망 실행 없음). "
                                       "손실 감소 방향의 증명이 아니다. L3 강도의 실제 적용값은 L2 수정 뒤 재실행이 필요해 "
                                       "여기서는 잔차 전 패킷(delta_L3_pre_residual)만 비교한다.")}
    if not path.is_file():
        out["status"] = DB_NOT_RUN
        return out
    g_all: dict[str, dict[str, Any]] = {}
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            r = json.loads(line)
            out["n_records"] += 1
            key = "|".join(str(r.get(k)) for k in ("condition", "epoch", "pair", "area", "vector"))
            g = g_all.setdefault(key, {k: r.get(k) for k in ("condition", "epoch", "pair", "policy_a", "policy_b",
                                                              "area", "vector")})
            g["records"] = g.get("records", 0) + 1
            for k in ("n_nonzero_a", "n_nonzero_b", "n_common", "n_new_in_b", "n_lost_in_b"):
                g[k] = g.get(k, 0) + int(r.get(k) or 0)
            for k in ("norm_a", "norm_b", "norm_a_common", "norm_b_common", "norm_b_new", "norm_a_lost"):
                g[f"{k}_sq"] = g.get(f"{k}_sq", 0.0) + float(r.get(k) or 0.0) ** 2
            g["dot_common"] = g.get("dot_common", 0.0) + float(r.get("dot_common") or 0.0)
    for g in g_all.values():
        for k in ("norm_a", "norm_b", "norm_a_common", "norm_b_common", "norm_b_new", "norm_a_lost"):
            g[k] = math.sqrt(g.pop(f"{k}_sq"))
        den = g["norm_a_common"] * g["norm_b_common"]
        g["cosine_common"] = (g["dot_common"] / den) if den > 0 else None
    out["rows_by_group"] = g_all
    return out


# ---------------------------------------------------------------------- 메뉴 21 보고서 · 그림 (저장 파일에서만)
DB_REPORT_CAUTIONS_KO: tuple[str, ...] = (
    "deadband 제거는 수정 대상 수와 기존 대상의 보폭(soft deadband 크기)을 함께 바꾼다. 완전 제거 조건이 좋아져도 "
    "방향 정보가 개선됐다고 단정하지 않는다.",
    "개선이 없어도 생물학적 하향식 학습 전체가 불가능하다는 결론을 내리지 않는다. 이 실험은 특정 계산 모형의 한 규칙만 본다.",
    "자극 종료 후 발화가 남았다는 사실만으로 재귀 폭주라고 부르지 않는다. 물리 회로는 순전파 DAG 검사를 통과한 F0r 이며, "
    "종료 후 활동은 늦게 도착한 입력의 전달일 수 있고 무입력(no_input) 반응과 따로 본다.",
    "L1/L5/L6 의 역할 분담과 임계값 교정·deadband 는 이 프로그램의 계산 가정이다. 실제 뇌가 이 수식을 그대로 쓴다는 주장이 아니다.",
    "작은 교정값을 자동으로 수치 잡음이라고 부르지 않으며, 반대로 반드시 올바른 방향 정보가 있다고 가정하지도 않는다.",
    "단일 시드·소량 자료 결과는 탐색적이다. 다중 시드는 사용자가 따로 고른 경우에만 실행된다.",
    "deadband·teacher_tolerance 는 정규화 활동 단위, 발화 임계값은 mV 다. 둘을 같은 임계값으로 읽지 않는다.",
)


def _db_mean(xs: Sequence[Any]) -> float | None:
    v = [float(x) for x in xs if x is not None and x != "" and x != "None" and _lat_num(x) is not None]
    return (sum(v) / len(v)) if v else None


def _db_load_conditions(run_dir: Path) -> dict[str, dict[str, Any]]:
    out: dict[str, dict[str, Any]] = {}
    cdir = Path(run_dir) / "conditions"
    if cdir.is_dir():
        for p in sorted(cdir.glob("*.json")):
            try:
                c = read_json(p)
            except Exception:                                   # noqa: BLE001
                continue
            if isinstance(c, dict) and c.get("condition"):
                out[str(c["condition"])] = c
    return out


def _db_report_checks(A: Callable[[str], None], chk: dict[str, Any]) -> None:
    ov = chk.get("overall")
    parts = chk.get("parts") or chk.get("checks") or {}
    if ov:
        A("| 검사 | 종합 | 부분 상태 |")
        A("|---|---|---|")
        sub = {"DB1": ("DB1a_cpu_synthetic", "DB1b_circuit"), "DB6": ("DB6a_cpu_synthetic", "DB6b_circuit")}
        for k in sorted(ov, key=lambda s: int(s[2:])):
            ps = sub.get(k, (k,))
            A(f"| {k} | **{ov[k]}** | " + ", ".join(f"{p}: {(parts.get(p) or {}).get('status', DB_NOT_RUN)}" for p in ps)
              + " |")
        A("")
        d1a, d1b = parts.get("DB1a_cpu_synthetic") or {}, parts.get("DB1b_circuit") or {}
        A(f"- DB1a (CPU 합성, float32): 비교 {d1a.get('n_compared')}개 중 비트 일치 {d1a.get('n_bitwise_equal')}, 최대차 "
          f"{db_fmt(d1a.get('max_abs_diff'))} (허용오차 0).")
        A(f"- DB1b (작은 회로, 결정론): 비교 {db_fmt(d1b.get('n_compared'))}개 중 허용오차 {db_fmt(d1b.get('tolerance_abs'))} 안 "
          f"{db_fmt(d1b.get('n_within_tolerance'))}, 비트 일치 {db_fmt(d1b.get('n_bitwise_equal'))}, 최대차 "
          f"{db_fmt(d1b.get('max_abs_diff'))}, 상태 {d1b.get('status', DB_NOT_RUN)}.")
        d2 = parts.get("DB2") or {}
        for pn, row in (d2.get("policies") or {}).items():
            vals = ", ".join(f"{a}: relay {db_fmt(v.get('relay'))} / local {db_fmt(v.get('local'))} / L3 증분 "
                             f"{db_fmt(v.get('delta_L3_mV_max_abs'))} mV" for a, v in row.items() if isinstance(v, dict)
                             and "relay" in v)
            A(f"- DB2 {pn}: {vals}")
        d5 = parts.get("DB5") or {}
        if d5:
            A(f"- DB5: S_0.02(0.03) = {db_fmt(d5.get('S_0.02(0.03)'))}, S_0(0.03) = {db_fmt(d5.get('S_0(0.03)'))}, 같은 r 에서 "
              f"증분 비율 (d=0 / d=0.02) {db_fmt(d5.get('delta_ratio_d0_over_d0.02'))}, 격자 비영 증분 수 "
              f"{d5.get('grid_[-0.05,0.05]_101')}. {d5.get('note_ko', '')}")
        d11 = parts.get("DB11") or {}
        if d11:
            A(f"- DB11: theta 비트 일치 {db_fmt(d11.get('theta_bitwise_equal'))}, 최대차 {db_fmt(d11.get('theta_max_abs_diff_mV'))} mV, "
              f"불일치 거부 {d11.get('mismatch_refused')}, 장치 {d11.get('device')}")
        failed = [k for k, v in parts.items() if isinstance(v, dict) and v.get("status") == DB_FAILED]
        if failed:
            A(f"- **FAILED 부분**: {failed} (근거는 checks.json 의 parts)")
    else:
        A("| 검사 | 상태 | 근거 |")
        A("|---|---|---|")
        for k in sorted(parts, key=lambda s: int(s[2:]) if s[2:].isdigit() else 99):
            v = parts[k] or {}
            A(f"| {k} | **{v.get('status', DB_NOT_RUN)}** | {v.get('reason_ko') or v.get('criterion') or ''} |")
    A("")


def build_db_report(run_dir: Path) -> Path:
    """저장된 JSON/CSV/NPZ 에서만 REPORT.md 를 만든다 (시뮬레이터·학습을 다시 실행하지 않는다)."""
    run_dir = Path(run_dir)
    mani = _inh_read(run_dir, "manifest.json") or {}
    cfg = (_inh_read(run_dir, "config_effective.json") or {}).get("deadband_ablation") or {}
    met = _inh_read(run_dir, "metrics.json") or {}
    chk = _inh_read(run_dir, "checks.json") or {}
    prep = _inh_read(run_dir, "preparation_report.json") or {}
    ev = _inh_read(run_dir, "evaluation.json") or {}
    split = _inh_read(run_dir, "data_split.json") or {}
    plan = _inh_read(run_dir, "plan.json") or (met.get("estimate") or {})
    flow = _inh_read(run_dir, "correction_flow_summary.json") or {}
    same = _inh_read(run_dir, "same_state_policy_comparison.json") or {}
    src = _inh_read(run_dir, "source_info.json") or {}
    tm = mani.get("deadband_ablation") or {}
    th_rows = _lat_csv(run_dir, "train_history.csv")
    lat = _lat_csv(run_dir, "latency_summary.csv")
    conds_saved = _db_load_conditions(run_dir)
    task = met.get("task") or tm.get("task") or "?"
    st = cfg.get("settings") or {}
    L: list[str] = []
    A = L.append
    A(f"# deadband 전달/갱신 분리 실험 보고서 — 작업 `{task}`")
    A("")
    A("> 이 폴더의 저장 결과(JSON/CSV/NPZ)에서 자동으로 만들었다. 시뮬레이터·학습을 다시 실행하지 않았다. 실행하지 않은 항목은 "
      "NOT_RUN, 기록되지 않은 값은 '미측정' 이며 0 으로 합산하지 않았다. 성공을 미리 가정하지 않았다.")
    A("")
    A("## 0. 상태")
    A("")
    A(f"- 상태 **{met.get('status', mani.get('experiment_status', '기록 없음(중단 추정)'))}**"
      + (f" — {met.get('reason')}" if met.get("reason") else "") + f", 실행 프리셋 `{met.get('run_preset')}`")
    A(f"- 실행한 단계: {met.get('executed') or tm.get('executed') or {}}")
    if met.get("run_preset") == "smoke" and task in ("smoke",):
        A("- **smoke** 실행이다. 연결·저장·재개 확인용이며 통계적 효과 판정용이 아니다.")
    A("- 단일 시드·소량 자료 결과는 탐색적이다." + (f" 이 실행의 시드 {tm.get('seed')}." if tm.get("seed") is not None else ""))
    A("")
    A("## 1. 실행 정보·구현 경로")
    A("")
    code = src.get("code") or tm.get("code") or {}
    bs = src.get("base_source") or tm.get("base_source") or DB_BASE_SOURCE
    A(f"- 코드 {code.get('file', 'n/a')} (버전 {src.get('version') or tm.get('version')}), SHA256 {code.get('sha256', 'n/a')}")
    A(f"- 기준 소스 {bs.get('file')} (내부 {bs.get('internal_version')}), SHA256 {bs.get('sha256')}. {bs.get('note_ko', '')}")
    A(f"- 장치 {src.get('device') or tm.get('device')} (CUDA 사용 {_thr_yes(src.get('cuda_used', tm.get('cuda_used')))}, GPU "
      f"{src.get('gpu') or tm.get('gpu')}), 결정론 합산 {_thr_yes(tm.get('deterministic'))}, 라이브러리 "
      f"{src.get('library_versions') or tm.get('library_versions')}")
    A(f"- 명령 `{src.get('command') or tm.get('command')}`")
    A(f"- 구조 `{tm.get('structure')}` (입력 보완 {(tm.get('input_repair') or {}).get('status')}), 마스크 SHA256 "
      f"{tm.get('mask_sha256')}")
    A("")
    A("| 단계 | 실제 사용 클래스 |")
    A("|---|---|")
    for r in tm.get("implementation_chain") or DB_IMPLEMENTATION_CHAIN:
        A(f"| {r['step']} | {r['class']} |")
    A("")
    A("기존 경로에서 바꾼 점 (이 실험에서만, 실제 설정값으로 기록):")
    A("")
    for x in tm.get("implementation_changes") or cfg.get("implementation_changes") or []:
        A(f"- {x}")
    A("")
    A("## 2. 설정 (모든 비교 조건 공통, 실제 해석된 값)")
    A("")
    A(f"- {cfg.get('units_ko', DB_UNITS_KO)}")
    te = cfg.get("theta_effective") or {}
    A(f"- 임계값 (mV): 학습 대상 L2/L3 초기 {te.get('init_L2_L3_mV')}, 범위 [{te.get('controller_min_mV')}, "
      f"{te.get('controller_max_mV')}], L4 고정 {te.get('L4_fixed_mV')}, 임시 변화 ±{te.get('fast_bound_mV')}, 엔진 "
      f"theta_min/max {te.get('engine_theta_min_mV')}/{te.get('engine_theta_max_mV')} (실험 전 {te.get('engine_bounds_before')}). "
      f"하향 학습 가능 {_thr_yes(te.get('downward_learning_possible'))}.")
    le = cfg.get("learning_effective") or st.get("learning") or {}
    A(f"- 학습: kappa L2 {le.get('kappa_L2_mV')} / L3 {le.get('kappa_L3_mV')} mV, eta_commit {le.get('eta_commit')}, beta "
      f"{le.get('beta')} (영역 간 동일), error_scale {le.get('error_scale')}, K {le.get('K_rounds')}, gate "
      f"{le.get('teacher_gate_rule')}, 교사 {le.get('teacher_policy')}, 조기 종료 {_thr_yes(le.get('early_stop'))}, target clip "
      f"{cfg.get('target_clip')}")
    dbd = st.get("deadband") or {}
    A(f"- teacher_tolerance {dbd.get('teacher_tolerance')} (모든 조건 같은 값), legacy deadband {dbd.get('legacy_deadband')}. "
      "자동 조정 없음.")
    A("")
    A("| 조건 | relay_deadband | update_deadband | teacher_tolerance | 학습 | 설명 |")
    A("|---|---:|---:|---:|---|---|")
    for p in cfg.get("policies") or met.get("policies") or []:
        learn = "동결" if p.get("freeze") else ("교사 0 강제" if p.get("zero_teacher") else
                                               ("위치 섞기" if p.get("shuffle") else "학습"))
        A(f"| {p['name']} | {p['relay_deadband']} | {p['update_deadband']} | {p['teacher_tolerance']} | {learn} | "
          f"{p.get('description_ko', '')} |")
    A("")
    A(f"- 주 비교: {cfg.get('main_contrasts')}")
    A(f"- 시간창: 활동·목표·분류기 [64,160) ms (step {cfg.get('readout_window_steps')}, 분모 {cfg.get('readout_window_s')} s), "
      f"자극 {cfg.get('stimulus_steps')} step, 관측 {cfg.get('observation_steps')} step. 종료 후 창은 진단용.")
    A(f"- 선택 규칙 `{st.get('selection_rule')}`"
      + (" — 마지막 에폭을 고른다. dev 를 선택에 쓰지 않았다." if st.get("selection_rule") == "last_epoch" else
         " — dev CE 최소 에폭 (dev 를 선택에 썼다)."))
    A("")
    if plan:
        sc = plan.get("settle_calls") or {}
        A(f"- 예상 계산량: {plan.get('train_settles_formula')} 학습 settle, 평가·진단 {sc.get('evaluation_and_diagnostic')}, "
          f"준비 {sc.get('preparation')}, 총 {sc.get('total')} settle, 물리 step {plan.get('physical_steps_total')}. "
          f"{plan.get('note_ko', '')}")
        A("")
    A("## 3. 분할·준비·교사 관측 공백")
    A("")
    for k in ("train", "dev"):
        s = split.get(k) or {}
        A(f"- {k}: {s.get('n')}개, 원본 {len(s.get('base_ids') or [])}개, 클래스별 {s.get('labels')}")
    ex = split.get("excluded_public_test") or {}
    A(f"- 개발에서 제외한 공개 test: {ex.get('n')}개 (원본 {len(ex.get('base_ids') or [])}개). 분할 겹침: {split.get('base_overlap')}")
    A(f"- 준비 상태 {prep.get('status')}, 표본 {prep.get('n_preparation_samples_used')}, 준비 중 theta 불변 "
      f"{_thr_yes(prep.get('theta_base_unchanged_by_preparation'))}")
    cov = prep.get("coverage_summary") or {}
    for pn, d in (cov.get("by_policy") or {}).items():
        A("")
        A(f"관측 공백 — 정책 `{pn}` (양의 목표 기준 {cov.get('coverage_positive_threshold')}, 정규화 활동 단위):")
        A("")
        A("| 영역/층 | 뉴런 | 늘 침묵 | 양의 목표 없음 | 늘 침묵 + 양의 목표 없음 | 침묵 부족 후보 사건 | L2 암묵적 목표 음수 사건 |")
        A("|---|---:|---:|---:|---:|---:|---:|")
        for g, r in (d.get("by_group") or {}).items():
            A(f"| {g} | {r['n_neurons']} | {r['n_never_active']} | {r['n_without_positive_target']} | "
              f"{r['n_always_silent_no_positive_target']} | {r['n_silent_deficit_candidate_events']} | "
              f"{r['n_negative_implicit_target_events'] if g.endswith('L2') else '해당 없음'} |")
    A("")
    A("## 4. 사전 검증")
    A("")
    if chk:
        _db_report_checks(A, chk)
        A(chk.get("note_ko", ""))
    else:
        A("- checks.json 없음 (미측정).")
    A("")
    if task == "holdout":
        _db_report_holdout(A, run_dir, ev, met)
    elif th_rows or conds_saved:
        _db_report_train(A, run_dir, th_rows, conds_saved, ev, lat, flow, same, met, cfg, prep)
    else:
        A("## 5. 학습 결과")
        A("")
        A("- 이 작업은 학습을 하지 않았다 (inspect / check / 취소). 질문 1~5 의 판정 재료가 없다 (미측정).")
        A("")
    A("## 해석 주의 (고정 문구)")
    A("")
    for c in DB_REPORT_CAUTIONS_KO:
        A(f"- {c}")
    A("")
    A("## 실행하지 않은 항목 / 미측정")
    A("")
    nr = []
    for k, v in ((chk.get("overall") or {}).items() if chk.get("overall") else
                 ((k_, (v_ or {}).get("status")) for k_, v_ in (chk.get("checks") or {}).items())):
        if v == DB_NOT_RUN:
            nr.append(k)
    A(f"- NOT_RUN 검사: {nr or '없음'}")
    for k in ("test", "holdout"):
        e = ev.get(k) if isinstance(ev, dict) else None
        if isinstance(e, dict) and e.get("status") == DB_NOT_RUN:
            A(f"- {k}: NOT_RUN — {e.get('reason_ko', '')}")
    A("")
    out = run_dir / "REPORT.md"
    out.write_text("\n".join(L) + "\n", encoding="utf-8")
    return out


def _db_report_train(A: Callable[[str], None], run_dir: Path, th_rows: list[dict[str, Any]],
                     conds: dict[str, dict[str, Any]], ev: dict[str, Any], lat: list[dict[str, Any]],
                     flow: dict[str, Any], same: dict[str, Any], met: dict[str, Any], cfg: dict[str, Any],
                     prep: dict[str, Any]) -> None:
    order = list(cfg.get("conditions") or conds.keys())
    areas = sorted({k[len("reach_relay_"):] for r in th_rows[:1] for k in r if k.startswith("reach_relay_")},
                   key=lambda a: ["V1", "V2", "V3", "V4", "IT"].index(a) if a in ("V1", "V2", "V3", "V4", "IT") else 9)
    causes = flow.get("causes_by_condition") or {}

    def cause(c: str, area: str, layer: str, key: str) -> Any:
        v = (causes.get(c) or {}).get(f"{area}|{layer}|{key}")
        return v
    A("## 5. 질문 1 — 교정 신호가 V2/V1 까지 도달했는가")
    A("")
    A("도달 = 그 영역의 전달용 교정 e_relay 가 비영인 표본 비율 (라운드 0, 배치 평균). 도달·요청·적용은 다른 단계다.")
    A("")
    A("| 조건 | 영역 | relay 도달률 | local 비영 비율 | relay 노름 평균 | local 노름 평균 | relay deadband 차단 | update deadband 차단 | target clip 소실 |")
    A("|---|---|---:|---:|---:|---:|---:|---:|---:|")
    for c in order:
        rs = [r for r in th_rows if r["condition"] == c]
        if not rs:
            continue
        for a_ in areas:
            A(f"| {c} | {a_} | {db_fmt(_db_mean([r.get(f'reach_relay_{a_}') for r in rs]))} | "
              f"{db_fmt(_db_mean([r.get(f'reach_local_{a_}') for r in rs]))} | "
              f"{db_fmt(_db_mean([r.get(f'relay_norm_{a_}') for r in rs]))} | "
              f"{db_fmt(_db_mean([r.get(f'local_norm_{a_}') for r in rs]))} | "
              f"{db_fmt(cause(c, a_, 'L3', 'n_blocked_by_relay_deadband'))} | "
              f"{db_fmt(cause(c, a_, 'L3', 'n_blocked_by_update_deadband'))} | "
              + ("해당 없음 (최상위, 교사 직접) |" if a_ == areas[-1] else
                 f"{db_fmt(cause(c, a_, 'L3', 'n_removed_by_target_clip'))} |"))
    A("")
    A("## 6. 질문 2 — 기본 임계값이 실제로 바뀌었는가")
    A("")
    A("| 조건 | 영역/층 | 변경 뉴런 | 상승 | 하락 | 평균 |변화| (mV) | 하한 도달 | 상한 도달 | 임시 변화 표본 비율 | float32 무변화 | 범위 clip | 배치 부호 상쇄 |")
    A("|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|")
    for c in order:
        cc = conds.get(c) or {}
        bg = ((cc.get("theta_change") or {}).get("by_group") or {})
        rs = [r for r in th_rows if r["condition"] == c]
        for g, r in bg.items():
            area, layer = g.split("/")
            A(f"| {c} | {g} | {r['n_changed']}/{r['n']} | {r['n_up']} | {r['n_down']} | {db_fmt(r['mean_abs_change_mV'])} | "
              f"{r['at_lower_bound']} | {r['at_upper_bound']} | "
              f"{db_fmt(_db_mean([x.get(f'applied_{area}_{layer}') for x in rs]))} | "
              f"{db_fmt(cause(c, area, layer, 'n_float32_no_change'))} | {db_fmt(cause(c, area, layer, 'n_base_clip_limited'))} | "
              f"{db_fmt(cause(c, area, layer, 'n_batch_mean_sign_cancel'))} |")
    A("")
    for c in order:
        cc = conds.get(c) or {}
        tc = cc.get("theta_change") or {}
        if tc:
            A(f"- {c}: 전체 변경 {tc.get('n_changed')} (상승 {tc.get('n_up')}, 하락 {tc.get('n_down')}), 최대 |변화| "
              f"{db_fmt(tc.get('max_abs_mV'))} mV, 마스크 밖 비트 불변 {_thr_yes(tc.get('outside_mask_bitwise_equal'))}, commit "
              f"{cc.get('n_commits')}회, 상태 {cc.get('status')}")
    A("")
    A("## 7. 질문 3 — 판독 구간 전달·도형별 구분")
    A("")
    sel = ev.get("selected") or {}
    ini = (ev.get("initial") or {}).get("dev") or {}
    A("| 조건 | dev IT L3 판독 [64,160) 스파이크 | 판독 창 발화 (표본x뉴런) | 입력은 있으나 무발화 | 무입력 | 첫 입력 중앙값 ms | 첫 발화 중앙값 ms | 클래스 간/내 분산 비 | 예측 클래스 수 |")
    A("|---|---:|---:|---:|---:|---:|---:|---:|---:|")
    for c, e in [("(공통 초기)", ini)] + [(c, sel.get(c) or {}) for c in order]:
        it = e.get("it_l3") or {}
        sep = (e.get("it_class_separation") or {}).get("between_within_ratio")
        A(f"| {c} | {db_fmt(it.get('spikes_readout_64_160'))} | {db_fmt(it.get('n_fired_in_readout'))} | "
          f"{db_fmt(it.get('n_input_no_spike'))} | {db_fmt(it.get('n_no_input'))} | {db_fmt(it.get('first_input_median_ms'))} | "
          f"{db_fmt(it.get('first_spike_median_ms'))} | {db_fmt(sep)} | {db_fmt(e.get('n_distinct_predictions'))} |")
    A("")
    A("## 8. 질문 4 — teacher-free 일반화 지표")
    A("")
    A("| 조건 | 선택 에폭 | dev CE | dev 정확도 | train CE (마지막 에폭) | train 정확도 | guided CE 평균 | post_update_free CE 평균 |")
    A("|---|---:|---:|---:|---:|---:|---:|---:|")
    vals: dict[str, dict[str, Any]] = {}
    for c in order:
        e = sel.get(c) or {}
        hist = (ev.get("epochs") or {}).get(c) or []
        last_tr = (hist[-1].get("train") if hist else None) or {}
        rs = [r for r in th_rows if r["condition"] == c]
        vals[c] = {"dev_ce": e.get("cross_entropy"), "dev_acc": e.get("accuracy")}
        A(f"| {c} | {db_fmt((e.get('selection') or {}).get('epoch'))} | {db_fmt(e.get('cross_entropy'))} | "
          f"{db_fmt(e.get('accuracy'))} | {db_fmt(last_tr.get('cross_entropy'))} | {db_fmt(last_tr.get('accuracy'))} | "
          f"{db_fmt(_db_mean([r.get('guided_ce') for r in rs]))} | {db_fmt(_db_mean([r.get('post_update_free_ce') for r in rs]))} |")
    A("")
    A("주 비교 (dev, 선택 theta, 뒤 - 앞):")
    A("")
    for b_, a_ in DB_MAIN_CONTRASTS:
        vb, va = vals.get(b_) or {}, vals.get(a_) or {}
        dce = (None if vb.get("dev_ce") is None or va.get("dev_ce") is None else vb["dev_ce"] - va["dev_ce"])
        dac = (None if vb.get("dev_acc") is None or va.get("dev_acc") is None else vb["dev_acc"] - va["dev_acc"])
        A(f"- {b_} − {a_}: dev CE 차 {db_fmt(dce)}, dev 정확도 차 {db_fmt(dac)}")
    A("")
    A("guided 는 교사가 있는 상태의 값이며 일반화 성능이 아니다. teacher-free 평가는 theta_fast 0, 교사 OFF, 라벨 없는 예측이다.")
    A("")
    A("## 9. 질문 5 — 비용 (흔들림·포화·불필요한 발화)")
    A("")
    A("| 조건 | 뉴런별 부호 반전 평균 (배치) | 반전 뉴런 수 (배치) | 반전 평균 (에폭) | theta_fast clip 제한 | IT L3 종료 후 [160,460) 스파이크 (dev) | no_input 활성 비율 (IT L3) |")
    A("|---|---:|---:|---:|---:|---:|---:|")
    for c in order:
        cc = conds.get(c) or {}
        sf = cc.get("sign_flips") or {}
        fc = sum(int(v) for k, v in (causes.get(c) or {}).items() if k.endswith("|n_fast_clip_limited")) if c in causes else None
        it = ((sel.get(c) or {}).get("it_l3") or {})
        noin = next((r for r in lat if r.get("condition") == c and r.get("phase") == "selected"
                     and r.get("split") == "diagnostic_no_input" and str(r.get("group", "")).endswith("/L3E")
                     and str(r.get("group", "")).startswith(str(met.get("top_area") or "IT"))), None)
        A(f"| {c} | {db_fmt(sf.get('per_batch_mean'))} | {db_fmt(sf.get('per_batch_neurons_flipped'))} | "
          f"{db_fmt(sf.get('per_epoch_mean'))} | {db_fmt(fc)} | {db_fmt(it.get('spikes_after_160'))} | "
          f"{db_fmt(None if noin is None else _lat_num(noin.get('active_fraction')))} |")
    A("")
    A("## 10. 같은 free 상태 정책 비교 (크기 진단)")
    A("")
    A(same.get("note_ko", "기록 없음 (미측정)."))
    A("")
    rows = list((same.get("rows_by_group") or {}).values())
    if rows:
        agg: dict[tuple[str, str, str, str], dict[str, float]] = {}
        for r in rows:
            k = (str(r.get("condition")), str(r.get("pair")), str(r.get("area")), str(r.get("vector")))
            g = agg.setdefault(k, {"n_common": 0, "n_new_in_b": 0, "n_lost_in_b": 0, "nb_new_sq": 0.0, "nb_com_sq": 0.0})
            g["n_common"] += r.get("n_common", 0)
            g["n_new_in_b"] += r.get("n_new_in_b", 0)
            g["n_lost_in_b"] += r.get("n_lost_in_b", 0)
            g["nb_new_sq"] += float(r.get("norm_b_new") or 0.0) ** 2
            g["nb_com_sq"] += float(r.get("norm_b_common") or 0.0) ** 2
        A("| 조건 | 쌍 | 영역 | 벡터 | 공통 생존 좌표 | 새로 생존 | 사라짐 | 새 좌표 노름 | 공통 좌표 노름 (B) |")
        A("|---|---|---|---|---:|---:|---:|---:|---:|")
        for (c, pr, ar, vc), g in sorted(agg.items()):
            if c not in ("legacy_deadband", "relay_and_update_unfiltered") and len(agg) > 60:
                continue
            A(f"| {c} | {pr} | {ar} | {vc} | {g['n_common']} | {g['n_new_in_b']} | {g['n_lost_in_b']} | "
              f"{db_fmt(math.sqrt(g['nb_new_sq']))} | {db_fmt(math.sqrt(g['nb_com_sq']))} |")
        A("")
    A("## 11. 이번 실험에서 고치지 않고 관측으로 남긴 한계")
    A("")
    cov = (prep.get("coverage_summary") or {}).get("by_policy") or {}
    for pn, d in cov.items():
        it_g = [(g, r) for g, r in (d.get("by_group") or {}).items() if g.endswith("L3")]
        A(f"- 준비 때 늘 침묵하고 양의 목표가 없는 축 ({pn}): " + ", ".join(
            f"{g} {r['n_always_silent_no_positive_target']}" for g, r in it_g))
    for c in order:
        cs = causes.get(c) or {}
        A(f"- {c}: 침묵 L3 부족 후보 중 intensity 성분 0 (좌표x표본) "
          f"{db_fmt(sum(int(v) for k, v in cs.items() if k.endswith('|n_silent_deficit_no_intensity')) if cs else None)}, "
          f"L2 암묵적 목표 a2 - correction < 0 사건 "
          f"{db_fmt(sum(int(v) for k, v in cs.items() if k.endswith('|n_negative_implicit_target')) if cs else None)}")
    A("")
    A("## 12. 실행 비용")
    A("")
    A("| 조건 | 벽시계 s | settle | GPU 최대 메모리 (학습 배치) |")
    A("|---|---:|---:|---:|")
    for c in order:
        tmg = (conds.get(c) or {}).get("timing") or {}
        A(f"| {c} | {db_fmt(tmg.get('wall_s'))} | {db_fmt(tmg.get('settles'))} | "
          f"{db_fmt(tmg.get('peak_gpu_memory_bytes_train_batches'))} |")
    A("")
    A(f"- jsonl 기록 바이트 {db_fmt(met.get('log_bytes_jsonl'))}, 기록 상세도 `{met.get('flow_detail')}`, 흐름 기록 "
      f"{db_fmt(flow.get('n_records'))}줄, 정책 비교 {db_fmt(same.get('n_records'))}줄")
    A("")


def _db_report_holdout(A: Callable[[str], None], run_dir: Path, ev: dict[str, Any], met: dict[str, Any]) -> None:
    man = _inh_read(run_dir, "holdout_manifest.json") or {}
    A("## 5. 최종 holdout 평가")
    A("")
    A(f"- 원 실행: {met.get('holdout_source') or ev.get('source_run')} (프리셋 {ev.get('source_run_preset')})")
    A(f"- holdout {man.get('n')}개, 클래스별 {man.get('labels')}, 스트림 {man.get('stream')}, SHA256 {man.get('sha256')}")
    dup = man.get("duplicates") or {}
    A(f"- 기존 분할과의 비교: 내용 해시 중복 {dup.get('n_exact_content_duplicates')}, 원본 id 겹침 {dup.get('base_id_overlap')}, "
      f"같은 클래스 기존 영상과의 최소 최대화소차 {db_fmt(dup.get('min_max_abs_pixel_diff_to_existing_same_label'))}")
    A("")
    A("| 조건 | 정확도 | CE | 접근 번호 | 독립 평가 | 선택 규칙/에폭 |")
    A("|---|---:|---:|---:|---|---|")
    for c, r in (ev.get("holdout") or {}).items():
        s = r.get("selection") or {}
        A(f"| {c} | {db_fmt(r.get('accuracy'))} | {db_fmt(r.get('cross_entropy'))} | {db_fmt(r.get('access_number'))} | "
          f"{_thr_yes(r.get('independent_evaluation'))} | {s.get('rule')} / {s.get('epoch')} |")
    A("")
    if ev.get("refused_repeat"):
        A(f"- 이미 평가해 건너뛴 조건: {ev.get('refused_repeat')}")
    A(f"- {ev.get('note_ko', '')}")
    A("")


def make_db_figures(run_dir: Path) -> list[str]:
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
    except Exception as exc:
        raise RuntimeError(f"matplotlib 를 쓸 수 없다: {type(exc).__name__}: {exc}") from exc
    korean_ok = _setup_korean_font(matplotlib)
    matplotlib.rcParams["axes.unicode_minus"] = False

    def K(ko: str, en: str) -> str:
        return ko if korean_ok else en
    run_dir = Path(run_dir)
    fdir = ensure_writable_dir(run_dir / "figures")
    made: list[str] = []

    def save(fig: Any, name: str) -> None:
        p = fdir / name
        fig.savefig(p, dpi=130, bbox_inches="tight")
        plt.close(fig)
        made.append(str(p))
    th = _lat_csv(run_dir, "train_history.csv")
    styles = ["-", "--", ":", "-.", (0, (5, 1, 1, 1, 1, 1)), (0, (1, 3))]

    def ls(i: int) -> Any:
        return styles[i % len(styles)]
    rank = {"V1": 0, "V2": 1, "V3": 2, "V4": 3, "IT": 4}
    if th:
        conds = list(dict.fromkeys(r["condition"] for r in th))
        areas = sorted([k[len("reach_relay_"):] for k in th[0] if k.startswith("reach_relay_")],
                       key=lambda a: rank.get(a, 9))
        if areas:
            fig, axs = plt.subplots(1, len(areas), figsize=(3.6 * len(areas), 3.2), sharey=True, squeeze=False)
            for ax, a_ in zip(axs[0], areas):
                for ci, c in enumerate(conds):
                    rs = [r for r in th if r["condition"] == c]
                    ax.plot(range(1, len(rs) + 1), [_lat_num(r.get(f"reach_relay_{a_}")) for r in rs], lw=1.2,
                            ls=ls(ci), label=c)
                ax.set_title(a_, fontsize=8)
                ax.set_xlabel(K("미니배치", "minibatch"))
                ax.set_ylim(-0.05, 1.05)
            axs[0][0].set_ylabel(K("relay 도달률 (라운드 0)", "relay reach (round 0)"))
            axs[0][-1].legend(fontsize=5)
            save(fig, "db_relay_reach.png")
        app = sorted([k for k in th[0] if k.startswith("applied_")],
                     key=lambda k: (rank.get(k.split("_")[1], 9), k))
        if app:
            fig, axs = plt.subplots(1, len(app), figsize=(3.0 * len(app), 3.0), sharey=True, squeeze=False)
            for ax, k in zip(axs[0], app):
                for ci, c in enumerate(conds):
                    rs = [r for r in th if r["condition"] == c]
                    ax.plot(range(1, len(rs) + 1), [_lat_num(r.get(k)) for r in rs], lw=1.2, ls=ls(ci), label=c)
                ax.set_title(k[len("applied_"):], fontsize=7)
                ax.set_ylim(-0.05, 1.05)
            axs[0][0].set_ylabel(K("theta_fast 비영 표본 비율", "fraction of samples with theta_fast != 0"))
            axs[0][-1].legend(fontsize=5)
            save(fig, "db_modification_rate.png")
        groups = [k[len("theta_mean_"):] for k in th[0] if k.startswith("theta_mean_")]
        fig, axs = plt.subplots(1, len(conds), figsize=(4.0 * len(conds), 3.3), sharey=True, squeeze=False)
        for ax, c in zip(axs[0], conds):
            rs = [r for r in th if r["condition"] == c]
            for g in groups:
                ax.plot(range(1, len(rs) + 1), [_lat_num(r[f"theta_mean_{g}"]) for r in rs], lw=1, label=g)
            ax.set_title(c, fontsize=7)
            ax.set_xlabel(K("미니배치", "minibatch"))
        axs[0][0].set_ylabel(K("theta_base 평균 (mV, 휴지 대비)", "mean theta_base (mV)"))
        axs[0][-1].legend(fontsize=5, ncol=2)
        save(fig, "db_theta.png")
    ev = _inh_read(run_dir, "evaluation.json") or {}
    eps = ev.get("epochs") or {}
    if eps:
        fig, (a1, a2) = plt.subplots(1, 2, figsize=(9.5, 3.4))
        ini = ev.get("initial") or {}
        for ci, (c, hist) in enumerate(eps.items()):
            if not isinstance(hist, list) or not hist:
                continue
            xs = [-1] + [h["epoch"] for h in hist]
            a1.plot(xs, [(ini.get("dev") or {}).get("cross_entropy")] + [(h.get("dev") or {}).get("cross_entropy")
                                                                         for h in hist], marker="o", ms=3, ls=ls(ci),
                     label=c)
            a2.plot(xs, [(ini.get("train") or {}).get("cross_entropy")] + [(h.get("train") or {}).get("cross_entropy")
                                                                           for h in hist], marker="o", ms=3, ls=ls(ci),
                     label=c)
        a1.set_title(K("dev CE (교사 없음, -1 = 공통 초기)", "dev CE (teacher-free, -1 = initial)"), fontsize=8)
        a2.set_title(K("train CE (교사 없음)", "train CE (teacher-free)"), fontsize=8)
        a1.legend(fontsize=6)
        save(fig, "db_ce.png")
        fig, ax = plt.subplots(figsize=(7.5, 3.4))
        for ci, (c, hist) in enumerate(eps.items()):
            if not isinstance(hist, list) or not hist:
                continue
            ys = []
            for h in hist:
                tcv = h.get("theta_change_vs_previous_epoch") or {}
                n = sum(v.get("n", 0) for v in tcv.values())
                ys.append((sum(v.get("n_changed", 0) for v in tcv.values()) / n) if n else None)
            ax.plot([h["epoch"] for h in hist], ys, marker="o", ms=3, ls=ls(ci), label=c)
        ax.set_ylabel(K("에폭 사이 theta_base 변경 뉴런 비율", "fraction of neurons changed per epoch"))
        ax.set_xlabel(K("에폭", "epoch"))
        ax.legend(fontsize=6)
        save(fig, "db_theta_change_rate.png")
    lat = [r for r in _lat_csv(run_dir, "latency_summary.csv") if r.get("phase") == "selected" and r.get("split") == "dev"]
    if lat:
        stages = list(dict.fromkeys(r["group"] for r in lat if r["group"].endswith("E")))
        conds = list(dict.fromkeys(r["condition"] for r in lat))
        fig, ax = plt.subplots(figsize=(max(6, 0.55 * len(stages)), 3.6))
        w = 0.8 / max(1, len(conds))
        for i, c in enumerate(conds):
            vals = [_lat_num(next((r["first_spike_median_ms"] for r in lat if r["condition"] == c and r["group"] == s),
                                  None)) or 0.0 for s in stages]
            ax.bar(np.arange(len(stages)) + i * w, vals, width=w, label=c)
        ax.axhspan(64, 160, color="0.9", zorder=0)
        ax.set_xticks(np.arange(len(stages)) + 0.4 - w / 2)
        ax.set_xticklabels(stages, rotation=60, fontsize=6)
        ax.set_ylabel(K("첫 발화 중앙값 (ms, dev 선택 theta)", "median first spike (ms, dev)"))
        ax.legend(fontsize=6)
        ax.set_title(K("반응 지연 (회색 = 판독 창 [64,160), 0 = 발화 없음)", "latency (grey = readout window)"), fontsize=8)
        save(fig, "db_latency.png")
        it = [r for r in lat if r["group"].endswith("/L3E")]
        top = it[-1]["group"] if it else None
        it_top = [r for r in it if r["group"] == top]
        if it_top:
            wins = ["spikes_readout_64_160", "spikes_post_160_210", "spikes_post_210_310", "spikes_post_310_460"]
            fig, ax = plt.subplots(figsize=(7, 3.4))
            w = 0.8 / max(1, len(it_top))
            for i, r in enumerate(it_top):
                ax.bar(np.arange(len(wins)) + i * w, [_lat_num(r[k]) or 0 for k in wins], width=w, label=r["condition"])
            ax.set_xticks(np.arange(len(wins)) + 0.4 - w / 2)
            ax.set_xticklabels(["[64,160)", "[160,210)", "[210,310)", "[310,460)"], fontsize=7)
            ax.set_ylabel(K("IT L3 스파이크 (dev 합)", "IT L3 spikes (dev)"))
            ax.legend(fontsize=6)
            ax.set_title(K("판독 창과 종료 후 활동", "readout window vs post-offset activity"), fontsize=8)
            save(fig, "db_post_offset.png")
    return made


def rebuild_db_outputs(path: Path) -> dict[str, Any]:
    path = Path(path)
    if not (path / "metrics.json").is_file():
        raise ValueError(f"메뉴 21 실행 폴더가 아니다 (metrics.json 없음): {path}")
    if (read_json(path / "metrics.json") or {}).get("format") != DB_FORMAT:
        raise ValueError(f"메뉴 21 형식의 실행 폴더가 아니다: {path}")
    out: dict[str, Any] = {"report": None, "figures": [], "errors": []}
    if (path / "correction_flow.jsonl").is_file():
        try:
            write_json(path / "correction_flow_summary.json", db_flow_summary(path / "correction_flow.jsonl"))
            if (path / "same_state_policy_comparison.jsonl").is_file():
                write_json(path / "same_state_policy_comparison.json",
                           db_same_state_summary(path / "same_state_policy_comparison.jsonl"))
        except Exception as exc:                              # noqa: BLE001
            out["errors"].append(f"요약 {type(exc).__name__}: {exc}")
    try:
        out["figures"] = make_db_figures(path)
    except Exception as exc:                                  # noqa: BLE001
        out["errors"].append(f"그림 {type(exc).__name__}: {exc}")
    try:
        out["report"] = str(build_db_report(path))
    except Exception as exc:                                  # noqa: BLE001
        out["errors"].append(f"보고서 {type(exc).__name__}: {exc}")
    return out


