def validate_cp_settings(settings: dict[str, Any] | None) -> dict[str, Any]:
    """메뉴 22 설정 검사. 공통 부분은 메뉴 21 검사기를 그대로 쓰고, 조건·프로토타입 부분만 따로 본다."""
    s = _db_merge(cp_defaults(), settings)
    common = copy.deepcopy(s)
    common["conditions"] = list(DB_MAIN_CONDITIONS)
    common["optional_conditions"] = []
    common.pop("prototype", None)
    validate_db_settings(common)
    dbd = s["deadband"]
    if float(dbd.get("relay_deadband", 0.0)) != 0.0 or float(dbd.get("update_deadband", 0.0)) != 0.0:
        raise ValueError("메뉴 22 는 relay_deadband / update_deadband 를 0 / 0 으로 고정한다 (deadband 실험을 섞지 않는다).")
    if s["compare_policies_each_batch"]:
        raise ValueError("메뉴 22 에서는 deadband 정책 비교(메뉴 21 기능)를 끈다.")
    if list(s["conditions"]) != list(CP_MAIN_CONDITIONS):
        raise ValueError(f"주 비교 조건은 순서까지 {list(CP_MAIN_CONDITIONS)} 로 고정이다.")
    for c in s["optional_conditions"]:
        if c not in CP_OPTIONAL_CONDITIONS:
            raise ValueError(f"선택 조건은 {list(CP_OPTIONAL_CONDITIONS)} 이다: {c}")
    p = s["prototype"]
    tau, rho, eps = float(p["tau_cos"]), float(p["rho_proto"]), float(p["eps_norm"])
    if not (math.isfinite(tau) and -1.0 <= tau <= 1.0):
        raise ValueError(f"tau_cos 는 [-1, 1] 의 유한한 값이다: {tau}")
    if not (math.isfinite(rho) and 0.0 <= rho <= 1.0):
        raise ValueError(f"rho_proto 는 [0, 1] 이다: {rho}")
    if not (math.isfinite(eps) and eps > 0.0):
        raise ValueError("eps_norm 은 양수다.")
    if int(p["min_accept_count"]) < 1 or int(p["min_accept_count"]) != float(p["min_accept_count"]):
        raise ValueError("min_accept_count 는 1 이상 정수다.")
    if int(p["per_class"]) < 1:
        raise ValueError("per_class 는 1 이상이다.")
    if p["refresh"] != "epoch":
        raise ValueError("프로토타입 갱신 주기는 에폭당 한 번(epoch) 만 지원한다.")
    for k in ("norm_equal_tol", "axis_zero_tol", "axis_one_tol", "range_rounding_tol"):
        if not float(p[k]) >= 0:
            raise ValueError(f"{k} 는 0 이상이다.")
    if not isinstance(p.get("teacher_globally_off"), bool):
        raise ValueError("teacher_globally_off 는 y/n 이다.")
    if p["teacher_globally_off"]:
        raise ValueError("teacher_globally_off 는 사전 검사(CP16) 전용이다. 주 실행에서는 켜지 않는다.")
    return s


def cp_all_conditions(s: dict[str, Any]) -> list[str]:
    return list(s["conditions"]) + [c for c in s["optional_conditions"] if c not in s["conditions"]]


def cp_policy(s: dict[str, Any], cond: str, *, zero_teacher: bool = False) -> DeadbandPolicy:
    """조건 -> 임계값 교정 정책. 모든 조건이 relay 0 / update 0 / 같은 teacher_tolerance 를 쓴다."""
    if cond not in CP_CONDITION_TABLE and not cond.startswith("cp_check"):
        raise ValueError(f"알 수 없는 메뉴 22 조건: {cond!r}")
    row = CP_CONDITION_TABLE.get(cond, {"threshold": True})
    return DeadbandPolicy(name=cond, teacher_tolerance=float(s["deadband"]["teacher_tolerance"]),
                          relay_deadband=0.0, update_deadband=0.0, freeze=not bool(row["threshold"]),
                          zero_teacher=bool(zero_teacher))


def cp_condition_table(s: dict[str, Any]) -> list[dict[str, Any]]:
    out = []
    for c in cp_all_conditions(s):
        row = CP_CONDITION_TABLE[c]
        pol = cp_policy(s, c)
        out.append({"condition": c, "threshold_learning": bool(row["threshold"]), "prototype_mode": row["proto"],
                    "relay_deadband": pol.relay_deadband, "update_deadband": pol.update_deadband,
                    "teacher_tolerance": pol.teacher_tolerance, "freeze_threshold": pol.freeze,
                    "tau_cos": float(s["prototype"]["tau_cos"]) if row["proto"] in ("cosine", "random_count_matched") else None,
                    "rho_proto": float(s["prototype"]["rho_proto"]) if row["proto"] != "fixed" else None,
                    "description_ko": CP_CONDITIONS_KO[c]})
    return out


def cp_estimate(*, n_conditions: int, n_train: int, n_dev: int, batch_size: int, epochs: int, K: int, n_prep: int,
                n_diag_stimuli: int, steps: int, diagnostic_each_epoch: bool) -> dict[str, Any]:
    """실행 전 계산량 (실측 없음). settle 1회 = 배치 하나를 steps 만큼 실행."""
    bs = max(1, int(batch_size))
    nb = max(1, math.ceil(n_train / bs))
    per_batch = 2 * int(K) + 2
    train = int(n_conditions) * int(epochs) * nb * per_batch
    tr_b = math.ceil(n_train / bs) if n_train else 0
    dev_b = math.ceil(n_dev / bs) if n_dev else 0
    readout = int(n_conditions) * int(epochs) * tr_b
    dev = int(n_conditions) * int(epochs) * dev_b
    diag = int(n_conditions) * int(epochs) * (n_diag_stimuli if diagnostic_each_epoch else 0)
    initial = tr_b + dev_b + n_diag_stimuli
    selected = int(n_conditions) * (dev_b + n_diag_stimuli)
    prep = math.ceil(n_prep / bs) if n_prep else 0
    tot = train + readout + dev + diag + initial + selected + prep
    return {"n_conditions": int(n_conditions), "n_batches_per_epoch": nb, "epochs": int(epochs), "K_rounds": int(K),
            "settles_per_batch": per_batch,
            "train_settles_formula": f"{n_conditions} 조건 x {int(epochs) * nb} 배치 x {per_batch} settle = {train}",
            "settle_calls": {"preparation": prep, "train": train, "train_readout_for_prototypes": readout,
                             "dev_eval": dev, "diagnostic_per_epoch": diag, "initial": initial,
                             "selected_dev_and_diagnostic": selected, "total": tot},
            "extra_readout_vs_menu21": 0,
            "physical_steps_total": tot * int(steps), "steps_per_settle": int(steps),
            "note_ko": ("train 판독(H_train)은 메뉴 21 의 에폭별 teacher-free train 평가와 같은 횟수이며, 그 결과를 명시적 반환값으로 "
                        "프로토타입 갱신에 쓴다 (같은 목적의 감각 실행을 추가하지 않는다). 고정 조건도 같은 판독을 한다. 실제 시간은 "
                        "재지 않았다.")}


# ---------------------------------------------------------------------- 공용 수식 (NumPy / torch)
def _xnan_like(x: Any) -> Any:
    if _is_torch(x):
        return require_torch().full_like(x, float("nan"))
    return np.full_like(np.asarray(x, dtype=np.float64), np.nan)


def _xones_like(x: Any) -> Any:
    return require_torch().ones_like(x) if _is_torch(x) else np.ones_like(x)


def _xall_finite(x: Any) -> bool:
    if _is_torch(x):
        return bool(require_torch().isfinite(x).all())
    return bool(np.isfinite(np.asarray(x)).all())


def _xint(x: Any) -> int:
    return int(x.sum()) if _is_torch(x) else int(np.sum(x))


def _xnonzero_idx(mask: Any) -> np.ndarray:
    if _is_torch(mask):
        return mask.nonzero().flatten().detach().to("cpu").numpy().astype(np.int64)
    return np.nonzero(np.asarray(mask))[0].astype(np.int64)


def _cp_hash(x: Any) -> str:
    if _is_torch(x):
        return tensor_hash(x)
    a = np.ascontiguousarray(np.asarray(x))
    return hashlib.sha256(a.tobytes() + str(a.dtype).encode() + str(a.shape).encode()).hexdigest()


def cp_select(H: Any, labels: Any, bank: Any) -> Any:
    """정답 클래스 안 제곱 유클리드 최근접 프로토타입 (동률은 가장 작은 k). select_prototype 과 같은 규칙."""
    Pc = bank[labels]                                       # [S, P, n]
    d = _xsum((Pc - H[:, None, :]) ** 2, -1)               # [S, P]
    return d.argmin(dim=-1) if _is_torch(d) else np.argmin(d, axis=-1)


def cp_propose_core(H: Any, labels: Any, k: Any, bank: Any, *, mode: str, tau: float, rho: float, eps: float,
                    min_count: int, random_pick: Callable[[int, int, np.ndarray, int], np.ndarray] | None = None,
                    range_tol: float = 1e-6) -> dict[str, Any]:
    """이전 bank 하나를 기준으로 모든 배정·gate 를 판정하고 다음 bank 후보를 계산한다 (입력은 바꾸지 않는다).

    * valid_norm = ||P_k|| > eps AND ||h|| > eps.  cos = dot / (||P|| ||h||), valid 일 때만 (분모에 eps 를 넣지 않는다).
    * cosine: accept = valid & cos >= tau.  ema: accept = valid.  random_count_matched: 코사인 통과 수만큼 유효 후보에서 무작위.
    * 프로토타입 (c,k) 마다 accept 수 >= min_count 이면 P_new = (1-rho) P + rho mean(h_accept), 아니면 그대로.
    * 크기 조건·크기 가중·정답 예측 여부 선별은 없다. 저장 P 는 정규화하지 않는다.
    """
    if mode not in CP_UPDATE_MODES:
        raise ValueError(f"알 수 없는 갱신 모드: {mode!r}")
    tau, rho, eps = float(tau), float(rho), float(eps)
    C, P = int(bank.shape[0]), int(bank.shape[1])
    Pk = bank[labels, k]
    nP = _xsqrt(_xsum(Pk * Pk, -1))
    nh = _xsqrt(_xsum(H * H, -1))
    valid = (nP > eps) & (nh > eps)
    dot = _xsum(Pk * H, -1)
    den = _xwhere(valid, nP * nh, _xones_like(nP))
    cos_raw = _xwhere(valid, dot / den, _xnan_like(dot))
    out_rng = valid & ((cos_raw > 1.0) | (cos_raw < -1.0))
    cos = _xwhere(valid, _xclip(cos_raw, -1.0, 1.0), cos_raw)
    cos_pass = valid & (cos >= tau)
    if mode == "cosine":
        accept = cos_pass
    elif mode == "ema":
        accept = valid
    else:
        accept = cos_pass & (cos_pass != cos_pass)          # 모두 False (모양·장치 유지)
    apply = mode in ("cosine", "ema", "random_count_matched")
    if mode == "random_count_matched":
        if random_pick is None:
            raise ValueError("random_count_matched 에는 전용 RNG 선택 함수가 필요하다.")
        acc_np = np.zeros(int(H.shape[0]), dtype=bool)
        for c in range(C):
            for j in range(P):
                m_as = (labels == c) & (k == j)
                n_target = _xint(cos_pass & m_as)
                idx = _xnonzero_idx(valid & m_as)
                if n_target > 0:
                    pick = np.asarray(random_pick(c, j, idx, n_target), np.int64)
                    acc_np[pick] = True
        if _is_torch(H):
            accept = require_torch().tensor(acc_np, device=H.device)
        else:
            accept = acc_np
    bank_new = _xcopy(bank)
    clusters: list[dict[str, Any]] = []
    updated = []
    for c in range(C):
        for j in range(P):
            m_as = (labels == c) & (k == j)
            m_acc = m_as & accept
            n_acc = _xint(m_acc)
            p_old = bank[c, j]
            zero_p = not float(_xsqrt(_xsum(p_old * p_old, -1))) > eps
            row = {"class": c, "proto": j, "n_assigned": _xint(m_as), "n_valid_norm": _xint(m_as & valid),
                   "n_zero_activity": _xint(m_as & ~(nh > eps)), "n_zero_prototype": _xint(m_as & ~(nP > eps)),
                   "n_cos_pass": _xint(m_as & cos_pass), "n_cos_below": _xint(m_as & valid & ~cos_pass),
                   "n_cos_out_of_range": _xint(m_as & out_rng), "n_accepted": n_acc, "prototype_zero_norm": zero_p}
            if not apply:
                row.update(applied=False, reason=("teacher_globally_off" if mode == "teacher_off" else "condition_fixed"))
            elif zero_p:
                row.update(applied=False, reason="prototype_zero_norm")
            elif row["n_assigned"] == 0:
                row.update(applied=False, reason="empty_cluster")
            elif n_acc < int(min_count):
                row.update(applied=False, reason="insufficient_count")
            else:
                mu = _xsum(H[m_acc], 0) / float(n_acc)
                bank_new[c, j] = (1.0 - rho) * p_old + rho * mu
                row.update(applied=True, reason="applied")
                updated.append((c, j))
            clusters.append(row)
    over_hi = over_lo = 0.0
    for c, j in updated:
        v = bank_new[c, j]
        over_hi = max(over_hi, float((v - 1.0).max()))
        over_lo = max(over_lo, float((-v).max()))
    if not _xall_finite(bank_new):
        raise CPNumericError("갱신 후 bank 에 NaN/Inf 가 있다.")
    overshoot = max(over_hi, over_lo, 0.0)
    if overshoot > float(range_tol):
        raise CPNumericError(f"갱신 후 bank 가 [0,1] 밖이다 (초과 {overshoot:.3g}). 조용히 clip 하지 않는다.")
    return {"bank_new": bank_new, "k": k, "valid": valid, "cos_raw": cos_raw, "cos": cos, "cos_pass": cos_pass,
            "accept": accept, "nh": nh, "nP": nP, "clusters": clusters, "mode": mode, "applied_any": bool(updated),
            "n_cos_out_of_range": _xint(out_rng), "range_overshoot": overshoot,
            "range_rounding_within_tol": bool(0.0 < overshoot <= float(range_tol))}


class PrototypeUpdater:
    """프로토타입 bank 갱신기. ``propose`` 는 읽기 전용, ``commit`` 이 유일한 변경 지점이다.

    상태: version (bank 가 실제로 바뀐 횟수), last_completed_refresh_epoch, commit 기록. 표본 누적기는 두지 않고 매 에폭
    전체 train 판독을 한 번에 받는다 (순서·배치 편향 없음, 재개 때 같은 입력으로 다시 계산 가능).
    """

    def __init__(self, mode: str, *, settings: dict[str, Any], seed: int) -> None:
        if mode not in CP_UPDATE_MODES:
            raise ValueError(f"알 수 없는 갱신 모드: {mode!r}")
        p = settings["prototype"]
        self.mode = mode
        self.tau, self.rho, self.eps = float(p["tau_cos"]), float(p["rho_proto"]), float(p["eps_norm"])
        self.min_count = int(p["min_accept_count"])
        self.range_tol = float(p["range_rounding_tol"])
        self.seed = int(seed)
        self.version = 0
        self.last_completed_refresh_epoch = -1
        self.n_commits = 0
        self.history: list[dict[str, Any]] = []

    def params(self) -> dict[str, Any]:
        return {"mode": self.mode, "tau_cos": self.tau, "rho_proto": self.rho, "eps_norm": self.eps,
                "min_accept_count": self.min_count, "seed": self.seed}

    def state_dict(self) -> dict[str, Any]:
        return {**self.params(), "version": self.version, "last_completed_refresh_epoch": self.last_completed_refresh_epoch,
                "n_commits": self.n_commits, "history": list(self.history)}

    def load_state_dict(self, st: dict[str, Any]) -> None:
        if {k: st.get(k) for k in self.params()} != self.params():
            raise ValueError(f"갱신기 설정이 다르다: 저장 {({k: st.get(k) for k in self.params()})} / 현재 {self.params()}")
        self.version = int(st["version"])
        self.last_completed_refresh_epoch = int(st["last_completed_refresh_epoch"])
        self.n_commits = int(st["n_commits"])
        self.history = list(st.get("history") or [])

    def state_hash(self) -> str:
        return sha256_text(json.dumps(self.state_dict(), sort_keys=True, default=str))

    def _random_pick(self, epoch: int) -> Callable[[int, int, np.ndarray, int], np.ndarray]:
        def pick(c: int, j: int, idx: np.ndarray, n: int) -> np.ndarray:
            ss = np.random.SeedSequence([self.seed, STREAM_OFFSETS["prototype_random_control"], int(epoch), c, j])
            rng = np.random.default_rng(ss)
            return np.sort(rng.choice(np.asarray(idx, np.int64), size=int(n), replace=False))
        return pick

    def propose(self, act: dict[str, Any], bank: Any, *, split: str, epoch: int, assign: Any | None = None
                ) -> dict[str, Any]:
        """train 판독 활동 -> 다음 bank 후보와 진단. 모델·bank·갱신기 상태를 바꾸지 않는다."""
        if split != "train":
            raise ValueError(f"프로토타입 갱신에는 train 판독만 쓴다 (받은 분할: {split!r}). dev/test/holdout 은 거부한다.")
        H, labels = act["h"], act["labels"]
        sids, bids = list(act["sample_ids"]), list(act["base_ids"])
        if len(sids) != int(H.shape[0]):
            raise ValueError("sample_ids 개수와 활동 행 수가 다르다.")
        seen: set[str] = set()
        keep = []
        for i, s in enumerate(sids):
            if s not in seen:
                seen.add(s)
                keep.append(i)
        n_dup = len(sids) - len(keep)
        if n_dup:
            if _is_torch(H):
                ki = require_torch().tensor(keep, dtype=require_torch().long, device=H.device)
            else:
                ki = np.asarray(keep, np.int64)
            H, labels = H[ki], labels[ki]
            assign = None if assign is None else assign[ki]
            sids, bids = [sids[i] for i in keep], [bids[i] for i in keep]
        if not _xall_finite(H) or not _xall_finite(bank):
            raise CPNumericError("train 판독 활동 또는 프로토타입에 NaN/Inf 가 있다 (0 으로 덮지 않고 멈춘다).")
        k = assign if assign is not None else cp_select(H, labels, bank)
        mode = self.mode
        core = cp_propose_core(H, labels, k, bank, mode=mode, tau=self.tau, rho=self.rho, eps=self.eps,
                               min_count=self.min_count,
                               random_pick=(self._random_pick(epoch) if mode == "random_count_matched" else None),
                               range_tol=self.range_tol)
        old_sha, new_sha = _cp_hash(bank), _cp_hash(core["bank_new"])
        return {"epoch": int(epoch), "split": split, "mode": mode, "params": self.params(),
                "version_before": self.version, "bank_old": _xcopy(bank), "bank_old_sha256": old_sha,
                "bank_new": core["bank_new"], "bank_new_sha256": new_sha, "changed": old_sha != new_sha,
                "core": core, "H": H, "labels": labels, "k": k, "sample_ids": sids, "base_ids": bids,
                "n_duplicates_dropped": n_dup, "assignment_source": ("given (TeacherTargetProvider.select_prototype)"
                                                                     if assign is not None else "cp_select")}

    def commit(self, prop: dict[str, Any], targets: Any) -> dict[str, Any]:
        """유일한 변경 지점. propose 이후 bank·버전이 그대로일 때만 한 번에 적용한다."""
        if prop["version_before"] != self.version:
            raise RuntimeError("propose 이후 갱신기 버전이 바뀌었다. 같은 에폭 갱신을 두 번 적용하지 않는다.")
        if int(prop["epoch"]) <= self.last_completed_refresh_epoch:
            raise RuntimeError(f"에폭 {prop['epoch']} 갱신은 이미 끝났다 (마지막 {self.last_completed_refresh_epoch}).")
        if _cp_hash(targets.prototypes) != prop["bank_old_sha256"]:
            raise RuntimeError("propose 이후 프로토타입 bank 가 바뀌었다. 적용하지 않는다.")
        rec = {"epoch": int(prop["epoch"]), "version_before": self.version, "bank_old_sha256": prop["bank_old_sha256"],
               "bank_new_sha256": prop["bank_new_sha256"], "changed": bool(prop["changed"]), "mode": self.mode}
        if prop["changed"]:
            nb = prop["bank_new"]
            targets.prototypes = nb.detach().clone() if _is_torch(nb) else np.array(nb, copy=True)
            self.version += 1
        self.n_commits += 1
        self.last_completed_refresh_epoch = int(prop["epoch"])
        rec["version_after"] = self.version
        self.history.append(rec)
        return rec


# ---------------------------------------------------------------------- 진단 (작은 배열, CPU NumPy)
def _cp_stats(x: np.ndarray) -> dict[str, Any]:
    x = np.asarray(x, np.float64)
    x = x[np.isfinite(x)]
    if x.size == 0:
        return {"n": 0, "min": None, "p10": None, "median": None, "p90": None, "max": None}
    return {"n": int(x.size), "min": float(x.min()), "p10": float(np.percentile(x, 10)), "median": float(np.median(x)),
            "p90": float(np.percentile(x, 90)), "max": float(x.max())}


def _cp_np(x: Any) -> np.ndarray:
    return x.detach().to("cpu").numpy() if _is_torch(x) else np.asarray(x)


def cp_proposal_rows(prop: dict[str, Any], *, settings: dict[str, Any], cond: str, classes: Sequence[str]
                     ) -> tuple[list[dict[str, Any]], dict[str, Any], dict[str, np.ndarray]]:
    """propose 결과 -> 프로토타입별 기록 행, bank 수준 지표, 표본별 배열 (한 번에 CPU 로 옮긴 뒤 계산)."""
    p = settings["prototype"]
    eps, ntol = float(p["eps_norm"]), float(p["norm_equal_tol"])
    zt, ot = float(p["axis_zero_tol"]), float(p["axis_one_tol"])
    core = prop["core"]
    H = _cp_np(prop["H"]).astype(np.float64)
    lab = _cp_np(prop["labels"]).astype(np.int64)
    k = _cp_np(prop["k"]).astype(np.int64)
    B0 = _cp_np(prop["bank_old"]).astype(np.float64)
    B1 = _cp_np(prop["bank_new"]).astype(np.float64)
    valid = _cp_np(core["valid"]).astype(bool)
    cos = _cp_np(core["cos"]).astype(np.float64)
    cos_raw = _cp_np(core["cos_raw"]).astype(np.float64)
    acc = _cp_np(core["accept"]).astype(bool)
    cpass = _cp_np(core["cos_pass"]).astype(bool)
    nh = _cp_np(core["nh"]).astype(np.float64)
    nP = _cp_np(core["nP"]).astype(np.float64)
    sids, bids = list(prop["sample_ids"]), list(prop["base_ids"])
    rows = []
    for cl in core["clusters"]:
        c, j = int(cl["class"]), int(cl["proto"])
        m_as = (lab == c) & (k == j)
        m_acc = m_as & acc
        po, pn = B0[c, j], B1[c, j]
        npo, npn = float(np.linalg.norm(po)), float(np.linalg.norm(pn))
        d = pn - po
        ratio = np.where(m_as & valid, nh / np.where(nP > 0, nP, 1.0), np.nan)
        r_acc = ratio[m_acc]
        mu = H[m_acc].mean(axis=0) if m_acc.any() else None
        cos_pp = (float(po @ pn / (npo * npn)) if npo > eps and npn > eps else None)
        rows.append({
            "condition": cond, "epoch": int(prop["epoch"]), "class": classes[c] if c < len(classes) else c,
            "class_index": c, "proto": j, "mode": prop["mode"], "version_before": int(prop["version_before"]),
            "bank_old_sha256": prop["bank_old_sha256"], "bank_new_sha256": prop["bank_new_sha256"],
            **{kk: cl[kk] for kk in ("n_assigned", "n_valid_norm", "n_zero_activity", "n_zero_prototype", "n_cos_pass",
                                     "n_cos_below", "n_cos_out_of_range", "n_accepted", "applied", "reason")},
            "n_applied": (int(m_acc.sum()) if cl["applied"] else 0),
            "n_distinct_samples_accepted": len({sids[i] for i in np.nonzero(m_acc)[0]}),
            "n_distinct_bases_accepted": len({bids[i] for i in np.nonzero(m_acc)[0]}),
            "n_would_pass_cosine": int((m_as & cpass).sum()),
            **{f"cos_candidates_{kk}": v for kk, v in _cp_stats(cos[m_as & valid]).items()},
            **{f"cos_accepted_{kk}": v for kk, v in _cp_stats(cos[m_acc]).items()},
            **{f"norm_ratio_candidates_{kk}": v for kk, v in _cp_stats(ratio[m_as & valid]).items()},
            "n_accepted_norm_ratio_gt1": int((r_acc > 1 + ntol).sum()), "n_accepted_norm_ratio_lt1": int((r_acc < 1 - ntol).sum()),
            "n_accepted_norm_ratio_eq1": int((np.abs(r_acc - 1) <= ntol).sum()), "norm_equal_tol": ntol,
            "n_cos_raw_above_1": int((valid & m_as & (cos_raw > 1)).sum()),
            "n_cos_raw_below_minus1": int((valid & m_as & (cos_raw < -1)).sum()),
            "norm_P_old": npo, "norm_mu": (None if mu is None else float(np.linalg.norm(mu))), "norm_P_new": npn,
            "norm_delta": float(np.linalg.norm(d)), "cos_P_old_P_new": cos_pp, "max_abs_component_change": float(np.abs(d).max()),
            "n_new_positive_axes": int(((po <= 0) & (pn > 0)).sum()), "n_near_zero_axes": int((pn <= zt).sum()),
            "n_near_one_axes": int((pn >= 1 - ot).sum()), "axis_zero_tol": zt, "axis_one_tol": ot,
            "norm_P_new_gt_old": (npn > npo), "norm_P_new_lt_old": (npn < npo)})
    bank = cp_bank_metrics(B1, eps=eps, assigned=[(r["class_index"], r["proto"], r["n_assigned"]) for r in rows])
    bank.update(condition=cond, epoch=int(prop["epoch"]), version_before=int(prop["version_before"]),
                changed=bool(prop["changed"]), n_duplicates_dropped=int(prop["n_duplicates_dropped"]),
                n_cos_out_of_range_total=int(core["n_cos_out_of_range"]), range_overshoot=float(core["range_overshoot"]),
                n_prototypes_updated=sum(1 for r in rows if r["applied"]),
                n_prototypes_norm_up=sum(1 for r in rows if r["applied"] and r["norm_P_new_gt_old"]),
                n_prototypes_norm_down=sum(1 for r in rows if r["applied"] and r["norm_P_new_lt_old"]),
                assignment_source=prop["assignment_source"])
    arrays = {"k": k.astype(np.int16), "label": lab.astype(np.int16), "cos": cos.astype(np.float32),
              "cos_raw": cos_raw.astype(np.float32), "accept": acc, "cos_pass": cpass, "valid_norm": valid,
              "norm_h": nh.astype(np.float32), "norm_P": nP.astype(np.float32)}
    return rows, bank, arrays


def cp_bank_metrics(bank: np.ndarray, *, eps: float, assigned: Sequence[tuple[int, int, int]] | None = None
                    ) -> dict[str, Any]:
    """bank 수준 지표: 같은 클래스 안 중복·클래스 간 최대 cosine·최소 거리·0 노름·포화."""
    B = np.asarray(bank, np.float64)
    C, P, n = B.shape
    norms = np.linalg.norm(B, axis=-1)
    flat = B.reshape(C * P, n)
    cls = np.repeat(np.arange(C), P)
    fn = norms.reshape(-1)
    within_cos, within_d, between_cos, between_d = [], [], [], []
    n_dup = 0
    for a in range(C * P):
        for b in range(a + 1, C * P):
            d = float(np.linalg.norm(flat[a] - flat[b]))
            cs = (float(flat[a] @ flat[b] / (fn[a] * fn[b])) if fn[a] > eps and fn[b] > eps else None)
            if cls[a] == cls[b]:
                within_d.append(d)
                if cs is not None:
                    within_cos.append(cs)
                n_dup += int(d <= 1e-12)
            else:
                between_d.append(d)
                if cs is not None:
                    between_cos.append(cs)
    unused = None if assigned is None else sum(1 for _c, _j, na in assigned if na == 0)
    return {"bank_shape": [C, P, n], "norm_mean": float(norms.mean()), "norm_min": float(norms.min()),
            "norm_max": float(norms.max()), "n_zero_norm_prototypes": int((norms <= eps).sum()),
            "fraction_zero_components": float((B <= 0).mean()), "fraction_saturated_components": float((B >= 1).mean()),
            "within_class_max_cosine": (max(within_cos) if within_cos else None),
            "within_class_min_distance": (min(within_d) if within_d else None),
            "n_within_class_duplicate_pairs": n_dup,
            "between_class_max_cosine": (max(between_cos) if between_cos else None),
            "between_class_min_distance": (min(between_d) if between_d else None),
            "n_between_pairs_valid_cosine": len(between_cos), "n_unused_prototypes": unused}


def cp_counterfactual(H: np.ndarray, logits: np.ndarray, labels: np.ndarray, k_old: np.ndarray, bank_old: np.ndarray,
                      bank_new: np.ndarray, *, tolerance: float, rule: str, classes: Sequence[str], cond: str,
                      epoch: int) -> list[dict[str, Any]]:
    """같은 H·같은 logits 에서 목표만 P_old -> P_new 로 바꾼 효과 (신경망 재실행 없음).

    residual_old = H - P_old[y, k_old]; residual_new_reselect = H - P_new[y, k_new] (기존 규칙으로 재선택);
    residual_new_fixed_k = H - P_new[y, k_old]. teacher gate 도 각각 계산. CE 는 같은 logits 에서 두 번 계산해 비교한다.
    """
    H = np.asarray(H, np.float64)
    lg = np.asarray(logits, np.float64)
    y = np.asarray(labels, np.int64)
    k0 = np.asarray(k_old, np.int64)
    B0, B1 = np.asarray(bank_old, np.float64), np.asarray(bank_new, np.float64)
    k1 = cp_select(H, y, B1)
    t0, t1r, t1f = B0[y, k0], B1[y, k1], B1[y, k0]

    def ce(z: np.ndarray) -> np.ndarray:
        zz = z - z.max(axis=1, keepdims=True)
        return -(zz[np.arange(len(y)), y] - np.log(np.exp(zz).sum(axis=1)))
    ce_old, ce_new = ce(lg), ce(lg.copy())
    wrong = lg.argmax(axis=1) != y
    g0 = db_teacher_gate(wrong[None], H[None], t0[None], rule=rule, tolerance=tolerance)[0][0]
    g1 = db_teacher_gate(wrong[None], H[None], t1r[None], rule=rule, tolerance=tolerance)[0][0]
    g1f = db_teacher_gate(wrong[None], H[None], t1f[None], rule=rule, tolerance=tolerance)[0][0]
    rows = []
    for c in [None] + sorted(set(y.tolist())):
        m = np.ones_like(y, bool) if c is None else (y == c)
        if not m.any():
            continue
        rows.append({"condition": cond, "epoch": int(epoch), "class": "ALL" if c is None else classes[c],
                     "n": int(m.sum()),
                     "residual_old_l2_mean": float(np.linalg.norm(H[m] - t0[m], axis=1).mean()),
                     "residual_new_reselect_l2_mean": float(np.linalg.norm(H[m] - t1r[m], axis=1).mean()),
                     "residual_new_fixed_k_l2_mean": float(np.linalg.norm(H[m] - t1f[m], axis=1).mean()),
                     "sqdist_old_mean": float(((H[m] - t0[m]) ** 2).sum(axis=1).mean()),
                     "sqdist_new_reselect_mean": float(((H[m] - t1r[m]) ** 2).sum(axis=1).mean()),
                     "sqdist_new_fixed_k_mean": float(((H[m] - t1f[m]) ** 2).sum(axis=1).mean()),
                     "n_reassigned": int((k1[m] != k0[m]).sum()),
                     "gate_fraction_old": float(g0[m].mean()), "gate_fraction_new_reselect": float(g1[m].mean()),
                     "gate_fraction_new_fixed_k": float(g1f[m].mean()), "argmax_wrong_fraction": float(wrong[m].mean()),
                     "ce_old": float(ce_old[m].mean()), "ce_new": float(ce_new[m].mean()),
                     "ce_identical": bool(np.array_equal(ce_old[m], ce_new[m])),
                     "note_ko": "같은 H·logits. 목표 거리 감소는 뉴런 학습 성공이 아니다."})
    return rows


def cp_representation(H: np.ndarray, labels: np.ndarray, *, eps: float, split: str, cond: str, epoch: Any
                      ) -> dict[str, Any]:
    """IT 활동 표현 지표 (고정 정의). 0 노름·0 분모는 None 과 유효 개수로 남긴다."""
    H = np.asarray(H, np.float64)
    y = np.asarray(labels, np.int64)
    nrm = np.linalg.norm(H, axis=1)
    cls = sorted(set(y.tolist()))
    within_d, within_cos, n_cos_pairs = [], [], 0
    cents = []
    for c in cls:
        X = H[y == c]
        cents.append(X.mean(axis=0))
        for a in range(len(X)):
            for b in range(a + 1, len(X)):
                within_d.append(float(np.linalg.norm(X[a] - X[b])))
                na, nb = np.linalg.norm(X[a]), np.linalg.norm(X[b])
                if na > eps and nb > eps:
                    within_cos.append(float(X[a] @ X[b] / (na * nb)))
                    n_cos_pairs += 1
    cents_a = np.asarray(cents)
    between = [float(np.linalg.norm(cents_a[a] - cents_a[b])) for a in range(len(cents_a)) for b in range(a + 1, len(cents_a))]
    wm = float(np.mean(within_d)) if within_d else None
    bm = float(np.mean(between)) if between else None
    sep = db_class_separation(H, y)
    return {"condition": cond, "epoch": epoch, "split": split, "n": int(H.shape[0]),
            "norm_mean": float(nrm.mean()) if nrm.size else None, "fraction_zero_norm": float((nrm <= eps).mean()) if nrm.size else None,
            "fraction_zero_components": float((H <= 0).mean()) if H.size else None,
            "fraction_saturated_components": float((H >= 1).mean()) if H.size else None,
            "within_class_mean_distance": wm, "between_centroid_mean_distance": bm,
            "between_over_within": (None if not wm or bm is None else bm / wm),
            "within_class_mean_cosine": (float(np.mean(within_cos)) if within_cos else None),
            "n_within_cosine_pairs_valid": n_cos_pairs,
            "between_within_variance_ratio": sep.get("between_within_ratio")}


def cp_fast_clip_counts(dm: Any, raw: Any, change: Any, bound: float) -> dict[str, Any]:
    """theta_fast 기록 (CP17): clip = 요청 비영이고 clamp 전 raw 가 ±bound 밖. 반올림만 = raw 가 범위 안인데 실제 변화 != 요청.

    float32 에서 `실제 변화 != 요청` 만으로 clip 을 세지 않는다 (작은 덧셈의 반올림은 rounding_only 로 따로 센다).
    """
    nz = dm != 0
    out = (raw > float(bound)) | (raw < -float(bound))
    return {"n_fast_clipped_raw": nz & out, "n_fast_rounding_only": nz & ~out & (change != dm)}


def cp_base_clip_counts(before: Any, req: Any, new: Any, mask: Any) -> dict[str, Any]:
    """commit 기록 (CP17): clip = 새 값이 clamp 전 후보 (before+req) 와 다름, 반올림 무변화 = 요청 비영인데 before+req == before."""
    cand = before + req
    nz = mask & (req != 0)
    return {"n_base_clipped": nz & (new != cand), "n_base_rounding_no_change": nz & (cand == before) & (new == cand)}


class CPPairedNetwork(DBPairedNetwork):
    """메뉴 22 네트워크. DBPairedNetwork 의 교정 계산을 그대로 쓰고, 에피소드 전후 프로토타입 bank 불변만 확인한다.

    에피소드 도중(K 회 L2/L3 교정 포함) 목표 bank 가 바뀌면 즉시 멈춘다. bank 는 실행기의 에폭 경계 refresh 에서만
    PrototypeUpdater.commit 으로 바뀐다. 추가 기록 (학습 수식 불변, 에피소드 끝에 한 번 CPU 로):
    * fast_clip: theta_fast 가 clamp 전 raw 에서 ±fast_bound 를 넘었는지 (clip) 와, 범위 안인데 float 반올림으로 실제 변화가
      요청과 다른지 (rounding_only) 를 따로 센다.
    * restorer: 영역별 D 복원 오차 노름과 실제 confidence (L3 강도 / L2 형태 패킷) 평균.
    """

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        super().__init__(*args, **kwargs)
        self.cp_bank_version = 0
        self.cp_bank_checks = 0
        self._cp_core: DBStatAcc | None = None

    def db_episode(self, x: Any, labels: Any, **kw: Any) -> dict[str, Any]:            # type: ignore[override]
        h0, v0 = tensor_hash(self.targets.prototypes), self.cp_bank_version
        self._cp_core = DBStatAcc(enabled=True)
        try:
            out = super().db_episode(x, labels, **kw)
            extra = self._cp_core.finish()
        finally:
            self._cp_core = None
        h1 = tensor_hash(self.targets.prototypes)
        if h1 != h0 or self.cp_bank_version != v0:
            raise RuntimeError("에피소드 도중 프로토타입 bank 가 바뀌었다 (에폭 경계 밖 변경 금지). 실행을 멈춘다.")
        self.cp_bank_checks += 1
        if out.get("status") == "completed":
            out["core"] = list(out.get("core") or []) + extra
        out["prototype_bank_version"] = v0
        out["prototype_bank_sha256"] = h0
        return out

    def _flow_apply(self, acc: DBStatAcc, rec: dict[str, Any], *, channel: str, round_id: int, d_req: Any,
                    d_after: Any | None, dm: Any, change: Any, shuffled: bool, raw: Any | None = None) -> None:
        super()._flow_apply(acc, rec, channel=channel, round_id=round_id, d_req=d_req, d_after=d_after, dm=dm,
                            change=change, shuffled=shuffled, raw=raw)
        core = self._cp_core
        if core is None or raw is None:
            return
        fb = float(self.controller.fast_bound)
        for area, layer, ids in self._slices(channel):
            cc = cp_fast_clip_counts(dm[:, :, ids], raw[:, :, ids], change[:, :, ids], fb)
            core.add({"kind": "fast_clip", "area": area, "layer": layer, "channel": channel, "round": round_id}, None,
                     n_fast_clipped_raw=cc["n_fast_clipped_raw"].sum(),
                     n_fast_rounding_only=cc["n_fast_rounding_only"].sum(),
                     n_fast_requested_nonzero=(dm[:, :, ids] != 0).sum())

    def _core_extra(self, core: DBStatAcc, packets: dict[str, dict[str, Any]], *, round_id: int) -> None:
        acc = self._cp_core
        if acc is None:
            return
        t = require_torch()
        for area, p in packets.items():
            vf = p["valid"].to(t.float64)
            nv = vf.sum()
            den = t.clamp(nv, min=1.0)
            pi, ps = p["packet_intensity"], p["packet_shape"]
            ci = (pi.confidence.to(t.float64).reshape(vf.shape) * vf).sum() / den
            extra: dict[str, Any] = {"reliability_mean": ci, "n_valid": nv}
            if ps is not None:
                extra["confidence_L2_mean"] = (ps.confidence.to(t.float64).reshape(vf.shape) * vf).sum() / den
            if p["restore_error"] is not None:
                extra["restore_error_norm_mean"] = (p["restore_error"].to(t.float64).norm(dim=-1) * vf).sum() / den
                extra["h_norm_mean"] = (p["h"].to(t.float64).norm(dim=-1) * vf).sum() / den
            else:
                extra["restore_error_norm_mean"] = None
            acc.add({"kind": "restorer", "area": area, "round": round_id, "sender": p["sender"],
                     "confidence_basis": pi.confidence_basis}, None, **extra)


