class _CPFakeTargets:
    """CPU 합성 검사용 목표 대역 (prototypes 속성만 가진다). 실제 TeacherTargetProvider 가 아니다."""

    def __init__(self, bank: Any) -> None:
        self.prototypes = np.array(bank, dtype=np.float64, copy=True)


def _cp_set(**proto: Any) -> dict[str, Any]:
    s = cp_defaults()
    s["prototype"].update(proto)
    return s


def _cp_act(H: Any, labels: Any, sids: Sequence[str] | None = None, **extra: Any) -> dict[str, Any]:
    H = np.asarray(H, np.float64)
    sids = list(sids) if sids is not None else [f"s{i}" for i in range(int(H.shape[0]))]
    return {"h": H, "labels": np.asarray(labels, np.int64), "sample_ids": sids,
            "base_ids": [f"b_{x}" for x in sids], **extra}


def _cp_run(H: Any, labels: Any, bank: Any, *, mode: str = "cosine", sids: Sequence[str] | None = None,
            epoch: int = 0, commit: bool = True, **proto: Any) -> tuple[Any, dict[str, Any], Any, Any]:
    upd = PrototypeUpdater(mode, settings=_cp_set(**proto), seed=7)
    prop = upd.propose(_cp_act(H, labels, sids), np.asarray(bank, np.float64), split="train", epoch=epoch)
    tg = _CPFakeTargets(bank)
    rec = upd.commit(prop, tg) if commit else None
    return upd, prop, tg, rec


def _cp_st(ok: bool) -> str:
    return CP_PASSED if ok else CP_FAILED


def _cp_rot(u: np.ndarray, ang: float) -> np.ndarray:
    c, s_ = math.cos(ang), math.sin(ang)
    return np.array([c * u[0] - s_ * u[1], s_ * u[0] + c * u[1]])


def _cp_check1() -> dict[str, Any]:
    P = np.array([[[0.2, 0.4]]])
    cases = {"larger_activity": (np.array([[0.3, 0.6], [0.5, 1.0]]), [0.22, 0.44]),
             "smaller_activity": (np.array([[0.05, 0.1], [0.15, 0.3]]), [0.19, 0.38])}
    det: dict[str, Any] = {}
    ok = True
    for name, (H, exp) in cases.items():
        _u, prop, tg, rec = _cp_run(H, [0, 0], P, tau_cos=0.95, rho_proto=0.1, min_accept_count=2)
        new = tg.prototypes[0, 0]
        cl = prop["core"]["clusters"][0]
        good = (bool(np.allclose(new, exp, rtol=0.0, atol=1e-12)) and cl["n_accepted"] == 2 and cl["reason"] == "applied"
                and rec["version_after"] == 1 and abs(float(np.linalg.norm(new)) - 1.0) > 1e-3)
        det[name] = {"mean_h": H.mean(axis=0).tolist(), "P_new": new.tolist(), "expected": exp,
                     "n_accepted": cl["n_accepted"], "reason": cl["reason"], "norm_P_new": float(np.linalg.norm(new)),
                     "pass": good}
        ok = ok and good
    _u, prop, tg, _r = _cp_run(np.array([[0.3, 0.6], [0.3, 0.6]]), [0, 0], P, sids=["same", "same"], tau_cos=0.95,
                               rho_proto=0.1, min_accept_count=2)
    dup = (prop["n_duplicates_dropped"] == 1 and prop["core"]["clusters"][0]["reason"] == "insufficient_count"
           and bool(np.array_equal(tg.prototypes, P)))
    det["duplicate_sample_id_counted_once"] = dup
    return {"status": _cp_st(ok and dup), "part": "cpu_synthetic", "detail": det,
            "criterion": "서로 다른 sample_id 2개, cos=1. 큰 평균·작은 평균 모두 (1-rho)P + rho*mu, 저장 P 비정규화"}


def _cp_check2() -> dict[str, Any]:
    u = np.array([0.6, 0.8])
    P = u[None, None, :].copy()
    det: dict[str, Any] = {}
    ang = math.acos(0.94)
    Hb = 0.5 * np.stack([_cp_rot(u, ang), _cp_rot(u, -ang)])
    upd, prop, tg, rec = _cp_run(Hb, [0, 0], P, tau_cos=0.95, rho_proto=0.1, min_accept_count=2)
    cl = prop["core"]["clusters"][0]
    a_ok = (cl["n_accepted"] == 0 and cl["n_cos_below"] == 2 and cl["reason"] == "insufficient_count"
            and bool(np.array_equal(tg.prototypes, P)) and rec["version_after"] == 0)
    det["below_threshold"] = {"cos": [float(v) for v in prop["core"]["cos"]], "tau": 0.95, "n_accepted": cl["n_accepted"],
                              "reason": cl["reason"], "bank_bitwise_unchanged": bool(np.array_equal(tg.prototypes, P)),
                              "pass": a_ok}
    Hc = 0.5 * np.stack([_cp_rot(u, 0.1), _cp_rot(u, -0.2)])
    _u, p0, _t, _r = _cp_run(Hc, [0, 0], P, tau_cos=-1.0, commit=False)
    cvals = np.asarray(p0["core"]["cos"], np.float64)
    tmin = float(cvals.min())
    _u, p_eq, _t, _r = _cp_run(Hc, [0, 0], P, tau_cos=tmin, commit=False)
    tnext = float(np.nextafter(tmin, 2.0))
    _u, p_gt, _t, _r = _cp_run(Hc, [0, 0], P, tau_cos=tnext, commit=False)
    b_ok = (p_eq["core"]["clusters"][0]["n_accepted"] == 2 and p_gt["core"]["clusters"][0]["n_accepted"] == 1)
    det["boundary_ge"] = {"cos": cvals.tolist(), "tau_equal_min_cos": tmin, "n_accepted_at_equal": p_eq["core"]["clusters"][0]["n_accepted"],
                          "tau_next_float": tnext, "n_accepted_next_float": p_gt["core"]["clusters"][0]["n_accepted"],
                          "rule": "cos >= tau (추가 허용오차 없음)", "pass": b_ok}
    Hs = np.stack([u * 1e-3, u * 2e-3])
    _u, ps, ts, _r = _cp_run(Hs, [0, 0], P, tau_cos=0.95, rho_proto=0.1, min_accept_count=2)
    cs = ps["core"]["clusters"][0]
    c_ok = (cs["n_accepted"] == 2 and cs["reason"] == "applied" and cs["n_zero_activity"] == 0
            and float(np.linalg.norm(ts.prototypes[0, 0])) < float(np.linalg.norm(P[0, 0])))
    det["small_magnitude_not_rejected"] = {"norm_h": [1e-3, 2e-3], "n_accepted": cs["n_accepted"],
                                           "norm_P_old": float(np.linalg.norm(P[0, 0])),
                                           "norm_P_new": float(np.linalg.norm(ts.prototypes[0, 0])), "pass": c_ok}
    Hp = np.stack([u * 0.9, u * 0.7, u * 0.3])
    _u, pp, _t, _r = _cp_run(Hp, [0, 0, 0], P, tau_cos=0.95, commit=False)
    raw = np.asarray(pp["core"]["cos_raw"], np.float64)
    n_out = int(((raw > 1.0) | (raw < -1.0)).sum())
    d_ok = (pp["core"]["n_cos_out_of_range"] == n_out and bool((np.asarray(pp["core"]["cos"]) <= 1.0).all())
            and float(np.abs(raw - 1.0).max()) <= 8 * np.finfo(np.float64).eps)
    det["rounding_record"] = {"cos_raw": raw.tolist(), "n_out_of_range_recorded": pp["core"]["n_cos_out_of_range"],
                              "n_out_of_range_direct": n_out, "pass": d_ok}
    return {"status": _cp_st(a_ok and b_ok and c_ok and d_ok), "part": "cpu_synthetic", "detail": det,
            "criterion": "cos<tau 면 0 갱신, cos==tau 는 통과·다음 float 는 거부, 작은 노름도 방향이 같으면 통과, 반올림 초과 기록"}


def _cp_check3() -> dict[str, Any]:
    P = np.array([[[0.2, 0.4]]])
    H = np.array([[0.3, 0.6], [0.5, 1.0]])
    _u, p0, t0, r0 = _cp_run(H, [0, 0], P, rho_proto=0.0)
    a_ok = bool(np.array_equal(p0["bank_new"], P)) and not p0["changed"] and r0["version_after"] == 0 \
        and bool(np.array_equal(t0.prototypes, P))
    _u, p1, t1, r1 = _cp_run(H, [0, 0], P, rho_proto=1.0)
    b_ok = bool(np.allclose(t1.prototypes[0, 0], H.mean(axis=0), rtol=0.0, atol=1e-15)) and r1["version_after"] == 1
    bad = [("rho_proto", -0.1), ("rho_proto", 1.1), ("rho_proto", float("nan")), ("tau_cos", 1.01), ("tau_cos", -1.01),
           ("tau_cos", float("nan")), ("eps_norm", 0.0), ("eps_norm", -1.0), ("min_accept_count", 0),
           ("min_accept_count", 1.5), ("refresh", "batch"), ("per_class", 0)]
    refused: dict[str, bool] = {}
    for k, v in bad:
        try:
            validate_cp_settings({"prototype": {k: v}})
            refused[f"{k}={v}"] = False
        except ValueError:
            refused[f"{k}={v}"] = True
    try:
        PrototypeUpdater("unknown_mode", settings=cp_defaults(), seed=1)
        refused["mode=unknown_mode"] = False
    except ValueError:
        refused["mode=unknown_mode"] = True
    try:
        validate_cp_settings({"deadband": {"relay_deadband": 0.01}})
        refused["relay_deadband=0.01"] = False
    except ValueError:
        refused["relay_deadband=0.01"] = True
    c_ok = all(refused.values())
    return {"status": _cp_st(a_ok and b_ok and c_ok), "part": "cpu_synthetic",
            "rho0_bitwise_unchanged": a_ok, "rho1_equals_selected_mean": b_ok,
            "rho1_P_new": t1.prototypes[0, 0].tolist(), "invalid_settings_refused": refused,
            "criterion": "rho=0 비트 무변화(버전 그대로), rho=1 은 채택 평균, 범위 밖 값은 ValueError"}


def _cp_check4() -> dict[str, Any]:
    det: dict[str, Any] = {}
    P = np.array([[[0.2, 0.4]]])
    H = np.array([[0.0, 0.0], [0.3, 0.6], [0.5, 1.0]])
    _u, p, t_, _r = _cp_run(H, [0, 0, 0], P)
    cos = np.asarray(p["core"]["cos"], np.float64)
    acc = np.asarray(p["core"]["accept"], bool)
    cl = p["core"]["clusters"][0]
    z_ok = (bool(np.isnan(cos[0])) and not bool(acc[0]) and not bool(np.asarray(p["core"]["valid"])[0])
            and cl["n_zero_activity"] == 1 and cl["n_accepted"] == 2
            and bool(np.allclose(t_.prototypes[0, 0], 0.9 * P[0, 0] + 0.1 * H[1:].mean(axis=0), rtol=0, atol=1e-15)))
    det["zero_activity"] = {"cos_of_zero_sample": None if np.isnan(cos[0]) else float(cos[0]), "n_zero_activity": cl["n_zero_activity"],
                            "n_accepted": cl["n_accepted"], "pass": z_ok}
    P0 = np.zeros((1, 1, 2))
    _u, p, t_, _r = _cp_run(H[1:], [0, 0], P0)
    cl = p["core"]["clusters"][0]
    zp_ok = (cl["reason"] == "prototype_zero_norm" and bool(np.isnan(np.asarray(p["core"]["cos"], np.float64)).all())
             and bool(np.array_equal(t_.prototypes, P0)) and cl["n_zero_prototype"] == 2)
    det["zero_prototype"] = {"reason": cl["reason"], "all_cos_nan": bool(np.isnan(np.asarray(p["core"]["cos"], np.float64)).all()),
                             "pass": zp_ok}
    P2 = np.array([[[0.2, 0.4], [0.9, 0.1]]])
    _u, p, t_, _r = _cp_run(H[1:], [0, 0], P2)
    cls = {c["proto"]: c for c in p["core"]["clusters"]}
    ec_ok = cls[1]["reason"] == "empty_cluster" and bool(np.array_equal(t_.prototypes[0, 1], P2[0, 1])) \
        and cls[0]["reason"] == "applied"
    det["empty_cluster"] = {"reasons": {j: c["reason"] for j, c in cls.items()}, "pass": ec_ok}
    _u, p, t_, _r = _cp_run(H[1:2], [0], P)
    cl = p["core"]["clusters"][0]
    ins_ok = cl["reason"] == "insufficient_count" and bool(np.array_equal(t_.prototypes, P))
    det["insufficient_count"] = {"reason": cl["reason"], "n_accepted": cl["n_accepted"], "pass": ins_ok}
    raised: dict[str, bool] = {}
    for tag, Hx, Bx in (("nan_activity", np.array([[np.nan, 0.5], [0.3, 0.6]]), P),
                        ("inf_activity", np.array([[np.inf, 0.5], [0.3, 0.6]]), P),
                        ("nan_prototype", H[1:], np.array([[[np.nan, 0.4]]]))):
        try:
            PrototypeUpdater("cosine", settings=cp_defaults(), seed=1).propose(_cp_act(Hx, [0, 0]), Bx, split="train",
                                                                               epoch=0)
            raised[tag] = False
        except CPNumericError:
            raised[tag] = True
    try:
        _cp_run(np.array([[0.75, 1.5], [0.75, 1.5]]), [0, 0], P, rho_proto=1.0, commit=False)
        raised["range_violation_not_clipped"] = False
    except CPNumericError:
        raised["range_violation_not_clipped"] = True
    det["numeric_errors_raised"] = raised
    ok = z_ok and zp_ok and ec_ok and ins_ok and all(raised.values())
    return {"status": _cp_st(ok), "part": "cpu_synthetic", "detail": det,
            "criterion": "0 벡터 cos 는 NaN(유효 아님), 0 P·빈 클러스터·표본 부족은 P 유지, NaN/Inf·[0,1] 위반은 CPNumericError"}


def _cp_check5() -> dict[str, Any]:
    bank = np.array([[[0.2, 0.4], [0.4, 0.2]], [[0.3, 0.6], [0.6, 0.3]]])
    H = np.array([[0.3, 0.6], [0.31, 0.62], [0.29, 0.58]])          # 클래스 1 프로토타입에 더 가깝지만 라벨은 0
    act1 = _cp_act(H, [0, 0, 0], logits=np.array([[0.0, 5.0]] * 3), predicted=np.array([1, 1, 1]))
    act2 = _cp_act(H, [0, 0, 0], logits=np.array([[5.0, 0.0]] * 3), predicted=np.array([0, 0, 0]))
    u1 = PrototypeUpdater("cosine", settings=_cp_set(tau_cos=0.95), seed=1)
    u2 = PrototypeUpdater("cosine", settings=_cp_set(tau_cos=0.95), seed=1)
    p1 = u1.propose(act1, bank, split="train", epoch=0)
    p2 = u2.propose(act2, bank, split="train", epoch=0)
    k = np.asarray(p1["k"])
    k_manual = np.argmin(((bank[0][None] - H[:, None, :]) ** 2).sum(-1), axis=1)
    other_same = bool(np.array_equal(p1["bank_new"][1], bank[1]))
    pred_ignored = p1["bank_new_sha256"] == p2["bank_new_sha256"] and bool(np.array_equal(np.asarray(p1["k"]), np.asarray(p2["k"])))
    ok = other_same and pred_ignored and bool(np.array_equal(k, k_manual))
    return {"status": _cp_st(ok), "part": "cpu_synthetic", "other_class_bitwise_unchanged": other_same,
            "assignment_within_true_class": k.tolist(), "assignment_manual": k_manual.tolist(),
            "prediction_logits_ignored": pred_ignored,
            "criterion": "라벨 0 표본은 클래스 0 프로토타입에만 배정·반영, 클래스 1 bank 비트 불변, logits/예측을 바꿔도 결과 동일"}


def _cp_synth(seed: int = 5, S: int = 60, C: int = 3, P: int = 3, n: int = 6) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    rng = np.random.default_rng(seed)
    bank = rng.uniform(0.05, 0.95, size=(C, P, n))
    lab = rng.integers(0, C, size=S)
    k = rng.integers(0, P, size=S)
    H = np.clip(bank[lab, k] * rng.uniform(0.5, 1.4, size=(S, 1)) + rng.normal(0, 0.06, size=(S, n)), 0.0, 1.0)
    return H, lab, bank


def _cp_check6() -> dict[str, Any]:
    H, lab, bank = _cp_synth()
    sids = [f"id{i:03d}" for i in range(H.shape[0])]
    perm = np.random.default_rng(11).permutation(H.shape[0])
    u1 = PrototypeUpdater("cosine", settings=_cp_set(tau_cos=0.97), seed=1)
    u2 = PrototypeUpdater("cosine", settings=_cp_set(tau_cos=0.97), seed=1)
    p1 = u1.propose(_cp_act(H, lab, sids), bank, split="train", epoch=0)
    p2 = u2.propose(_cp_act(H[perm], lab[perm], [sids[i] for i in perm]), bank, split="train", epoch=0)
    acc1 = {sids[i] for i in np.nonzero(np.asarray(p1["core"]["accept"]))[0]}
    acc2 = {p2["sample_ids"][i] for i in np.nonzero(np.asarray(p2["core"]["accept"]))[0]}
    k1 = {sids[i]: int(v) for i, v in enumerate(np.asarray(p1["k"]))}
    k2 = {p2["sample_ids"][i]: int(v) for i, v in enumerate(np.asarray(p2["k"]))}
    max_diff = float(np.abs(np.asarray(p1["bank_new"]) - np.asarray(p2["bank_new"])).max())
    Pk = bank[lab, np.asarray(p1["k"])]
    cos_direct = (Pk * H).sum(-1) / (np.linalg.norm(Pk, axis=-1) * np.linalg.norm(H, axis=-1))
    old_based = bool(np.allclose(np.asarray(p1["core"]["cos_raw"]), cos_direct, rtol=0, atol=1e-12)) \
        and bool(np.array_equal(p1["bank_old"], bank))
    tg = _CPFakeTargets(bank)
    u1.commit(p1, tg)
    twice: dict[str, bool] = {}
    try:
        u1.commit(p1, tg)
        twice["same_proposal_again_refused"] = False
    except RuntimeError:
        twice["same_proposal_again_refused"] = True
    try:
        p_again = u1.propose(_cp_act(H, lab, sids), tg.prototypes, split="train", epoch=0)
        u1.commit(p_again, tg)
        twice["same_epoch_again_refused"] = False
    except RuntimeError:
        twice["same_epoch_again_refused"] = True
    ok = acc1 == acc2 and k1 == k2 and max_diff <= 1e-12 and old_based and all(twice.values())
    return {"status": _cp_st(ok), "part": "cpu_synthetic", "n_samples": int(H.shape[0]), "n_accepted": len(acc1),
            "accepted_set_equal": acc1 == acc2, "assignment_equal": k1 == k2, "bank_new_max_abs_diff": max_diff,
            "tolerance": 1e-12, "decisions_from_old_bank": old_based, "once_per_epoch": twice,
            "criterion": "순서 바꿈에도 채택 집합·배정 동일, bank 차이 <= 1e-12 (합산 순서 차이), 같은 에폭 두 번 적용 거부"}


def _cp_check7() -> dict[str, Any]:
    H, lab, bank = _cp_synth(seed=9)
    sids = [f"id{i:03d}" for i in range(H.shape[0])]
    pc = PrototypeUpdater("cosine", settings=_cp_set(tau_cos=-1.0), seed=1).propose(_cp_act(H, lab, sids), bank,
                                                                                     split="train", epoch=0)
    pe = PrototypeUpdater("ema", settings=_cp_set(tau_cos=0.95), seed=1).propose(_cp_act(H, lab, sids), bank,
                                                                                  split="train", epoch=0)
    same = bool(np.array_equal(pc["bank_new"], pe["bank_new"])) and bool(np.array_equal(
        np.asarray(pc["core"]["accept"]), np.asarray(pe["core"]["accept"])))
    upd_rows = [(c["class"], c["proto"]) for c in pc["core"]["clusters"] if c["applied"]]
    rho = 0.1
    manual_ok = True
    norms = []
    for c, j in upd_rows:
        m = (lab == c) & (np.asarray(pc["k"]) == j) & np.asarray(pc["core"]["accept"])
        exp = (1.0 - rho) * bank[c, j] + rho * (H[m].sum(axis=0) / float(m.sum()))
        manual_ok = manual_ok and bool(np.allclose(pc["bank_new"][c, j], exp, rtol=0, atol=1e-15))
        norms.append(float(np.linalg.norm(pc["bank_new"][c, j])))
    not_unit = bool(norms) and any(abs(v - 1.0) > 1e-3 for v in norms)
    ok = same and manual_ok and not_unit
    return {"status": _cp_st(ok), "part": "cpu_synthetic", "cosine_all_pass_equals_ema": same,
            "n_prototypes_updated": len(upd_rows), "matches_full_vector_ema": manual_ok, "updated_norms": norms,
            "stored_not_unit_normalized": not_unit,
            "criterion": "tau=-1 cosine == ema (비트), 갱신값 == (1-rho)P + rho*mean(h), 저장 P 노름이 1 로 강제되지 않음"}


def _cp_check12a() -> dict[str, Any]:
    H, lab, bank = _cp_synth(seed=3)
    act = _cp_act(H, lab)
    upd = PrototypeUpdater("cosine", settings=cp_defaults(), seed=1)
    h_before = (_cp_hash(H), _cp_hash(lab), _cp_hash(bank), upd.state_hash())
    refused = {}
    for sp in ("dev", "test", "holdout", "validation"):
        try:
            upd.propose(act, bank, split=sp, epoch=0)
            refused[sp] = False
        except ValueError:
            refused[sp] = True
    upd.propose(act, bank, split="train", epoch=0)
    h_after = (_cp_hash(H), _cp_hash(lab), _cp_hash(bank), upd.state_hash())
    ok = all(refused.values()) and h_before == h_after
    return {"status": _cp_st(ok), "part": "cpu_synthetic", "non_train_split_refused": refused,
            "propose_read_only": h_before == h_after,
            "criterion": "train 외 분할은 ValueError, propose 전후 입력 배열·bank·갱신기 상태 해시 동일"}


def _cp_check13a() -> dict[str, Any]:
    H, lab, bank = _cp_synth(seed=4, C=3)
    rng = np.random.default_rng(2)
    logits = rng.normal(0, 1, size=(H.shape[0], 3))
    upd = PrototypeUpdater("cosine", settings=_cp_set(tau_cos=0.5), seed=1)
    prop = upd.propose(_cp_act(H, lab), bank, split="train", epoch=0)
    hb = (_cp_hash(H), _cp_hash(logits))
    cf = cp_counterfactual(H, logits, lab, np.asarray(prop["k"]), bank, np.asarray(prop["bank_new"]), tolerance=0.02,
                           rule="argmax_wrong_or_tolerance", classes=["a", "b", "c"], cond="cp13a", epoch=0)
    ha = (_cp_hash(H), _cp_hash(logits))
    allrow = next(r for r in cf if r["class"] == "ALL")
    ce_same = all(r["ce_identical"] for r in cf)
    ok = ce_same and hb == ha and prop["changed"]
    return {"status": _cp_st(ok), "part": "cpu_synthetic", "ce_identical_all_rows": ce_same,
            "inputs_unchanged": hb == ha, "bank_changed": prop["changed"],
            "residual_old": allrow["residual_old_l2_mean"], "residual_new_reselect": allrow["residual_new_reselect_l2_mean"],
            "residual_new_fixed_k": allrow["residual_new_fixed_k_l2_mean"],
            "gate_old": allrow["gate_fraction_old"], "gate_new": allrow["gate_fraction_new_reselect"],
            "criterion": "같은 H·logits 에서 CE 동일, 입력 불변. 목표 거리·gate 는 달라질 수 있다 (학습 성공이 아님)"}


def _cp_check16a() -> dict[str, Any]:
    H, lab, bank = _cp_synth(seed=6)
    upd = PrototypeUpdater("teacher_off", settings=_cp_set(tau_cos=-1.0), seed=1)
    prop = upd.propose(_cp_act(H, lab), bank, split="train", epoch=0)
    tg = _CPFakeTargets(bank)
    rec = upd.commit(prop, tg)
    reasons = {c["reason"] for c in prop["core"]["clusters"]}
    ok = (reasons == {"teacher_globally_off"} and bool(np.array_equal(tg.prototypes, bank)) and rec["version_after"] == 0
          and not prop["changed"])
    return {"status": _cp_st(ok), "part": "cpu_synthetic", "reasons": sorted(reasons),
            "bank_bitwise_unchanged": bool(np.array_equal(tg.prototypes, bank)), "version_after": rec["version_after"],
            "criterion": "teacher_off 갱신 모드는 모든 프로토타입을 teacher_globally_off 로 유지 (회로 부분은 CP16b)"}


def _cp_check17() -> dict[str, Any]:
    f32 = np.float32
    tf = np.array([0.5, 0.9, -0.95, 0.25], f32)
    dm = np.array([1e-9, 0.5, -0.25, 0.125], f32)
    raw = tf + dm
    nxt = np.clip(raw, f32(-1.0), f32(1.0))
    change = nxt - tf
    cc = cp_fast_clip_counts(dm, raw, change, 1.0)
    legacy = (dm != 0) & (change != dm)
    f_ok = (cc["n_fast_clipped_raw"].tolist() == [False, True, True, False]
            and cc["n_fast_rounding_only"].tolist() == [True, False, False, False])
    before = np.array([10.0, 29.9, 1.05, 5.0], f32)
    req = np.array([1e-7, 0.5, -0.1, 0.25], f32)
    cand = before + req
    new = np.clip(cand, f32(1.0), f32(30.0))
    bc = cp_base_clip_counts(before, req, new, np.ones(4, bool))
    b_ok = (bc["n_base_clipped"].tolist() == [False, True, True, False]
            and bc["n_base_rounding_no_change"].tolist() == [True, False, False, False])
    return {"status": _cp_st(f_ok and b_ok), "part": "cpu_synthetic",
            "fast": {"clipped_raw": cc["n_fast_clipped_raw"].tolist(), "rounding_only": cc["n_fast_rounding_only"].tolist(),
                     "menu21_metric_change_ne_request": legacy.tolist()},
            "base": {"clipped": bc["n_base_clipped"].tolist(), "rounding_no_change": bc["n_base_rounding_no_change"].tolist()},
            "criterion": ("float32 에서 0.5 + 1e-9 는 범위 안 반올림 (clip 아님), 0.9 + 0.5 는 raw 가 범위 밖 (clip). base 도 "
                          "clamp 전 후보와 비교. 메뉴 21 지표는 첫 항목을 clip 으로 셌다 (학습 수식은 바꾸지 않음)")}


def cp_cpu_checks(cps: dict[str, Any]) -> dict[str, Any]:
    """CPU 합성 검사 (회로 없음, NumPy). 실제 피질 성능과 무관한 계산 일관성 검사다."""
    out: dict[str, Any] = {}
    for name, fn in (("CP1", _cp_check1), ("CP2", _cp_check2), ("CP3", _cp_check3), ("CP4", _cp_check4),
                     ("CP5", _cp_check5), ("CP6", _cp_check6), ("CP7", _cp_check7), ("CP12a_cpu", _cp_check12a),
                     ("CP13a_cpu", _cp_check13a), ("CP16a_cpu", _cp_check16a), ("CP17", _cp_check17)):
        try:
            out[name] = fn()
        except Exception as exc:                                    # noqa: BLE001
            out[name] = {"status": CP_FAILED, "part": "cpu_synthetic", "error": f"{type(exc).__name__}: {exc}",
                         "traceback": traceback.format_exc(limit=6)}
    out["settings_used"] = {"note_ko": "합성 검사는 각 항목에 적힌 tau/rho/min_count 를 쓴다 (실행 설정과 별개).",
                            "run_settings_prototype": dict(cps["prototype"])}
    return out


def cp_combine(parts: dict[str, Any]) -> dict[str, str]:
    def comb(keys: Sequence[str]) -> str:
        st = [parts[k]["status"] for k in keys if isinstance(parts.get(k), dict) and "status" in parts[k]]
        if any(s == CP_FAILED for s in st):
            return CP_FAILED
        if st and len(st) == len(keys) and all(s == CP_PASSED for s in st):
            return CP_PASSED
        return CP_NOT_RUN
    return {cid: comb(CP_CHECK_PARTS[cid]) for cid in CP_CHECK_IDS}


class _CPChecksMixin:
    """CosinePrototypeExperiment 의 사전 검사 (메뉴 22-2). 작은 회로 검사는 사용자 확인 뒤 사용자 PC 에서만 실행한다."""

    # ------------------------------------------------------------------ 보조
    def _cp_balanced(self, stims: Sequence[Any], n: int) -> list[Any]:
        """라벨을 돌아가며 고른 앞쪽 n 개 (작은 통합 검사용, 원래 순서 안에서 결정론적)."""
        cnt: dict[str, int] = {}
        keyed = []
        for i, s in enumerate(stims):
            r = cnt.get(str(s.label), 0)
            cnt[str(s.label)] = r + 1
            keyed.append((r, str(s.label), i, s))
        keyed.sort(key=lambda z: z[:3])
        return [z[3] for z in keyed[:int(n)]]

    def _cp_mini(self, cond: str, *, epochs: int = 2, n_batches: int = 2, **kw: Any) -> dict[str, Any]:
        """작은 통합 실행: train 앞쪽 n_batches x batch 표본 (라벨 교대), dev 1 배치, 진단 자극 생략."""
        bs = int(self.pre["batch_size"])
        saved = (self.sel["train"], self.sel["dev"], self.pre["epochs"], getattr(self, "_cp_skip_diag", False))
        try:
            self.sel["train"] = self._cp_balanced(saved[0], int(n_batches) * bs)
            self.sel["dev"] = self._cp_balanced(saved[1], bs)
            self.pre["epochs"] = int(epochs)
            self._cp_skip_diag = True
            return self._train_condition(cond, **kw)
        finally:
            self.sel["train"], self.sel["dev"], self.pre["epochs"], self._cp_skip_diag = saved

    def _cp_reset(self) -> None:
        net = self.net
        self.model.neurons.theta_base.copy_(self.theta_init)
        net.targets.prototypes = self.P0.detach().clone()
        net.cp_bank_version = 0
        self.cp_updater = None
        c0 = self.db_conditions[0]
        net.set_policy(self.policies[c0], self.db_masks[c0])

    # ------------------------------------------------------------------ CP8 (변조 검사)
    def _cp8_tamper(self, x: Any, labels: Any, cond: str = "threshold_plus_cosine") -> dict[str, Any]:
        net = self.net
        saved_bank = net.targets.prototypes.detach().clone()
        theta0 = self.model.neurons.theta_base.detach().clone()
        orig = net.build_packets
        seen = {"n": 0}

        def bad(*args: Any, **kw: Any) -> Any:
            out = orig(*args, **kw)
            if kw.get("round_id") == 0 and seen["n"] == 0:
                seen["n"] += 1
                net.targets.prototypes = net.targets.prototypes * 0.5
            return out
        net.set_policy(self.policies[cond], self.db_masks[cond])
        raised, msg = False, None
        net.build_packets = bad                                               # type: ignore[method-assign]
        try:
            net.db_episode(x, labels, sample_id=-31, episode_id=-31, drive_key=("input_noise", 990_031), train=False,
                           compare_policies=None, detail="summary")
        except RuntimeError as exc:
            msg = str(exc)
            raised = "프로토타입 bank" in msg
        finally:
            net.__dict__.pop("build_packets", None)
            net.targets.prototypes = saved_bank
            self.model.neurons.theta_base.copy_(theta0)
        restored = "build_packets" not in net.__dict__ and tensor_hash(net.targets.prototypes) == tensor_hash(saved_bank)
        return {"tamper_applied_mid_episode": seen["n"] == 1, "episode_refused": raised, "message": msg,
                "state_restored": restored}

    def _cp8(self, m1: dict[str, Any], tamper: dict[str, Any]) -> dict[str, Any]:
        by_ep: dict[int, set[str]] = {}
        for r in m1["rows"]:
            by_ep.setdefault(int(r["epoch"]), set()).add(r["prototype_bank_sha256"])
        within = bool(by_ep) and all(len(v) == 1 for v in by_ep.values())
        evs = m1["epoch_evals"]
        chain = all(evs[i]["bank_after_sha256"] == evs[i + 1]["bank_used_sha256"] for i in range(len(evs) - 1))
        hist = m1["prototype_updater"]["history"]
        once = [int(h["epoch"]) for h in hist] == list(range(len(evs)))
        changed0 = bool(hist and hist[0]["changed"])
        used_next = (evs[1]["bank_used_sha256"] == hist[0]["bank_new_sha256"]) if len(evs) > 1 and hist else None
        row_sha_e1 = sorted(by_ep.get(1, set()))
        ok = (m1["status"] == "completed" and within and chain and once and used_next is not False
              and tamper["episode_refused"] and tamper["state_restored"] and tamper["tamper_applied_mid_episode"])
        return {"status": _cp_st(ok), "part": "circuit", "condition": m1["condition"], "epochs": len(evs),
                "bank_constant_within_epoch": within, "next_epoch_uses_refreshed_bank": chain,
                "one_refresh_per_epoch": once, "epoch0_refresh_changed_bank": changed0,
                "epoch1_rows_bank_sha256": row_sha_e1, "epoch0_new_bank_used_in_epoch1": used_next,
                "next_epoch_effect_observed": bool(changed0 and used_next),
                "tamper_test": tamper,
                "note_ko": ("epoch0_refresh_changed_bank 가 false 면 작은 자료에서 min_accept_count 를 채운 프로토타입이 없어 "
                            "'다음 에폭이 바뀐 bank 를 쓰는지' 는 bank 해시 연결로만 확인했다."),
                "criterion": "배치 기록 bank 해시가 에폭 안에서 하나, 에폭 e+1 사용 bank == 에폭 e 갱신 뒤 bank, 도중 변조는 거부"}

    # ------------------------------------------------------------------ CP9
    def _cp9_direct(self) -> dict[str, Any]:
        """같은 theta·같은 drive 에서 bank 를 바꿔도 교사 없는 dev logits 가 같다 (C(h_IT) 는 bank 를 쓰지 않는다)."""
        net = self.net
        sub = self._cp_balanced(self.sel["dev"], int(self.pre["batch_size"]))
        self.model.neurons.theta_base.copy_(self.theta_init)
        e0 = self._evaluate(sub, split="dev", cond="cp9_check", phase="check_P0")
        net.targets.prototypes = self.P0.detach().clone().flip(1) * 0.5
        e1 = self._evaluate(sub, split="dev", cond="cp9_check", phase="check_P_changed")
        net.targets.prototypes = self.P0.detach().clone()
        for e in (e0, e1):
            e.pop("latency", None)
        return {"logits_equal": e0.get("logits_sha256") == e1.get("logits_sha256"),
                "h_equal": e0.get("h_sha256") == e1.get("h_sha256"), "ce_equal": e0["cross_entropy"] == e1["cross_entropy"],
                "purity_preserved": bool(e0["purity_preserved"] and e1["purity_preserved"])}

    def _cp9(self, mf: dict[str, Any], mp: dict[str, Any], direct: dict[str, Any]) -> dict[str, Any]:
        pairs = list(zip(mf["epoch_evals"], mp["epoch_evals"]))
        dev_same = bool(pairs) and all(a["dev"].get("logits_sha256") == b["dev"].get("logits_sha256")
                                       and a["dev"]["cross_entropy"] == b["dev"]["cross_entropy"] for a, b in pairs)
        tr_same = bool(pairs) and all(a["train"].get("h_sha256") == b["train"].get("h_sha256")
                                      and a["train"].get("logits_sha256") == b["train"].get("logits_sha256")
                                      for a, b in pairs)
        rows_same = len(mf["rows"]) == len(mp["rows"]) and all(
            ra["free_before_ce"] == rb["free_before_ce"] and ra["post_update_free_ce"] == rb["post_update_free_ce"]
            for ra, rb in zip(mf["rows"], mp["rows"]))
        theta_same = mf["theta_change"]["unchanged_exactly"] and mp["theta_change"]["unchanged_exactly"]
        gate_diff = [round(float(rb["teacher_gate_fraction"]) - float(ra["teacher_gate_fraction"]), 6)
                     for ra, rb in zip(mf["rows"], mp["rows"])]
        ok = (mf["status"] == mp["status"] == "completed" and dev_same and tr_same and rows_same and theta_same
              and direct["logits_equal"] and direct["ce_equal"] and direct["purity_preserved"])
        return {"status": _cp_st(ok), "part": "circuit", "epochs_compared": len(pairs), "dev_logits_ce_equal": dev_same,
                "train_readout_h_logits_equal": tr_same, "episode_free_post_ce_equal": rows_same,
                "theta_unchanged_both": theta_same, "bank_changed_in_prototype_only": mp["prototype_bank_changed_from_P0"],
                "teacher_gate_fraction_diff_per_batch": gate_diff, "direct_bank_swap_test": direct,
                "note_ko": "teacher gate 빈도·프로토타입 거리는 목표 이동만으로 달라질 수 있다 (기록용). 추론 출력은 같아야 한다.",
                "criterion": "에폭별 dev logits·CE, train 판독 H·logits, 배치 free/post CE 동일, theta 불변, bank 바꿔도 logits 동일"}

    # ------------------------------------------------------------------ CP10
    def _cp10(self, x: Any, labels: Any) -> dict[str, Any]:
        t = require_torch()
        m = self.model
        a = m.neurons
        mask = self.db_masks["threshold_only"]
        pol_db = db_policy(self.cps, "relay_and_update_unfiltered")
        ref = DBPairedNetwork(self.runner.cfg, m, self.runner.seeds, tl=self.tls, policy=pol_db, learn_mask=mask,
                              obs_steps=self.obs_steps, stim_steps=self.stim_steps, window_steps=self.window,
                              gate_ref=self.ff_gate)
        ref_cal = PairedCalibrationRunner(self.runner.cfg, ref, self.runner.seeds, log=self.runner.recorder.log)
        ref_cal.load_state_dict(copy.deepcopy(self.prep_snapshot))
        prep_same = ref_cal.signatures() == self.prep_sig
        out: dict[str, Any] = {}
        thetas: dict[str, Any] = {}
        for tag, net_, pol in (("menu21_relay_and_update_unfiltered", ref, pol_db),
                               ("menu22_threshold_only", self.net, self.policies["threshold_only"])):
            net_.set_policy(pol, mask)
            a.theta_base.copy_(self.theta_init)
            ep = net_.db_episode(x, labels, sample_id=0, episode_id=0, drive_key=("input_noise", 0), train=True,
                                 compare_policies=None, detail="summary")
            thetas[tag] = a.theta_base.detach().clone()
            out[tag] = {"status": ep.get("status"), "free_ce": ep["free_before"]["cross_entropy"],
                        "guided_ce": ep["guided"]["cross_entropy"], "post_ce": ep["post_update_free"]["cross_entropy"],
                        "teacher_gate_fraction": ep["teacher_gate_fraction"],
                        "commit_actual_norm": ep["commit"].get("actual_norm"), "forward_calls": ep["forward_calls"]}
        a.theta_base.copy_(self.theta_init)
        self.net.set_policy(self.policies[self.db_conditions[0]], self.db_masks[self.db_conditions[0]])
        ka, kb = "menu21_relay_and_update_unfiltered", "menu22_threshold_only"
        same = bool(t.equal(thetas[ka], thetas[kb]))
        md = float((thetas[ka] - thetas[kb]).abs().max())
        scal_same = all(out[ka][k] == out[kb][k] for k in ("free_ce", "guided_ce", "post_ce", "teacher_gate_fraction"))
        moved = bool((thetas[kb] != self.theta_init).any())
        params_same = (pol_db.teacher_tolerance, pol_db.relay_deadband, pol_db.update_deadband, pol_db.freeze,
                       pol_db.zero_teacher, pol_db.shuffle) == (
            self.policies["threshold_only"].teacher_tolerance, self.policies["threshold_only"].relay_deadband,
            self.policies["threshold_only"].update_deadband, self.policies["threshold_only"].freeze,
            self.policies["threshold_only"].zero_teacher, self.policies["threshold_only"].shuffle)
        ok = prep_same and same and scal_same and params_same
        return {"status": _cp_st(ok), "part": "circuit", "theta_bitwise_equal": same, "theta_max_abs_diff_mV": md,
                "episode_scalars_equal": scal_same, "theta_moved_from_init": moved, "policy_parameters_equal": params_same,
                "preparation_same": prep_same, "per_network": out,
                "note_ko": "같은 모델·준비 스냅샷·theta_init·입력 사건으로 1 배치 학습을 두 네트워크에서 각각 실행해 비교했다.",
                "criterion": "4.0.11 DBPairedNetwork(relay_and_update_unfiltered) 와 CPPairedNetwork(threshold_only) 의 commit 뒤 theta 비트 일치"}

    # ------------------------------------------------------------------ CP11
    def _cp11(self, minis: dict[str, dict[str, Any]]) -> dict[str, Any]:
        t = require_torch()
        net = self.net
        per = {c: {"fixed_modules_unchanged": r["fixed_modules_unchanged"],
                   "P0_in_snapshot_unchanged": r["P0_in_preparation_snapshot_unchanged"],
                   "full_signatures_equal_at_start": r["initial_state_check"]["preparation_signatures_equal_initial"]}
               for c, r in minis.items()}
        clf = net.classifier
        b0 = clf.b.detach().clone()
        try:
            with t.no_grad():
                clf.b.add_(1e-3)
            detected = cp_fixed_signatures(self.cal.signatures()) != self.prep_fixed_sig
        finally:
            with t.no_grad():
                clf.b.copy_(b0)
        bank0 = net.targets.prototypes
        try:
            net.targets.prototypes = bank0 * 0.5
            sig = self.cal.signatures()
            separated = cp_fixed_signatures(sig) == self.prep_fixed_sig and sig != self.prep_sig
        finally:
            net.targets.prototypes = bank0
        restored = self.cal.signatures() == self.prep_sig
        fixed = self.model.verify_fixed_unchanged()
        ok = (all(all(v.values()) for v in per.values()) and detected and separated and restored
              and bool(fixed.get("unchanged")))
        return {"status": _cp_st(ok), "part": "circuit", "per_condition": per,
                "negative_control_classifier_change_detected": detected,
                "prototype_change_only_affects_prototype_signature": separated, "restored": restored,
                "fixed_physical_parameters": fixed, "fixed_signature_keys": sorted(self.prep_fixed_sig),
                "criterion": ("모든 조건 끝에 고정 서명(C·D·T·scale·slot) 불변, 분류기를 일부러 바꾸면 검사가 잡고, 프로토타입만 "
                              "바꾸면 고정 서명은 그대로·전체 서명만 달라진다 (동결 검사를 끄지 않았다)")}

    # ------------------------------------------------------------------ CP12b / CP13b
    def _cp12_13(self) -> tuple[dict[str, Any], dict[str, Any]]:
        t = require_torch()
        net = self.net
        bs = int(self.pre["batch_size"])
        classes = list(self.runner.cfg["decoder"]["classes"])
        sub_tr = self._cp_balanced(self.sel["train"], 2 * bs)
        sub_dv = self._cp_balanced(self.sel["dev"], bs)
        self.model.neurons.theta_base.copy_(self.theta_init)
        self.cp_updater, pkw = self._cp_check_updater()
        try:
            p0 = self._purity()
            tr = self._evaluate(sub_tr, split="train", cond="cp12_check", phase="check", key_stream="prototype_readout",
                                key_base=0, return_activity=True)
            act = tr.pop("_activity")
            tr.pop("latency", None)
            p1 = self._purity()
            lg_sha = _cp_hash(act["logits"])
            with t.no_grad():
                sel_p = net.targets.select_prototype(act["h"].unsqueeze(0), act["labels"])
                prop = self.cp_updater.propose(act, net.targets.prototypes, split="train", epoch=0,
                                               assign=sel_p["prototype_id"][0], **pkw)
                rows, bank_m, arr = cp_proposal_rows(prop, settings=self.cps, cond="cp12_check", classes=classes)
                H_np = act["h"].detach().to("cpu").numpy().astype(np.float64)
                lab_np = act["labels"].detach().to("cpu").numpy()
                cf = cp_counterfactual(H_np, act["logits"].detach().to("cpu").numpy(), lab_np, arr["k"],
                                       _cp_np(prop["bank_old"]), _cp_np(prop["bank_new"]),
                                       tolerance=float(self.cps["deadband"]["teacher_tolerance"]),
                                       rule=str(self.cps["learning"]["teacher_gate_rule"]), classes=classes,
                                       cond="cp13_check", epoch=0)
                cp_representation(H_np, lab_np, eps=float(self.cps["prototype"]["eps_norm"]), split="train",
                                  cond="cp12_check", epoch=0)
            p2 = self._purity()
            refused = {}
            for sp in ("dev", "test", "holdout"):
                try:
                    self.cp_updater.propose(act, net.targets.prototypes, split=sp, epoch=0, **pkw)
                    refused[sp] = False
                except ValueError:
                    refused[sp] = True
            dv = self._evaluate(sub_dv, split="dev", cond="cp12_check", phase="check")
            dv.pop("latency", None)
            p3 = self._purity()
            sel_mismatch = int((cp_select(H_np, lab_np, _cp_np(prop["bank_old"]).astype(np.float64)) != arr["k"]).sum())
        finally:
            self.cp_updater = None
        same = p0 == p1 == p2 == p3
        ok12 = bool(tr["purity_preserved"] and dv["purity_preserved"] and same and all(refused.values()))
        r12 = {"status": _cp_st(ok12), "part": "circuit", "train_readout_purity": tr["purity_preserved"],
               "dev_eval_purity": dv["purity_preserved"], "diagnostics_state_unchanged": same,
               "purity_keys": sorted(p0), "non_train_split_refused": refused,
               "criterion": "평가·진단(propose 포함) 전후 theta·bank·준비·갱신기·난수 해시 동일, train 외 분할 거부"}
        ce_same = all(r["ce_identical"] for r in cf)
        lg_same = _cp_hash(act["logits"]) == lg_sha
        allrow = next((r for r in cf if r["class"] == "ALL"), {})
        ok13 = ce_same and lg_same
        r13 = {"status": _cp_st(ok13), "part": "circuit", "ce_identical_all_rows": ce_same, "logits_unchanged": lg_same,
               "bank_would_change": prop["changed"], "n_prototypes_would_update": bank_m["n_prototypes_updated"],
               "assignment_select_prototype_vs_vectorized_mismatch": sel_mismatch,
               **{k: allrow.get(k) for k in ("residual_old_l2_mean", "residual_new_reselect_l2_mean",
                                             "residual_new_fixed_k_l2_mean", "gate_fraction_old",
                                             "gate_fraction_new_reselect", "gate_fraction_new_fixed_k")},
               "criterion": "실제 train 판독 H 에서 P_old/P_new 반사실 진단: logits·CE 불변 (목표 거리 감소는 학습 성공이 아님)"}
        return r12, r13

    # ------------------------------------------------------------------ CP14
    def _cp_check_updater(self) -> tuple[Any, dict[str, Any]]:
        """CP12/13 회로 검사에 쓸 갱신기와 propose 추가 인자 (하위 실험이 바꾼다)."""
        return PrototypeUpdater("cosine", settings=self.cps, seed=int(self.runner.cfg["seed"])), {}

    def _chk_mark(self, name: str, status: str, **extra: Any) -> None:
        """checks_progress.json: 검사 ID 별 진행·완료 상태 (도중에 끝나도 어디까지 검증했는지 남긴다)."""
        try:
            p = self.run_dir / "checks_progress.json"
            cur = read_json(p) if p.is_file() else {"format": getattr(self, "_cp_fmt", None), "parts": {}, "order": []}
            if name not in cur["parts"]:
                cur["order"].append(name)
            cur["parts"][name] = {"status": status, "utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), **extra}
            cur["note_ko"] = ("running 으로 남은 항목은 그 검사 도중 프로그램이 끝났다는 뜻이다 (결과 없음). 최종 판정은 checks.json "
                              "(작업 끝에 한 번 저장) 에 있다.")
            write_json(p, cur)
        except Exception:                                           # noqa: BLE001
            pass

    def _cp14(self, base: dict[str, Any], base_theta: np.ndarray, cond: str,
              scen: Sequence[tuple[str, dict[str, Any]]] | None = None,
              extra: Callable[[dict[str, Any], dict[str, Any]], dict[str, bool]] | None = None) -> dict[str, Any]:
        scen = scen or (("after_batch_1", {"stop_after_batches": 1}),
                        ("collecting_train_features_epoch0", {"stop_after_phase": ("collecting_train_features", 0)}),
                        ("refresh_committed_epoch0", {"stop_after_phase": ("refresh_committed", 0)}))
        bu = base["prototype_updater"]
        out: dict[str, Any] = {}
        ok = base["status"] == "completed"
        for name, kw in scen:
            r1 = self._cp_mini(cond, epochs=2, n_batches=2, **kw)
            ck = self._load_ckpt(cond, self.run_dir)
            info = {"interrupted": r1["status"] == "interrupted", "checkpoint_phase": ck["phase"] if ck else None,
                    "checkpoint_epoch": ck["epoch"] if ck else None,
                    "updater_version_at_stop": ((ck or {}).get("updater_state") or {}).get("version"),
                    "refreshes_done_at_stop": ((ck or {}).get("updater_state") or {}).get("last_completed_refresh_epoch")}
            if ck is None:
                out[name] = {**info, "pass": False, "reason_ko": "체크포인트가 없다"}
                ok = False
                continue
            r2 = self._cp_mini(cond, epochs=2, n_batches=2, resume=ck)
            th2 = np.asarray(self._tl_arrays[cond]["theta_final"])
            u2 = r2["prototype_updater"]
            pk = [(int(r["epoch"]), int(r["class_index"]), int(r["proto"])) for r in r2["prototype_rows"]]
            bk = [(int(r["epoch"]), int(r["batch"])) for r in r2["rows"]]
            res = {**info, "resumed_status": r2["status"], "theta_bitwise_equal": bool(np.array_equal(th2, base_theta)),
                   "bank_equal": r2["prototype_bank_final_sha256"] == base["prototype_bank_final_sha256"],
                   "updater_equal": (u2["version"], u2["n_commits"], u2["last_completed_refresh_epoch"])
                   == (bu["version"], bu["n_commits"], bu["last_completed_refresh_epoch"]),
                   "refresh_epochs": [int(h["epoch"]) for h in u2["history"]],
                   "prototype_rows_unique_and_same_count": len(pk) == len(set(pk)) == len(base["prototype_rows"]),
                   "batch_rows_unique_and_same_count": len(bk) == len(set(bk)) == len(base["rows"]),
                   "counterfactual_rows_same_count": len(r2["counterfactual_rows"]) == len(base["counterfactual_rows"]),
                   "dev_ce_equal": [a_["dev"]["cross_entropy"] for a_ in r2["epoch_evals"]]
                   == [b_["dev"]["cross_entropy"] for b_ in base["epoch_evals"]]}
            res["refresh_epochs_once_each"] = res["refresh_epochs"] == list(range(len(base["epoch_evals"])))
            ex = extra(r2, base) if extra is not None else {}
            res.update(ex)
            res["pass"] = bool(info["interrupted"] and r2["status"] == "completed" and all(
                res[k] for k in ("theta_bitwise_equal", "bank_equal", "updater_equal", "refresh_epochs_once_each",
                                 "prototype_rows_unique_and_same_count", "batch_rows_unique_and_same_count",
                                 "counterfactual_rows_same_count", "dev_ce_equal")) and all(ex.values()))
            self._chk_mark(f"resume:{name}", "PASSED" if res["pass"] else "FAILED")
            out[name] = res
            ok = ok and res["pass"]
        return {"status": _cp_st(ok), "part": "circuit", "condition": cond, "scenarios": out,
                "note_ko": ("같은 장치·결정론 합산에서의 비교다. refresh_committed 뒤 중단은 재개 때 EMA 를 다시 적용하지 않고 "
                            "(갱신기 last_completed_refresh_epoch 로 거부), collecting 단계 중단은 같은 theta·같은 판독 스트림으로 "
                            "H_train 을 다시 계산한다."),
                "criterion": "연속 2 에폭 실행과 중단(배치 1 뒤 / 판독 전 / commit 뒤)+재개 결과의 theta·bank·갱신기·기록 수 일치"}

    # ------------------------------------------------------------------ CP15
    def _cp15a(self) -> dict[str, Any]:
        offs = list(STREAM_OFFSETS.values())
        uniq = len(offs) == len(set(offs))
        new_streams = {k: STREAM_OFFSETS.get(k) for k in ("prototype_readout", "prototype_random_control")}
        split = read_json(self.run_dir / "data_split.json") if (self.run_dir / "data_split.json").is_file() else {}
        overlap = split.get("base_overlap") or {}
        no_overlap = bool(split) and not any(overlap.values())
        ta = self.runner.test_access
        no_test = int(ta["n_test_evaluations"]) == 0 and "test" not in self.sel
        no_holdout = not (self.run_dir / "holdout_manifest.json").exists()
        ok = uniq and all(v is not None for v in new_streams.values()) and no_overlap and no_test and no_holdout
        return {"status": _cp_st(ok), "part": "registry", "stream_offsets_unique": uniq, "new_streams": new_streams,
                "base_overlap": overlap, "n_test_evaluations": int(ta["n_test_evaluations"]),
                "test_split_removed_from_selection": "test" not in self.sel, "holdout_not_generated": no_holdout,
                "criterion": "스트림 오프셋 중복 없음, 원본 단위 분할 겹침 없음, test 평가 0, holdout 자료 미생성 (생성·평가 없이 등록 정보로)"}

    def _cp15b(self, minis: dict[str, dict[str, Any]], m4: dict[str, Any]) -> dict[str, Any]:
        init_ok = all(all(v is not False for v in r["initial_state_check"].values()) for r in minis.values())
        e0 = (m4.get("epoch_evals") or [{}])[0]
        leak_ok = (m4["status"] == "completed" and e0.get("bank_used_sha256") == self.P0_sha
                   and m4["prototype_updater"]["version"] == 0 and m4["prototype_bank_final_sha256"] == self.P0_sha
                   and m4["initial_state_check"].get("theta_equals_initial") is True)
        sub = self._cp_balanced(self.sel["train"], int(self.pre["batch_size"]))
        self.model.neurons.theta_base.copy_(self.theta_init)
        r1 = self._evaluate(sub, split="train", cond="cp15_check", phase="check_a", key_stream="prototype_readout",
                            key_base=0)
        r2 = self._evaluate(sub, split="train", cond="cp15_check", phase="check_b", key_stream="prototype_readout",
                            key_base=0)
        for r in (r1, r2):
            r.pop("latency", None)
        repro = r1.get("h_sha256") == r2.get("h_sha256") and r1.get("logits_sha256") == r2.get("logits_sha256")
        ok = init_ok and leak_ok and repro and int(self.runner.test_access["n_test_evaluations"]) == 0
        return {"status": _cp_st(ok), "part": "circuit", "initial_state_checks": {c: r["initial_state_check"]
                                                                                 for c, r in minis.items()},
                "no_leak_from_previous_condition": leak_ok,
                "leak_test_ko": "threshold_plus_cosine 다음에 실행한 threshold_only 의 첫 에폭 bank == P0, 갱신기 새 상태, theta_init",
                "prototype_readout_stream_reproducible": repro,
                "retina_drive_mode": str(self.runner.cfg["retina"]["drive"]["mode"]),
                "criterion": "조건마다 P0·theta_init·새 갱신기에서 시작, 이전 조건 상태 비전이, 같은 표본·스트림 판독 재현, test 0"}

    # ------------------------------------------------------------------ CP16b
    def _cp16b(self, mp: dict[str, Any], mask_cond: str = "threshold_plus_cosine") -> dict[str, Any]:
        name = "cp_check_teacher_off"
        self.policies[name] = cp_policy(self.cps, name, zero_teacher=True)
        self.db_masks[name] = self.db_masks[mask_cond]
        self.proto_modes[name] = "teacher_off"
        try:
            r = self._cp_mini(name, epochs=1, n_batches=2)
        finally:
            for d in (self.policies, self.db_masks, self.proto_modes):
                d.pop(name, None)
        reasons = sorted({row["reason"] for row in r["prototype_rows"]})
        gates = [float(row["teacher_gate_fraction"]) for row in r["rows"]]
        ok = (r["status"] == "completed" and r["theta_change"]["unchanged_exactly"]
              and not r["prototype_bank_changed_from_P0"] and r["prototype_updater"]["version"] == 0
              and reasons == ["teacher_globally_off"] and all(g == 0.0 for g in gates))
        return {"status": _cp_st(ok), "part": "circuit", "theta_unchanged": r["theta_change"]["unchanged_exactly"],
                "bank_unchanged": not r["prototype_bank_changed_from_P0"], "reasons": reasons,
                "teacher_gate_fraction": gates,
                "contrast_prototype_only_cosine_bank_changed": mp.get("prototype_bank_changed_from_P0"),
                "note_ko": ("국소 theta 교정만 0 인 조건(prototype_only_cosine: 임계값 동결, teacher ON)은 라벨 기반 P 갱신을 "
                            "계속 할 수 있다. 전역 teacher OFF 는 둘 다 끈다 (주 실행 조건이 아니다)."),
                "criterion": "zero_teacher 정책 + teacher_off 갱신 모드: theta·bank 비트 불변, gate 0, 모든 프로토타입 teacher_globally_off"}

    # ------------------------------------------------------------------ CP17 회로 기록 (정보용)
    def _cp17_record(self, m1: dict[str, Any]) -> dict[str, Any]:
        def tot(k: str) -> int | None:
            v = [r.get(k) for r in m1["rows"] if r.get(k) is not None]
            return int(sum(v)) if v else None
        return {"status": "INFO", "part": "circuit_record", "n_fast_clipped_raw": tot("n_fast_clipped_raw"),
                "n_fast_rounding_only": tot("n_fast_rounding_only"),
                "n_fast_clip_limited_menu21_metric": tot("n_fast_clip_limited_menu21_metric"),
                "n_base_clipped": tot("n_base_clipped"), "n_base_rounding_no_change": tot("n_base_rounding_no_change"),
                "note_ko": "작은 통합 실행의 새 계측 합계 (판정 대상 아님). CP17 판정은 CPU 합성 사례로 한다."}

    # ------------------------------------------------------------------ 메뉴 22-2
    def _cp_circuit_estimate(self) -> dict[str, Any]:
        K = int(self.cps["learning"]["K_rounds"])
        per = 2 * K + 2
        nb = 2
        per_epoch = nb * per + nb + 1
        runs = {"M1 threshold_plus_cosine 2에폭": 2, "M4 threshold_only 1에폭": 1, "M2 frozen_all 2에폭": 2,
                "M3 prototype_only_cosine 2에폭": 2, "CP14 중단+재개 3회 (각 약 2에폭 + 중단 전 부분)": 6 + 2,
                "CP16 teacher OFF 1에폭": 1}
        settles = sum(runs.values()) * per_epoch + 2 * per + 1 + 2 + 3 + 2
        return {"settles_per_epoch_mini": per_epoch, "mini_runs_epochs": runs, "settles_total_approx": settles,
                "batch_size": int(self.pre["batch_size"]), "train_batches_per_epoch_mini": nb}

    def run_checks(self, *, circuit: bool | None = None) -> dict[str, Any]:
        """CP1~CP17. CPU 합성 검사는 바로, 작은 회로 검사는 확인 뒤 사용자 PC 에서 실행한다."""
        self.run_tag = self._run_tag_given or "cosine_prototype_check"
        self._db_open("check")
        self.say("CPU 합성 검사 CP1~CP7·CP12a·CP13a·CP16a·CP17 (회로 없음) ...")
        cpu = cp_cpu_checks(self.cps)
        for k_, v_ in cpu.items():
            if isinstance(v_, dict) and "status" in v_:
                self._chk_mark(k_, v_["status"])
        est = self._cp_circuit_estimate()
        self._latency_rows, self._tl_arrays, self._selected, self._cp_arrays = [], {}, {}, {}
        circ: dict[str, Any] = {}
        do = circuit if circuit is not None else self.confirm(
            f"작은 회로 검사 CP8~CP16 (준비 1회 + 약 {est['settles_total_approx']} settle, 배치 {est['batch_size']}, "
            f"작은 학습 실행 {len(est['mini_runs_epochs'])}종, 장치 {self.runner.device}). 실행할까?")
        reg = self._cp15a()
        if do:
            prep = self._tl_prepare()
            if prep.get("status") != "completed":
                circ = {k: {"status": CP_NOT_RUN, "part": "circuit", "reason_ko": "준비 단계 실패 (IT 신호 부족)"}
                        for k in CP_CIRCUIT_PARTS}
            else:
                circ = self._cp_circuit_checks()
            self._cp_reset()
            self.tl_exec["circuit_checks"] = "completed"
        else:
            circ = {k: {"status": CP_NOT_RUN, "part": "circuit", "reason_ko": "사용자가 회로 검사를 실행하지 않았다"}
                    for k in CP_CIRCUIT_PARTS}
        parts = {**cpu, "CP15a_registry": reg, **circ}
        overall = cp_combine(parts)
        self.tl_exec["cpu_checks"] = "completed"
        checks = {"format": CP_FORMAT, "overall": overall, "parts": parts, "descriptions_ko": CP_CHECKS_KO,
                  "part_map": {k: list(v) for k, v in CP_CHECK_PARTS.items()}, "circuit_estimate": est,
                  "overall_rule_ko": ("부분 중 하나라도 FAILED 면 FAILED, 모든 부분 PASSED 면 PASSED, 그 밖(일부 NOT_RUN)은 "
                                      "NOT_RUN. 부분별 상태는 parts 에 있다."),
                  "note_ko": ("성능 향상은 통과 조건이 아니다. 합성 사례는 실제 피질 성능 예측이 아니다. smoke 1 에폭은 다음 에폭 "
                              "사용 효과를 측정하지 못하므로 CP8·CP14 는 2 에폭 작은 통합 실행으로 확인한다.")}
        if getattr(self, "_latency_rows", None):
            _write_rows_csv(self.run_dir / "latency_summary.csv", self._latency_rows)
        return self._db_finish({"validation_only": True, "path_log": self.net.path_log, "checks_overall": overall},
                               checks, "completed", "")

    def _cp_circuit_checks(self) -> dict[str, Any]:
        circ: dict[str, Any] = {}
        x, labels = self._check_batch()

        def run(name: str, fn: Callable[[], Any]) -> Any:
            self._progress({"check": name, "status": "running"})
            self._chk_mark(name, "running")
            g = lat_guard(name, fn)
            self._progress({"check": name, "status": g["status"]})
            res_ = g.get("result")
            self._chk_mark(name, (res_.get("status", "completed") if isinstance(res_, dict) else g["status"])
                           if g["status"] == "completed" else f"error: {g.get('reason_ko')}")
            if g["status"] != "completed":
                self._cp_reset()
                return None, {k: v for k, v in g.items() if k != "result"}
            return g["result"], None

        def put(key: str, res: Any, err: Any) -> None:
            circ[key] = res if err is None else {"status": CP_FAILED, "part": "circuit", "error": err}

        r, e = run("CP10", lambda: self._cp10(x, labels))
        put("CP10_circuit", r, e)
        self._cp_reset()
        tamper, e_t = run("CP8_tamper", lambda: self._cp8_tamper(x, labels))
        self._cp_reset()
        direct, e_d = run("CP9_direct", self._cp9_direct)
        self._cp_reset()
        r12_13, e = run("CP12_CP13", self._cp12_13)
        if e is None:
            circ["CP12b_circuit"], circ["CP13b_circuit"] = r12_13
        else:
            put("CP12b_circuit", None, e)
            put("CP13b_circuit", None, e)
        self._cp_reset()
        cond = "threshold_plus_cosine"
        m1, e1 = run("M1", lambda: self._cp_mini(cond, epochs=2, n_batches=2))
        m1_theta = np.asarray(self._tl_arrays[cond]["theta_final"]).copy() if e1 is None else None
        m4, e4 = run("M4", lambda: self._cp_mini("threshold_only", epochs=1, n_batches=2))
        mf, ef = run("M2", lambda: self._cp_mini("frozen_all", epochs=2, n_batches=2))
        mp, ep_ = run("M3", lambda: self._cp_mini("prototype_only_cosine", epochs=2, n_batches=2))
        if e1 is None and e_t is None:
            put("CP8_circuit", self._cp8(m1, tamper), None)
        else:
            put("CP8_circuit", None, e1 or e_t)
        if ef is None and ep_ is None and e_d is None:
            put("CP9_circuit", self._cp9(mf, mp, direct), None)
        else:
            put("CP9_circuit", None, ef or ep_ or e_d)
        minis = {k: v for k, v in (("threshold_plus_cosine", m1), ("threshold_only", m4), ("frozen_all", mf),
                                   ("prototype_only_cosine", mp)) if v is not None}
        if minis and all(v is not None for v in (m1, m4, mf, mp)):
            r, e = run("CP11", lambda: self._cp11(minis))
            put("CP11_circuit", r, e)
            r, e = run("CP15b", lambda: self._cp15b(minis, m4))
            put("CP15b_circuit", r, e)
        else:
            put("CP11_circuit", None, e1 or e4 or ef or ep_)
            put("CP15b_circuit", None, e1 or e4 or ef or ep_)
        self._cp_reset()
        if m1 is not None:
            r, e = run("CP14", lambda: self._cp14(m1, m1_theta, cond))
            put("CP14_circuit", r, e)
            self._chk_mark("CP14", circ["CP14_circuit"].get("status"))
            circ["CP17_circuit_record"] = self._cp17_record(m1)
        else:
            put("CP14_circuit", None, e1)
        self._cp_reset()
        if mp is not None:
            r, e = run("CP16b", lambda: self._cp16b(mp))
            put("CP16b_circuit", r, e)
        else:
            put("CP16b_circuit", None, ep_)
        self._cp_reset()
        return circ


CP_IMPLEMENTATION_CHAIN: list[dict[str, str]] = [
    {"step": "메뉴 22 / --mode cosine_prototype", "class": "KoreanMenu.cosine_prototype_menu / run_cli"},
    {"step": "실행기", "class": "CosinePrototypeExperiment (DeadbandAblation 상속: F0r 열기·준비·평가·지연 계측·holdout 재사용)"},
    {"step": "임계값 교정", "class": "DeadbandPolicy (relay 0, update 0, teacher_tolerance 공통) + DBPairedNetwork.db_episode"},
    {"step": "네트워크", "class": "CPPairedNetwork (DBPairedNetwork 상속, 에피소드 동안 bank 불변 검사)"},
    {"step": "목표 선택", "class": "TeacherTargetProvider.select_prototype (기존 규칙 그대로)"},
    {"step": "프로토타입 갱신", "class": "PrototypeUpdater.propose (읽기 전용) / commit (유일한 변경 지점), cp_propose_core"},
    {"step": "train 판독", "class": "_evaluate(split='train', key_stream='prototype_readout', return_activity=True)"},
    {"step": "물리 실행", "class": "CorticalModel.run -> GpuConductanceEngine.step (기존 적분식·지연·순서 그대로)"},
]
CP_FIXED_SIGNATURE_EXCLUDE: tuple[str, ...] = ("prototypes",)


def cp_fixed_signatures(sig: dict[str, str]) -> dict[str, str]:
    """준비 산출물 서명 중 고정이어야 하는 것 (C / D / T / rate_scale / attention scale / slot map). 프로토타입은 따로 본다."""
    return {k: v for k, v in sig.items() if k not in CP_FIXED_SIGNATURE_EXCLUDE}


def _cp_sum_key(rows: Sequence[dict[str, Any]], key: str) -> int | None:
    vals = [r.get(key) for r in rows if r.get(key) is not None]
    return int(sum(int(v) for v in vals)) if vals else None


class CosinePrototypeExperiment(_CPChecksMixin, DeadbandAblation):
    """메뉴 22. 메뉴 21 relay_and_update_unfiltered 회로·교정 위에서 프로토타입 bank 를 에폭마다 한 번 갱신한다.

    조건: frozen_all / threshold_only / prototype_only_cosine / threshold_plus_ema / threshold_plus_cosine
    (+ 선택 threshold_plus_random_count_matched). 감각 회로·deadband·자료·준비 산출물·settle 수는 공통이다.
    """

    def __init__(self, base_cfg: dict[str, Any], output_root: Path, device_choice: str, *,
                 settings: dict[str, Any] | None = None, seed: int | None = None,
                 env: "EnvironmentInfo | None" = None, progress: Callable[[str], None] | None = None,
                 confirm: Callable[[str], bool] | None = None, resume_from: Path | None = None,
                 allow_code_mismatch: bool = False, run_tag: str | None = None) -> None:
        cps = validate_cp_settings(settings)
        pre = cps[cps["run_preset"]]
        pf = {"preset": cps["preset"], "engine_kind": cps["engine_kind"], "stimulus_ms": cps["stimulus_ms"],
              "offset_ms": cps["offset_ms"], "dt_ms": cps["dt_ms"], "conditions": ["F0"], "include_R0": False,
              "input_repair_compare": True, "batch_size": int(pre["batch_size"]), "shapes_per_class": 1,
              "stim_types": ["shape", "no_input"]}
        PairedFeedforwardExperiment.__init__(self, base_cfg, output_root, device_choice, settings=pf, seed=seed,
                                             env=env, progress=progress, confirm=confirm)
        self.dbs = cps
        self.cps = cps
        self.tls = db_to_tl_settings(cps)
        self.pre = dict(pre)
        self._run_tag_given = run_tag
        self.run_tag = run_tag or f"cosine_prototype_{cps['run_preset']}"
        self.resume_from = Path(resume_from) if resume_from is not None else None
        self.allow_code_mismatch = bool(allow_code_mismatch)
        self.tl_exec: dict[str, Any] = {}
        self.checks: dict[str, Any] = {}
        self.db_conditions = cp_all_conditions(cps)
        self.policies = {c: cp_policy(cps, c) for c in CP_CONDITION_TABLE}
        self.proto_modes = {c: CP_CONDITION_TABLE[c]["proto"] for c in CP_CONDITION_TABLE}
        self.compare_policies: list[DeadbandPolicy] = []
        self.excluded_test: list[Any] = []
        self._log_bytes = 0
        self.cp_updater: PrototypeUpdater | None = None

    # ------------------------------------------------------------------ 설정·열기
    def model_cfg(self) -> tuple[dict[str, Any], str]:
        cfg, note = DeadbandAblation.model_cfg(self)
        cfg["readout_prep"]["prototypes"]["per_class"] = int(self.cps["prototype"]["per_class"])
        validate_config(cfg)
        return cfg, note.replace("deadband 전달/갱신 분리 실험(메뉴 21)", "코사인 기반 프로토타입 갱신 실험(메뉴 22)")

    def _make_network(self, runner: "ExperimentRunner", m: "CorticalModel", mask: Any) -> "CPPairedNetwork":
        return CPPairedNetwork(runner.cfg, m, runner.seeds, tl=self.tls, policy=self.policies["frozen_all"],
                               learn_mask=mask, obs_steps=self.obs_steps, stim_steps=self.stim_steps,
                               window_steps=self.window, gate_ref=self.ff_gate)

    def _coverage_policy_names(self) -> tuple[str, ...]:
        return ("threshold_only",)

    def _db_policy_rows(self) -> list[dict[str, Any]]:
        return cp_condition_table(self.cps)

    def _tl_write_config(self, task: str) -> None:
        DeadbandAblation._tl_write_config(self, task)
        m, rec = self.model, self.runner.recorder
        a = m.neurons
        cfg_path = self.run_dir / "config_effective.json"
        cur = read_json(cfg_path)
        dba = cur.pop("deadband_ablation", {}) or {}
        mask = self.masks["local_all_L23"]
        n_it = int(self.net.activity.specs[self.net.top_area].size)
        C = len(self.runner.cfg["decoder"]["classes"])
        Pn = int(self.runner.cfg["readout_prep"]["prototypes"]["per_class"])
        cur["cosine_prototype"] = {
            **{k: v for k, v in dba.items() if k not in ("format", "settings", "settings_sha256", "conditions", "policies",
                                                         "compare_policies_same_state", "main_contrasts",
                                                         "menu20_defaults_unchanged")},
            "format": CP_FORMAT, "settings": self.cps, "settings_sha256": db_settings_sha(self.cps),
            "conditions": self.db_conditions, "condition_table": cp_condition_table(self.cps),
            "main_contrasts": [f"{b} - {a_}" for b, a_ in CP_MAIN_CONTRASTS],
            "base_policy_ko": ("메뉴 21 relay_and_update_unfiltered 와 같은 교정 (relay 0, update 0, teacher_tolerance "
                               f"{self.cps['deadband']['teacher_tolerance']}). 임계값 동결 조건은 같은 경로를 기록용으로 계산하고 "
                               "적용하지 않는다."),
            "prototype_effective": {**self.cps["prototype"], "bank_shape": [C, Pn, n_it],
                                    "bank_shape_source": "classes x readout_prep.prototypes.per_class x IT L3 판독 슬롯 수",
                                    "assignment_rule": "정답 클래스 안 제곱 유클리드 최근접 (select_prototype, 동률은 작은 k)",
                                    "refresh_order_ko": ("에폭 마지막 commit 뒤 같은 theta_base 로 train 전체를 교사 없이 판독 -> "
                                                         "propose -> commit (프로토타입만) -> dev 평가·체크포인트. 다음 에폭부터 새 bank.")},
            "menu21_defaults_unchanged": {"conditions": list(DB_MAIN_CONDITIONS),
                                          "legacy_deadband": db_defaults()["deadband"]["legacy_deadband"]},
            "counts_from_source": {"n_neurons": int(a.n), "n_synapses": int(m.synapses.src.numel()),
                                   "n_learn_L2_L3_excitatory": int(mask.sum()), "n_IT_L3_readout": n_it,
                                   "n_classes": C, "prototypes_per_class": Pn},
            "fixed_after_preparation_ko": ["분류기 C", "영역 간 복원기 D", "L3->L2 복원기 T", "발화율 scale", "입력 정규화",
                                           "attention scale (OFF)"],
            "frozen_ko": ["W(w0)·P(전달률)·지연·막용량·누설·구획 결합·배선 고정, 연결 추가/삭제 없음",
                          "억제 출력 0, GABA-B OFF, 로그 전달률 조절 OFF, attention OFF, 항상성·theta 감쇠 OFF",
                          "준비 뒤 C / D_A / T_B / rate_scale / 입력 정규화 고정 (조건마다 같은 스냅샷 재적재). 프로토타입 bank 만 "
                          "조건의 갱신 모드에 따라 에폭 경계에서 바뀐다 (준비 파일의 P0 는 그대로).",
                          "L1/L5/L6 교정은 임계값에만. 물리 시냅스에 피드백 전류·재귀 연결을 추가하지 않는다"]}
        write_json(cfg_path, cur)
        mf = rec.manifest.pop("deadband_ablation", {}) or {}
        rec.manifest["cosine_prototype"] = {**mf, "format": CP_FORMAT, "base_source": CP_BASE_SOURCE,
                                            "implementation_chain": CP_IMPLEMENTATION_CHAIN,
                                            "change_summary": list(CP_CHANGE_SUMMARY_KO)}
        si = read_json(self.run_dir / "source_info.json")
        si.update(format=CP_FORMAT, base_source=CP_BASE_SOURCE, change_summary=list(CP_CHANGE_SUMMARY_KO),
                  modified_source=source_hash())
        write_json(self.run_dir / "source_info.json", si)
        write_json(self.run_dir / "condition_table.json", {"format": CP_FORMAT, "conditions": cp_condition_table(self.cps),
                                                           "main_contrasts": [list(x) for x in CP_MAIN_CONTRASTS]})
        drive_mode = str(self.runner.cfg["retina"]["drive"]["mode"])
        write_json(self.run_dir / "stream_registry.json", {
            "format": CP_FORMAT, "master_seed": int(self.runner.cfg["seed"]),
            "offsets": {k: STREAM_OFFSETS[k] for k in ("stimulus", "split", "input_noise", "readout_prep", "prototypes",
                                                       "prototype_readout", "prototype_random_control",
                                                       "deadband_holdout")},
            "uses": {"train_episode_drive": "('input_noise', epoch*10000 + batch) — 조건 공통",
                     "train_readout_for_prototypes": "('prototype_readout', 시작 행 번호) — train 순서 고정, 조건·에폭 공통",
                     "dev_eval_drive": "('input_noise', 900000 + 시작 행 번호)",
                     "random_count_matched": "SeedSequence([seed, 210, epoch, class, proto]) (선택 조건만, 감각 RNG 미사용)",
                     "holdout_data": "deadband_holdout 스트림 (메뉴 22-7 에서만)"},
            "retina_drive_mode": drive_mode,
            "note_ko": ("retina drive 가 current 모드면 외생 입력에 잡음이 없어 키가 결과를 바꾸지 않는다. poisson 이면 같은 키·같은 "
                        "배치 구성에서 같은 잡음이 재현된다. 갱신기 진단은 감각 RNG 를 쓰지 않는다.")})

    # ------------------------------------------------------------------ 준비·순수성·메타
    def _tl_prepare(self) -> dict[str, Any]:
        info = DeadbandAblation._tl_prepare(self)
        if info.get("status") in ("completed", "reused_for_resume"):
            bank = self.net.targets.prototypes
            self.P0 = bank.detach().clone()
            self.P0_sha = tensor_hash(self.P0)
            self.prep_fixed_sig = cp_fixed_signatures(self.prep_sig)
            info["prototype_bank_P0"] = {"shape": list(bank.shape), "sha256": self.P0_sha,
                                         "note_ko": "준비 파일의 P0 는 덮어쓰지 않는다. 조건별 동적 bank 는 체크포인트에 따로 저장한다."}
            write_json(self.run_dir / "preparation_report.json", info)
        return info

    def _cp_p0_sha(self) -> str | None:
        if getattr(self, "P0_sha", None):
            return self.P0_sha
        snap = getattr(self, "prep_snapshot", None)
        if snap and (snap.get("prototypes") or {}).get("prototypes") is not None:
            t = require_torch()
            return tensor_hash(t.tensor(np.asarray(snap["prototypes"]["prototypes"], np.float64), dtype=self.model.dtype))
        return None

    def _purity(self) -> dict[str, str]:
        p = DeadbandAblation._purity(self)
        p["prototype_bank"] = tensor_hash(self.net.targets.prototypes) if self.net.targets.prototypes is not None else "none"
        p["prototype_updater"] = self.cp_updater.state_hash() if self.cp_updater is not None else "none"
        return p

    def _db_meta_common(self, cond: str) -> dict[str, Any]:
        out = DeadbandAblation._db_meta_common(self, cond)
        out["format"] = CP_FORMAT
        out["prototype_mode"] = self.proto_modes.get(cond)
        out["prototype_settings_sha256"] = sha256_text(json.dumps(self.cps["prototype"], sort_keys=True))
        out["P0_sha256"] = self._cp_p0_sha()
        return out

    def _db_ckpt_issues(self, meta: dict[str, Any], cond: str) -> list[str]:
        issues = DeadbandAblation._db_ckpt_issues(self, meta, cond)
        now = self._db_meta_common(cond)
        for k in ("prototype_mode", "prototype_settings_sha256", "P0_sha256"):
            if meta.get(k) != now.get(k):
                issues.append(k)
        return issues

    def _evaluate(self, stims: Sequence[Any], *, split: str, cond: str, phase: str, key_stream: str = "input_noise",
                  key_base: int = 900_000, return_activity: bool = False) -> dict[str, Any]:
        res = DeadbandAblation._evaluate(self, stims, split=split, cond=cond, phase=phase, key_stream=key_stream,
                                         key_base=key_base, return_activity=True)
        act = res.pop("_activity", None)
        if act is not None:
            res["logits_sha256"] = _cp_hash(act["logits"])
            res["h_sha256"] = _cp_hash(act["h"])
            res["readout_stream"] = [key_stream, int(key_base)]
            if return_activity:
                res["_activity"] = act
        return res

    def _estimate(self) -> dict[str, Any]:
        n_prep = (len(self.sel["train"]) if not int(self.pre.get("prep_max_samples") or 0)
                  else min(len(self.sel["train"]), int(self.pre["prep_max_samples"])))
        C = len(self.runner.cfg["decoder"]["classes"])
        return {**cp_estimate(n_conditions=len(self.db_conditions), n_train=len(self.sel["train"]), n_dev=len(self.sel["dev"]),
                              batch_size=int(self.pre["batch_size"]), epochs=int(self.pre["epochs"]),
                              K=int(self.cps["learning"]["K_rounds"]), n_prep=n_prep,
                              n_diag_stimuli=len(self.cps["diagnostic_stimuli"]), steps=self.obs_steps,
                              diagnostic_each_epoch=bool(self.cps["diagnostic_each_epoch"])),
                "model_memory": self.model.memory_estimate(1, int(self.pre["batch_size"])),
                "split_sizes": {k: len(v) for k, v in self.sel.items()},
                "split_labels": {k: {lab: sum(1 for s in v if s.label == lab) for lab in sorted({s.label for s in v})}
                                 for k, v in self.sel.items()},
                "excluded_public_test": len(self.excluded_test), "conditions": cp_condition_table(self.cps),
                "prototype_bank_shape": [C, int(self.runner.cfg["readout_prep"]["prototypes"]["per_class"]),
                                         int(self.net.activity.specs[self.net.top_area].size)],
                "expected_outputs": ["config_effective.json", "condition_table.json", "plan.json", "data_split.json",
                                     "stream_registry.json", "test_access.json", "preparation_report.json",
                                     "train_history.csv", "evaluation.json", "prototype_update_history.csv",
                                     "prototype_assignment_history.npz", "prototype_history.npz",
                                     "prototype_counterfactual.csv", "representation_metrics.csv", "latency_summary.csv",
                                     "correction_flow_summary.json", "checkpoints/<조건>/", "checks.json", "timing.json",
                                     "progress.jsonl", "run.log", "REPORT.md", "figures/"],
                "device": str(self.runner.device), "cuda": str(self.runner.device).startswith("cuda")}

    # ------------------------------------------------------------------ 체크포인트 (npz 하나에 메타까지, 원자적 교체)
    def _save_ckpt(self, cond: str, st: dict[str, Any]) -> None:
        t = require_torch()
        jp, npz = self._ckpt_paths(cond)
        upd = self.cp_updater
        meta = {**self._db_meta_common(cond), "epoch": int(st["epoch"]), "next_batch": int(st["next_batch"]),
                "phase": st["phase"], "rng": self.runner.seeds.state_dict(),
                "rng_sha256": sha256_text(json.dumps(self.runner.seeds.state_dict(), sort_keys=True, default=str)),
                "torch_cpu_rng_sha256": hashlib.sha256(t.random.get_rng_state().numpy().tobytes()).hexdigest(),
                "rows": st["rows"], "epoch_evals": st["epoch_evals"], "n_commits": st["n_commits"],
                "selection": st["selection"], "proto_rows": st["proto_rows"], "bank_rows": st["bank_rows"],
                "cf_rows": st["cf_rows"], "repr_rows": st["repr_rows"], "pending_train_eval": st["pending_train_eval"],
                "bank_used_sha256": st["bank_used_sha"], "updater_state": (upd.state_dict() if upd else None),
                "prototype_version": (upd.version if upd else None),
                "last_completed_refresh_epoch": (upd.last_completed_refresh_epoch if upd else None),
                "assign_sample_ids": st["assign_sample_ids"], "timing": st["timing"],
                "accepted_counts": [[int(r["epoch"]), int(r["class_index"]), int(r["proto"]), int(r["n_accepted"]),
                                     bool(r["applied"])] for r in st["proto_rows"]],
                "accepted_counts_columns": ["epoch", "class_index", "proto", "n_accepted", "applied"],
                "log_commit_marker": {"n_rows": len(st["rows"]), "n_proto_rows": len(st["proto_rows"]),
                                      "n_cf_rows": len(st["cf_rows"]), "jsonl_bytes": self._log_bytes},
                "source_sha256": source_hash().get("sha256", ""), "dataset_split_digest": self.runner.data_digest,
                "preparation_state_reference": "checkpoints/preparation_state.json", "phases": list(CP_PHASES),
                "resume_unit": "completed_minibatch 또는 에폭 경계 단계",
                "note_ko": ("phase=refresh_committed 이면 이 에폭의 프로토타입 갱신은 이미 적용됐다 (재개 때 다시 적용하지 않는다). "
                            "phase=collecting_train_features 이면 같은 theta 로 train 판독을 다시 계산한다.")}
        meta.update(self._cp_ckpt_meta_extra(st))
        nl = int(self.learn_ids.numel())
        bank = self.net.targets.prototypes.detach().to("cpu").numpy()
        shp = bank.shape

        def stack(xs: list[Any], shape: tuple[int, ...], dtype: Any) -> np.ndarray:
            return np.asarray(xs, dtype).reshape((-1,) + tuple(shape)) if xs else np.zeros((0,) + tuple(shape), dtype)
        S = len(st["assign_sample_ids"])
        arrs = {"theta_base": self.model.neurons.theta_base.detach().to("cpu").numpy(),
                "theta_history": np.asarray(st["theta_history"], np.float32).reshape(-1, nl),
                "epoch_end_theta": np.asarray(st["epoch_end_theta"], np.float32).reshape(-1, self.model.neurons.n),
                "batch_signs": np.asarray(st["batch_signs"], np.int8).reshape(-1, nl),
                "torch_cpu_rng_state": t.random.get_rng_state().numpy(),
                "prototype_bank_current": bank,
                "prototype_bank_used_for_epoch": (np.asarray(st["bank_used_current"]) if st["bank_used_current"] is not None
                                                  else bank),
                "bank_used_history": stack(st["bank_used"], shp, np.float64),
                "bank_after_history": stack(st["bank_after"], shp, np.float64)}
        for key in ("k", "label", "cos", "cos_raw", "accept", "cos_pass", "valid_norm", "norm_h", "norm_P"):
            arrs[f"assign_{key}"] = (np.stack([np.asarray(x[key]) for x in st["assign"]]) if st["assign"]
                                     else np.zeros((0, S)))
        arrs.update(self._cp_ckpt_arrays_extra(st))
        tmp = npz.with_name("latest_tmp.npz")
        np.savez_compressed(tmp, meta_json=np.array(dumps(meta, indent=None)), **arrs)
        os.replace(tmp, npz)
        write_json(jp, {k: meta[k] for k in ("format", "condition", "epoch", "next_batch", "phase", "prototype_version",
                                             "last_completed_refresh_epoch", "code_sha256", "policy", "note_ko")})

    def _load_ckpt(self, cond: str, src_root: Path) -> dict[str, Any] | None:
        t = require_torch()
        npz = src_root / "checkpoints" / safe_name(cond) / "latest.npz"
        if not npz.is_file():
            return None
        with np.load(npz, allow_pickle=False) as z:
            if "meta_json" not in z.files:
                raise RuntimeError(f"메뉴 22 체크포인트 형식이 아니다: {npz}")
            meta = json.loads(str(z["meta_json"]))
            arr = {k: np.array(z[k]) for k in z.files if k != "meta_json"}
        issues = self._db_ckpt_issues(meta, cond)
        if issues:
            raise RuntimeError(f"체크포인트가 현재 실행과 맞지 않는다 ({cond}): {issues}. 조용히 이어 붙이지 않는다.")
        n_as = int(arr["assign_k"].shape[0])
        assign = [{key: arr[f"assign_{key}"][i] for key in ("k", "label", "cos", "cos_raw", "accept", "cos_pass",
                                                             "valid_norm", "norm_h", "norm_P")} for i in range(n_as)]
        out = {"epoch": int(meta["epoch"]), "next_batch": int(meta["next_batch"]), "phase": meta["phase"],
                "rows": list(meta["rows"]), "epoch_evals": list(meta["epoch_evals"]), "n_commits": int(meta["n_commits"]),
                "selection": dict(meta["selection"]), "proto_rows": list(meta["proto_rows"]),
                "bank_rows": list(meta["bank_rows"]), "cf_rows": list(meta["cf_rows"]), "repr_rows": list(meta["repr_rows"]),
                "pending_train_eval": meta["pending_train_eval"], "bank_used_sha": meta["bank_used_sha256"],
                "updater_state": meta["updater_state"], "assign_sample_ids": list(meta["assign_sample_ids"]),
                "timing": dict(meta.get("timing") or {}),
                "theta": t.tensor(arr["theta_base"], dtype=self.model.dtype, device=self.model.device),
                "theta_history": list(arr["theta_history"]), "epoch_end_theta": list(arr["epoch_end_theta"]),
                "batch_signs": list(arr["batch_signs"]), "torch_cpu_rng_state": arr["torch_cpu_rng_state"],
                "bank_current": arr["prototype_bank_current"],
                "bank_used_current": (arr["prototype_bank_used_for_epoch"] if meta.get("bank_used_sha256") else None),
                "bank_used": list(arr["bank_used_history"]), "bank_after": list(arr["bank_after_history"]),
                "assign": assign, "rng": meta.get("rng"),
                "code_same": meta.get("code_sha256") == source_hash().get("sha256", "")}
        self._cp_ckpt_restore(out, meta, arr)
        return out

    def _save_selected(self, cond: str, theta: Any, sel: dict[str, Any], *, bank_used: np.ndarray | None = None,
                       bank_after: np.ndarray | None = None, version_after: int | None = None,
                       extra_arrays: dict[str, np.ndarray] | None = None) -> None:
        d = ensure_writable_dir(self.run_dir / "checkpoints" / safe_name(cond))
        bu = np.asarray(bank_used if bank_used is not None else self.net.targets.prototypes.detach().to("cpu").numpy())
        ba = np.asarray(bank_after if bank_after is not None else bu)
        np.savez_compressed(d / "selected.npz", theta_base=theta.detach().to("cpu").numpy(),
                            prototype_bank_used_for_epoch=bu, prototype_bank_after_epoch=ba, **(extra_arrays or {}))
        write_json(d / "selected.json", {
            **self._db_meta_common(cond), **sel, "theta_sha256": tensor_hash(theta),
            "prototype_bank_used_sha256": _cp_hash(bu.astype(np.float64)),
            "prototype_bank_after_sha256": _cp_hash(ba.astype(np.float64)), "prototype_version_after": version_after,
            "final": True,
            "note_ko": ("prototype_bank_used_for_epoch 는 그 에폭의 임계값 학습에 쓴 bank, prototype_bank_after_epoch 는 그 에폭 끝 "
                        "갱신 뒤 bank 다 (다음 에폭용). 추론 분류기는 C(h_IT) 이며 bank 를 쓰지 않는다.")})

    def _db_selected_extra(self, cond: str, z: Any, meta: dict[str, Any]) -> dict[str, Any] | None:
        if "prototype_bank_after_epoch" not in z.files:
            return None
        return {"bank_after": np.array(z["prototype_bank_after_epoch"]), "bank_used": np.array(z["prototype_bank_used_for_epoch"]),
                "sha_after": meta.get("prototype_bank_after_sha256")}

    def _db_apply_selected_extra(self, cond: str, extra: dict[str, Any] | None) -> None:
        if extra is None:
            return
        t = require_torch()
        if extra.get("sha_after") and _cp_hash(extra["bank_after"].astype(np.float64)) != extra["sha_after"]:
            raise RuntimeError(f"{cond}: selected.npz 의 bank 해시가 selected.json 과 다르다.")
        self.net.targets.prototypes = t.tensor(extra["bank_after"], dtype=self.model.dtype, device=self.model.device)

    # ------------------------------------------------------------------ 하위 실험(메뉴 23)용 연결 지점 (기본 동작 = 메뉴 22 그대로)
    _cp_fmt: str = CP_FORMAT
    _cp_key: str = "cosine_prototype"
    _cp_menu: str = "22"

    def _cp_tag(self, kind: str) -> str:
        return f"{self._cp_key}_{kind}"

    def _cp_validate(self, settings: dict[str, Any] | None) -> dict[str, Any]:
        return validate_cp_settings(settings)

    def _cp_condition_rows(self) -> list[dict[str, Any]]:
        return cp_condition_table(self.cps)

    def _cp_new_updater(self, mode: str) -> Any:
        return PrototypeUpdater(mode, settings=self.cps, seed=int(self.runner.cfg["seed"]))

    def _cp_state_init(self, cond: str, st: dict[str, Any], init: dict[str, Any], resume: dict[str, Any] | None) -> None:
        return None

    def _cp_epoch_begin(self, st: dict[str, Any], epoch: int, cond: str) -> None:
        return None

    def _cp_row_extra(self, st: dict[str, Any], row: dict[str, Any]) -> None:
        return None

    def _cp_refresh(self, cond: str, epoch: int, act: dict[str, Any], upd: Any, st: dict[str, Any],
                    classes: list[str], eps: float) -> tuple[Any, ...]:
        """에폭 끝 train 판독 -> 배정 -> propose -> 진단 -> commit (메뉴 22 계산 그대로)."""
        net = self.net
        sel_p = net.targets.select_prototype(act["h"].unsqueeze(0), act["labels"])
        assign = sel_p["prototype_id"][0]
        prop = upd.propose(act, net.targets.prototypes, split="train", epoch=epoch, assign=assign)
        H_np = act["h"].detach().to("cpu").numpy().astype(np.float64)
        lab_np = act["labels"].detach().to("cpu").numpy()
        prows, bank_m, arr = cp_proposal_rows(prop, settings=self.cps, cond=cond, classes=classes)
        bank_m["assign_selfcheck_mismatch"] = int(
            (cp_select(H_np, lab_np, _cp_np(prop["bank_old"]).astype(np.float64)) != arr["k"]).sum())
        cf = cp_counterfactual(H_np, act["logits"].detach().to("cpu").numpy(), lab_np, arr["k"],
                               _cp_np(prop["bank_old"]), _cp_np(prop["bank_new"]),
                               tolerance=float(self.cps["deadband"]["teacher_tolerance"]),
                               rule=str(self.cps["learning"]["teacher_gate_rule"]), classes=classes,
                               cond=cond, epoch=epoch)
        rep = cp_representation(H_np, lab_np, eps=eps, split="train", cond=cond, epoch=epoch)
        crec = upd.commit(prop, net.targets)
        return prows, bank_m, arr, cf, rep, crec

    def _cp_epoch_eval_extra(self, st: dict[str, Any], ev: dict[str, Any]) -> None:
        return None

