class APNumericError(CPNumericError):
    """상태 판정·적응 갱신 입력/결과에 NaN/Inf 또는 허용 반올림을 넘는 범위 위반이 있다 (0 으로 덮지 않는다)."""


def ap_defaults() -> dict[str, Any]:
    """메뉴 23 기본값 (명세 3절 표). 메뉴 20·21·22 기본값과 별개."""
    s = cp_defaults()
    s["conditions"] = list(AP_MAIN_CONDITIONS)
    s["optional_conditions"] = []
    s["prototype"] = {"per_class": 3, "tau_cos": 0.95, "tau_cos_unstable": 0.90, "rho_proto": 0.10,
                      "rho_proto_unstable": 0.30, "instability_enter_cos": 0.99, "instability_exit_cos": 0.97,
                      "max_angle_step_deg": 2.0, "backtrack_max": 32, "alpha_min": 1e-8, "eps_norm": 1e-8,
                      "min_accept_count": 2, "refresh": "epoch", "cos_round_tol": 1e-9, "range_rounding_tol": 1e-6,
                      "change_log_tol": 1e-7, "norm_equal_tol": 1e-6, "axis_zero_tol": 1e-3, "axis_one_tol": 1e-3,
                      "teacher_globally_off": False,
                      "note_ko": ("tau_cos / rho_proto 는 STABLE 값, *_unstable 은 UNSTABLE 이면서 해당 기능을 켠 조건의 값이다. 사전 "
                                  "지정 시작값이며 검증된 최적값이 아니다. rho_proto 는 eta_commit·rho_fast·시냅스 전달률과 다른 "
                                  "변수다. cos_round_tol·change_log_tol·norm_equal_tol·axis_* 는 기록용 허용오차이며 gate 에 쓰지 않는다.")}
    s["note_ko"] = ("초기 P0 직후와 매 에폭 끝에 프로토타입끼리 비교해 다른 클래스와 방향이 지나치게 비슷한 것을 UNSTABLE 로 두고, 그 "
                    "동안 자기 클래스 활동의 허들을 낮추고 반영률을 높이되 방향 변화는 작게 제한한다. 성능 향상을 가정하지 않는다.")
    return s


def validate_ap_settings(settings: dict[str, Any] | None) -> dict[str, Any]:
    """메뉴 23 설정 검사. 공통 부분은 메뉴 21 검사기를 그대로 쓰고 조건·프로토타입 부분만 따로 본다."""
    s = _db_merge(ap_defaults(), settings)
    common = copy.deepcopy(s)
    common["conditions"] = list(DB_MAIN_CONDITIONS)
    common["optional_conditions"] = []
    common.pop("prototype", None)
    validate_db_settings(common)
    dbd = s["deadband"]
    if float(dbd.get("relay_deadband", 0.0)) != 0.0 or float(dbd.get("update_deadband", 0.0)) != 0.0:
        raise ValueError("메뉴 23 은 relay_deadband / update_deadband 를 0 / 0 으로 고정한다.")
    if s["compare_policies_each_batch"]:
        raise ValueError("메뉴 23 에서는 deadband 정책 비교(메뉴 21 기능)를 끈다.")
    if list(s["conditions"]) != list(AP_MAIN_CONDITIONS):
        raise ValueError(f"주 비교 조건은 순서까지 {list(AP_MAIN_CONDITIONS)} 로 고정이다 (몰래 늘리지 않는다).")
    for c in s["optional_conditions"]:
        if c not in AP_OPTIONAL_CONDITIONS:
            raise ValueError(f"메뉴 23 의 선택 조건은 {list(AP_OPTIONAL_CONDITIONS) or '없음'} 이다: {c}")
    p = s["prototype"]
    f = {k: float(p[k]) for k in ("tau_cos", "tau_cos_unstable", "rho_proto", "rho_proto_unstable",
                                  "instability_enter_cos", "instability_exit_cos", "max_angle_step_deg", "eps_norm",
                                  "alpha_min", "cos_round_tol", "range_rounding_tol", "change_log_tol")}
    if not all(math.isfinite(v) for v in f.values()):
        raise ValueError("프로토타입 설정에 NaN/Inf 가 있다.")
    if not (0.0 <= f["rho_proto"] <= f["rho_proto_unstable"] <= 1.0):
        raise ValueError("0 <= rho_proto(STABLE) <= rho_proto_unstable <= 1 이어야 한다.")
    if not (-1.0 <= f["tau_cos_unstable"] <= f["tau_cos"] <= 1.0):
        raise ValueError("-1 <= tau_cos_unstable <= tau_cos(STABLE) <= 1 이어야 한다.")
    if not (-1.0 <= f["instability_exit_cos"] < f["instability_enter_cos"] <= 1.0):
        raise ValueError("-1 <= instability_exit_cos < instability_enter_cos <= 1 이어야 한다 (이력 규칙).")
    if not (0.0 < f["max_angle_step_deg"] <= 90.0):
        raise ValueError("max_angle_step_deg 는 0 보다 크고 90 이하다.")
    if not f["eps_norm"] > 0 or not f["alpha_min"] > 0:
        raise ValueError("eps_norm, alpha_min 은 양수다.")
    for k in ("cos_round_tol", "range_rounding_tol", "change_log_tol"):
        if f[k] < 0:
            raise ValueError(f"{k} 는 0 이상이다.")
    for k in ("min_accept_count", "backtrack_max", "per_class"):
        if int(p[k]) != float(p[k]) or int(p[k]) < (0 if k == "backtrack_max" else 1):
            raise ValueError(f"{k} 는 {'0' if k == 'backtrack_max' else '1'} 이상 정수다.")
    if p["refresh"] != "epoch":
        raise ValueError("프로토타입 갱신·상태 판정 주기는 에폭당 한 번(epoch) 만 지원한다.")
    if not isinstance(p.get("teacher_globally_off"), bool) or p["teacher_globally_off"]:
        raise ValueError("teacher_globally_off 는 사전 검사(AP12) 전용이다. 주 실행에서는 켜지 않는다.")
    return s


def ap_all_conditions(s: dict[str, Any]) -> list[str]:
    return list(s["conditions"]) + [c for c in s["optional_conditions"] if c not in s["conditions"]]


def ap_policy(s: dict[str, Any], cond: str, *, zero_teacher: bool = False) -> DeadbandPolicy:
    """조건 -> 임계값 교정 정책. 모든 조건이 같은 L2/L3 학습 (relay 0 / update 0 / 같은 teacher_tolerance)."""
    if cond not in AP_CONDITION_TABLE and not cond.startswith("cp_check"):
        raise ValueError(f"알 수 없는 메뉴 23 조건: {cond!r}")
    return DeadbandPolicy(name=cond, teacher_tolerance=float(s["deadband"]["teacher_tolerance"]),
                          relay_deadband=0.0, update_deadband=0.0, freeze=False, zero_teacher=bool(zero_teacher))


def ap_condition_table(s: dict[str, Any]) -> list[dict[str, Any]]:
    p = s["prototype"]
    out = []
    for c in ap_all_conditions(s):
        row = AP_CONDITION_TABLE[c]
        pol = ap_policy(s, c)
        out.append({"condition": c, "threshold_learning": True, "prototype_mode": row["proto"],
                    "adapt_rho": row["adapt_rho"], "adapt_tau": row["adapt_tau"],
                    "angle_cap_deg": float(p["max_angle_step_deg"]) if row["angle_cap"] else None,
                    "tau_stable": float(p["tau_cos"]) if row["proto"] != "fixed" else None,
                    "tau_unstable": (float(p["tau_cos_unstable"]) if row["adapt_tau"] else
                                     (float(p["tau_cos"]) if row["proto"] != "fixed" else None)),
                    "rho_stable": float(p["rho_proto"]) if row["proto"] != "fixed" else None,
                    "rho_unstable": (float(p["rho_proto_unstable"]) if row["adapt_rho"] else
                                     (float(p["rho_proto"]) if row["proto"] != "fixed" else None)),
                    "relay_deadband": pol.relay_deadband, "update_deadband": pol.update_deadband,
                    "teacher_tolerance": pol.teacher_tolerance, "description_ko": AP_CONDITIONS_KO[c]})
    return out


def ap_rates(states: np.ndarray, row: dict[str, Any], p: dict[str, Any]) -> tuple[np.ndarray, np.ndarray]:
    """상태 [C,P] -> (tau_j, rho_j). UNSTABLE 이고 해당 기능이 켜진 조건에서만 바꾼다 (INVALID/UNDETERMINED 은 STABLE 값)."""
    st = np.asarray(states)
    tau = np.full(st.shape, float(p["tau_cos"]), np.float64)
    rho = np.full(st.shape, float(p["rho_proto"]), np.float64)
    uns = st == AP_UNSTABLE
    if row.get("adapt_tau"):
        tau[uns] = float(p["tau_cos_unstable"])
    if row.get("adapt_rho"):
        rho[uns] = float(p["rho_proto_unstable"])
    return tau, rho


def _ap_hash(*arrs: Any) -> str:
    h = hashlib.sha256()
    for a in arrs:
        a = np.ascontiguousarray(np.asarray(a))
        h.update(a.tobytes() + str(a.dtype).encode() + str(a.shape).encode())
    return h.hexdigest()


# ---------------------------------------------------------------------- 상태 판정 (작은 bank, 에폭당 한 번)
def ap_judge_states(bank: Any, prev_state: Any = None, prev_valid: Any = None, *, enter: float, exit_: float,
                    eps: float, round_tol: float = 1e-9) -> dict[str, Any]:
    """수정 완료된 bank 한 벌로 모든 프로토타입의 상태를 동시에 판정한다 (클래스 순서로 바꿔 가며 적용하지 않는다).

    s_j = max cosine(P_j, P_k), class(k) != class(j), 둘 다 ||P|| > eps. abs 를 쓰지 않는다. 동률은 평탄 ID 순서의 첫 값.
    prev_state 가 None 이면 초기 판정. 이전이 INVALID/UNDETERMINED 이면 초기 규칙으로 복귀한다.
    """
    enter, exit_, eps = float(enter), float(exit_), float(eps)
    if _is_torch(bank):
        t = require_torch()
        B = bank.detach().to(t.float64)
        if not bool(t.isfinite(B).all()):
            raise APNumericError("상태 판정 bank 에 NaN/Inf 가 있다 (정상 상태로 덮지 않는다).")
        C, P, n = (int(v) for v in B.shape)
        flat = B.reshape(C * P, n)
        nrm = t.sqrt((flat * flat).sum(dim=-1))
        valid_t = nrm > eps
        U = t.where(valid_t.unsqueeze(-1), flat / t.where(valid_t, nrm, t.ones_like(nrm)).unsqueeze(-1),
                    t.zeros_like(flat))
        G = (U @ U.T).to("cpu").numpy()
        nrm_np = nrm.to("cpu").numpy()
    else:
        B = np.asarray(bank, np.float64)
        if not np.isfinite(B).all():
            raise APNumericError("상태 판정 bank 에 NaN/Inf 가 있다 (정상 상태로 덮지 않는다).")
        C, P, n = B.shape
        flat = B.reshape(C * P, n)
        nrm_np = np.sqrt((flat * flat).sum(axis=-1))
        vv = nrm_np > eps
        U = np.where(vv[:, None], flat / np.where(vv, nrm_np, 1.0)[:, None], 0.0)
        G = U @ U.T
    Np = C * P
    valid = nrm_np > eps
    cls = np.repeat(np.arange(C), P)
    pid = np.tile(np.arange(P), C)
    pair_valid = valid[:, None] & valid[None, :]
    over = np.where(pair_valid, np.abs(G) - 1.0, -np.inf)
    max_over = float(over.max()) if Np else 0.0
    n_clip = int((over > 0).sum())
    if max_over > float(round_tol):
        raise APNumericError(f"cosine 이 [-1,1] 을 반올림 허용오차({round_tol}) 넘게 벗어났다: {max_over:.3g}")
    G = np.where(pair_valid, np.clip(G, -1.0, 1.0), np.nan)
    other = (cls[:, None] != cls[None, :]) & pair_valid
    same = (cls[:, None] == cls[None, :]) & pair_valid & ~np.eye(Np, dtype=bool)
    ps = (np.full(Np, AP_NO_STATE, np.int64) if prev_state is None else np.asarray(prev_state, np.int64).reshape(-1))
    pv = (np.full(Np, AP_NO_STATE, np.int64) if prev_valid is None else np.asarray(prev_valid, np.int64).reshape(-1))
    states = np.zeros(Np, np.int64)
    new_valid = pv.copy()
    s_max = np.full(Np, np.nan)
    partner = np.full(Np, -1, np.int64)
    within = np.full(Np, np.nan)
    reasons: list[str] = []
    for j in range(Np):
        if same[j].any():
            within[j] = float(np.nanmax(np.where(same[j], G[j], -np.inf)))
        if not valid[j]:
            states[j] = AP_INVALID
            reasons.append("zero_norm")
            continue
        if not other[j].any():
            states[j] = AP_UNDETERMINED
            reasons.append("no_comparable_other_class")
            continue
        row = np.where(other[j], G[j], -np.inf)
        k = int(np.argmax(row))
        s = float(row[k])
        s_max[j], partner[j] = s, k
        prev = int(ps[j])
        if prev not in (AP_STABLE, AP_UNSTABLE):
            states[j] = AP_UNSTABLE if s >= enter else AP_STABLE
            reasons.append("initial_rule" if prev == AP_NO_STATE else "reentry_initial_rule")
        elif s >= enter:
            states[j] = AP_UNSTABLE
            reasons.append("enter" if prev == AP_STABLE else "stay_above_enter")
        elif s < exit_:
            states[j] = AP_STABLE
            reasons.append("exit" if prev == AP_UNSTABLE else "stay_below_exit")
        else:
            states[j] = prev
            reasons.append("hold_between_exit_enter")
        new_valid[j] = states[j]
    trans = int(((ps != states) & (ps != AP_NO_STATE)).sum())
    return {"states": states.reshape(C, P), "prev_state": ps.reshape(C, P), "prev_valid": new_valid.reshape(C, P),
            "s_max": s_max.reshape(C, P), "partner_flat": partner.reshape(C, P),
            "partner_class": np.where(partner >= 0, cls[np.maximum(partner, 0)], -1).reshape(C, P),
            "partner_proto": np.where(partner >= 0, pid[np.maximum(partner, 0)], -1).reshape(C, P),
            "within_class_max_cos": within.reshape(C, P), "norm": nrm_np.reshape(C, P), "valid": valid.reshape(C, P),
            "reasons": reasons, "cos_matrix": G, "class_index": cls, "proto_index": pid,
            "n_cos_clipped": n_clip, "max_cos_overshoot": max(0.0, max_over), "round_tol": float(round_tol),
            "n_transitions": trans, "n_judged": Np, "initial": prev_state is None,
            "enter": enter, "exit": exit_, "precision": "float64 (U @ U.T, 저장 bank 는 원래 dtype 그대로)",
            "counts": {AP_STATE_NAMES[k]: int((states == k).sum()) for k in AP_STATE_NAMES}}


def ap_state_rows(jd: dict[str, Any], *, cond: str, epoch: int, applies_from: int, classes: Sequence[str]
                  ) -> list[dict[str, Any]]:
    C, P = jd["states"].shape
    rows = []
    for c in range(C):
        for k in range(P):
            j = c * P + k
            prev = int(jd["prev_state"][c, k])
            nxt = int(jd["states"][c, k])
            pc, pk = int(jd["partner_class"][c, k]), int(jd["partner_proto"][c, k])
            s = jd["s_max"][c, k]
            w = jd["within_class_max_cos"][c, k]
            rows.append({"condition": cond, "epoch": int(epoch), "applies_from_epoch": int(applies_from),
                         "class": classes[c] if c < len(classes) else c, "class_index": c, "proto": k,
                         "previous_state": AP_STATE_NAMES.get(prev, "NONE"), "next_state": AP_STATE_NAMES[nxt],
                         "transition": (AP_STATE_NAMES.get(prev, "NONE") + "->" + AP_STATE_NAMES[nxt]) if prev != nxt
                         else "none", "changed": prev != nxt and prev != AP_NO_STATE,
                         "s_max_other": (None if not np.isfinite(s) else float(s)),
                         "partner_class": (classes[pc] if 0 <= pc < len(classes) else None),
                         "partner_class_index": (pc if pc >= 0 else None), "partner_proto": (pk if pk >= 0 else None),
                         "reason": jd["reasons"][j], "enter_cos": jd["enter"], "exit_cos": jd["exit"],
                         "within_class_max_cos": (None if not np.isfinite(w) else float(w)),
                         "norm_P": float(jd["norm"][c, k])})
    return rows


# ---------------------------------------------------------------------- 적응 갱신 (각도 상한 EMA)
def _ap_to64(x: Any) -> Any:
    return x.detach().to(require_torch().float64) if _is_torch(x) else np.asarray(x, np.float64)


def _ap_cast(x64: Any, like: Any) -> Any:
    return x64.to(like.dtype) if _is_torch(like) else np.asarray(x64).astype(np.asarray(like).dtype)


def _ap_f(x: Any) -> float:
    return float(x)


def ap_capped_step(p_old: Any, mu: Any, rho: float, *, max_angle_deg: float, backtrack_max: int, alpha_min: float,
                   eps: float) -> dict[str, Any]:
    """candidate(alpha) = P_old + alpha (mu - P_old), 0 <= alpha <= rho. 저장 dtype 으로 바꾼 뒤 angle(P_old, P_new) <= 상한.

    초과하면 alpha 를 절반으로 줄인다 (최대 backtrack_max 회, alpha < alpha_min 이면 중단). alpha = 0 은 즉시 비트 무변화.
    """
    p64 = _ap_to64(p_old)
    m64 = _ap_to64(mu)
    n0 = math.sqrt(_ap_f((p64 * p64).sum()))
    cmin = math.cos(math.radians(float(max_angle_deg)))

    def cand(alpha: float) -> Any:
        return _ap_cast(p64 + alpha * (m64 - p64), p_old)

    def cosang(cs: Any) -> float | None:
        v = _ap_to64(cs)
        nv = math.sqrt(_ap_f((v * v).sum()))
        if not (nv > eps and n0 > eps):
            return None
        return max(-1.0, min(1.0, _ap_f((p64 * v).sum()) / (n0 * nv)))
    out: dict[str, Any] = {"rho_requested": float(rho), "max_angle_deg": float(max_angle_deg), "cos_limit": cmin}
    req = cand(float(rho))
    cr = cosang(req)
    out["cos_requested"] = cr
    out["angle_requested_deg"] = (None if cr is None else math.degrees(math.acos(cr)))
    if float(rho) == 0.0:
        out.update(new=_xcopy(p_old), alpha=0.0, n_backtrack=0, feasible=True, cap_active=False, cos_actual=1.0,
                   angle_actual_deg=0.0, status="applied_alpha_zero")
        return out
    alpha, nb = float(rho), 0
    while True:
        cs = req if nb == 0 else cand(alpha)
        cv = cosang(cs)
        if cv is not None and cv >= cmin:
            out.update(new=cs, alpha=alpha, n_backtrack=nb, feasible=True, cap_active=nb > 0, cos_actual=cv,
                       angle_actual_deg=math.degrees(math.acos(cv)), status="applied")
            return out
        if nb >= int(backtrack_max) or alpha / 2.0 < float(alpha_min):
            out.update(new=_xcopy(p_old), alpha=0.0, n_backtrack=nb, feasible=False, cap_active=True, cos_actual=None,
                       angle_actual_deg=None, status="angle_cap_no_feasible_alpha", alpha_last_tried=alpha)
            return out
        alpha /= 2.0
        nb += 1


def ap_propose_core(H: Any, labels: Any, k: Any, bank: Any, *, mode: str, tau: np.ndarray, rho: np.ndarray,
                    tau_stable: float, eps: float, min_count: int, max_angle_deg: float, backtrack_max: int,
                    alpha_min: float, range_tol: float, change_log_tol: float, base_ids: Sequence[str]
                    ) -> dict[str, Any]:
    """P_used 하나와 프로토타입별 (tau_j, rho_j) 로 모든 배정·선별·후보를 계산한다 (입력·bank 는 바꾸지 않는다).

    accept_i = valid_i & cos(h_i, P[y_i,k_i]) >= tau[y_i,k_i]. 다른 라벨의 활동은 섞지 않는다 (배정이 정답 클래스 안).
    서로 다른 sample_id 가 min_count 이상인 프로토타입만 각도 상한 안에서 갱신한다. 저장 P 는 정규화하지 않는다.
    """
    if mode not in AP_UPDATE_MODES:
        raise ValueError(f"알 수 없는 적응 갱신 모드: {mode!r}")
    eps = float(eps)
    C, P = int(bank.shape[0]), int(bank.shape[1])
    tau = np.asarray(tau, np.float64).reshape(C, P)
    rho = np.asarray(rho, np.float64).reshape(C, P)
    if _is_torch(H):
        t = require_torch()
        tau_x = t.tensor(tau, dtype=t.float64, device=H.device)
    else:
        tau_x = tau
    Pk = bank[labels, k]
    nP = _xsqrt(_xsum(Pk * Pk, -1))
    nh = _xsqrt(_xsum(H * H, -1))
    valid = (nP > eps) & (nh > eps)
    dot = _xsum(Pk * H, -1)
    den = _xwhere(valid, nP * nh, _xones_like(nP))
    cos_raw = _xwhere(valid, dot / den, _xnan_like(dot))
    out_rng = valid & ((cos_raw > 1.0) | (cos_raw < -1.0))
    cos = _xwhere(valid, _xclip(cos_raw, -1.0, 1.0), cos_raw)
    tau_i = tau_x[labels, k]
    cos_pass = valid & (cos >= tau_i)
    cos_pass_stable = valid & (cos >= float(tau_stable))
    accept = cos_pass if mode == "adaptive" else (cos_pass & (cos_pass != cos_pass))
    bank_new = _xcopy(bank)
    H64 = _ap_to64(H)
    clusters: list[dict[str, Any]] = []
    changed_any = False
    bids = list(base_ids)
    for c in range(C):
        for j in range(P):
            m_as = (labels == c) & (k == j)
            m_acc = m_as & accept
            n_acc = _xint(m_acc)
            p_old = bank[c, j]
            n_old = math.sqrt(_ap_f(_xsum(_ap_to64(p_old) ** 2, -1)))
            zero_p = not n_old > eps
            idx = _xnonzero_idx(m_acc)
            row: dict[str, Any] = {
                "class": c, "proto": j, "tau_used": float(tau[c, j]), "rho_requested": float(rho[c, j]),
                "n_assigned": _xint(m_as), "n_valid_norm": _xint(m_as & valid),
                "n_zero_activity": _xint(m_as & ~(nh > eps)), "n_zero_prototype": _xint(m_as & ~(nP > eps)),
                "n_cos_pass": _xint(m_as & cos_pass), "n_cos_below": _xint(m_as & valid & ~cos_pass),
                "n_cos_pass_stable_tau": _xint(m_as & cos_pass_stable),
                "n_accepted_only_due_to_relaxed_tau": _xint(m_acc & ~cos_pass_stable),
                "n_cos_out_of_range": _xint(m_as & out_rng), "n_accepted": n_acc,
                "n_distinct_samples_accepted": n_acc,
                "n_distinct_bases_accepted": len({bids[i] for i in idx.tolist()}) if bids else None,
                "prototype_zero_norm": zero_p, "norm_P_old": n_old, "proposed": False, "applied": False,
                "actual_alpha": 0.0, "n_backtrack": 0, "cap_active": False, "angle_requested_deg": None,
                "angle_actual_deg": None, "norm_mu": None, "norm_P_new": n_old, "norm_delta": 0.0,
                "max_abs_component_change": 0.0, "bitwise_changed": False, "rounding_no_change": False,
                "change_above_logged_tolerance": False, "change_log_tol": float(change_log_tol)}
            if mode == "fixed":
                row["reason"] = "condition_fixed"
            elif mode == "teacher_off":
                row["reason"] = "teacher_globally_off"
            elif zero_p:
                row["reason"] = "prototype_zero_norm"
            elif row["n_assigned"] == 0:
                row["reason"] = "empty_cluster"
            elif n_acc < int(min_count):
                row["reason"] = "insufficient_count"
            else:
                mu64 = _xsum(H64[m_acc], 0) / float(n_acc)
                stp = ap_capped_step(p_old, mu64, float(rho[c, j]), max_angle_deg=max_angle_deg,
                                     backtrack_max=backtrack_max, alpha_min=alpha_min, eps=eps)
                newv = stp["new"]
                d64 = _ap_to64(newv) - _ap_to64(p_old)
                n_new = math.sqrt(_ap_f(_xsum(_ap_to64(newv) ** 2, -1)))
                mx = _ap_f(_xabs(d64).max())
                bitch = mx > 0.0
                row.update(proposed=True, applied=bool(stp["feasible"]), reason=stp["status"],
                           actual_alpha=float(stp["alpha"]), n_backtrack=int(stp["n_backtrack"]),
                           cap_active=bool(stp["cap_active"]), angle_requested_deg=stp["angle_requested_deg"],
                           angle_actual_deg=stp["angle_actual_deg"], cos_limit=stp["cos_limit"],
                           norm_mu=math.sqrt(_ap_f(_xsum(mu64 ** 2, -1))), norm_P_new=n_new,
                           norm_delta=math.sqrt(_ap_f(_xsum(d64 ** 2, -1))), max_abs_component_change=mx,
                           bitwise_changed=bitch,
                           rounding_no_change=bool(stp["feasible"] and stp["alpha"] > 0 and not bitch),
                           change_above_logged_tolerance=mx > float(change_log_tol),
                           norm_ratio_new_old=(n_new / n_old if n_old > 0 else None))
                if stp["feasible"]:
                    lo, hi = _ap_f(newv.min()), _ap_f(newv.max())
                    if lo < -float(range_tol) or hi > 1.0 + float(range_tol):
                        raise APNumericError(f"갱신 후보가 [0,1] 밖이다 ({lo:.3g}, {hi:.3g}). 조용히 clip 하지 않는다.")
                    bank_new[c, j] = newv
                    changed_any = changed_any or bitch
            clusters.append(row)
    if not _xall_finite(bank_new):
        raise APNumericError("갱신 후 bank 에 NaN/Inf 가 있다.")
    return {"bank_new": bank_new, "k": k, "valid": valid, "cos_raw": cos_raw, "cos": cos, "cos_pass": cos_pass,
            "cos_pass_stable": cos_pass_stable, "tau_sample": tau_i, "accept": accept, "nh": nh, "nP": nP,
            "clusters": clusters, "mode": mode, "applied_any": changed_any,
            "n_cos_out_of_range": _xint(out_rng), "range_overshoot": 0.0, "range_rounding_within_tol": False}


class AdaptivePrototypeUpdater(PrototypeUpdater):
    """메뉴 23 갱신기. propose 는 읽기 전용 (상태 S_used 로 정한 tau_j / rho_j 를 받는다), commit 은 메뉴 22 와 같은 유일한 변경 지점."""

    def __init__(self, mode: str, *, settings: dict[str, Any], seed: int) -> None:            # noqa: D107
        if mode not in AP_UPDATE_MODES:
            raise ValueError(f"알 수 없는 적응 갱신 모드: {mode!r}")
        p = settings["prototype"]
        self.mode = mode
        self.tau, self.rho, self.eps = float(p["tau_cos"]), float(p["rho_proto"]), float(p["eps_norm"])
        self.tau_unstable, self.rho_unstable = float(p["tau_cos_unstable"]), float(p["rho_proto_unstable"])
        self.enter, self.exit = float(p["instability_enter_cos"]), float(p["instability_exit_cos"])
        self.max_angle = float(p["max_angle_step_deg"])
        self.backtrack_max, self.alpha_min = int(p["backtrack_max"]), float(p["alpha_min"])
        self.min_count = int(p["min_accept_count"])
        self.range_tol = float(p["range_rounding_tol"])
        self.change_log_tol = float(p["change_log_tol"])
        self.seed = int(seed)
        self.version = 0
        self.last_completed_refresh_epoch = -1
        self.n_commits = 0
        self.history: list[dict[str, Any]] = []

    def params(self) -> dict[str, Any]:
        return {"mode": self.mode, "tau_cos": self.tau, "tau_cos_unstable": self.tau_unstable, "rho_proto": self.rho,
                "rho_proto_unstable": self.rho_unstable, "instability_enter_cos": self.enter,
                "instability_exit_cos": self.exit, "max_angle_step_deg": self.max_angle,
                "backtrack_max": self.backtrack_max, "alpha_min": self.alpha_min, "eps_norm": self.eps,
                "min_accept_count": self.min_count, "seed": self.seed}

    def propose(self, act: dict[str, Any], bank: Any, *, split: str, epoch: int, assign: Any | None = None,
                tau: Any = None, rho: Any = None, state_used: Any = None) -> dict[str, Any]:  # type: ignore[override]
        """train 판독 활동 + P_used + (tau_j, rho_j) -> 다음 bank 후보와 진단. 모델·bank·갱신기·상태를 바꾸지 않는다."""
        if split != "train":
            raise ValueError(f"프로토타입 갱신에는 train 판독만 쓴다 (받은 분할: {split!r}). dev/test/holdout 은 거부한다.")
        C, P = int(bank.shape[0]), int(bank.shape[1])
        if tau is None or rho is None:
            raise ValueError("적응 갱신기에는 에폭 시작 때 고정한 tau_used / rho_used 가 필요하다.")
        H, labels = act["h"], act["labels"]
        sids, bids = list(act["sample_ids"]), list(act["base_ids"])
        if len(sids) != int(H.shape[0]):
            raise ValueError("sample_ids 개수와 활동 행 수가 다르다.")
        seen: set[str] = set()
        keep = []
        for i, s_ in enumerate(sids):
            if s_ not in seen:
                seen.add(s_)
                keep.append(i)
        n_dup = len(sids) - len(keep)
        if n_dup:
            if _is_torch(H):
                ki = require_torch().tensor(keep, dtype=require_torch().long, device=H.device)
            else:
                ki = np.asarray(keep, np.int64)
            H, labels = H[ki], labels[ki]
            assign = None if assign is None else assign[ki]
            sids, bids = [sids[i] for i in keep], [bids[i] for i in keep]
        if not _xall_finite(H) or not _xall_finite(bank):
            raise APNumericError("train 판독 활동 또는 프로토타입에 NaN/Inf 가 있다 (0 으로 덮지 않고 멈춘다).")
        k = assign if assign is not None else cp_select(H, labels, bank)
        core = ap_propose_core(H, labels, k, bank, mode=self.mode, tau=np.asarray(tau).reshape(C, P),
                               rho=np.asarray(rho).reshape(C, P), tau_stable=self.tau, eps=self.eps,
                               min_count=self.min_count, max_angle_deg=self.max_angle,
                               backtrack_max=self.backtrack_max, alpha_min=self.alpha_min, range_tol=self.range_tol,
                               change_log_tol=self.change_log_tol, base_ids=bids)
        old_sha, new_sha = _cp_hash(bank), _cp_hash(core["bank_new"])
        return {"epoch": int(epoch), "split": split, "mode": self.mode, "params": self.params(),
                "version_before": self.version, "bank_old": _xcopy(bank), "bank_old_sha256": old_sha,
                "bank_new": core["bank_new"], "bank_new_sha256": new_sha, "changed": old_sha != new_sha,
                "core": core, "H": H, "labels": labels, "k": k, "sample_ids": sids, "base_ids": bids,
                "n_duplicates_dropped": n_dup, "tau_used": np.asarray(tau, np.float64).reshape(C, P).copy(),
                "rho_used": np.asarray(rho, np.float64).reshape(C, P).copy(),
                "state_used": (None if state_used is None else np.asarray(state_used).reshape(C, P).copy()),
                "assignment_source": ("given (TeacherTargetProvider.select_prototype)" if assign is not None
                                      else "cp_select")}


AP_ROW_EXTRA_KEYS: tuple[str, ...] = (
    "tau_used", "rho_requested", "n_cos_pass_stable_tau", "n_accepted_only_due_to_relaxed_tau", "proposed",
    "actual_alpha", "n_backtrack", "cap_active", "angle_requested_deg", "angle_actual_deg", "norm_mu",
    "bitwise_changed", "rounding_no_change", "change_above_logged_tolerance", "change_log_tol", "norm_ratio_new_old",
    "n_distinct_bases_accepted")


def ap_proposal_rows(prop: dict[str, Any], *, settings: dict[str, Any], cond: str, classes: Sequence[str]
                     ) -> tuple[list[dict[str, Any]], dict[str, Any], dict[str, np.ndarray]]:
    """메뉴 22 기록 행 + 적응 갱신 열 (상태·요청/실제 alpha·각도·backtrack·반올림 무변화)."""
    rows, bank, arrays = cp_proposal_rows(prop, settings=settings, cond=cond, classes=classes)
    st = prop.get("state_used")
    for r, cl in zip(rows, prop["core"]["clusters"]):
        for kk in AP_ROW_EXTRA_KEYS:
            if kk in cl:
                r[kk] = cl[kk]
        r["norm_P_new"] = cl.get("norm_P_new", r.get("norm_P_new"))
        r["state_used"] = (AP_STATE_NAMES[int(st[r["class_index"], r["proto"]])] if st is not None else None)
        r["norm_P_new_gt_old"] = bool(cl.get("applied") and cl.get("norm_P_new", 0) > cl.get("norm_P_old", 0))
        r["norm_P_new_lt_old"] = bool(cl.get("applied") and cl.get("norm_P_new", 0) < cl.get("norm_P_old", 0))
    arrays["tau_sample"] = _cp_np(prop["core"]["tau_sample"]).astype(np.float32)
    arrays["cos_pass_stable"] = _cp_np(prop["core"]["cos_pass_stable"]).astype(bool)
    app = [cl for cl in prop["core"]["clusters"] if cl.get("applied")]
    bank["n_proposed"] = sum(1 for cl in prop["core"]["clusters"] if cl.get("proposed"))
    bank["n_cap_active"] = sum(1 for cl in app if cl.get("cap_active"))
    bank["n_bitwise_changed"] = sum(1 for cl in app if cl.get("bitwise_changed"))
    bank["n_rounding_no_change"] = sum(1 for cl in app if cl.get("rounding_no_change"))
    bank["n_angle_cap_infeasible"] = sum(1 for cl in prop["core"]["clusters"]
                                         if cl.get("reason") == "angle_cap_no_feasible_alpha")
    return rows, bank, arrays


# ---------------------------------------------------------------------- 진단: 같은 H 의 자기/다른 클래스 cosine margin
def ap_margins(H: np.ndarray, labels: np.ndarray, bank: np.ndarray, *, eps: float) -> dict[str, np.ndarray]:
    """s_own = max_k cos(h, P[y,k]), s_other = max_(c!=y,k) cos(h, P[c,k]), margin = s_own - s_other (진단용, gate 아님).

    영벡터·유효 비교 없음은 NaN 으로 둔다 (유효 개수를 따로 센다).
    """
    H = np.asarray(H, np.float64)
    y = np.asarray(labels, np.int64)
    B = np.asarray(bank, np.float64)
    C, P, n = B.shape
    flat = B.reshape(C * P, n)
    nb = np.linalg.norm(flat, axis=1)
    nh = np.linalg.norm(H, axis=1)
    vb, vh = nb > eps, nh > eps
    cls = np.repeat(np.arange(C), P)
    with np.errstate(invalid="ignore", divide="ignore"):
        M = (H @ flat.T) / (np.where(vh, nh, 1.0)[:, None] * np.where(vb, nb, 1.0)[None, :])
    M = np.clip(M, -1.0, 1.0)
    ok = vh[:, None] & vb[None, :]
    own_m = ok & (cls[None, :] == y[:, None])
    oth_m = ok & (cls[None, :] != y[:, None])
    s_own = np.where(own_m.any(axis=1), np.where(own_m, M, -np.inf).max(axis=1), np.nan)
    s_oth = np.where(oth_m.any(axis=1), np.where(oth_m, M, -np.inf).max(axis=1), np.nan)
    return {"s_own": s_own, "s_other": s_oth, "margin": s_own - s_oth}


def ap_margin_rows(mg: dict[str, np.ndarray], labels: np.ndarray, *, cond: str, epoch: int, kind: str,
                   classes: Sequence[str]) -> list[dict[str, Any]]:
    y = np.asarray(labels, np.int64)
    rows = []
    for c in [None] + sorted(set(y.tolist())):
        m = np.ones_like(y, bool) if c is None else (y == c)
        mm = mg["margin"][m]
        v = mm[np.isfinite(mm)]
        so, sx = mg["s_own"][m], mg["s_other"][m]
        rows.append({"condition": cond, "epoch": int(epoch), "kind": kind,
                     "class": "ALL" if c is None else (classes[c] if c < len(classes) else c), "n": int(m.sum()),
                     "n_valid": int(v.size), "margin_mean": float(v.mean()) if v.size else None,
                     "margin_median": float(np.median(v)) if v.size else None,
                     "margin_p10": float(np.percentile(v, 10)) if v.size else None,
                     "fraction_margin_le0": float((v <= 0).mean()) if v.size else None,
                     "s_own_mean": float(np.nanmean(so)) if np.isfinite(so).any() else None,
                     "s_other_mean": float(np.nanmean(sx)) if np.isfinite(sx).any() else None,
                     "note_ko": ("old_same_H: 에폭 끝 H 와 그 에폭에 쓴 P_used, new_same_H: 같은 H 와 갱신 뒤 P_next. 다음 에폭 "
                                 "old_same_H 와 이번 new_same_H 의 차이가 실제 표현 변화다. margin 은 진단용이며 gate 가 아니다.")})
    return rows


# ---------------------------------------------------------------------- 메뉴 23 사전 검사 (AP1~AP15)
AP_CHECK_IDS: tuple[str, ...] = tuple(f"AP{i}" for i in range(1, 16))
