        "--compare-budget-modes summed,fixed_total_budget --output \"D:\\CortexResults\"\n"
        f"  python {n} --mode paired-train --preset hierarchy_small --wiring-mode "
        "paired_only --paired-condition sequential_dual --device cuda --output "
