def _parse_float_list(raw: str, *, name: str) -> list[float]:
    """쉼표 구분 실수 목록. 잘못된 값은 조용히 넘기지 않고 막는다."""
    out: list[float] = []
    for part in str(raw).split(","):
        part = part.strip()
        if not part:
            continue
        try:
            v = float(part)
        except ValueError as exc:
            raise SystemExit(f"{name} 에 숫자가 아닌 값이 있다: {part!r}") from exc
        if not math.isfinite(v):
            raise SystemExit(f"{name} 에 유한수가 아닌 값이 있다: {part!r}")
        out.append(v)
    if not out:
        raise SystemExit(f"{name} 가 비어 있다.")
    return out


def _parse_int_list(raw: str, *, name: str) -> list[int]:
    out: list[int] = []
    for part in str(raw).split(","):
        part = part.strip()
        if not part:
            continue
        try:
            out.append(int(part))
        except ValueError as exc:
            raise SystemExit(f"{name} 에 정수가 아닌 값이 있다: {part!r}") from exc
    if not out:
        raise SystemExit(f"{name} 가 비어 있다.")
    if len(set(out)) != len(out):
        raise SystemExit(f"{name} 에 중복된 시드가 있다: {out}")
    return out


def _check_inhibition_option_modes(args: argparse.Namespace) -> None:
    """의미 없는 모드에 준 새 옵션을 **조용히 무시하지 않고** 막는다."""
    mode = str(args.mode or "")
    bad: list[str] = []
    for attr, modes in INHIBITION_OPTION_MODES.items():
        if getattr(args, attr, None) is None:
            continue
        if mode not in modes:
            flag = "--" + attr.replace("_", "-")
            bad.append(f"{flag} 는 {list(modes)} 에서만 의미가 있다 "
                       f"(지금 --mode {mode or '없음'})")
    if bad:
        raise SystemExit("옵션과 모드가 맞지 않는다:\n  - " + "\n  - ".join(bad))
    # 기존 --epochs 와 단계별 에폭 수의 충돌은 조용히 정하지 않는다
    stage_given = any(getattr(args, a, None) is not None
                      for a in ("warmup_epochs", "ramp_epochs", "hold_epochs"))
    if (mode in ("inhibition-train", "inhibition-compare")
            and getattr(args, "epochs", None) is not None):
        raise SystemExit(
            "억제 실험의 총 에폭 수는 --warmup-epochs / --ramp-epochs / "
            "--hold-epochs 의 합으로 정해진다.\n"
            "  --epochs 를 함께 주면 어느 쪽이 이기는지 조용히 정하지 않고 "
            "여기서 멈춘다. 둘 중 하나만 써라.")
    if stage_given and mode not in ("inhibition-train", "inhibition-compare"):
        raise SystemExit(
            "단계별 에폭 수 옵션은 inhibition-train / inhibition-compare 에서만 "
            "쓴다.")
    if (getattr(args, "seeds", None) is not None
            and getattr(args, "seed", None) is not None):
        raise SystemExit(
            "--seeds 와 --seed 를 함께 줄 수 없다. 여러 시드는 --seeds, 하나는 "
            "--seed 로 지정한다.")
    # 값 자체의 유효성도 **torch 가 없는 환경에서도** 먼저 잡는다.
    if getattr(args, "inhibition_values", None) is not None:
        for v in _parse_float_list(args.inhibition_values,
                                   name="--inhibition-values"):
            if not (INHIBITION_GAIN_MIN <= v <= INHIBITION_GAIN_MAX):
                raise SystemExit(
                    f"--inhibition-values 의 배율은 [0, 1] 이어야 한다: {v}")
    if getattr(args, "seeds", None) is not None:
        _parse_int_list(args.seeds, name="--seeds")
    for flag, attr in (("--inhibition-start", "inhibition_start"),
                       ("--inhibition-end", "inhibition_end"),
                       ("--inhibition-eval-gain", "inhibition_eval_gain")):
        v = getattr(args, attr, None)
        if v is None:
            continue
        if not math.isfinite(float(v)):
            raise SystemExit(f"{flag} 는 유한수여야 한다: {v!r}")
        if not (INHIBITION_GAIN_MIN <= float(v) <= INHIBITION_GAIN_MAX):
            raise SystemExit(f"{flag} 는 [0, 1] 이어야 한다: {v}")
    a_s, a_e = getattr(args, "inhibition_start", None), \
        getattr(args, "inhibition_end", None)
    if a_s is not None and a_e is not None and float(a_s) > float(a_e):
        raise SystemExit(
            f"--inhibition-start 는 --inhibition-end 보다 클 수 없다 "
            f"({a_s} > {a_e})")
    if (getattr(args, "ramp_epochs", None) is not None
            and int(args.ramp_epochs) < 1):
        raise SystemExit(f"--ramp-epochs 는 1 이상이어야 한다: {args.ramp_epochs}")
    for flag, attr in (("--warmup-epochs", "warmup_epochs"),
                       ("--hold-epochs", "hold_epochs")):
        v = getattr(args, attr, None)
        if v is not None and int(v) < 0:
            raise SystemExit(f"{flag} 는 0 이상이어야 한다: {v}")
    _check_wiring_option_modes(args)


def _check_wiring_option_modes(args: argparse.Namespace) -> None:
    """배선 실험 옵션이 의미 없는 모드에 오면 **조용히 무시하지 않고** 막는다."""
    mode = str(args.mode or "")
    bad: list[str] = []
    for attr, modes in WIRING_OPTION_MODES.items():
        if getattr(args, attr, None) is None:
            continue
        if mode not in modes:
            flag = "--" + attr.replace("_", "-")
            bad.append(f"{flag} 는 {list(modes)} 에서만 의미가 있다 "
                       f"(지금 --mode {mode or '없음'})")
    if bad:
        raise SystemExit("옵션과 모드가 맞지 않는다:\n  - " + "\n  - ".join(bad))
    if mode == "wiring-compare" and not getattr(args, "wiring_group", None):
        raise SystemExit(
            "--mode wiring-compare 에는 --wiring-group 이 필요하다.\n"
            "  한 번에 한 연결군만 바꾼다. 여러 연결군은 --mode wiring-bundle 로 "
            "하나씩 돌린다.")
    if getattr(args, "wiring_seeds", None) is not None:
        _parse_int_list(args.wiring_seeds, name="--wiring-seeds")
    if getattr(args, "wiring_conditions", None) is not None:
        for c in str(args.wiring_conditions).split(","):
            c = c.strip()
            if c and c not in WIRING_CONDITIONS:
                raise SystemExit(
                    f"--wiring-conditions 에 알 수 없는 조건이 있다: {c!r} "
                    f"(가능: {list(WIRING_CONDITIONS)})")
    g = getattr(args, "wiring_inhibition_gain", None)
    if g is not None and not (math.isfinite(float(g))
                              and INHIBITION_GAIN_MIN <= float(g)
                              <= INHIBITION_GAIN_MAX):
        raise SystemExit(f"--wiring-inhibition-gain 은 [0, 1] 의 유한수다: {g}")
    d = getattr(args, "wiring_min_in_degree", None)
    if d is not None and int(d) < 0:
        raise SystemExit(f"--wiring-min-in-degree 는 0 이상이어야 한다: {d}")
    b = getattr(args, "wiring_strength_bounds", None)
    if b is not None:
        vals = _parse_float_list(b, name="--wiring-strength-bounds")
        if len(vals) != 2:
            raise SystemExit(
                f"--wiring-strength-bounds 는 'lo,hi' 두 값이다: {b!r}")
        if not (0.0 < vals[0] <= 1.0 <= vals[1]):
            raise SystemExit(
                f"--wiring-strength-bounds 는 0 < lo <= 1 <= hi 여야 한다: {vals}")


def _cfg_from_args(args: argparse.Namespace) -> dict[str, Any]:
    profile_path = getattr(args, "transmission_config", None)
    cfg = (load_transmission_config(clean_user_path(profile_path)) if profile_path
           else build_config(args.preset, include_v3=bool(getattr(args, "include_v3", False))))
    if profile_path and getattr(args, "include_v3", False) and "V3" not in cfg["areas"]:
        raise ValueError("보정 설정에 V3가 없다. V3를 추가한 새 설정에서 다시 보정하라.")
    # ---- 4.0 배선 모드·엔진 ----
    wm = getattr(args, "wiring_mode", None)
    ek = getattr(args, "engine_kind", None)
    fan = {k: v for k, v in (("K0", getattr(args, "fanin_k0", None)),
                             ("c", getattr(args, "fanin_c", None)),
                             ("r0_deg", getattr(args, "fanin_r0", None)),
                             ("K_max", getattr(args, "fanin_kmax", None)))
           if v is not None}
    bm = getattr(args, "budget_mode", None)
    if profile_path and ((wm and wm != cfg["paired"]["wiring_mode"])
                         or (ek and ek != cfg["engine_model"]["kind"]) or fan or bm):
        raise ValueError("불러온 보정 설정의 배선/엔진은 바꿀 수 없다. 보정은 그 모델 "
                         "전용이다. 새 배선에서 메뉴 12-1 로 다시 보정하라.")
    if not profile_path and (wm or ek or fan or bm):
        cfg = paired_config(args.preset, str(wm or "legacy"), engine_kind=ek,
                            fanin=fan or None, budget_mode=bm,
                            include_v3=bool(getattr(args, "include_v3", False)))
    fbk = cfg["paired"]["feedback"]
    if getattr(args, "l3_to_l2", None) is not None:
        fbk["l3_to_l2_projection"] = str(args.l3_to_l2)
    if getattr(args, "gate_rule", None) is not None:
        fbk["teacher_gate_rule"] = str(args.gate_rule)
    if getattr(args, "paired_condition", None) is not None:
        fbk["condition"] = str(args.paired_condition)
    if args.seed is not None:
        cfg["seed"] = int(args.seed)
    if args.batch_size is not None:
        cfg["training"]["batch_size"] = int(args.batch_size)
    if args.epochs is not None:
        cfg["training"]["epochs"] = int(args.epochs)
    if args.train_mode is not None:
        cfg["training"]["mode"] = args.train_mode
        if is_threshold_condition(args.train_mode):
            cfg["threshold_learning"]["condition"] = args.train_mode
    if args.recording_mode is not None:
        cfg["recording"]["mode"] = args.recording_mode
    if args.backend is not None:
        cfg["recording"]["backend"] = args.backend
    if getattr(args, "data_mode", None) is not None:
        cfg["data"]["mode"] = args.data_mode
    tl = cfg["threshold_learning"]
    for attr, key, cast in (("k_rounds", "K_rounds", int),
                            ("eta_commit", "eta_commit", float),
                            ("kappa", "kappa_mV_per_round", float),
                            ("deadband", "deadband", float),
                            ("beta", "beta", float)):
        val = getattr(args, attr, None)
        if val is not None:
            tl[key] = cast(val)
    if getattr(args, "alpha_att", None) is not None:
        tl["attention"]["alpha_att"] = float(args.alpha_att)
    # ---- 억제 점진 복원 실험 옵션 ----------------------------------
    inh = cfg["inhibition"]
    if getattr(args, "inhibition_values", None) is not None:
        inh["scan_values"] = _parse_float_list(args.inhibition_values,
                                               name="--inhibition-values")
    for attr, key, cast in (("inhibition_start", "start", float),
                            ("inhibition_end", "end", float),
                            ("warmup_epochs", "warmup_epochs", int),
                            ("ramp_epochs", "ramp_epochs", int),
                            ("hold_epochs", "hold_epochs", int),
                            ("inhibition_schedule", "schedule", str),
                            ("inhibition_condition", "condition", str)):
        val = getattr(args, attr, None)
        if val is not None:
            inh[key] = cast(val)
    if getattr(args, "inhibition_eval_gain", None) is not None:
        inh["eval_gain"] = float(args.inhibition_eval_gain)
    wb = cfg["wiring_balance"]
    if getattr(args, "wiring_groups", None) is not None:
        wb["target_groups"] = [x.strip() for x in str(args.wiring_groups).split(",")
                               if x.strip()]
    if getattr(args, "wiring_conditions", None) is not None:
        conds = [x.strip() for x in str(args.wiring_conditions).split(",")
                 if x.strip()]
        if "C0_baseline" not in conds:
            conds = ["C0_baseline"] + conds
        wb["conditions"] = conds
    if getattr(args, "wiring_seeds", None) is not None:
        wb["seeds"] = _parse_int_list(args.wiring_seeds, name="--wiring-seeds")
    if getattr(args, "wiring_inhibition_gain", None) is not None:
        wb["inhibition_gain"] = float(args.wiring_inhibition_gain)
        if wb["inhibition_gain"] == float(wb["aux_inhibition_gain"]):
            wb["aux_inhibition_gain"] = (0.0 if wb["inhibition_gain"] != 0.0
                                         else 0.01)
    if getattr(args, "wiring_min_in_degree", None) is not None:
        wb["degree"]["min_in_degree"] = int(args.wiring_min_in_degree)
    if getattr(args, "wiring_strength_bounds", None) is not None:
        lo, hi = _parse_float_list(args.wiring_strength_bounds,
                                   name="--wiring-strength-bounds")
        wb["strength"]["lo_multiplier"] = float(lo)
        wb["strength"]["hi_multiplier"] = float(hi)
    # 억제 실험 모드에서는 스케줄의 start 에서 출발한다.
    if str(getattr(args, "mode", "")) in ("inhibition-train",
                                          "inhibition-compare"):
        inh["gain"] = float(inh["start"])
    validate_config(cfg)
    return cfg


def _adaptive_cli_settings(args: argparse.Namespace) -> dict[str, Any]:
    """CLI 옵션 -> 메뉴 23 설정 (검증은 validate_ap_settings). 모든 비교 조건에 공통으로 적용된다."""
    st: dict[str, Any] = {}
    lst = lambda v: [x for x in str(v).replace(" ", "").split(",") if x]      # noqa: E731
    key = "main" if str(getattr(args, "adaptive_task", "") or "") == "main" else "smoke"
    if args.adaptive_seeds:
        st["seeds"] = [int(x) for x in lst(args.adaptive_seeds)]
    pre = {k: int(v) for k, v in (("epochs", args.adaptive_epochs), ("batch_size", args.adaptive_batch_size),
                                  ("train_bases_per_class", args.adaptive_train_bases)) if v is not None}
    if pre:
        st[key] = pre
    pp = {k: v for k, v in (("instability_enter_cos", args.adaptive_enter), ("instability_exit_cos", args.adaptive_exit),
                            ("tau_cos", args.adaptive_tau), ("tau_cos_unstable", args.adaptive_tau_unstable),
                            ("rho_proto", args.adaptive_rho), ("rho_proto_unstable", args.adaptive_rho_unstable),
                            ("max_angle_step_deg", args.adaptive_max_angle), ("min_accept_count", args.adaptive_min_accept))
          if v is not None}
    if pp:
        st["prototype"] = pp
    if args.adaptive_selection:
        st["selection_rule"] = str(args.adaptive_selection)
    if args.adaptive_flow_detail:
        st["flow_detail"] = str(args.adaptive_flow_detail)
    if args.adaptive_nondeterministic:
        st["deterministic_engine"] = False
    if args.adaptive_no_epoch_diagnostic:
        st["diagnostic_each_epoch"] = False
    ho = {k: v for k, v in (("n_base_per_class", args.adaptive_holdout_n_base),
                            ("n_variants", args.adaptive_holdout_variants),
                            ("stream_sub", args.adaptive_holdout_sub)) if v is not None}
    if ho:
        st["holdout"] = ho
    return st


